const SearchFunction = {
  formatSearchKeyword: function(keyword) {
    const nothing = "";
    const space = " ";
    if (!keyword) return nothing;
    return keyword.replace(/(!=)|['"=<>/\\:]/g, nothing).replace(/[,，|(){}]/g, space).trim();
  }
};

