const JSONWebToken = {
  header: { alg: 'RS256', typ: 'JWT' },
  importKey: async function(pemKey) {
    const pemDER = this.textUtils.base64ToArrayBuffer(pemKey.split('\n').map(s => s.trim()).filter(l => l.length && !l.startsWith('---')).join(''));
    return crypto.subtle.importKey('pkcs8', pemDER, { name: 'RSASSA-PKCS1-v1_5', hash: 'SHA-256' }, false, ['sign']);
  },
  createSignature: async function(text, key) {
    const textBuffer = this.textUtils.stringToArrayBuffer(text);
    return crypto.subtle.sign('RSASSA-PKCS1-v1_5', key, textBuffer);
  },
  generateGCPToken: async function(serviceAccount) {
    const iat = parseInt(Date.now() / 1000, 10);  // ★ v1.0.103 Task 20-11 Fix #2: parseInt sem radix — Number arg ainda beneficia de base 10 explícita (engines podem coercionar via String).
    const payload = { iss: serviceAccount.client_email, scope: "https://www.googleapis.com/auth/drive", aud: "https://oauth2.googleapis.com/token", exp: iat + 3600, iat: iat };
    const toBase64Url = s => s.replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');
    const encPayload = toBase64Url(btoa(JSON.stringify(payload)));
    const encHeader = toBase64Url(btoa(JSON.stringify(this.header)));
    const key = await this.importKey(serviceAccount.private_key);
    const signed = await this.createSignature(encHeader + "." + encPayload, key);
    return encHeader + "." + encPayload + "." + toBase64Url(this.textUtils.arrayBufferToBase64(signed));
  },
  textUtils: {
    base64ToArrayBuffer: function(base64) {
      const binary_string = atob(base64);
      const len = binary_string.length;
      const bytes = new Uint8Array(len);
      for (let i = 0; i < len; i++) bytes[i] = binary_string.charCodeAt(i);
      return bytes.buffer;
    },
    stringToArrayBuffer: function(str) {
      const len = str.length;
      const bytes = new Uint8Array(len);
      for (let i = 0; i < len; i++) bytes[i] = str.charCodeAt(i);
      return bytes.buffer;
    },
    arrayBufferToBase64: function(buffer) {
      let binary = '';
      const bytes = new Uint8Array(buffer);
      const len = bytes.byteLength;
      for (let i = 0; i < len; i++) binary += String.fromCharCode(bytes[i]);
      return btoa(binary);
    }
  }
};

// ★ Cache de CryptoKey — importKey é caro (5-15ms por request), 
// mas a chave é determinística (depende só de crypto_base_key).
// Cache na memória do isolado → 1 cold importKey, subsequentes instantâneos.
let _cachedAesKeyEnc = null, _cachedAesKeyDec = null, _cachedHmacKey = null;

// ═══ v84-FIX-BATTALION BUG 4/5: mutexes in-memory por folderId para serializar
// read-modify-write no cache ISA e em general_courses.json. Sem isso, saves
// concorrentes com chaves diferentes → last-write-wins → outras chaves perdidas.
// Trava é per-isolate (CF pode rodar múltiplos isolates, mas para o mesmo user
// na mesma janela de tempo, normalmente cai no mesmo isolate). Não é perfeito
// mas elimina a maioria das races observadas.
const _isaCacheMutex = {};       // folderId → Promise chain
const _generalCoursesMutex = {}; // folderId → Promise chain
function _withMutex(map, key, fn){
  const k = key || '_global';
  const next = (map[k] || Promise.resolve()).then(fn, fn);
  const settled = next.catch(() => {});  // nunca deixa a chain rejeitar
  map[k] = settled;
  // ★ v1.0.103 Task 20-2 Fix #1: cleanup após settle — Map crescia indefinidamente com
  // folderIds distintos (cada RMW em isa-cache/general-courses adicionava uma entry que
  // nunca era removida). Após a chain resolver, se nenhum novo caller encadeou em map[k]
  // (i.e., map[k] ainda aponta para `settled`), removemos a entry. Callers concorrentes
  // que encadearam terão substituído map[k] por uma nova chain, e a deleção aqui é no-op
  // para eles (guard === previne a deleção). Em isolates de longa vida, isso mantém o
  // Map estável; em isolates curtos, é um no-op barato (uma microtask).
  settled.then(() => { if (map[k] === settled) delete map[k]; });
  return next;
}
async function withIsaCacheLock(folderId, fn){
  return _withMutex(_isaCacheMutex, folderId, fn);
}
async function withGeneralCoursesLock(folderId, fn){
  return _withMutex(_generalCoursesMutex, folderId, fn);
}

async function getAesKey(forUse) {
  // forUse: 'encrypt' | 'decrypt' (a mesma chave serve, mas WebCrypto exige permissões diferentes)
  const cache = forUse === 'encrypt' ? _cachedAesKeyEnc : _cachedAesKeyDec;
  if (cache) return cache;
  const key = await crypto.subtle.importKey(
    "raw", new TextEncoder().encode(resolveCryptoBaseKey()), "AES-CBC", false, [forUse]
  );
  if (forUse === 'encrypt') _cachedAesKeyEnc = key;
  else _cachedAesKeyDec = key;
  return key;
}

async function getHmacKey() {
  if (_cachedHmacKey) return _cachedHmacKey;
  const encoder = new TextEncoder();
  _cachedHmacKey = await crypto.subtle.importKey(
    'raw', encoder.encode(resolveHmacBaseKey()), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']
  );
  return _cachedHmacKey;
}

async function encryptString(string) {
  const iv = crypto.getRandomValues(new Uint8Array(16));
  const key = await getAesKey('encrypt');
  const encryptedData = await crypto.subtle.encrypt({ name: "AES-CBC", iv }, key, new TextEncoder().encode(string));
  const encryptedBytes = new Uint8Array(encryptedData);
  const combined = new Uint8Array(iv.length + encryptedBytes.length);
  combined.set(iv);
  combined.set(encryptedBytes, iv.length);
  return btoa(Array.from(combined, b => String.fromCharCode(b)).join(""));
}

async function decryptString(encryptedString) {
  const key = await getAesKey('decrypt');
  const combined = Uint8Array.from(atob(encryptedString), c => c.charCodeAt(0));
  const iv = combined.slice(0, 16);
  const ciphertext = combined.slice(16);
  const decryptedData = await crypto.subtle.decrypt({ name: "AES-CBC", iv }, key, ciphertext);
  return new TextDecoder().decode(decryptedData);
}

async function genIntegrity(data, key) {
  const encoder = new TextEncoder();
  const hmacKey = !key ? await getHmacKey() : await crypto.subtle.importKey('raw', encoder.encode(key), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  const hmacBuffer = await crypto.subtle.sign('HMAC', hmacKey, encoder.encode(data));
  const hmacArray = Array.from(new Uint8Array(hmacBuffer));
  return hmacArray.map(byte => byte.toString(16).padStart(2, '0')).join('');
}

async function checkintegrity(expectedHex, actualHex) {
  if (typeof expectedHex !== 'string' || typeof actualHex !== 'string') return false;
  if (expectedHex.length !== actualHex.length) return false;
  const enc = new TextEncoder();
  const keyMaterial = await crypto.subtle.importKey('raw', enc.encode(resolveHmacBaseKey()), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  const sig1 = await crypto.subtle.sign('HMAC', keyMaterial, enc.encode(expectedHex));
  const sig2 = await crypto.subtle.sign('HMAC', keyMaterial, enc.encode(actualHex));
  const a = new Uint8Array(sig1);
  const b = new Uint8Array(sig2);
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a[i] ^ b[i];
  return diff === 0;
}

