// ═══ USER STATE — progresso por usuário (JSON no Drive) ═══
// ★ grava na pasta 0 (PARABURGUER)
const USERSTATE_FOLDER = 'AULAS - ESTADO DOS ALUNOS';
const USERSTATE_PARENT_DRIVE = 0;

async function gdiSessionUser(request){
  try{
    const cookie=request.headers.get('cookie')||'';
    const m=cookie.match(/(?:^|;\s*)session=([^;]*)/);
    if(!m)return null;
    const parts=m[1].trim().split('|');
    const user=await decryptString(parts[0]);
    if(!user)return null;
    // ★ v2.15.43 (SEC-10/SEC-2): expiração verificada AQUI — antes só
    //   o gate principal a via; scanAdminAuth e todas as rotas com
    //   gdiSessionUser aceitavam cookies expirados para sempre.
    if(parts.length>=2){
      let t=NaN;
      try{ t=Number(await decryptString(parts[2]||parts[1])); }catch(_){ t=NaN; }
      if(!isFinite(t)||t<Date.now())return null;
    }
    return user;
  }catch(_){return null}
}

async function gdiUserFolderId(gd0){
  // ★ CYCLE2-1 Fix Bug #2: defensive guard against undefined gd0. Multiple handlers
  // (handleBattalionStatus, handleIsaCacheGet/Save/List, handleSharedSummariesGet/Save,
  // handleSharedFlashcardsGet/Save, handleRedacaoCorrect, handleEssaySave, handleCourseAdd/
  // Remove/List, handleCourseScanProgress, handleCourseDistributedStatus, handleCourseRescan,
  // handleCourseValidate, handleMaterialsSaveInFolder/LoadFromFolder/CheckExists,
  // handleMaterialsMetaGet/Save/Delete, handleCourseSaveUserProgress, handleCourseSharedProgress
  // Save/Get, handleMaterialsList/Save/Exists) call `gdiUserFolderId(gds[0])` without first
  // checking `if(!gd0)`. If gds is empty (e.g., a misconfigured deployment with 0 drives in
  // authConfig.roots, OR a transient init failure that left gds=[] but set _gdsInitialized),
  // the first line `if(gd0.__userFolderId)` throws TypeError (cannot read property of
  // undefined). The error propagates to the top-level catch (500 "Internal Server Error"
  // plain text) — losing the JSON CORS-safe error envelope the handler intended to return.
  // Returning null here lets each handler's existing `if(!folderId)` check fire and return
  // its proper 502 JSON response. Only handleBrainList/handleBrainSave (lines 1352, 1410)
  // had a `!gd0` check before this fix; the others relied on gds always being non-empty
  // (true in practice when authConfig.roots has ≥1 entry, but defense-in-depth is cheap).
  if(!gd0) return null;
  if(gd0.__userFolderId)return gd0.__userFolderId;
  const parentGd=gds[USERSTATE_PARENT_DRIVE]||gds[0];
  const parentId=parentGd.root.id;
  const q=`'${parentId}' in parents and name = '${USERSTATE_FOLDER}' and trashed = false`;
  const listOpts=await parentGd.requestOptions();
  const lr=await fetch('https://www.googleapis.com/drive/v3/files?'+enQuery({includeItemsFromAllDrives:'true',supportsAllDrives:'true',q,fields:'files(id)',pageSize:'1'}),listOpts);
  if(lr.ok){
    const lj=await lr.json();
    if(lj.files&&lj.files[0]){gd0.__userFolderId=lj.files[0].id;return gd0.__userFolderId;}
  }
  const cOpts=await parentGd.requestOptions({'Content-Type':'application/json'},'POST');
  cOpts.body=JSON.stringify({name:USERSTATE_FOLDER,mimeType:'application/vnd.google-apps.folder',parents:[parentId]});
  const cr=await fetch('https://www.googleapis.com/drive/v3/files?supportsAllDrives=true',cOpts);
  if(!cr.ok)return null;
  const cj=await cr.json();
  gd0.__userFolderId=cj.id||null;
  return gd0.__userFolderId;
}

async function gdiUserFileId(gd0,folderId,username){
  const q=`'${folderId}' in parents and name = '${username}.json' and trashed = false`;
  const opts=await gd0.requestOptions();
  const r=await fetch('https://www.googleapis.com/drive/v3/files?'+enQuery({includeItemsFromAllDrives:'true',supportsAllDrives:'true',q,fields:'files(id)',pageSize:'1'}),opts);
  if(!r.ok)return null;
  const j=await r.json();
  return (j.files&&j.files[0])?j.files[0].id:null;
}

// ═══ v1.0.116 USER COURSES — cursos adicionados pelo aluno, persistidos no Drive ═══
// ★ v1.0.116: Cada usuário tem seu próprio arquivo de cursos no Drive, em
// AULAS - ESTADO DOS ALUNOS/<username>.courses.json. Isso substitui o modelo antigo
// (general_courses.json compartilhado com users[]/hiddenFor[]) por um modelo
// estritamente per-user: ao logar, busca do Drive; ao adicionar, escreve no Drive;
// ★ v2.15.29-C: CORTE D1 — o Drive já não é lido nem escrito aqui (ver
//   gdiUserCoursesRead/gdiUserCoursesWrite, agora sobre user_courses).
// ao remover, deleta do Drive. O localStorage (gdi-manual-courses-v1) agora é só
// cache write-through — Drive é a source of truth.
//
// Shape do arquivo:
// {
//   v: 1,                                  // versão do schema
//   user: "<username>",                    // dono do arquivo
//   courses: [                             // lista de cursos deste usuário
//     {
//       coursePath: "/3:/Matemágicando",   // path no Drive
//       courseName: "Matemágicando",       // nome de exibição
//       pdfCount: 12,                      // nº de PDFs (materiais)
//       icon: "bi-calculator",             // ícone Bootstrap
//       color: "#ff8b9f",                  // cor do tile
//       addedAt: 1698765432000             // timestamp
//     }
//   ],
//   updatedAt: 1698765432000               // última modificação
// }
async function gdiUserCoursesFileId(gd0,folderId,username){
  const safeName=String(username).replace(/[^a-zA-Z0-9._@-]/g,'_')+'.courses.json';
  const q=`'${folderId}' in parents and name = '${driveEscape(safeName)}' and trashed = false`;
  const opts=await gd0.requestOptions();
  const r=await fetch('https://www.googleapis.com/drive/v3/files?'+enQuery({includeItemsFromAllDrives:'true',supportsAllDrives:'true',q,fields:'files(id)',pageSize:'1'}),opts);
  if(!r.ok)return null;
  const j=await r.json();
  return (j.files&&j.files[0])?j.files[0].id:null;
}

// ★ v2.15.29-C: CORTE D1 — os cursos do usuário vivem SÓ em user_courses.
//   A assinatura é mantida p/ os chamadores (add/remove/list, backfill do
//   scanner) — gd0/folderId são ignorados. Sem linha no D1 = lista vazia
//   (log). O ficheiro <username>.courses.json no Drive NUNCA é apagado
//   (fica como arquivo legado; a migração é da frente B).
async function gdiUserCoursesRead(gd0,folderId,username){
  const d1=meggyD1Binding();
  if(!d1){ console.warn('[v2.15.29-C] gdiUserCoursesRead sem D1 p/ '+username); return {v:1,user:username,courses:[],updatedAt:0}; }
  try{
    await d1EnsureSchema();
    const r=await d1.prepare('SELECT course_path, course_name, pdf_count, icon, color, added_at FROM user_courses WHERE username = ? ORDER BY added_at DESC').bind(username).all();
    let _ucr=r.results||[];
    try{ if(typeof fbMergeTableRows==='function') _ucr=await fbMergeTableRows('user_courses',_ucr,{rowDefaults:{username:username},insertFilter:function(r){return r.username===username;}}); }catch(_){}
    const courses=_ucr.map(function(x){ return {coursePath:x.course_path,courseName:x.course_name||'',pdfCount:x.pdf_count||0,icon:x.icon||'',color:x.color||'',addedAt:x.added_at||0}; });
    return {v:1,user:username,courses:courses,updatedAt:courses.reduce(function(m,c){ return Math.max(m,c.addedAt||0); },0)};
  }catch(e){ console.warn('[v2.15.29-C] gdiUserCoursesRead falhou p/ '+username+':',e.message);
    // ★ v2.15.61 (Fase 1.3): a rede que faltava — snapshot de
    //   user_courses (loadTableSnapshot já mergeia o journal).
    try{ const _snap = await loadTableSnapshot('user_courses'); if (_snap){ const _mine = _snap.filter(function(x){ return x.username === username; }).sort(function(a, b){ return (b.added_at || 0) - (a.added_at || 0); }); const _courses = _mine.map(function(x){ return { coursePath: x.course_path, courseName: x.course_name || '', pdfCount: x.pdf_count || 0, icon: x.icon || '', color: x.color || '', addedAt: x.added_at || 0 }; }); return { v: 1, user: username, courses: _courses, updatedAt: _courses.reduce(function(m, c){ return Math.max(m, c.addedAt || 0); }, 0), fallback: true }; } }catch(_){}
    return {v:1,user:username,courses:[],updatedAt:0}; }
}



// ★ v2.15.29-fusion: leitor Drive ORIGINAL de <username>.courses.json,
// preservado só para o endpoint de migração da frente B
// (/admin?api=migrate-drive-to-d1), que tem o Drive como FONTE. Os locais
// normais usam o shim D1 gdiUserCoursesRead (frente C, E1). Corpo
// byte-idêntico ao da base (deploy-staging-c/worker.js L961-973).
async function gdiUserCoursesReadDrive(gd0,folderId,username){
  const fileId=await gdiUserCoursesFileId(gd0,folderId,username);
  if(!fileId)return {v:1,user:username,courses:[],updatedAt:0};
  const opts=await gd0.requestOptions();
  const r=await fetch(`https://www.googleapis.com/drive/v3/files/${fileId}?alt=media&supportsAllDrives=true`,opts);
  if(!r.ok)return {v:1,user:username,courses:[],updatedAt:0};
  try{
    const j=JSON.parse(await r.text());
    if(!j||!Array.isArray(j.courses))return {v:1,user:username,courses:[],updatedAt:0};
    return j;
  }catch(_){return {v:1,user:username,courses:[],updatedAt:0};}
}

async function gdiUserCoursesWrite(gd0,folderId,username,data){
  // ★ v2.15.29-C: CORTE D1 — reescrita total da lista no D1 (DELETE +
  //   INSERT em lotes de 8 p/ d1.batch()). Sem escrita no Drive. Mantida
  //   p/ compatibilidade de chamada; add/remove usam upsert/delete de 1
  //   linha. Cap 500 p/ não estourar o teto de subrequests por chamada.
  const d1=meggyD1Binding();
  if(!d1){ console.warn('[v2.15.29-C] gdiUserCoursesWrite sem D1 p/ '+username); return false; }
  try{
    await d1EnsureSchema();
    const courses=Array.isArray(data&&data.courses)?data.courses.slice(0,500):[];
    if(data&&Array.isArray(data.courses)&&data.courses.length>500) console.warn('[v2.15.29-C] gdiUserCoursesWrite truncado a 500 cursos p/ '+username);
    const stmts=[d1.prepare('DELETE FROM user_courses WHERE username = ?').bind(username)];
    for(const c of courses){
      if(!c||!c.coursePath) continue;
      stmts.push(d1.prepare('INSERT OR REPLACE INTO user_courses (username, course_path, course_name, pdf_count, icon, color, added_at) VALUES (?,?,?,?,?,?,?)').bind(username,String(c.coursePath),String(c.courseName||'').slice(0,200),parseInt(c.pdfCount||'0',10)||0,String(c.icon||'').slice(0,60),String(c.color||'').slice(0,30),Number(c.addedAt)||Date.now()));
    }
    for(let i=0;i<stmts.length;i+=8){ await d1.batch(stmts.slice(i,i+8)); }
    return true;
  }catch(e){ console.warn('[v2.15.29-C] gdiUserCoursesWrite falhou p/ '+username+':',e.message); return false; }
}


// ═══ v2.15.29-C: USERSTATE NO D1 ═══
// O blob /userstate decompõe-se assim (mesma forma que o front lê/escreve):
//   watched {path:{at}}            → user_watched (watched_at)
//   resume  {path:{t,d,at}}        → user_watched.last_position (+watched_at)
//   history [{path,at,minutes}]    → user_history_events (INSERT OR IGNORE)
//   notes/srs/last/outras chaves   → user_state_kv (merge 1 nível p/
//                                    objetos, como o merge antigo do Drive)
//   concursos[]                    → NUNCA escrito aqui (vive na tabela D1
//                                    concursos; no GET é composto dessa tabela)
// Sem fallback p/ o Drive: sem linha no D1 = vazio (log). O ficheiro
// <username>.json no Drive fica intocado — a migração (frente B) continua
// a lê-lo via gdiReadUserState, que NÃO foi alterado.
// ★ v2.15.69: chave interna em user_state_kv com o mapa de valores
//   ESCALARES do /userstate (forma do Roku: watched[path]=true,
//   resume[path]=<segundos>). A produção guarda o blob verbatim e
//   os escalares fazem round-trip; aqui a decomposição p/ o D1
//   regista a FORMA neste mapa e a recomposição devolve-os
//   verbatim (ver userStateSaveApplyD1/userStateComposeD1).
//   Nunca vaza p/ o blob servido.
const USERSTATE_SCALAR_KEY = 'scalar-state';
// ★ v2.15.76: resume pendente no journal (ops userstate) por aluno —
//   a leitura de progresso funde D1 + journal (regra do Elton
//   2026-11-23 15:09: Drive, D1 ou cache, o que estiver disponível).
async function fbJournalResumeByUser21576(user){
  const out = {};
  try {
    const ops = (await fbJournalLoadOps()).filter(function(o){ return o.table === 'userstate' && o.key && o.key.username === user; });
    for (const op of ops) {
      const rIn = (op.row && op.row.blob && op.row.blob.resume && typeof op.row.blob.resume === 'object') ? op.row.blob.resume : {};
      for (const p of Object.keys(rIn)) {
        const v = rIn[p];
        const t = (typeof v === 'number') ? v : (v && typeof v.t === 'number' ? v.t : null);
        if (t !== null && t > 0) out[p] = t;
      }
    }
  } catch (_) {}
  return out;
}
async function fbMergeProgressRows21576(user, coursePath, rows){
  const jr = await fbJournalResumeByUser21576(user);
  const keys = Object.keys(jr);
  if (!keys.length) return rows;
  const prefix = String(coursePath).replace(/\/+$/, '') + '/';
  const byPath = {};
  for (const r of rows) byPath[r.lesson_path] = r;
  for (const p of keys) {
    if (p !== coursePath && p.indexOf(prefix) !== 0) continue;
    if (byPath[p]) byPath[p].last_position = jr[p];
    else { const nr = { lesson_path: p, last_position: jr[p] }; rows.push(nr); byPath[p] = nr; }
  }
  return rows;
}
// ★ v2.15.76: uma chave watched/resume/history que é um URL absoluto
//   SEM caminho de drive (':/') nunca é uma aula — é o URL de
//   reprodução (forma GDIndex 'https://<host>/download.aspx', query
//   já removida pelo cliente) gravado como chave. Linhas reais assim
//   existem em user_watched e a derivação de "Matérias" (split '/'
//   [2]) transformava o HOST em "curso" fantasma. Usado p/ blindar a
//   gravação (userStateSaveApplyD1) e a leitura dos contadores
//   (analytics/coach) — sem apagar dados existentes.
function userStateIsUrlKey21576(p){
  if(typeof p!=='string'||!/^https?:\/\//i.test(p)) return false;
  const rest=p.replace(/^https?:\/\//i,'');
  const slash=rest.indexOf('/');
  const pathPart=slash>=0?rest.slice(slash):'';
  return pathPart.indexOf(':/')===-1;
}
async function userStateKvGet(d1,username,key){
  // ★ v2.15.41: read-your-writes — uma op pendente do journal p/ esta
  //   (username, key) vence o D1 se for mais nova (ou se o D1 falhar).
  let _je;
  try{ if(typeof fbJournalKvEntry==='function') _je=await fbJournalKvEntry(username,key); }catch(_){ _je=undefined; }
  try{
    const r=await d1.prepare('SELECT value, updated_at FROM user_state_kv WHERE username = ? AND key = ?').bind(username,key).first(); // ★ v2.15.43 (CF-8): 1 SELECT em vez de 2 à mesma linha
    if(_je){
      const _uat=(r&&typeof r.updated_at==='number')?r.updated_at:0;
      if(!r||_je.ts>=_uat) return _je.deleted?null:_je.value;
    }
    if(!r||r.value==null) return null;
    try{ return JSON.parse(r.value); }catch(_){ return null; }
  }catch(_){ if(_je) return _je.deleted?null:_je.value; return null; }
}
async function userStateKvPut(d1,username,key,value){
  await d1.prepare('INSERT OR REPLACE INTO user_state_kv (username, key, value, updated_at) VALUES (?,?,?,?)').bind(username,key,JSON.stringify(value==null?null:value),Date.now()).run();
}
async function userStateComposeD1(d1,username){
  await d1EnsureSchema();
  let watchedRows=[],eventRows=[],kvRows=[],concRows=[];
  try{ const r=await d1.prepare('SELECT lesson_path, lesson_name, course_path, watched_at, last_position FROM user_watched WHERE username = ? ORDER BY watched_at DESC LIMIT 2000').bind(username).all(); watchedRows=r.results||[]; }catch(e){ console.warn('[v2.15.29-C] userstate watched falhou:',e.message); }
  try{ const r=await d1.prepare('SELECT lesson_path, lesson_name, course_path, event_at, minutes FROM user_history_events WHERE username = ? ORDER BY event_at DESC LIMIT 500').bind(username).all(); eventRows=r.results||[]; }catch(e){ console.warn('[v2.15.29-C] userstate history falhou:',e.message); }
  try{ const r=await d1.prepare('SELECT key, value FROM user_state_kv WHERE username = ?').bind(username).all(); kvRows=r.results||[]; }catch(e){ console.warn('[v2.15.29-C] userstate kv falhou:',e.message); }
  try{ const r=await d1.prepare('SELECT id, name, banca, exam_date, daily_hours, status FROM concursos WHERE username = ? ORDER BY created_at DESC').bind(username).all(); concRows=r.results||[]; }catch(e){ console.warn('[v2.15.29-C] userstate concursos falhou:',e.message); }
  try{ if(typeof fbMergeTableRows==='function'){ const _md={username:username}; const _flt=function(r){return r.username===username;}; watchedRows=await fbMergeTableRows('user_watched',watchedRows,{rowDefaults:_md,insertFilter:_flt}); eventRows=await fbMergeTableRows('user_history_events',eventRows,{rowDefaults:_md,insertFilter:_flt}); kvRows=await fbMergeTableRows('user_state_kv',kvRows,{rowDefaults:_md,insertFilter:_flt}); concRows=await fbMergeTableRows('concursos',concRows,{rowDefaults:_md,insertFilter:_flt}); } }catch(_){}
  const kv={};
  for(const row of kvRows){ try{ kv[row.key]=JSON.parse(row.value); }catch(_){} }
  // ★ v2.15.69: mapa de escalares (forma Roku) guardado por
  //   userStateSaveApplyD1 — aplicado por cima da forma web no
  //   fim da composição (verbatim, como a produção).
  const scalarMap=(kv[USERSTATE_SCALAR_KEY]&&typeof kv[USERSTATE_SCALAR_KEY]==='object'&&!Array.isArray(kv[USERSTATE_SCALAR_KEY]))?kv[USERSTATE_SCALAR_KEY]:null;
  const watched={},resume={};
  for(const w of watchedRows){
    if(!w.lesson_path) continue;
    watched[w.lesson_path]={at:w.watched_at||0};
    if(typeof w.last_position==='number'&&w.last_position>0) resume[w.lesson_path]={t:w.last_position,at:w.watched_at||0};
  }
  const history=[];
  for(const ev of eventRows){
    if(!ev.lesson_path) continue;
    const h={path:ev.lesson_path,at:ev.event_at,minutes:ev.minutes||0};
    if(ev.lesson_name) h.name=ev.lesson_name;
    if(ev.course_path) h.course_path=ev.course_path;
    history.push(h);
  }
  const blob={watched:watched,resume:resume,history:history};
  if(kv.notes!==undefined) blob.notes=kv.notes;
  if(kv.srs!==undefined) blob.srs=kv.srs;
  if(kv.last!==undefined) blob.last=kv.last;
  for(const k in kv){
    if(k==='notes'||k==='srs'||k==='last'||k==='study-plan'||k===USERSTATE_SCALAR_KEY||k.indexOf('course-progress:')===0||k.indexOf('course-meta:')===0) continue;
    blob[k]=kv[k];
  }
  if(concRows.length) blob.concursos=concRows.map(function(c){ return {id:c.id,name:c.name,banca:c.banca||'',examDate:c.exam_date||'',dailyHours:c.daily_hours||0,status:c.status||'active'}; });
  // ★ v2.15.69: escalares verbatim por cima da forma decomposta —
  //   quem gravou escalar (Roku) lê escalar; a forma web dos
  //   outros paths fica intacta. Os dois formatos convivem no
  //   mesmo blob, como no blob verbatim da produção. (blob
  //   referencia os mesmos objectos watched/resume — a mutação
  //   aqui reflecte-se no blob devolvido.)
  if(scalarMap){
    if(scalarMap.watched&&typeof scalarMap.watched==='object') for(const p in scalarMap.watched){ if(typeof scalarMap.watched[p]==='boolean') watched[p]=scalarMap.watched[p]; }
    if(scalarMap.resume&&typeof scalarMap.resume==='object') for(const p in scalarMap.resume){ if(typeof scalarMap.resume[p]==='number'&&Number.isFinite(scalarMap.resume[p])) resume[p]=scalarMap.resume[p]; }
  }
  let visibleKv=0;
  for(const k in kv){ if(k==='study-plan'||k===USERSTATE_SCALAR_KEY||k.indexOf('course-progress:')===0||k.indexOf('course-meta:')===0) continue; visibleKv++; }
  const empty=!Object.keys(watched).length&&!Object.keys(resume).length&&!history.length&&!visibleKv&&!concRows.length;
  if(empty){ console.log('[v2.15.29-C] userstate vazio no D1 p/ '+username); return null; }
  return blob;
}
// ★ v2.15.29-C: compõe o MESMO blob do /userstate a partir do D1 — usado
//   por handleAnalyticsSummary e handleAiCoach. NÃO confundir com
//   gdiReadUserState (Drive, usado pela migração da frente B — intocado).
async function gdiReadUserStateD1(username){
  const d1=meggyD1Binding();
  if(!d1){ console.warn('[v2.15.29-C] gdiReadUserStateD1 sem D1 p/ '+username); return null; }
  try{ const _b=await userStateComposeD1(d1,username); if(_b) return _b; }
  catch(e){ console.warn('[v2.15.29-C] gdiReadUserStateD1 falhou:',e.message); }
  if(await d1ReadProbeFails(d1)){ const _s=await userStateComposeSnapshot(username); if(_s) return _s; }
  return null;
}

async function handleUserStateGet(request){
  const cors={'Content-Type':'application/json;charset=UTF-8','Access-Control-Allow-Origin':'*'};
  const user=await gdiSessionUser(request);
  if(!user)return new Response('{}',{status:401,headers:cors});
  const d1=meggyD1Binding();
  if(!d1){ console.warn('[v2.15.29-C] userstate get sem D1 p/ '+user); return new Response('{}',{status:502,headers:cors}); }
  let blob=null;
  try{ blob=await userStateComposeD1(d1,user); }catch(_){ blob=null; }
  if(!blob && await d1ReadProbeFails(d1)){ blob=await userStateComposeSnapshot(user); }
  try{ if(typeof fbMergeUserStateBlob==='function') blob=await fbMergeUserStateBlob(user,blob); }catch(_){}
  if(!blob)return new Response('{}',{status:404,headers:cors});
  return new Response(JSON.stringify(blob),{headers:{...cors,'Cache-Control':'no-store'}});
}


async function handleUserStateSave(request){
  const cors={'Content-Type':'application/json;charset=UTF-8','Access-Control-Allow-Origin':'*'};
  const user=await gdiSessionUser(request);
  if(!user)return new Response(JSON.stringify({ok:false,error:'auth'}),{status:401,headers:cors});
  // ★ v80-FIX-WORKER BUG 9: rejecting oversized payloads avoids splitting UTF-16 surrogate pairs (caused JSON.parse failures on reload).
  const body=await request.text();
  if(body.length>512*1024) return new Response(JSON.stringify({ok:false,error:'payload too large'}),{status:413,headers:cors});
  let incoming;
  try{ incoming=JSON.parse(body); }catch(_){ return new Response(JSON.stringify({ok:false,error:'invalid json'}),{status:400,headers:cors}); }
  if(!incoming||typeof incoming!=='object'||Array.isArray(incoming)) return new Response(JSON.stringify({ok:false,error:'invalid json'}),{status:400,headers:cors});
  const d1=meggyD1Binding();
  if(!d1){ console.warn('[v2.15.29-C] userstate save sem D1 p/ '+user); try{ if(typeof fbJournalUserStateBlob==='function' && await fbJournalUserStateBlob(user,incoming)) return new Response(JSON.stringify({ok:true,fallback:true}),{status:200,headers:cors}); }catch(_){} return new Response(JSON.stringify({ok:false,error:'no d1'}),{status:502,headers:cors}); }
  try{
    await userStateSaveApplyD1(d1,user,incoming);
    // ★ v2.15.94: dual-write literal SÓ dos eventos watched (decisão
    //   do Elton 2026-11-25; desenho PROGRESSO_AULAS §3.3.1): com o
    //   D1 gravado, as linhas watched espelham-se no journal do
    //   Drive. Best-effort total — falha do espelho NUNCA falha o
    //   save. O resume NÃO é espelhado (fica D1-primeiro + journal
    //   em falha, como sempre). O replay do journal não passa por
    //   aqui (fbExecOp chama userStateSaveApplyD1 directo): sem
    //   ciclos de re-journal.
    try{ await userStateMirrorWatched94(d1,user,incoming); }catch(_){}
    return new Response(JSON.stringify({ok:true}),{status:200,headers:cors});
  }catch(e){ try{ if(typeof fbJournalUserStateBlob==='function' && await fbJournalUserStateBlob(user,incoming)) return new Response(JSON.stringify({ok:true,fallback:true}),{status:200,headers:cors}); }catch(_){} console.warn('[v2.15.29-C] userstate save falhou:',e.message); return new Response(JSON.stringify({ok:false,error:'save failed'}),{status:502,headers:cors}); }
}

// ★ v2.15.94: espelho dos watched do /userstate/save no journal
//   do Drive. Lê as linhas ACABADAS de gravar no D1 (valores
//   exactos já fundidos: watched_at/last_position) e anexa-as via
//   fbJournalUserProgressSave em modo watchedOnly — na hidratação
//   o replay é idempotente (linha igual = salta; nunca regride a
//   posição). Sem watched no save, tráfego zero.
async function userStateMirrorWatched94(d1,user,incoming){
  const watchedIn=(incoming&&incoming.watched&&typeof incoming.watched==='object')?incoming.watched:{};
  const paths=Object.keys(watchedIn).slice(0,240);
  if(!paths.length) return false;
  const rows=[];
  for(let i=0;i<paths.length;i+=50){
    const chunk=paths.slice(i,i+50);
    const r=await d1.prepare('SELECT lesson_path, course_path, watched_at, last_position FROM user_watched WHERE username = ? AND lesson_path IN ('+chunk.map(function(){return '?';}).join(',')+')').bind(user,...chunk).all();
    for(const row of (r.results||[])) rows.push(row);
  }
  if(!rows.length) return false;
  const byCourse={};
  for(const row of rows){ const cp=row.course_path||''; (byCourse[cp]=byCourse[cp]||[]).push({ path: row.lesson_path, watched: true, lastPosition: (typeof row.last_position==='number'?row.last_position:undefined), watchedAt: (typeof row.watched_at==='number'?row.watched_at:undefined) }); }
  let ok=false;
  for(const cp in byCourse){ if(await fbJournalUserProgressSave(user,cp,courseHashFromPath(cp),null,byCourse[cp],{watchedOnly:true,source:'userstate'})) ok=true; }
  return ok;
}

// ★ v2.15.41: decomposição do save do /userstate extraída de
//   handleUserStateSave (corpo idêntico) p/ o executor de replay
//   aplicar ops 'userstate' do journal com a MESMA semântica.
async function userStateSaveApplyD1(d1,user,incoming){
    await d1EnsureSchema();
    const now=Date.now();
    const courses=await historyUserCourses(d1,user);
    // 1) watched + resume → user_watched (merge c/ o existente: o at é o
    //    maior; last_position só é substituído quando o resume traz t>0).
    //    Cap 240 p/ não estourar o teto de subrequests (o front envia deltas).
    const watchedIn=(incoming.watched&&typeof incoming.watched==='object')?incoming.watched:{};
    const resumeIn=(incoming.resume&&typeof incoming.resume==='object')?incoming.resume:{};
    const paths=[].concat(Object.keys(watchedIn),Object.keys(resumeIn).filter(function(k){ return !(k in watchedIn); })).filter(function(p){ return (p in resumeIn) || !userStateIsUrlKey21576(p); }).slice(0,240);  // ★ v2.15.76: chave-URL de WATCHED (download.aspx) não vira "aula"; chave de RESUME passa — é a única persistência de posição p/ aulas servidas por esse endpoint (a leitura dos contadores é blindada à parte)
    if(Object.keys(watchedIn).length+Object.keys(resumeIn).length>240) console.warn('[v2.15.29-C] userstate save truncado a 240 paths p/ '+user);
    // ★ v2.15.69: valores ESCALARES (forma do Roku: watched=true,
    //   resume=<segundos>) — a decomposição antiga assumia só a
    //   forma web ({at}/{t,at}) e o resume escalar perdia-se em
    //   silêncio (last_position nunca era gravado). Os escalares
    //   decompõem-se na mesma (marca/posição visíveis p/ a web) e
    //   a FORMA fica registada no mapa 'scalar-state'
    //   (user_state_kv) p/ a recomposição os devolver verbatim,
    //   como a produção (blob verbatim). Último escritor vence na
    //   forma: valor-objecto apaga a entrada escalar do path.
    let scalarMap=null, scalarDirty=false;
    async function scalarMapLoad(){
      if(scalarMap) return scalarMap;
      try{ const _sm=await userStateKvGet(d1,user,USERSTATE_SCALAR_KEY); scalarMap=(_sm&&typeof _sm==='object'&&!Array.isArray(_sm))?_sm:{}; }catch(_){ scalarMap={}; }
      if(!scalarMap.watched||typeof scalarMap.watched!=='object'||Array.isArray(scalarMap.watched)) scalarMap.watched={};
      if(!scalarMap.resume||typeof scalarMap.resume!=='object'||Array.isArray(scalarMap.resume)) scalarMap.resume={};
      return scalarMap;
    }
    if(paths.length){
      const existing=new Map();
      try{ const r=await d1.prepare('SELECT lesson_path, watched_at, last_position FROM user_watched WHERE username = ?').bind(user).all(); for(const row of (r.results||[])) existing.set(row.lesson_path,row); }catch(_){}
      const stmts=[];
      for(const p of paths){
        if(!p||p.length>2000) continue;
        const wRaw=(p in watchedIn)?watchedIn[p]:null, rRaw=(p in resumeIn)?resumeIn[p]:null;
        const w=(wRaw&&typeof wRaw==='object')?wRaw:null, r=(rRaw&&typeof rRaw==='object')?rRaw:null;
        const prev=existing.get(p)||null;
        const at=Math.max(historyNormAt(w&&w.at)||0, historyNormAt(r&&r.at)||0, (prev&&prev.watched_at)||0);
        let lp=(prev&&typeof prev.last_position==='number')?prev.last_position:null;
        if(r&&typeof r.t==='number'&&r.t>0) lp=r.t;
        if(typeof rRaw==='number'&&Number.isFinite(rRaw)) lp=rRaw;
        stmts.push(d1.prepare('INSERT OR REPLACE INTO user_watched (username, lesson_path, lesson_name, course_path, watched_at, last_position, source, updated_at) VALUES (?,?,?,?,?,?,?,?)').bind(user,p,historyLessonName(p),historyCourseForPath(p,courses),at||now,lp,'userstate',now));
        if(wRaw!==null&&wRaw!==undefined){
          const sm=await scalarMapLoad();
          if(typeof wRaw==='boolean'){ if(sm.watched[p]!==wRaw){ sm.watched[p]=wRaw; scalarDirty=true; } }
          else if(p in sm.watched){ delete sm.watched[p]; scalarDirty=true; }
        }
        if(rRaw!==null&&rRaw!==undefined){
          const sm=await scalarMapLoad();
          if(typeof rRaw==='number'&&Number.isFinite(rRaw)){ if(sm.resume[p]!==rRaw){ sm.resume[p]=rRaw; scalarDirty=true; } }
          else if(p in sm.resume){ delete sm.resume[p]; scalarDirty=true; }
        }
      }
      for(let i=0;i<stmts.length;i+=8){ await d1.batch(stmts.slice(i,i+8)); }
      if(scalarDirty&&scalarMap){ try{ await userStateKvPut(d1,user,USERSTATE_SCALAR_KEY,scalarMap); }catch(_){} }
    }
    // 2) history → INSERT OR IGNORE (append). DIVERGÊNCIA DOCUMENTADA: o
    //    merge antigo do Drive SUBSTITUÍA o array — se o front enviasse só
    //    o delta, o histórico inteiro sumia. Append preserva; o front não
    //    depende do replace (nunca apaga eventos).
    const histIn=Array.isArray(incoming.history)?incoming.history.slice(0,240):[];
    if(Array.isArray(incoming.history)&&incoming.history.length>240) console.warn('[v2.15.29-C] userstate history truncado a 240 eventos p/ '+user);
    if(histIn.length){
      const stmts=[];
      for(const ev of histIn){
        if(!ev||!ev.path||userStateIsUrlKey21576(ev.path)) continue;  // ★ v2.15.76: idem p/ eventos
        stmts.push(d1.prepare('INSERT OR IGNORE INTO user_history_events (username, lesson_path, lesson_name, course_path, event_at, minutes, source, created_at) VALUES (?,?,?,?,?,?,?,?)').bind(user,ev.path,ev.name||historyLessonName(ev.path),ev.course_path||historyCourseForPath(ev.path,courses),historyNormAt(ev.at)||now,Number(ev.minutes||ev.duration||0)||0,'userstate',now));
      }
      for(let i=0;i<stmts.length;i+=8){ await d1.batch(stmts.slice(i,i+8)); }
    }
    // 3) restantes chaves → user_state_kv (merge 1 nível p/ objetos, como
    //    o merge antigo do Drive; arrays substituem). concursos[] NUNCA é
    //    escrito aqui (regra v1.0.195 — vive na tabela D1 concursos).
    for(const key in incoming){
      if(key==='watched'||key==='resume'||key==='history'||key==='concursos') continue;
      const val=incoming[key];
      if(val===undefined) continue;
      let merged=val;
      if(val!==null&&typeof val==='object'&&!Array.isArray(val)){
        try{ const prev=await userStateKvGet(d1,user,key); if(prev&&typeof prev==='object'&&!Array.isArray(prev)) merged=Object.assign({},prev,val); }catch(_){}
      }
      await userStateKvPut(d1,user,key,merged);
    }
}


// ═══ fim USER STATE ═══

// ═══ ISA CACHE — resumos/questões gerados pela IA, salvos no Drive ═══
// Arquivo compartilhado isa_cache.json na pasta oculta de estado.
// Key = path da aula. Evita regenerar resumo/questões a cada visita.
const ISA_CACHE_FILE = 'isa_cache.json';

async function gdiIsaCacheFileId(gd0, folderId){
  // ★ FASE 0 bug #3: memoize fileId no gd0 (economiza 1 roundtrip Drive por cacheGet).
  // Antes, cada cacheGet/cacheSave re-listava o Drive para achar o isa_cache.json.
  // Agora, primeira chamada lista e guarda em gd0.__isaCacheFileId; próximas usam o cache.
  // Se o arquivo for deletado/renomeado no Drive, o cache fica stale — mas como o arquivo
  // é interno (nunca deletado por users), isso é seguro. TTL implícito: vida do isolate.
  if(gd0.__isaCacheFileId !== undefined) return gd0.__isaCacheFileId;
  const q=`'${folderId}' in parents and name = '${ISA_CACHE_FILE}' and trashed = false`;
  const opts=await gd0.requestOptions();
  const r=await fetch('https://www.googleapis.com/drive/v3/files?'+enQuery({includeItemsFromAllDrives:'true',supportsAllDrives:'true',q,fields:'files(id)',pageSize:'1'}),opts);
  if(!r.ok){ gd0.__isaCacheFileId = null; return null; }
  const j=await r.json();
  const fid = (j.files&&j.files[0])?j.files[0].id:null;
  gd0.__isaCacheFileId = fid;  // cache (inclui null — evita re-listar se arquivo não existe)
  return fid;
}

async function gdiIsaCacheRead(gd0, folderId){
  const fileId=await gdiIsaCacheFileId(gd0, folderId);
  if(!fileId)return {};
  const opts=await gd0.requestOptions();
  const r=await fetch(`https://www.googleapis.com/drive/v3/files/${fileId}?alt=media&supportsAllDrives=true`,opts);
  if(!r.ok)return {};
  try{return JSON.parse(await r.text())||{};}catch(_){return {};}
}

async function gdiIsaCacheWrite(gd0, folderId, data){
  const body=JSON.stringify(data);
  const existingId=await gdiIsaCacheFileId(gd0, folderId);
  if(existingId){
    const opts=await gd0.requestOptions({'Content-Type':'application/json; charset=UTF-8'},'PATCH');
    const r=await fetch(`https://www.googleapis.com/upload/drive/v3/files/${existingId}?uploadType=media&supportsAllDrives=true`,{method:'PATCH',headers:opts.headers,body});
    return r.ok;
  }
  const boundary='gdiisa'+Date.now();
  const mp=`--${boundary}\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n${JSON.stringify({name:ISA_CACHE_FILE,parents:[folderId]})}\r\n--${boundary}\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n${body}\r\n--${boundary}--`;
  const opts=await gd0.requestOptions({'Content-Type':'multipart/related; boundary='+boundary},'POST');
  const r=await fetch('https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&supportsAllDrives=true',{method:'POST',headers:opts.headers,body:mp});
  return r.ok;
}

// ★ FASE 1 (KV migration): try KV first, fall back to Drive cache.
// Cache backend selection via env var (default "both" during dual-write period):
//   "drive" → Drive only (legacy)
//   "both"  → KV read first, Drive fallback (dual-write period)
//   "kv"    → KV only (after Drive decommissioned)
function meggyCacheBackend(){
  // vars from wrangler.toml [vars] are exposed on globalThis in CF Workers
  return (typeof globalThis.CACHE_BACKEND === 'string' && globalThis.CACHE_BACKEND) || 'both';
}
function meggyKvBinding(){
  // KV namespace bindings are exposed on globalThis by the runtime
  return (typeof globalThis.MEGGY_CACHE !== 'undefined') ? globalThis.MEGGY_CACHE : null;
}

// ★ FASE 3a: D1 metadata layer — read-only mirror for structured queries
function meggyD1Backend(){
  return (typeof globalThis.D1_BACKEND === 'string' && globalThis.D1_BACKEND) || 'off';
}
function meggyD1Binding(){
  return (typeof globalThis.MEGGY_D1 !== 'undefined') ? globalThis.MEGGY_D1 : null;
}

// ═══ SEED DE DRIVES DO ADMIN (tabela admin_drives) ═══
// Drives de DEMONSTRAÇÃO (IDs fictícios — não são IDs reais do Drive).
// O seed só corre quando a tabela admin_drives está vazia (1º arranque).
// Depois disso o admin é dono da tabela (painel /admin → Drives).
// Substitua-os pelos SEUS drives no painel, ou ponha DEMO_SEED=false
// nas vars p/ não semear nada (ver docs/DEPLOY.md).
// Formato: { driveId: 'DRIVE_EXEMPLO_01', name: 'Pasta de Exemplo 1',
//            targetApps: ['meggy'], rootIndex: 0 }
const ADMIN_DRIVES_SEED = [
  { driveId: 'DRIVE_EXEMPLO_01', name: 'Pasta de Exemplo 1', targetApps: ['meggy'], rootIndex: 0 },
  { driveId: 'DRIVE_EXEMPLO_02', name: 'Pasta de Exemplo 2', targetApps: ['meggy'], rootIndex: 1 },
];
const ADMIN_DRIVE_TARGETS = ['meggy', 'bibi', 'vovo'];

function adminDrivesParseTargets(raw) {
  const out = [];
  const arr = Array.isArray(raw) ? raw : null;
  if (!arr) return out;
  for (const t of arr) {
    const v = String(t || '').trim().toLowerCase();
    if (ADMIN_DRIVE_TARGETS.indexOf(v) >= 0 && out.indexOf(v) < 0) out.push(v);
  }
  return out;
}

function adminDrivesValidUrl(u) {
  return typeof u === 'string' && u.length > 0 && u.length <= 2000 && /^https?:\/\//i.test(u);
}

// Valida coverUrl/subCoverUrl/subfolderCovers de um body de add/update.
// Devolve a mensagem de erro (pt-BR) ou null. Aceita camelCase e snake_case.
function adminDrivesCheckCovers(body) {
  const cover = (body.coverUrl !== undefined) ? body.coverUrl : body.cover_url;
  if (cover !== undefined && cover !== null && String(cover).trim() !== '' && !adminDrivesValidUrl(String(cover).trim())) return 'coverUrl inválido (use uma URL http(s), ex.: https://drive.google.com/thumbnail?id=...&sz=w1600)';
  const sub = (body.subCoverUrl !== undefined) ? body.subCoverUrl : body.sub_cover_url;
  if (sub !== undefined && sub !== null && String(sub).trim() !== '' && !adminDrivesValidUrl(String(sub).trim())) return 'subCoverUrl inválido (use uma URL http(s))';
  const cov = (body.subfolderCovers !== undefined) ? body.subfolderCovers : body.subfolder_covers;
  if (cov !== undefined && cov !== null) {
    if (typeof cov !== 'object' || Array.isArray(cov)) return 'subfolderCovers inválido (use um objeto {caminho: url})';
    for (const k of Object.keys(cov)) {
      if (String(k).length > 500) return 'subfolderCovers inválido (caminho demasiado longo)';
      const v = String(cov[k] || '').trim();
      if (v !== '' && !adminDrivesValidUrl(v)) return 'subfolderCovers inválido (a capa de "' + String(k).slice(0, 60) + '" não é uma URL http(s))';
    }
  }
  return null;
}

function adminDrivesRowToJson(x) {
  let targets = [];
  try { const t = JSON.parse(x.target_apps || '[]'); if (Array.isArray(t)) targets = adminDrivesParseTargets(t); } catch (_) {}
  let covers = {};
  try { const c = JSON.parse(x.subfolder_covers || '{}'); if (c && typeof c === 'object' && !Array.isArray(c)) covers = c; } catch (_) {}
  return { id: x.id, driveId: x.drive_id, name: x.name, targetApps: targets, coverUrl: x.cover_url || null, subCoverUrl: x.sub_cover_url || null, subfolderCovers: covers, source: x.source || 'admin', rootIndex: (x.root_index === undefined || x.root_index === null) ? null : x.root_index };
}

// Bootstrap de 1º arranque: semeia os drives de demonstração SÓ quando a
// tabela está vazia (ver nota no ADMIN_DRIVES_SEED). Best-effort: nunca
// falha o schema (não toca em `errors`) — um D1 sem a tabela ou com erro
// devolve false e o próximo request tenta outra vez.
async function adminDrivesSeed(d1) {
  try {
    const c = await d1.prepare('SELECT COUNT(*) AS n FROM admin_drives').first();
    if (c && Number(c.n) > 0) return false;
    const now = Date.now();
    const stmts = ADMIN_DRIVES_SEED.map(function (s) {
      return d1.prepare('INSERT OR IGNORE INTO admin_drives (drive_id, name, target_apps, cover_url, sub_cover_url, subfolder_covers, source, root_index, created_by, created_at, updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?)').bind(s.driveId, s.name, JSON.stringify(s.targetApps), null, null, '{}', 'hardcoded', s.rootIndex, 'seed', now, now);
    });
    for (let i = 0; i < stmts.length; i += 8) {
      const chunk = stmts.slice(i, i + 8);
      try { await d1.batch(chunk); }
      catch (_) { for (const s of chunk) { try { await s.run(); } catch (_) {} } }
    }
    return true;
  } catch (e) {
    console.warn('[admin-drives] seed falhou:', (e && e.message) || e);
    return false;
  }
}

// ═══ DADOS DE DEMONSTRAÇÃO (versão pública) ═══
// O worker cria estes dados no 1º arranque, SÓ com as tabelas vazias.
// São dados FICTÍCIOS e PÚBLICOS (ver docs/DEPLOY.md): nenhum nome,
// email ou ID real. A senha do admin de demonstração é "admin" —
// credencial pública, por desenho — e o painel /admin mostra um aviso
// enquanto ela ainda for a senha ativa. Para desligar o seed, ponha
// DEMO_SEED=false nas vars do wrangler.toml.
//   Para apagar os dados de demonstração: crie a sua conta em /signup
//   (aí o seed nunca mais corre) e apague as linhas de demonstração no
//   painel /admin → Usuários / Drives, ou por SQL no D1.
//   Para repor o seed: esvazie as tabelas users/admin_drives e reinicie
//   (o seed corre de novo com as tabelas vazias).
// Os hashes das senhas de demonstração são calculados EM TEMPO DE
// EXECUÇÃO (hashPassword) — nenhuma senha nem hash aparece como literal
// fora das credenciais públicas abaixo (marcadas DEMO).
function demoSeedEnabled() {
  const v = (typeof globalThis.DEMO_SEED !== 'undefined') ? String(globalThis.DEMO_SEED).toLowerCase() : 'true';
  return v !== 'false' && v !== '0' && v !== 'no';
}
// Credenciais de DEMONSTRAÇÃO (públicas, por desenho — trocar no 1º deploy).
const DEMO_USERS = [
  { username: 'admin', password: 'admin', role: 'admin' },
  { username: 'aluno@teste.example.com', password: 'aluno123', role: 'aluno' },
  { username: 'professor@teste.example.com', password: 'professor123', role: 'professor' },
];
async function demoUsersSeed(d1) {
  try {
    const c = await d1.prepare('SELECT COUNT(*) AS n FROM users').first();
    if (c && Number(c.n) > 0) return false;
    const now = Date.now();
    for (const u of DEMO_USERS) {
      const salt = Array.from(crypto.getRandomValues(new Uint8Array(8))).map(b => b.toString(16).padStart(2, '0')).join('');
      const h = await hashPassword(u.password, salt);
      await d1.prepare('INSERT OR IGNORE INTO users (username, salt, password_hash, created) VALUES (?,?,?,?)').bind(u.username, salt, h, now).run();
    }
    // Dados de exemplo do aluno de teste (nunca de pessoa real).
    const aluno = 'aluno@teste.example.com';
    await d1.prepare('INSERT OR IGNORE INTO user_courses (username, course_path, course_name, pdf_count, added_at) VALUES (?,?,?,?,?)').bind(aluno, '/0:/Pasta de Exemplo 1', 'Pasta de Exemplo 1', 0, now).run();
    await d1.prepare('INSERT OR IGNORE INTO user_history_events (username, lesson_path, lesson_name, course_path, event_at, minutes, source, created_at) VALUES (?,?,?,?,?,?,?,?)').bind(aluno, '/0:/Pasta de Exemplo 1/Aula de Exemplo 1', 'Aula de Exemplo 1', '/0:/Pasta de Exemplo 1', now - 3600000, 12, 'drive', now).run();
    await d1.prepare('INSERT OR IGNORE INTO user_state_kv (username, key, value, updated_at) VALUES (?,?,?,?)').bind(aluno, 'progress:/0:/Pasta de Exemplo 1', JSON.stringify({ watched: 1, total: 3, updatedAt: now }), now).run();
    globalThis.__dynUsers = undefined; globalThis.__dynUsersAt = 0;
    return true;
  } catch (e) {
    console.warn('[demo] seed de usuários falhou:', (e && e.message) || e);
    return false;
  }
}
// O admin de demonstração ainda está com a senha pública "admin"?
async function demoAdminStillDefault(d1) {
  try {
    const row = await d1.prepare('SELECT salt, password_hash FROM users WHERE username = ?').bind('admin').first();
    if (!row) return false;
    return (await hashPassword('admin', row.salt || '')) === row.password_hash;
  } catch (_) { return false; }
}
// Banner de aviso no painel /admin enquanto a senha for a de demonstração.
async function demoAdminBannerHtml() {
  try {
    const d1 = meggyD1Binding();
    if (!d1 || !await demoAdminStillDefault(d1)) return '';
    return '<div style="background:#3d2b00;border:1px solid #d29922;color:#ffd479;padding:12px 16px;margin:0;font-size:14px;line-height:1.5">'
      + '<b>⚠️ Senha de demonstração ativa.</b> Você está usando o admin de demonstração (<code>admin</code> / <code>admin</code>), uma credencial pública. '
      + 'Crie a sua conta em <a href="/signup" style="color:#ffd479">/signup</a>, ponha o seu usuário em <code>ADMIN_USERS</code> no wrangler.toml, faça re-deploy e apague o usuário <code>admin</code> em Usuários — <b>antes de expor o site</b>. Ver docs/DEPLOY.md, passo 7.</div>';
  } catch (_) { return ''; }
}

// Schema init — creates tables if not exist. Idempotent. Runs on first D1 request.
// ★ v1.0.169: executar CREATE statements individualmente (não em batch) — d1.batch() com 19 statements falha.
let _d1SchemaReady = false;
// ★ v2.15.59: D1 MORTO POR QUOTA — carimbo de 60 s. Diagnóstico
//   2026-11-21 22:36: com a quota de leitura esgotada (7500), o
//   d1EnsureSchema NUNCA marca ready (erros => return false) e cada
//   pedido autenticado repetia a corrida inteira (25–76 chamadas
//   D1 falhadas, contadas no código) ANTES de o handler tentar a
//   sua query — o fallback do Drive (agregado de itens, provado a
//   responder em ~2–4 s via scan-courses, que NÃO corre o ensure)
//   só era alcançado depois disso, e a vista do banco estourava
//   os 20 s do front ×2 = erro vermelho, mesmo com
//   question-bank-items.json já no Drive. Com o carimbo activo,
//   os chamadores saltam o ensure e as queries condenadas e vão
//   directos ao fallback; sem carimbo, tudo como antes.
let _d1QuotaDeadAt21559 = 0;
function d1QuotaDead21559(){ return !!_d1QuotaDeadAt21559 && (Date.now() - _d1QuotaDeadAt21559) < 60000; }
// ★ v2.15.60: detecção de quota pelo texto REAL do binding D1.
//   Prova ao vivo (print do Elton, 2026-11-21 23:15, geração de
//   plano no meuc): o binding lança 'D1_ERROR: Your account has
//   exceeded D1's free tier daily row read limit. Upgrade to a
//   paid plan or wait until tomorrow (midnight UTC) to continue.'
//   — SEM '7500' em lado nenhum (o 7500 é o código da API REST).
//   A assinatura da .59 começava por 7500 e só lia e.message; a
//   documentação da Cloudflare (Debug D1) avisa que o texto
//   completo pode vir em error.cause.message — a detecção .60
//   lê a cadeia message+cause e casa as formas reais:
//   'exceeded D1's free tier', 'daily row read limit', 'daily
//   row written limit' (e mantém 7500 p/ erros vindos da REST).
function _d1ErrText21560(e){ let s = ''; let cur = e; for(let i = 0; i < 4 && cur; i++){ try{ s += ' ' + String((cur && cur.message) || cur || ''); }catch(_){} cur = cur && cur.cause; } return s; }
function d1QuotaErrorTest21560(e){ return /7500|exceeded|free tier|daily row|rows? (read|written)|row (read|written|write) limit/i.test(_d1ErrText21560(e)); }
function d1StampQuotaDead21559(e){ if(d1QuotaErrorTest21560(e)){ d1StampDead21560(); return true; } return false; }
// ★ v2.15.60: carimbo PARTILHADO entre isolates (Cache API do
//   próprio worker, caches.default — por colo e sem quota de
//   escrita; o KV custaria puts dos 1.000/dia e já teve o seu
//   próprio esgotamento, 10048 em 2026-11-20). A .59 guardava
//   o carimbo numa variável de módulo = memória de UM isolate:
//   com o tráfego de um utilizador, quase todos os pedidos
//   caem num isolate frio com o carimbo a zero — e a tempestade
//   do ensure corria outra vez (H2, provado por construção).
//   Agora quem carimba escreve também na Cache API (TTL 120 s,
//   renovado a cada nova falha) e quem arranca frio lê-a ANTES
//   de tocar no D1. Com D1 saudável o carimbo nunca nasce e é
//   limpo no primeiro sucesso — comportamento idêntico.
const _D1_STAMP_URL21560 = 'https://meggy-internal.invalid/d1-quota-dead-21560';
function _d1CacheDefault21560(){ try{ return (typeof caches !== 'undefined' && caches && caches.default) ? caches.default : null; }catch(_){ return null; } }
function d1StampDead21560(){ _d1QuotaDeadAt21559 = Date.now(); try{ const c = _d1CacheDefault21560(); if(c){ const p = c.put(_D1_STAMP_URL21560, new Response('1', { headers: { 'Cache-Control': 'max-age=120', 'Content-Type': 'text/plain' } })); if(p && p.catch) p.catch(function(){}); } }catch(_){} }
let _d1SharedCheckedAt21560 = 0;
async function d1QuotaDeadShared21560(){ if(d1QuotaDead21559()) return true; const now = Date.now(); if(now - _d1SharedCheckedAt21560 < 5000) return false; _d1SharedCheckedAt21560 = now; try{ const c = _d1CacheDefault21560(); if(!c) return false; const r = await c.match(_D1_STAMP_URL21560); if(r){ _d1QuotaDeadAt21559 = Date.now(); return true; } }catch(_){} return false; }
async function d1ClearDead21560(){ _d1QuotaDeadAt21559 = 0; _d1SharedCheckedAt21560 = 0; try{ const c = _d1CacheDefault21560(); if(c){ const p = c.delete(_D1_STAMP_URL21560); if(p && p.catch) p.catch(function(){}); } }catch(_){} }
async function d1EnsureSchema(force21559){
  if(_d1SchemaReady) return true;
  if(!force21559 && d1QuotaDead21559()) return false;  // ★ v2.15.59: sob quota morta não se repete a corrida — o chamador degrada p/ o fallback
  if(!force21559 && await d1QuotaDeadShared21560()) return false;  // ★ v2.15.60: carimbo PARTILHADO (Cache API) — um isolate frio salta a tempestade sem a correr (a .59 só conhecia o carimbo do próprio isolate)

  const d1 = meggyD1Binding();
  if(!d1) return false;
  const errors = [];
  let _quotaSeen21561 = false;  // ★ v2.15.61 (Fase 4): quota vista pelo teste COMPLETO (forma CAUSE incluída)
  // ★ v2.15.53 (endurecimento H1): a migração .48 de shared_flashcards
  //   (topic/source/qfp + índices) corre AQUI, no INÍCIO — antes dos
  //   ~38 CREATEs. Diagnóstico de 2026-11-21 (provado por API REST):
  //   nos dois D1 as colunas NUNCA aterraram — o bloco vivia perto do
  //   FIM da função e, sob quota, o ensure morria nos CREATEs antes
  //   de o alcançar (erros => nunca ready => cada pedido recomeçava
  //   do topo). No início, os probes+ALTERs são 3-5 pedidos e aterram
  //   mesmo quando o resto degrada. Em D1 novo a tabela ainda não
  //   existe: os probes falham com "no such table" (não dispara
  //   ALTER) e os índices falham nesta passagem — o schema não marca
  //   ready e a passagem seguinte completa (padrão de retry da casa).
  for (const col of ['topic', 'source', 'qfp']){
    try {
      await d1.prepare('SELECT ' + col + ' FROM shared_flashcards LIMIT 0').all();
    } catch (e) {
      if (/no such column/i.test(String(e && e.message || e))) {
        try { await d1.prepare('ALTER TABLE shared_flashcards ADD COLUMN ' + col + ' TEXT').run(); }
        catch (ae) { if (!/duplicate column/i.test(String(ae.message || ae))) errors.push('shared_flashcards ' + col + ': ' + String(ae.message || ae).slice(0, 80)); }
      }
    }
  }
  try { await d1.prepare('CREATE INDEX IF NOT EXISTS idx_sf_subject_topic ON shared_flashcards(subject, topic)').run(); }
  catch (e) { errors.push('idx_sf_subject_topic: ' + String(e.message || e).slice(0, 80)); }
  try { await d1.prepare('CREATE INDEX IF NOT EXISTS idx_sf_subject_qfp ON shared_flashcards(subject, qfp)').run(); }
  catch (e) { errors.push('idx_sf_subject_qfp: ' + String(e.message || e).slice(0, 80)); }
  const statements = [
    `CREATE TABLE IF NOT EXISTS lessons (id TEXT PRIMARY KEY, course_hash TEXT NOT NULL, course_path TEXT NOT NULL, lesson_path TEXT NOT NULL, lesson_name TEXT NOT NULL, lesson_type TEXT, mime_type TEXT, ext TEXT, size INTEGER, drive_index INTEGER NOT NULL DEFAULT 0, parent_folder_path TEXT, has_summary INTEGER DEFAULT 0, has_questions INTEGER DEFAULT 0, has_flashcards INTEGER DEFAULT 0, has_simulado INTEGER DEFAULT 0, has_pilulas INTEGER DEFAULT 0, scanned_at INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL)`,
    `CREATE INDEX IF NOT EXISTS idx_lessons_course_hash ON lessons(course_hash)`,
    `CREATE INDEX IF NOT EXISTS idx_lessons_lesson_name ON lessons(lesson_name)`,
    `CREATE INDEX IF NOT EXISTS idx_lessons_course_path ON lessons(course_path)`,
    `CREATE UNIQUE INDEX IF NOT EXISTS idx_lessons_course_lesson ON lessons(course_path, lesson_path)`,
    `CREATE TABLE IF NOT EXISTS shared_summaries (id INTEGER PRIMARY KEY AUTOINCREMENT, lesson_name TEXT NOT NULL, summary TEXT NOT NULL, questions TEXT, mindmap TEXT, author TEXT NOT NULL, course_path TEXT, date INTEGER NOT NULL, UNIQUE(lesson_name, author))`,
    `CREATE INDEX IF NOT EXISTS idx_ss_lesson_name ON shared_summaries(lesson_name)`,
    `CREATE INDEX IF NOT EXISTS idx_ss_author ON shared_summaries(author)`,
    `CREATE INDEX IF NOT EXISTS idx_ss_date ON shared_summaries(date DESC)`,
    `CREATE TABLE IF NOT EXISTS shared_flashcards (id INTEGER PRIMARY KEY AUTOINCREMENT, subject TEXT NOT NULL, front TEXT, back TEXT, statement TEXT, options TEXT, correct INTEGER DEFAULT 0, explanation TEXT, legal_text TEXT, fundamentacao TEXT, type TEXT DEFAULT 'mc', author TEXT NOT NULL, date INTEGER NOT NULL, topic TEXT, source TEXT, qfp TEXT)`,
    `CREATE INDEX IF NOT EXISTS idx_sf_subject ON shared_flashcards(subject)`,
    `CREATE INDEX IF NOT EXISTS idx_sf_author ON shared_flashcards(author)`,
    `CREATE TABLE IF NOT EXISTS user_courses (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL, course_path TEXT NOT NULL, course_name TEXT, pdf_count INTEGER DEFAULT 0, icon TEXT, color TEXT, added_at INTEGER NOT NULL, UNIQUE(username, course_path))`,
    `CREATE INDEX IF NOT EXISTS idx_uc_username ON user_courses(username)`,
    `CREATE TABLE IF NOT EXISTS materials_meta (id INTEGER PRIMARY KEY AUTOINCREMENT, course_hash TEXT NOT NULL, lesson_path TEXT NOT NULL, material_type TEXT NOT NULL, file TEXT, generated_at INTEGER NOT NULL, generated_by TEXT, UNIQUE(lesson_path, material_type))`,
    `CREATE INDEX IF NOT EXISTS idx_mm_course_hash ON materials_meta(course_hash)`,
    `CREATE INDEX IF NOT EXISTS idx_mm_lesson_path ON materials_meta(lesson_path)`,
    // ★ v1.0.212: MEUS CONCURSOS — 3 tabelas para feature de concursos (port do main; tabelas já existiam na staging)
    `CREATE TABLE IF NOT EXISTS concursos (id TEXT PRIMARY KEY, username TEXT NOT NULL, name TEXT NOT NULL, banca TEXT, exam_date TEXT, daily_hours REAL DEFAULT 3, status TEXT DEFAULT 'active', created_at INTEGER NOT NULL, updated_at INTEGER)`,
    `CREATE INDEX IF NOT EXISTS idx_concursos_username ON concursos(username)`,
    `CREATE TABLE IF NOT EXISTS concurso_disciplinas (id INTEGER PRIMARY KEY AUTOINCREMENT, concurso_id TEXT NOT NULL, nome TEXT NOT NULL, peso INTEGER DEFAULT 0, incidencia TEXT DEFAULT 'media', topicos TEXT)`,
    `CREATE INDEX IF NOT EXISTS idx_cd_concurso_id ON concurso_disciplinas(concurso_id)`,
    `CREATE TABLE IF NOT EXISTS concurso_lessons (id INTEGER PRIMARY KEY AUTOINCREMENT, concurso_id TEXT NOT NULL, lesson_path TEXT NOT NULL, lesson_name TEXT, disciplina TEXT, topico TEXT, matched_by TEXT, confidence REAL DEFAULT 0, is_intensivo INTEGER DEFAULT 0, matched_at INTEGER)`,
    `CREATE INDEX IF NOT EXISTS idx_cl_concurso_id ON concurso_lessons(concurso_id)`,
    `CREATE INDEX IF NOT EXISTS idx_cl_disciplina ON concurso_lessons(disciplina)`,
    // ★ v2.15.0: fontes (pastas) anexadas a um concurso — cada fonte é um módulo
    //   (name = nome personalizado, sort_order = ordem, intensivo, lesson_count
    //   = cache da contagem, disciplinas = JSON das disciplinas DERIVADAS desta
    //   fonte pelo scan — usado na remoção da fonte; sem ALTER TABLE, pois o
    //   schema retorna false se qualquer statement falhar)
    `CREATE TABLE IF NOT EXISTS concurso_sources (id INTEGER PRIMARY KEY AUTOINCREMENT, concurso_id TEXT NOT NULL, course_path TEXT NOT NULL, name TEXT, sort_order INTEGER DEFAULT 0, intensivo INTEGER DEFAULT 0, lesson_count INTEGER DEFAULT 0, disciplinas TEXT, added_at INTEGER NOT NULL, UNIQUE(concurso_id, course_path))`,
    `CREATE INDEX IF NOT EXISTS idx_cs_concurso_id ON concurso_sources(concurso_id)`,
    // ★ v2.15.0 item 8: caderno de erros do quiz por módulo (D1, sincroniza
    //   entre aparelhos — o caderno em localStorage continua existindo no front)
    `CREATE TABLE IF NOT EXISTS concurso_errors (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL, concurso_id TEXT NOT NULL, pergunta TEXT NOT NULL, resposta_certa TEXT, resposta_aluno TEXT, modulo TEXT, created_at INTEGER NOT NULL)`,
    `CREATE INDEX IF NOT EXISTS idx_ce_user_concurso ON concurso_errors(username, concurso_id)`,
    // ★ v2.2: novos alunos no D1 (a lista em código continua como está)
    `CREATE TABLE IF NOT EXISTS users (username TEXT PRIMARY KEY, salt TEXT NOT NULL, password_hash TEXT NOT NULL, created INTEGER)`,
    // ★ v2.2: segredos no D1 (KV é a outra fonte; código continua como fallback)
    `CREATE TABLE IF NOT EXISTS app_secrets (key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at INTEGER NOT NULL)`,
    // ★ v2.15.6: foto de capa dos destaques (cover_url) — D1 novo já nasce
    //   com a coluna; tabelas antigas ganham a coluna na migração guardada abaixo.
    `CREATE TABLE IF NOT EXISTS featured_courses (id INTEGER PRIMARY KEY AUTOINCREMENT, course_path TEXT NOT NULL UNIQUE, course_name TEXT, icon TEXT, color TEXT, cover_url TEXT, sort_order INTEGER DEFAULT 0, created_at INTEGER NOT NULL)`,
    // ★ Ronda 13 Frente A: drives do admin por ID (um registo por drive,
    //   NÃO um por APK). drive_id UNIQUE p/ o upsert do add; target_apps e
    //   subfolder_covers são JSON em TEXT. source='hardcoded' = seed dos 16
    //   drives fixos (ver ADMIN_DRIVES_SEED); 'admin' = criado no /admin ou
    //   no app. root_index = índice canónico 0–15 (só nos sementados).
    `CREATE TABLE IF NOT EXISTS admin_drives (id INTEGER PRIMARY KEY AUTOINCREMENT, drive_id TEXT NOT NULL UNIQUE, name TEXT NOT NULL, target_apps TEXT NOT NULL DEFAULT '["meggy"]', cover_url TEXT, sub_cover_url TEXT, subfolder_covers TEXT NOT NULL DEFAULT '{}', source TEXT NOT NULL DEFAULT 'admin', root_index INTEGER, created_by TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL)`,
    `CREATE INDEX IF NOT EXISTS idx_ad_drive_id ON admin_drives(drive_id)`,
    `CREATE INDEX IF NOT EXISTS idx_ad_root_index ON admin_drives(root_index)`,
    // ★ v2.7: status do scan por curso — done = nunca mais entra na fila do backfill
    // ★ v2.15.6 (scan): diagnóstico de quarentena — last_error (o erro da
    //   última falha) + fail_count (nº de quarentenas). D1 novo já nasce com
    //   as colunas; tabelas antigas ganham via migração guardada abaixo.
    `CREATE TABLE IF NOT EXISTS scan_status (course_path TEXT PRIMARY KEY, status TEXT NOT NULL, lessons INTEGER DEFAULT 0, completed_at INTEGER, updated_at INTEGER NOT NULL, last_error TEXT, fail_count INTEGER DEFAULT 0)`,
    // ★ v2.15.34 (GenQueue): fila de geração de resumos em segundo plano.
    //   lesson_path é PRIMARY KEY (1 job por aula = idempotência do enqueue).
    //   Colunas do brief: lesson_path, priority, status, attempts, last_error,
    //   created_at, updated_at. Extensões documentadas: course_key, video_path,
    //   source, requested_by (origem/auditoria), next_retry_at (backoff),
    //   source_text (texto do cliente p/ PDFs — o worker não extrai PDFs),
    //   result (JSON do resultado: driveSaved, pillsOk, ...).
    `CREATE TABLE IF NOT EXISTS generation_queue (lesson_path TEXT PRIMARY KEY, course_key TEXT, video_path TEXT, source TEXT NOT NULL DEFAULT 'queue', requested_by TEXT, priority INTEGER NOT NULL DEFAULT 4, status TEXT NOT NULL DEFAULT 'queued', attempts INTEGER NOT NULL DEFAULT 0, next_retry_at INTEGER NOT NULL DEFAULT 0, last_error TEXT, source_text TEXT, result TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL)`,
    `CREATE INDEX IF NOT EXISTS idx_gq_status_priority ON generation_queue(status, priority, created_at)`,
    `CREATE INDEX IF NOT EXISTS idx_gq_requested_by ON generation_queue(requested_by)`,
    // ★ v2.8 Fase B: perfis de banca + planos de estudo direcionados
    `CREATE TABLE IF NOT EXISTS banca_profiles (banca TEXT NOT NULL, disciplina TEXT NOT NULL, incidencia TEXT NOT NULL, topicos TEXT NOT NULL, PRIMARY KEY(banca, disciplina))`,
    // ★ v2.15.6: plano da Meggy — origem do plano (meggy-ai | deterministico)
    //   + fonte do edital (url | texto | pdf | nenhum | url-falha) e URL do
    //   edital, p/ a lista mostrar o selo sem parsear o JSON do plano.
    `CREATE TABLE IF NOT EXISTS study_plans (id TEXT PRIMARY KEY, username TEXT NOT NULL, concurso_id TEXT, banca TEXT NOT NULL, name TEXT NOT NULL, exam_date TEXT, daily_hours REAL DEFAULT 2, total_days INTEGER NOT NULL, plan TEXT NOT NULL, origin TEXT DEFAULT 'deterministico', edital_source TEXT, edital_url TEXT, banca_profile TEXT, created_at INTEGER NOT NULL, updated_at INTEGER)`,
    `CREATE INDEX IF NOT EXISTS idx_study_plans_username ON study_plans(username)`,
    `CREATE INDEX IF NOT EXISTS idx_study_plans_concurso ON study_plans(concurso_id)`,
    // ★ v2.11: histórico do aluno (Drive → D1) — 1 linha por aula/evento
    `CREATE TABLE IF NOT EXISTS user_watched (username TEXT NOT NULL, lesson_path TEXT NOT NULL, lesson_name TEXT, course_path TEXT, watched_at INTEGER, last_position REAL, source TEXT DEFAULT 'drive', updated_at INTEGER NOT NULL, PRIMARY KEY(username, lesson_path))`,
    `CREATE INDEX IF NOT EXISTS idx_uw_username ON user_watched(username)`,
    `CREATE INDEX IF NOT EXISTS idx_uw_course ON user_watched(course_path)`,
    `CREATE TABLE IF NOT EXISTS user_history_events (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL, lesson_path TEXT, lesson_name TEXT, course_path TEXT, event_at INTEGER NOT NULL, minutes INTEGER DEFAULT 0, source TEXT DEFAULT 'drive', created_at INTEGER NOT NULL, UNIQUE(username, lesson_path, event_at))`,
    `CREATE INDEX IF NOT EXISTS idx_uhe_username ON user_history_events(username)`,
    `CREATE INDEX IF NOT EXISTS idx_uhe_event_at ON user_history_events(event_at DESC)`,
    `CREATE TABLE IF NOT EXISTS history_migrations (username TEXT PRIMARY KEY, status TEXT NOT NULL DEFAULT 'pending', watched_total INTEGER DEFAULT 0, watched_done INTEGER DEFAULT 0, events_total INTEGER DEFAULT 0, events_done INTEGER DEFAULT 0, source_bytes INTEGER DEFAULT 0, error TEXT, migrated_at INTEGER, updated_at INTEGER NOT NULL, courses_total INTEGER DEFAULT 0, courses_done INTEGER DEFAULT 0, progress_files_total INTEGER DEFAULT 0, progress_files_done INTEGER DEFAULT 0)`,
    // ★ v2.15.29-C: estado por usuário fora do Drive — notas/SRS/última aula
    //   e outras chaves do blob /userstate que não têm tabela própria
    //   (watched/resume → user_watched; history → user_history_events;
    //   plano legado → key 'study-plan'; progresso por curso → key
    //   'course-progress:<hash>'). value = JSON da chave. Fonte de verdade
    //   = D1; o KV 'progress:*' passa a espelho derivado (best-effort) do
    //   /api/courses/user-progress, nunca fonte de leitura.
    `CREATE TABLE IF NOT EXISTS user_state_kv (username TEXT NOT NULL, key TEXT NOT NULL, value TEXT NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY(username, key))`,
    `CREATE INDEX IF NOT EXISTS idx_usk_username ON user_state_kv(username)`, 
  ];
  // ★ v2.13.4: CREATEs em lotes de 8 via d1.batch() (antes: 1 chamada por
  // statement, 38 subrequests num isolate frio — o backfill morria com "Too
  // many subrequests" antes do primeiro curso; d1.batch() com 19 falha, mas
  // lotes de 8 funcionam, como o d1InsertLessons já provava). Fallback p/
  // execução individual se um lote falhar — o comportamento de erro é o mesmo.
  for(let i = 0; i < statements.length; i += 8){
    const chunk = statements.slice(i, i + 8);
    try{
      const results = await d1.batch(chunk.map(sql => d1.prepare(sql)));
      for(const r of (results || [])){ if(r && r.error){ errors.push(String(r.error).slice(0, 80)); if(d1QuotaErrorTest21560(r.error)) _quotaSeen21561 = true; } }
    }catch(_){
      for(const sql of chunk){
        try{ await d1.prepare(sql).run(); }catch(e){ errors.push(e.message.slice(0,80)); if(d1QuotaErrorTest21560(e)) _quotaSeen21561 = true; }
      }
    }
  }
  // ★ v2.15.6: foto de capa dos destaques — migração guardada: só adiciona
  //   cover_url se a coluna ainda não existir (tabelas criadas antes da
  //   v2.15.6). O probe é um SELECT que falha com "no such column" quando a
  //   coluna falta; qualquer outro erro não dispara o ALTER. O ALTER roda
  //   1x por D1 (depois o probe passa e nada mais acontece). Não é um ALTER
  //   solto na lista de statements (ele falharia no 2º boot e o schema
  //   nunca marcaria ready).
  try {
    await d1.prepare('SELECT cover_url FROM featured_courses LIMIT 0').all();
  } catch (e) {
    if (/no such column/i.test(String(e && e.message || e))) {
      try { await d1.prepare('ALTER TABLE featured_courses ADD COLUMN cover_url TEXT').run(); }
      catch (ae) { errors.push('featured cover_url: ' + String(ae.message || ae).slice(0, 80)); }
    }
  }
  // ★ v2.15.91 (Ronda 25-B, Gerar Completo): a coluna mindmap do
  //   índice mestre — as pílulas passam a viver no D1 junto com o
  //   resumo e as questões da aula (antes só existiam no cache web).
  try {
    await d1.prepare('SELECT mindmap FROM shared_summaries LIMIT 0').all();
  } catch (e) {
    if (/no such column/i.test(String(e && e.message || e))) {
      try { await d1.prepare('ALTER TABLE shared_summaries ADD COLUMN mindmap TEXT').run(); }
      catch (ae) { if (!/duplicate column/i.test(String(ae.message || ae))) errors.push('shared_summaries mindmap: ' + String(ae.message || ae).slice(0, 80)); }
    }
  }
  // ★ v2.15.6: plano da Meggy — migração guardada: só adiciona origin /
  //   edital_source / edital_url / banca_profile se a coluna ainda não existir (tabelas
  //   criadas antes da v2.15.6). Um probe por coluna: se o ALTER da 1ª
  //   coluna rodar e o da 2ª falhar, o schema não marca ready e o retry
  //   no próximo request completa o que falta (mesmo padrão da cover_url).
  for (const col of ['origin', 'edital_source', 'edital_url', 'banca_profile']){
    try {
      await d1.prepare('SELECT ' + col + ' FROM study_plans LIMIT 0').all();
    } catch (e) {
      if (/no such column/i.test(String(e && e.message || e))) {
        try { await d1.prepare('ALTER TABLE study_plans ADD COLUMN ' + col + ' TEXT').run(); }
        catch (ae) { if (!/duplicate column/i.test(String(ae.message || ae))) errors.push('study_plans ' + col + ': ' + String(ae.message || ae).slice(0, 80)); }
      }
    }
  }
  // ★ v2.15.6 (scan): migração guardada de scan_status.last_error /
  //   fail_count (mesmo padrão de cover_url / study_plans: probe por
  //   coluna, ALTER só com "no such column"; 1x por D1).
  //   Âncora curta de propósito: o loop acima ganhou 'banca_profile' no
  //   ajuste do plano (v2.15.6-banca) e a migração de concursos.banca foi
  //   inserida logo abaixo — a âncora não depende de nenhum dos dois.
  for (const colDef of [['last_error', 'TEXT'], ['fail_count', 'INTEGER DEFAULT 0']]){
    const col = colDef[0];
    try {
      await d1.prepare('SELECT ' + col + ' FROM scan_status LIMIT 0').all();
    } catch (e) {
      if (/no such column/i.test(String(e && e.message || e))) {
        try { await d1.prepare('ALTER TABLE scan_status ADD COLUMN ' + col + ' ' + colDef[1]).run(); }
        catch (ae) { if (!/duplicate column/i.test(String(ae.message || ae))) errors.push('scan_status ' + col + ': ' + String(ae.message || ae).slice(0, 80)); }
      }
    }
  }
  // ★ v2.15.6-banca: a banca do concurso passa a ser gravada — antes a
  //   tabela concursos NÃO tinha a coluna e o SELECT de /api/plans/generate
  //   com concursoId quebrava no D1 real com "no such column: banca"
  //   (o fake de teste não valida colunas, por isso o bug passou).
  //   D1 novo já nasce com a coluna; tabelas antigas ganham via probe.
  try {
    await d1.prepare('SELECT banca FROM concursos LIMIT 0').all();
  } catch (e) {
    if (/no such column/i.test(String(e && e.message || e))) {
      try { await d1.prepare('ALTER TABLE concursos ADD COLUMN banca TEXT').run(); }
      catch (ae) { errors.push('concursos banca: ' + String(ae.message || ae).slice(0, 80)); }
    }
  }
  // ★ v2.15.29 (B): contadores da migração Drive→D1 em history_migrations
  //   (mesmo padrão guardado: probe por coluna, ALTER só com "no such column").
  for (const colDef of [['courses_total', 'INTEGER DEFAULT 0'], ['courses_done', 'INTEGER DEFAULT 0'], ['progress_files_total', 'INTEGER DEFAULT 0'], ['progress_files_done', 'INTEGER DEFAULT 0']]) {
    const col = colDef[0];
    try {
      await d1.prepare('SELECT ' + col + ' FROM history_migrations LIMIT 0').all();
    } catch (e) {
      if (/no such column/i.test(String(e && e.message || e))) {
        try { await d1.prepare('ALTER TABLE history_migrations ADD COLUMN ' + col + ' ' + colDef[1]).run(); }
        catch (ae) { if (!/duplicate column/i.test(String(ae.message || ae))) errors.push('history_migrations ' + col + ': ' + String(ae.message || ae).slice(0, 80)); }
      }
    }
  }
  // ★ v2.15.53 (H1): a migração .48 de shared_flashcards (topic/
  //   source/qfp + índices) vive no INÍCIO desta função — ver o bloco
  //   marcado v2.15.53 acima. Estava aqui, no fim, e sob quota o
  //   ensure morria nos CREATEs antes de a alcançar: as colunas nunca
  //   aterraram em nenhum dos dois D1 (diagnóstico de 2026-11-21).
  // ★ Ronda 13 Frente A: seed dos drives hardcoded (só quando a tabela
  //   está vazia — ver adminDrivesSeed). Best-effort, nunca falha o schema.
  if (demoSeedEnabled()) { try { await adminDrivesSeed(d1); } catch (_) {} try { await demoUsersSeed(d1); } catch (_) {} }
  if(errors.length){
    if(_quotaSeen21561 || d1QuotaErrorTest21560(errors.join('; '))) d1StampDead21560();  // ★ v2.15.61 (Fase 4): _quotaSeen21561 cobre a forma CAUSE  // ★ v2.15.60: detecção pelo texto REAL do binding (sem '7500') + carimbo local E partilhado — a assinatura .59 era frágil e o carimbo morria com o isolate
    console.warn('[Meggy D1] schema init errors:', errors.join('; '));
    // ★ v1.0.171: NÃO marcar como ready se houve erros — permite retry no próximo request.
    // Antes marcava como ready mesmo com erros, o que impedia re-criar tabelas faltantes.
    // Só marca ready se NÃO houve erros (todas as tabelas criadas com sucesso).
    return false;
  }
  _d1SchemaReady = true;
  d1ClearDead21560();  // ★ v2.15.60: o ensure correu limpo → o D1 está vivo; limpa o carimbo (local + partilhado)
  console.log('[Meggy D1] schema ready');
  return true;
}


// ═══════════════════════════════════════════════════════════════════════
// ★ v2.2 SECRETS NO D1/KV (sem remover do código ainda)
// Os segredos continuam no código como fallback. A fonte preferida passa a
// ser KV (chave secret:<NOME>) e D1 (tabela app_secrets), nesta ordem:
//   KV secret:<NOME> → D1 app_secrets → valor embutido no código / Worker secret.
// - POST /api/admin/secrets/migrate (admin) copia os valores efetivos atuais
//   (código + Worker secrets) para D1 e KV, SEM sobrescrever o que já existe
//   lá e SEM devolver valores na resposta (só os nomes das chaves).
// - ensureSecretsLoaded() roda 1x por isolate no início de cada request/cron
//   e sobrepõe authConfig/globalThis com o que estiver em D1/KV.
// - Rotação sem redeploy: grave o novo valor em D1 (app_secrets) ou KV
//   (secret:<NOME>) e o próximo isolate já usa o novo valor.
// ═══════════════════════════════════════════════════════════════════════
const APP_SECRET_KEYS = ['GOOGLE_CLIENT_ID','GOOGLE_CLIENT_SECRET','GOOGLE_REFRESH_TOKEN','SERVICE_ACCOUNT_JSON','SERVICE_ACCOUNT_JSON_0','SERVICE_ACCOUNT_JSON_1','NVIDIA_API_KEY','NVIDIA_API_KEY_2','NVIDIA_API_KEY_3','GROQ_API_KEY','GROQ_API_KEY_2','ZHIPU_API_KEY','OPENROUTER_API_KEY','OPENAI_API_KEY'];
function appSecretKv(){ try{ if(typeof meggyKvBinding==='function'){ const kv=meggyKvBinding(); if(kv) return kv; } }catch(_){} try{ return (typeof globalThis.MEGGY_CACHE!=='undefined'&&globalThis.MEGGY_CACHE)||null; }catch(_){ return null; } }
async function ensureSecretsLoaded(){
  if(globalThis.__SECRETS_LOADED) return;
  if(globalThis.__SECRETS_LOADING) return globalThis.__SECRETS_LOADING;
  const p=(async()=>{
    let _srcOk=false;
    try{
      const found={};
      const kv=appSecretKv();
      if(kv){
        // ★ v2.15.43 (CF-6): objecto único secret:__all = 1 get em vez
        //   de 14 (gravado por handleSecretsMigrate). Sem ele, o loop
        //   por nome mantém-se como fallback.
        let _all=null;
        try{ const _raw=await kv.get('secret:__all'); _srcOk=true; if(_raw){ const _p=JSON.parse(_raw); if(_p&&typeof _p==='object'&&!Array.isArray(_p)) _all=_p; } }catch(_){}
        if(_all){ for(const name of APP_SECRET_KEYS){ if(_all[name]) found[name]=_all[name]; } }
        else{ for(const name of APP_SECRET_KEYS){ try{ const v=await kv.get('secret:'+name); _srcOk=true; if(v) found[name]=v; }catch(_){} } }
      }
      const d1=meggyD1Binding();
      if(d1){ try{ const res=await d1.prepare('SELECT key, value FROM app_secrets').all(); _srcOk=true; for(const r of (res.results||[])){ if(r&&r.key&&!found[r.key]) found[r.key]=r.value; } }catch(_){} } // ★ v2.15.43: SELECT isolado do d1EnsureSchema — uma falha do schema (quota) não pode famar os segredos
      if(found.GOOGLE_CLIENT_ID) authConfig.client_id=found.GOOGLE_CLIENT_ID;
      if(found.GOOGLE_CLIENT_SECRET) authConfig.client_secret=found.GOOGLE_CLIENT_SECRET;
      if(found.GOOGLE_REFRESH_TOKEN) authConfig.refresh_token=found.GOOGLE_REFRESH_TOKEN;
      // ★ NÃO muda authConfig.service_account (false hoje): o Drive principal usa
      // OAuth refresh_token; o JSON da service account só é sobreposto em valor,
      // para o cron/backfill que lê authConfig.service_account_json direto.
      if(found.SERVICE_ACCOUNT_JSON){ try{ authConfig.service_account_json=JSON.parse(found.SERVICE_ACCOUNT_JSON); }catch(_){} }
      // ★ v2.15.43 (SEC-3): a lista de service accounts vem de
      //   SERVICE_ACCOUNT_JSON_0/_1 (KV/D1) — o código já não a contém.
      try{
        const _sas=[];
        if(found.SERVICE_ACCOUNT_JSON_0){ const _j=JSON.parse(found.SERVICE_ACCOUNT_JSON_0); if(_j&&typeof _j==='object') _sas.push(_j); }
        if(found.SERVICE_ACCOUNT_JSON_1){ const _j=JSON.parse(found.SERVICE_ACCOUNT_JSON_1); if(_j&&typeof _j==='object') _sas.push(_j); }
        if(_sas.length){ serviceaccounts=_sas; if(!authConfig.service_account_json) authConfig.service_account_json=pickRandomServiceAccount(); }
      }catch(_){}
      for(const k of ['NVIDIA_API_KEY','NVIDIA_API_KEY_2','NVIDIA_API_KEY_3','GROQ_API_KEY','GROQ_API_KEY_2','ZHIPU_API_KEY','OPENROUTER_API_KEY','OPENAI_API_KEY']){
        if(found[k]) globalThis[k]=found[k];
      }
    }catch(_){}
    // ★ v2.15.43 (QA-8): só marca carregado se alguma fonte respondeu;
    //   KV+D1 em baixo => o próximo pedido tenta outra vez em vez de
    //   ficar o isolate inteiro sem segredos.
    if(_srcOk) globalThis.__SECRETS_LOADED=true;
  })();
  globalThis.__SECRETS_LOADING=p;
  try{ await p; }finally{ globalThis.__SECRETS_LOADING=null; }
}

async function handleSecretsMigrate(request){
  const user=await gdiSessionUser(request);
  if(!user||!ADMIN_USERS.includes(user))return new Response(JSON.stringify({ok:false,error:'admin only'}),{status:403,headers:CORS_JSON});
  await d1EnsureSchema();
  const d1=meggyD1Binding();
  const kv=appSecretKv();
  // Valores efetivos atuais (código + Worker secrets). Nunca entram na resposta.
  const current={};
  try{ current.GOOGLE_CLIENT_ID=authConfig.client_id||''; }catch(_){}
  try{ current.GOOGLE_CLIENT_SECRET=authConfig.client_secret||''; }catch(_){}
  try{ current.GOOGLE_REFRESH_TOKEN=authConfig.refresh_token||''; }catch(_){}
  try{ current.SERVICE_ACCOUNT_JSON=authConfig.service_account_json?JSON.stringify(authConfig.service_account_json):''; }catch(_){}
  try{ if(typeof serviceaccounts!=='undefined'&&serviceaccounts[0]) current.SERVICE_ACCOUNT_JSON_0=JSON.stringify(serviceaccounts[0]); }catch(_){}
  try{ if(typeof serviceaccounts!=='undefined'&&serviceaccounts[1]) current.SERVICE_ACCOUNT_JSON_1=JSON.stringify(serviceaccounts[1]); }catch(_){}
  for(const k of ['NVIDIA_API_KEY','NVIDIA_API_KEY_2','NVIDIA_API_KEY_3','GROQ_API_KEY','GROQ_API_KEY_2','ZHIPU_API_KEY','OPENROUTER_API_KEY','OPENAI_API_KEY']){
    if(globalThis[k]) current[k]=globalThis[k];
  }
  const migrated=[],skipped=[],missing=[];
  for(const name of Object.keys(current)){
    const value=current[name];
    if(!value){ missing.push(name); continue; }
    let exists=false;
    if(kv){ try{ if(await kv.get('secret:'+name)) exists=true; }catch(_){} }
    if(!exists&&d1){ try{ const row=await d1.prepare('SELECT key FROM app_secrets WHERE key=?').bind(name).first(); if(row) exists=true; }catch(_){} }
    if(exists){ skipped.push(name); continue; }
    let ok=false;
    if(d1){ try{ await d1.prepare('INSERT OR IGNORE INTO app_secrets (key,value,updated_at) VALUES (?,?,?)').bind(name,value,Date.now()).run(); ok=true; }catch(_){} }
    if(kv){ try{ await kv.put('secret:'+name,value); ok=true; }catch(_){} }
    if(ok) migrated.push(name); else missing.push(name);
  }
  // ★ v2.15.43 (CF-6): objecto único secret:__all (1 get por isolate
  //   frio em vez de 14). current traz os valores efectivos de todas
  //   as APP_SECRET_KEYS (código + Worker secrets + já migrados).
  try{
    if(kv){ const _all={}; for(const _k of Object.keys(current)){ if(current[_k]) _all[_k]=current[_k]; } if(Object.keys(_all).length) await kv.put('secret:__all', JSON.stringify(_all)); }
  }catch(_){}
  return new Response(JSON.stringify({ok:true,migrated,skipped,missing}),{headers:{...CORS_JSON,'Cache-Control':'no-store'}});
}

// ★ v2.15.11-B12-detector-recusa (worker): detetor de RECUSA da IA —
//   a MESMA lista de padrões do shell (Shell._isIsaRefusal); manter as
//   duas sincronizadas (o harness compara-as). Um texto de recusa ("não
//   recebi o conteúdo da aula", "me forneça o material", "cole a
//   transcrição"...) NÃO é um resumo: nunca pode ser gravado nem selado
//   como tal. Padrões case-insensitive, sem acentos (o texto é
//   normalizado), com tolerância a variações — NUNCA um único literal.
//   Lê o texto INTEIRO (o gancho pode preceder a recusa quando ela abre
//   com '#' ou '⚠️' — battalionEnsureSummaryHook abaixo). Nenhum padrão
//   casa a palavra isolada ('transcrição', 'conteúdo da aula'), por isso
//   um resumo REAL que as menciona não é falso positivo.
function isIsaRefusalText(t){
  if(!t || typeof t !== 'string') return false;
  const s = String(t).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[*#_`>|]/g, ' ').replace(/\s+/g, ' ').trim();
  if(!s) return false;
  const REFUSAL_PATTERNS = [
        /nao recebi (ainda )?(o |nenhum |qualquer )?(conteudo|material|texto|arquivo)/,
        /nao tenho (ainda )?(o |nenhum |qualquer )?(conteudo|material|texto|arquivo)/,
        /nao possuo (o |nenhum )?(conteudo|material|texto)/,
        /nao tenho acesso (ao |a )?(conteudo|material|transcricao|video|arquivo)/,
        /nao tive acesso (ao |a )?(conteudo|material|transcricao)/,
        /me passou apenas (as informacoes|os dados|o titulo|a identificacao|informacoes)/,
        /apenas as informacoes de identificacao/,
        /so (recebi|tenho) (as informacoes|o titulo|os dados)/,
        /nao enviou (o |nenhum )?(conteudo|material|texto)/,
        /(conteudo|material|arquivo|transcricao) nao (me )?foi (fornecido|enviado|disponibilizado|anexado)/,
        /nenhum (material|conteudo) (foi )?(fornecido|enviado|recebido|disponibilizado)/,
        /(conteudo|material) nao chegou/,
        /nao ha (conteudo|material) (disponivel|nesta|neste|na |no |suficiente|para)/,
        /sem o conteudo (da aula|necessario|para resumir|para gerar)/,
        /falta o conteudo (da aula|necessario|para)/,
        /preciso que voce (me )?(forneca|envie|cole|informe|anexe|compartilhe)/,
        /me forneca (o |a |seu |sua )?(material|conteudo|texto|transcricao)/,
        /forneca (o |a |seu |sua )?(material|conteudo|texto|transcricao)/,
        /cole (a|o) (transcricao|texto|material|conteudo)/,
        /envie (o|a) (conteudo|material|transcricao|texto)/,
        /informe (o|a) (conteudo|material|transcricao|texto)/,
        /anexe (o|a) (conteudo|material|arquivo|transcricao)/,
        /compartilhe (comigo )?(o |a )?(conteudo|material|transcricao|texto)/,
        /aguardando (o|a) (conteudo|material|transcricao)/,
        /nao consigo (gerar|criar|fazer|elaborar|produzir) (o resumo|um resumo|este resumo|as pilulas|o conteudo|o material)/,
        // ★ v2.15.12-B1-detector-pilulas: recusa de PÍLULAS (Passo 16) —
        //   "Desculpe, mas não posso criar "pílulas de revisão" para
        //   você. Posso, no entanto, ajudar com a criação de material
        //   de estudos... Qual é o assunto específico que você gostaria
        //   de revisar?" — o detetor da v2.15.11 NÃO a apanhava:
        //   "não posso" ≠ "não consigo" (nenhum padrão casava "posso"),
        //   e a pergunta final é o redirecionamento da recusa (o modelo
        //   devolve a pergunta ao usuário em vez do conteúdo). As duas
        //   últimas linhas estendem os objetos de "não foi possível" /
        //   "não é possível" (que só listavam conteúdo/material/
        //   transcrição) p/ pílulas/resumo/questões/flashcards.
        /nao (posso|consigo) (criar|gerar|fazer|elaborar|produzir|montar|fornecer|apresentar|resumir)/,
        /nao tenho como (criar|gerar|elaborar|produzir|fazer|resumir|montar)/,
        /nao (posso|consigo) (criar|gerar|elaborar|produzir|montar)[\\s\\S]{0,40}(pilulas|resumo|conteudo|material|flashcards|questoes)/,
        /(desculpe|sinto muito|infelizmente)[\\s\\S]{0,60}nao (posso|consigo)/,
        /posso,? (no entanto|entretanto|porem)?[\\s\\S]{0,80}ajudar com a criacao/,
        /assunto especifico que voce (gostaria|quer|deseja)/,
        /que voce (gostaria de|quer|deseja|precisa de) (revisar|estudar|aprender|ver)/,
        /nao foi possivel (gerar|criar|elaborar|produzir|fazer|montar)[\\s\\S]{0,120}(pilulas|resumo|questoes|flashcards)/,
        /nao e possivel (gerar|criar|resumir|elaborar)[\\s\\S]{0,120}(pilulas|resumo|questoes|flashcards)/,
        /nao foi possivel (resumir|fazer o resumo|fazer um resumo)/,
        /nao foi possivel (gerar|criar|elaborar|produzir|fazer|montar)[\s\S]{0,120}(conteudo|material|transcricao|texto da aula)/,
        /nao e possivel (gerar|criar|resumir|elaborar)[\s\S]{0,120}(conteudo|material|transcricao)/,
  ];
  return REFUSAL_PATTERNS.some((re) => re.test(s));
}

// ★ v2.15.13-B1-validacao-forma: validade ESTRUTURAL do conteúdo
//   guardado/gerado, por campo — a autoridade, acima do detetor por
//   padrões (primeira passagem, barato). Um texto que pede material ou
//   não tem a forma esperada é recusa, seja qual for a redação (Passo
//   17: a nova recusa "eu preciso do conteúdo da aula" não diz "não
//   posso/consigo" e o detetor devolve false — mas é prosa sem
//   cabeçalhos nem bullets, por isso falha aqui). A MESMA função vive no
//   shell (Shell._isIsaValidContent); manter sincronizadas. Resumo =
//   texto longo com estrutura markdown; pílulas = lista com 3 ou mais
//   itens; questões = array com 1 ou mais objetos com enunciado (string
//   crua não-recusa passa, como antes — o batalhão guarda-a assim quando
//   o parse falha).
function isIsaValidContent(field, value){
  if(field === 'questions'){
    if(Array.isArray(value)){
      if(!value.length) return false;
      return value.some(function(q){
        if(!q || typeof q !== 'object') return false;
        const s = q.statement || q.question || q.text;
        return typeof s === 'string' && !!s.trim();
      });
    }
    if(typeof value === 'string') return value.trim().length >= 10 && !isIsaRefusalText(value);
    return false;
  }
  if(typeof value !== 'string' || !value) return false;
  if(isIsaRefusalText(value)) return false;
  const lines = String(value).split('\n');
  let headings = 0, bullets = 0;
  for(let i = 0; i < lines.length; i++){
    const t = lines[i].trim();
    if(/^#{1,3}\s+\S/.test(t)) headings++;
    else if(/^(-|\*|•)\s+\S/.test(t)) bullets++;
    else if(/^\d+[.)]\s+\S/.test(t)) bullets++;
  }
  if(field === 'summary') return value.length >= 200 && (headings >= 1 || bullets >= 3);
  if(field === 'mindmap') return value.length >= 50 && bullets >= 3;
  return false;
}

// ★ v2.15.11-B12-detector-recusa (save): saneia UMA entrada do cache ISA
//   antes de gravar — recusa vira null, o resto passa intacto (um resumo
//   recusado NÃO apaga as 10 questões boas gravadas juntas). O clear
//   (tudo null, botão Regerar) passa por aqui sem mudar: null continua null.
function sanitizeIsaCacheEntry(body){
  const b = body || {};
  const refused = [];
  let summary = (typeof b.summary === 'string' && b.summary) ? b.summary : null;
  let mindmap = (typeof b.mindmap === 'string' && b.mindmap) ? b.mindmap : null;
  let questions = b.questions || null;
  // ★ v2.15.13-B4-save-forma-worker-save: a autoridade é a forma esperada, não só
  //   o padrão — uma recusa em prosa sem cabeçalhos nem bullets (Passo
  //   17) também vira null; um array de questões sem objeto válido idem.
  if(typeof summary === 'string' && !isIsaValidContent('summary', summary)){ refused.push('summary'); summary = null; }
  if(typeof mindmap === 'string' && !isIsaValidContent('mindmap', mindmap)){ refused.push('mindmap'); mindmap = null; }
  if(typeof questions === 'string' && !isIsaValidContent('questions', questions)){ refused.push('questions'); questions = null; }
  else if(Array.isArray(questions) && !isIsaValidContent('questions', questions)){ refused.push('questions'); questions = null; }
  return { summary, mindmap, questions, lessonName: b.lessonName || '', refused };
}

// ★ v2.15.11-B12-detector-recusa (batalhão): saneia UM patch do batalhão
//   in place (o merge faz Object.assign) — campos de recusa são
//   apagados e devolvidos na lista, para o merge não os contar como
//   gerados nem os espelhar no KV / partilhar no pool.
function sanitizeIsaCachePatch(patch){
  const refused = [];
  if(!patch || typeof patch !== 'object') return refused;
  for(const f of ['summary', 'mindmap', 'questions']){
    if(typeof patch[f] === 'string' && !isIsaValidContent(f, patch[f])){ refused.push(f); delete patch[f]; }
  }
  // ★ v2.15.13-B4-save-forma-worker-patch: array de questões sem objeto válido idem.
  if(Array.isArray(patch.questions) && !isIsaValidContent('questions', patch.questions)){ refused.push('questions'); delete patch.questions; }
  return refused;
}

async function handleIsaCacheGet(request, url){
  const cors = { 'Content-Type': 'application/json;charset=UTF-8', 'Access-Control-Allow-Origin': '*', 'Cache-Control': 'no-store' };
  const gd0 = gds[0];
  const user = await gdiSessionUser(request);
  if (!user) return new Response(JSON.stringify({ ok: false, error: 'auth' }), { status: 401, headers: cors });
  const key = url.searchParams.get('key') || '';
  if (!key) return new Response(JSON.stringify({ ok: false, error: 'no key' }), { status: 400, headers: cors });

  const backend = meggyCacheBackend();
  const kv = meggyKvBinding();

  // 1) Try KV first (when configured and backend allows)
  if ((backend === 'both' || backend === 'kv') && kv) {
    try {
      const raw = await kv.get('summary:' + key);
      if (raw) {
        let cached;
        try { cached = JSON.parse(raw); } catch (_) { cached = null; }
        if (cached) {
          console.log('[Meggy KV] hit for key:', key.slice(0, 50));
          return new Response(JSON.stringify({ ok: true, cached, source: 'kv' }), { headers: cors });
        }
      }
      console.log('[Meggy KV] miss for key:', key.slice(0, 50));
    } catch (e) { console.warn('[Meggy KV] get failed:', e.message); }
  }

  // 2) Fallback to Drive cache (sempre disponível para leitura, mesmo em modo "kv")
  // ★ FASE 1.5: mesmo com backend=kv, ainda lemos do Drive como fallback para entries
  // antigas que não foram migradas. Só NÃO escrevemos mais no Drive (handleIsaCacheSave).
  // Quando um hit do Drive acontece, salvamos no KV (lazy migration) para próximas leituras.
  const folderId = await gdiUserFolderId(gd0);
  if (folderId) {
    const cache = await gdiIsaCacheRead(gd0, folderId);
    const entry = cache[key] || null;
    if (entry) {
      console.log('[Meggy Drive] hit (fallback) for key:', key.slice(0, 50));
      // ★ Lazy migration: se backend=kv e achou no Drive, salva no KV para próximas leituras
      if (backend === 'kv' && kv) {
        try { await kv.put('summary:' + key, JSON.stringify(entry), { expirationTtl: 2592000 }); console.log('[Meggy KV] migrated from Drive:', key.slice(0, 50)); } catch(_){} // ★ v2.15.43 (CF-7): TTL 30d
      }
      return new Response(JSON.stringify({ ok: true, cached: entry, source: 'drive' }), { headers: cors });
    }
  }

  // No backend produced a hit
  return new Response(JSON.stringify({ ok: true, cached: null }), { headers: cors });
}

// ★ v2.15.35-R14D: núcleo da gravação do cache ISA, extraído de
//   handleIsaCacheSave SEM mudar comportamento (saneia, aplica o
//   gancho, grava KV 'summary:<key>' + Drive isa_cache.json).
//   O ramo /api/ai (aula aberta) reutiliza-o. Devolve o mesmo
//   {ok, kv, drive, refused} que o handler devolvia no corpo.
async function isaCacheSaveInternal(user, gd0, key, body){

  // ★ FASE 1: entry now includes `author` for future anti-clobber (FASE 2+).
  // ★ v2.15.6-hook: todo resumo salvo abre com o gancho da aula — a
  // geração via /api/ai (cliente) não passa pelo batalhão; o gancho é
  // garantido aqui, no ponto de gravação do cache.
  // ★ v2.15.11-B13-save-limpo: SANEIA ANTES do gancho e de gravar — o
  //   gancho só se aplica a resumo real (a recusa vira null aqui; o
  //   hook nunca a "legitima"). Sem isto a recusa era gravada verbatim
  //   no KV ('summary:'+key) e no Drive — foi assim que nasceu a chave
  //   órfã da Aula 09 (04:50:37 UTC, Passo 13).
  const _san = sanitizeIsaCacheEntry(body);
  if(_san.refused.length) console.warn('[Meggy cache] recusa da IA descartada no save — campos:', _san.refused.join(','), 'chave:', String(key).slice(0, 80));
  const hookedSummary = (typeof _san.summary === 'string' && _san.summary.trim()) ? battalionEnsureSummaryHook(_san.summary, _san.lessonName || '', '') : _san.summary;
  const entry = {
    summary: hookedSummary || null,
    questions: _san.questions || null,
    mindmap: _san.mindmap || null,
    lessonName: _san.lessonName || '',
    author: user,
    date: Date.now()
  };

  const backend = meggyCacheBackend();
  const kv = meggyKvBinding();
  let kvOk = false, driveOk = false;

  // 1) KV write — atomic per key, no RMW, no mutex needed, cross-isolate safe.
  if ((backend === 'both' || backend === 'kv') && kv) {
    try {
      // expirationTtl: 0 means "no expiration" — we evict manually via LRU on the Drive side
      // (KV does not support TTL=0 explicitly; omitting the option keeps it indefinitely).
      await kv.put('summary:' + key, JSON.stringify(entry), { expirationTtl: 2592000 }); // ★ v2.15.43 (CF-7): TTL 30d
      kvOk = true;
      console.log('[Meggy KV] saved key:', key.slice(0, 50));
    } catch (e) { console.warn('[Meggy KV] put failed:', e.message); }
  }

  // 2) Drive write — existing RMW logic, preserved as fallback/dual-write.
  if (backend === 'both' || backend === 'drive') {
    const folderId = await gdiUserFolderId(gd0);
    if (folderId) {
      try {
        // ★ v84-FIX-BATTALION BUG 4: serializa RMW por folderId — sem isso, saves concorrentes
        // com chaves diferentes → last-write-wins → outras chaves perdidas.
        await withIsaCacheLock(folderId, async () => {
          const cache = await gdiIsaCacheRead(gd0, folderId);
          cache[key] = entry;  // ★ FASE 1: same entry shape as KV (with author)
          // limita a 200 aulas mais recentes (evita crescer indefinidamente)
          const keys = Object.keys(cache);
          if (keys.length > 200) {
            keys.sort((a, b) => (cache[a].date || 0) - (cache[b].date || 0));
            keys.slice(0, keys.length - 200).forEach(k => delete cache[k]);
          }
          const ok = await gdiIsaCacheWrite(gd0, folderId, cache);
          driveOk = ok;
        });
      } catch (e) { console.warn('[Meggy Drive] save failed:', e.message); }
    } else {
      console.warn('[Meggy Drive] save skipped: no folderId');
    }
  }

  const ok = kvOk || driveOk;
  // ★ v2.15.11-B14-save-resposta: devolve os campos recusados (aditivo —
  //   a forma anterior {ok, kv, drive} mantém-se) para o cliente/logs
  //   saberem que a geração recusou sem ser selada como resumo.
  return { ok, kv: kvOk, drive: driveOk, refused: _san.refused };
}

async function handleIsaCacheSave(request){
  const cors = { 'Content-Type': 'application/json;charset=UTF-8', 'Access-Control-Allow-Origin': '*' };
  const gd0 = gds[0];
  const user = await gdiSessionUser(request);
  if (!user) return new Response(JSON.stringify({ ok: false, error: 'auth' }), { status: 401, headers: cors });
  let body;
  try { body = await request.json(); } catch (_) { return new Response(JSON.stringify({ ok: false, error: 'invalid json' }), { status: 400, headers: cors }); }
  const key = body.key || '';
  if (!key) return new Response(JSON.stringify({ ok: false, error: 'no key' }), { status: 400, headers: cors });

  const _r14d = await isaCacheSaveInternal(user, gd0, key, body);
  return new Response(JSON.stringify(_r14d), { status: _r14d.ok ? 200 : 502, headers: cors });
}

// ★ WORKER-FIXES-v79: lista todas as aulas em cache do usuário.
async function handleIsaCacheList(request){
  const cors={'Content-Type':'application/json;charset=UTF-8','Access-Control-Allow-Origin':'*'};
  const gd0=gds[0];
  const user=await gdiSessionUser(request);
  if(!user)return new Response(JSON.stringify({ok:false,error:'auth'}),{status:401,headers:cors});
  const folderId=await gdiUserFolderId(gd0);
  // ★ v2.15.12-D7-lista-le-KV: a lista lia SÓ o isa_cache.json do Drive —
  //   mas com CACHE_BACKEND=kv (staging-c e meuc) o save escreve SÓ no
  //   KV e o Drive nunca é atualizado. O GET por chave lê o KV primeiro
  //   (por isso o selo da aula mostra "✓ 9 questões") mas a lista
  //   devolvia [] — e as bibliotecas próprias /questoes, /flashcards e
  //   /resumos ficavam vazias (Passo 16). Agora funde as duas fontes
  //   (o KV ganha na mesma chave — é o caminho de escrita atual) e
  //   devolve só as entradas DESTE utilizador (o KV não tem namespace
  //   por utilizador; as entradas guardam `author` desde a FASE 1 —
  //   as sem autor são legado pré-FASE-1 e contam como próprias, tal
  //   como o GET por chave já as serve a qualquer utilizador). A forma
  //   da resposta não muda ({ok, entries[]}); sem KV, é a lista de antes.
  let cache={};
  if(folderId){
    try{ cache=await gdiIsaCacheRead(gd0, folderId); }catch(_){ cache={}; }
  }
  const _listBackend=(typeof meggyCacheBackend==='function')?meggyCacheBackend():'both';
  const _listKv=(typeof meggyKvBinding==='function')?meggyKvBinding():null;
  if((_listBackend==='both'||_listBackend==='kv') && _listKv && typeof _listKv.list==='function'){
    try{
      const _kvKeys=[];
      let _cursor;
      do{
        const _page=await _listKv.list({prefix:'summary:',...(_cursor?{cursor:_cursor}:{})});
        for(const _k of (_page.keys||[])){ if(_k && _k.name) _kvKeys.push(_k.name); }
        _cursor=(_page.list_complete===false && _page.cursor)?_page.cursor:undefined;
      }while(_cursor && _kvKeys.length<1000);
      // leituras em lotes (evita 1000 awaits sequenciais)
      for(let _i=0;_i<_kvKeys.length;_i+=50){
        const _chunk=_kvKeys.slice(_i,_i+50);
        const _vals=await Promise.all(_chunk.map(async _kn=>{
          try{ const _raw=await _listKv.get(_kn); return _raw?JSON.parse(_raw):null; }catch(__){ return null; }
        }));
        _chunk.forEach((_kn,_ix)=>{
          const _entry=_vals[_ix];
          if(!_entry) return;
          const _author=_entry.author||'';
          if(_author && _author!==user) return; // entrada de outro aluno
          const _key=_kn.slice('summary:'.length);
          cache[_key]=_entry; // KV ganha: escrita mais recente que o Drive
        });
      }
    }catch(_){ /* lista segue só com o Drive — comportamento anterior */ }
  }
  const entries=Object.keys(cache).map(key=>({key,summary:cache[key]?.summary||null,questions:cache[key]?.questions||null,mindmap:cache[key]?.mindmap||null,lessonName:cache[key]?.lessonName||'',date:cache[key]?.date||0})).sort((a,b)=>(b.date||0)-(a.date||0));
  return new Response(JSON.stringify({ok:true,entries}),{headers:{...cors,'Cache-Control':'no-store'}});
}
