  if(!disc && o.subjectFallback){
    const sf = String(o.subjectFallback).trim();
    if(sf && !qbIsFileName21554(sf)) disc = qbMatchDiscipline21554(sf, lists);
  }
  const candT = String(o.assunto || '').trim();
  if(candT && !qbIsFileName21554(candT)) topic = candT;
