// ════════════════════════════════════════════════════════════════
// ★ v2.15.92 (Ronda 28-C): GERAR POPULA O ÍNDICE MESTRE —
//   cada save de resumo (D1 ou journal) actualiza o índice
//   mestre no Drive (upsert da entry pela chave lessonName +
//   coursePath, norma igual à de qbBankRowMatchesLesson21589).
//   Sem pares do banco → 'A classificar' (o refresh reclassifica).
//   Se o índice tiver >1 parte no manifesto, SALTA o upsert
//   inline (o refresh rebakeia; o merge do journal na leitura
//   mantém a entry visível). NUNCA quebra o save: tudo em
//   try/catch, falha do índice só loga.
//   Agendamento: via _ctx.waitUntil quando há contexto (o mesmo
//   padrão de fbHydrateOnRead21572) — o upsert NÃO está no
//   caminho crítico do save (a leitura funde o journal, por isso
//   a entry já é visível sem o índice; o índice só importa p/
//   o fallback quando o D1 está morto); sem _ctx, await inline.
//   Os upserts correm numa fila em cadeia p/ não se perderem
//   uns aos outros (ler → upsert → escrever).
// ════════════════════════════════════════════════════════════════
let _summaryMasterIndexQueue21592 = Promise.resolve();
function summaryMasterIndexNormKey21592(s){ return String(s || '').replace(/\.[a-z0-9]{2,5}$/i, '').trim().toLowerCase(); }
async function summaryMasterIndexUpsert21592(user, body){
  try{
    const lessonName = String((body && body.lessonName) || '').trim();
    if(!lessonName || !(body && body.summary)) return false;
    const coursePath = String((body && body.coursePath) || '') || null;
    // Manifesto FRESCO (fallbackDriveFileJson, sem a cache de 60 s):
    // um refresh da peça A acabado de chegar não pode mandar o
    // upsert p/ o ficheiro directo quando o manifesto já lista a parte.
    let manParts = null;
    try{
      const manFresh = await fallbackDriveFileJson('manifest.json');
      const entF = manFresh && manFresh.ok === true && manFresh.tables ? manFresh.tables['summary-master-index'] : null;
      if(entF && Array.isArray(entF.parts) && entF.parts.length) manParts = entF.parts.slice();
    }catch(_){ manParts = null; }
    if(!manParts){ try{ manParts = await summaryMasterIndexManifest21592(); }catch(_){} }
    if(manParts && manParts.length > 1){ console.log('[v2.15.92] índice mestre com ' + manParts.length + ' partes — upsert inline saltado (o refresh rebakeia)'); return false; }
    const targetName = (manParts && manParts.length === 1) ? manParts[0] : 'summary-master-index.json';
    // Classificação na hora: pares do banco (D1; qbSummaryBankRows21590
    // cai p/ qbBankRows21563() quando o D1 falha). Sem pares →
    // 'A classificar' (o refresh reclassifica).
    let pairs = null;
    try{
      const _d1c21592 = (typeof meggyD1Binding === 'function') ? meggyD1Binding() : null;
      const bankRows = await qbSummaryBankRows21590(_d1c21592);
      pairs = qbSummaryPairs21590({ lesson_name: lessonName, course_path: coursePath }, bankRows);
    }catch(_){ pairs = null; }
    if(!pairs || !pairs.length) pairs = [{ subject: 'A classificar', topic: 'A classificar' }];
    const now = Date.now();
    const entry = {
      lessonName: lessonName, coursePath: coursePath,
      subject: pairs[0].subject, topic: pairs[0].topic, subjects: pairs,
      author: user || null, date: now, generatedAt: now,
      drivePath: (coursePath ? coursePath + '/' : '') + lessonName,
      summary: body.summary || '', mindmap: (body.mindmap === undefined) ? null : body.mindmap,
      questions: (body.questions === undefined || body.questions === null) ? null : body.questions
    };
    // Cache fora antes de ler: o upsert anterior da fila já pode ter
    // escrito depois da última leitura.
    summaryMasterIndexDrop21592();
    const idx = await summaryMasterIndex21592();
    const entries = (idx && Array.isArray(idx.entries)) ? idx.entries.slice() : [];
    const nk = summaryMasterIndexNormKey21592(lessonName);
    const ck = summaryMasterIndexNormKey21592(coursePath);
    let at = -1;
    for(let i = 0; i < entries.length; i++){
      const e = entries[i] || {};
      if(summaryMasterIndexNormKey21592(e.lessonName) !== nk) continue;
      const ec = summaryMasterIndexNormKey21592(e.coursePath);
      if(!ck || !ec || ec === ck){ at = i; break; }
    }
    if(at >= 0) entries[at] = entry; else entries.push(entry);
    const drv = summaryMasterIndexDerive21592(entries);
    const payload = { ok: true, table: 'summary-master-index', part: 1, parts: 1, generatedAt: now, disciplines: drv.disciplines, topics: drv.topics, counts: drv.counts, totalSummaries: entries.length, entries: entries };
    const got = await fallbackSnapshotFolderId();
    if(!got.gd0 || !got.folderId) return false;
    await scanBufferUpsertJsonFile(got.gd0, got.folderId, targetName, JSON.stringify(payload));
    summaryMasterIndexDrop21592();
    return true;
  }catch(e){ console.warn('[v2.15.92] upsert do índice mestre falhou (o save NÃO quebrou):', String((e && e.message) || e).slice(0, 160)); return false; }
}
function summaryMasterIndexUpsertSchedule21592(user, body){
  // Devolve null quando agendou via waitUntil (nada p/ o chamador
  // esperar); devolve a promise quando NÃO há contexto — aí o
  // chamador aguarda inline (o chamador já corre em background).
  try{
    const task = _summaryMasterIndexQueue21592.then(function(){ return summaryMasterIndexUpsert21592(user, body); }).catch(function(){ return false; });
    _summaryMasterIndexQueue21592 = task.catch(function(){});
    const c = (typeof _ctx !== 'undefined') ? _ctx : null;
    if(c && typeof c.waitUntil === 'function'){ try{ c.waitUntil(task); }catch(_){} return null; }
    return task;
  }catch(_){ return null; }
}

async function handleSharedSummariesSave(request){
  const user=await gdiSessionUser(request);  // ★ v2.15.29-C: sem gd0 (sem Drive)
  if(!user)return new Response(JSON.stringify({ok:false,error:'auth'}),{status:401,headers:{'Content-Type':'application/json;charset=UTF-8','Access-Control-Allow-Origin':'*'}});
  let body;
  try{body=await request.json();}catch(_){return new Response(JSON.stringify({ok:false,error:'invalid json'}),{status:400,headers:{'Content-Type':'application/json;charset=UTF-8','Access-Control-Allow-Origin':'*'}});}
  const lessonName=body.lessonName||'';
  const summary=body.summary||'';
  const questions=body.questions||null;
  if(!lessonName||!summary)return new Response(JSON.stringify({ok:false,error:'missing data'}),{status:400,headers:{'Content-Type':'application/json;charset=UTF-8','Access-Control-Allow-Origin':'*'}});

  const _r14d = await sharedSummarySaveInternal(user, body);
  return new Response(JSON.stringify({ok:_r14d.ok, fallback:_r14d.fallback?true:undefined}),{status:_r14d.ok?200:502,headers:{'Content-Type':'application/json;charset=UTF-8','Access-Control-Allow-Origin':'*'}});
}
