const REDACAO_DEFAULT_21587={label:'Critérios gerais (banca sem grelha localizada)',max:10,
 crit:[['Adequação ao tema e ao tipo textual',null,'O texto responde ao tema/comando no tipo textual pedido.'],
       ['Estrutura e argumentação',null,'Tese, desenvolvimento organizado e conclusão.'],
       ['Coesão e coerência',null,'Articulação entre frases, períodos e parágrafos.'],
       ['Norma culta',null,'Domínio da modalidade escrita formal.']],
 zero:['Fuga ao tema','Texto em branco ou ilegível','Identificação do candidato'],
 extra:'Não foi localizada grelha oficial pública desta banca/instituição: corrija pelos critérios gerais das provas discursivas brasileiras e declare essa limitação ao aluno (a nota é uma estimativa sem grelha oficial de referência).',
 src:'Sem fonte oficial específica localizada — ver skills redacao-bancas e redacao-vestibulares.'};
const REDACAO_ALIASES_21587={'CESPE':'CEBRASPE','USP':'FUVEST','COMVEST':'UNICAMP','ALBERT EINSTEIN':'EINSTEIN','FGV SP':'FGVSP'};
function redacaoNormKey21587(banca){
  let s=String(banca||'').toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  s=s.replace(/\(.*?\)/g,' ').replace(/[^A-Z0-9]+/g,' ').trim().replace(/\s+/g,' ');
  return s;
}
function redacaoProfile21587(banca){
  const raw=String(banca||'');
  if(redacaoIsEnem21575(raw)) return null; // ENEM tem caminho próprio (.75/.82)
  let k=redacaoNormKey21587(raw);
  if(REDACAO_ALIASES_21587[k]) k=REDACAO_ALIASES_21587[k];
  if(REDACAO_PROFILES_21587[k]) return {key:k,p:REDACAO_PROFILES_21587[k]};
  const kc=k.replace(/ /g,'');
  if(REDACAO_PROFILES_21587[kc]) return {key:kc,p:REDACAO_PROFILES_21587[kc]};
  // correspondência por prefixo na forma compacta, da chave mais longa
  // para a mais curta (ex.: 'UERJMED' → UERJ, 'UNESPMED' → UNESP);
  // VUNESP casa exactamente acima, antes de poder cair em UNESP, e
  // FGVSP (5) é tentado antes de FGV (3).
  const keys=Object.keys(REDACAO_PROFILES_21587).sort((a,b)=>b.length-a.length);
  for(const key of keys){ if(kc.startsWith(key)) return {key:key,p:REDACAO_PROFILES_21587[key]}; }
  return {key:'DEFAULT',p:REDACAO_DEFAULT_21587};
}
function redacaoProfilePrompt21587(p,tipo,tema,text){
  const t=String(tema||'').trim();
  let s='Você é um corretor experiente de provas discursivas/redações ('+p.label+'). Corrija este texto (tipo: '+tipo+') EXCLUSIVAMENTE pelo modelo oficial descrito abaixo — não use critérios de outras bancas nem do ENEM.\n\n';
  s+='CRITÉRIOS:\n';
  for(const c of p.crit){ s+='- '+c[0]+(c[1]!=null?' (até '+redacaoFmtN21587(c[1])+' pontos)':'')+': '+c[2]+'\n'; }
  if(p.extra) s+='\nREGRAS DESTA BANCA/INSTITUIÇÃO: '+p.extra+'\n';
  if(p.zero&&p.zero.length) s+='\nSITUAÇÕES DE NOTA ZERO: '+p.zero.join('; ')+'.\nEstamos em MODO TREINO: NÃO zere a nota por estas situações — sinalize o risco na secção "Riscos de Nota Zero" e corrija pedagogicamente.\n';
  if(t) s+='\nTEMA/COMANDO OFICIAL: "'+t+'" — avalie a adequação em relação a este tema/comando; fuga ou tangenciamento devem ser apontados.\n';
  else s+='\nTEMA NÃO INFORMADO pelo aluno: identifique o tema a partir do próprio texto e declare-o na primeira linha da secção "Riscos de Nota Zero".\n';
  s+='\nFONTE DOS CRITÉRIOS: '+p.src+'\nA nota é uma ESTIMATIVA pedagógica: a nota oficial vem dos examinadores da banca/instituição. Diga isto numa linha, na secção de riscos.\n';
  s+='\nFORMATO Markdown — usa EXACTAMENTE estas secções e estes títulos, nesta ordem:\n';
  if(p.kind==='verdict'){
    s+='## Veredito: APTO ou INAPTO\n## Riscos de Nota Zero\n## Avaliação por Critério\n';
    for(const c of p.crit){ s+='### '+c[0]+'\n'; }
  }else{
    s+='## Nota Geral: X/'+p.max+'\n## Riscos de Nota Zero\n## Avaliação por Critério\n';
    for(const c of p.crit){ s+='### '+c[0]+(c[1]!=null?': X/'+redacaoFmtN21587(c[1]):'')+'\n'; }
  }
  s+='## Comentários por Parágrafo (cite o trecho)\n## Pontos Fortes\n## Pontos Fracos\n## Desvios de Norma Culta (erro → correção; no máximo 10, os mais graves e recorrentes)\n## Sugestões de Melhoria\n## Versão Reescrita\n\nREDAÇÃO ('+text.length+' chars):\n\n'+text.slice(0,30000);
  return s;
}
function redacaoBuildPrompt21575(banca,tipo,tema,text){
  if(redacaoIsEnem21575(banca)) return redacaoEnemPrompt21575(tipo,tema,text);
  const r=redacaoProfile21587(banca);
  return redacaoProfilePrompt21587(r.p,tipo,tema,text);
}
function redacaoIsEnem21575(banca){ return /^enem\b/i.test(String(banca||'')); }
function redacaoEnemPrompt21575(tipo,tema,text){
  const t=String(tema||'').trim();
  const temaBlock=t
    ? 'TEMA OFICIAL DA REDAÇÃO: "'+t+'"\nAvalie C2 e C3 em relação a ESTE tema: abordagem completa de todos os termos-chave, sem fuga nem tangenciamento.'
    : 'TEMA NÃO INFORMADO pelo aluno: identifique o tema a partir do próprio texto e declare-o na primeira linha da secção "Riscos de Anulação"; avalie C2 e C3 em relação a esse tema identificado.';
  return 'Você é um corretor de redações do ENEM treinado na matriz de referência do INEP. Corrija esta redação (tipo: '+tipo+') EXCLUSIVAMENTE pelas 5 competências oficiais do ENEM.\n\n'+temaBlock+'\n\n'+
  'GRELHA OFICIAL — cada competência vale SOMENTE um destes valores: 0, 40, 80, 120, 160 ou 200 pontos.\n'+
  'C1 — Domínio da modalidade escrita formal (norma culta): ortografia, acentuação, crase, concordância verbal e nominal, regência, pontuação, paralelismo, registro formal (sem oralidade nem gíria). 200 = domínio excelente, desvios raros e leves; 160 = poucos desvios; 120 = domínio mediano, desvios recorrentes; 80 = muitos desvios, alguns dificultam a leitura; 40 = desvios sistemáticos e graves; 0 = desconhecimento da norma culta.\n'+
  'C2 — Compreender a proposta, desenvolver o tema e repertório: abordagem COMPLETA do tema (todos os termos-chave), estrutura dissertativo-argumentativa (tese, argumentos e conclusão com proposta) e repertório sociocultural LEGITIMADO (fonte reconhecível: dado, lei, obra, facto histórico, citação), PERTINENTE e PRODUTIVO (usado para argumentar — repertório decorado, citado sem ligação ao argumento, vale no máximo 120). Tangenciamento (abordagem parcial do tema) NÃO anula, mas limita C2, C3 e C5 a no máximo 40 pontos (Cartilha do Participante do INEP).\n'+
  'C3 — Selecionar, relacionar, organizar e interpretar argumentos: projeto de texto (estratégia argumentativa visível), argumentos DESENVOLVIDOS (com explicação, exemplo ou consequência — argumento que só afirma vale pouco) e autoria (ponto de vista próprio, não senso comum repetido). 200 = projeto consistente e autoria clara; 160 = projeto com poucas falhas; 120 = projeto limitado, desenvolvimento irregular; 80 = argumentos pouco desenvolvidos; 40 = ideias justapostas, sem projeto.\n'+
  'C4 — Mecanismos linguísticos de coesão: articulação INTERparagrafal e INTRAparagrafal, referenciação (pronomes, sinônimos, elipse sem ambiguidade) e operadores variados e PRECISOS (conector decorado usado na relação lógica errada conta como uso impróprio, não como variedade). 200 = articulação excelente; 160 = boa, com poucos deslizes; 120 = repertório limitado de conectores ou usos impróprios; 80 = coesão precária; 40 = frases soltas, referenciação confusa.\n'+
  'C5 — Proposta de intervenção: exige CINCO elementos — (1) agente (quem faz), (2) ação (o que faz), (3) meio/modo (como faz), (4) efeito/finalidade (para quê) e (5) detalhamento de um dos elementos. Tem de estar ligada ao problema discutido e respeitar os direitos humanos. 200 = os 5 elementos com detalhamento; 160 = 4 elementos com detalhamento, ou 5 sem detalhamento consistente; 120 = 3 elementos (proposta vaga); 80 = 2 elementos; 40 = 1 elemento ou mera constatação ("é preciso mudar essa realidade" NÃO é proposta); 0 = sem proposta, desconectada do tema ou contra os direitos humanos.\n\n'+
  'REGRAS DA CORREÇÃO:\n'+
  '- Corrija C1 a C5 SEPARADAMENTE, sem efeito halo (texto bonito não inflaciona C3; tema bem abordado não salva C1). Em cada competência: a nota, UMA citação literal do texto do aluno que prova o nível atribuído, e UMA ação concreta para subir um nível.\n'+
  '- Situações de anulação do INEP (edital, item 14.7: fuga total ao tema ou tipo textual diferente do dissertativo-argumentativo; folha em branco; até 7 linhas manuscritas; impropérios, desenhos ou outras formas propositais de anulação; trecho deliberadamente desconectado; identificação do candidato no texto; texto predominante em língua estrangeira; letra ilegível; cópia sem pelo menos 8 linhas de produção própria — as linhas copiadas são desconsideradas da contagem). NOTA: desrespeito aos direitos humanos NÃO é anulação total nos editais actuais — é 0 na C5: estamos em MODO TREINO — NÃO zere a nota; sinalize o risco na secção própria e corrija pedagogicamente.\n'+
  '- A nota é uma ESTIMATIVA pedagógica: a nota oficial do ENEM vem de dois avaliadores humanos do INEP. Diga isto numa linha, na secção de riscos.\n\n'+
  'FORMATO Markdown — usa EXACTAMENTE estas secções e estes títulos, nesta ordem:\n'+
  '## Nota Total: XXX/1000\n'+
  '## Riscos de Anulação\n'+
  '## Avaliação por Competência\n'+
  '### C1 — Norma culta: XXX/200\n'+
  '### C2 — Tema, estrutura e repertório: XXX/200\n'+
  '### C3 — Argumentação e projeto de texto: XXX/200\n'+
  '### C4 — Coesão: XXX/200\n'+
  '### C5 — Proposta de intervenção: XXX/200 (elementos presentes: agente ✓/✗ · ação ✓/✗ · meio ✓/✗ · efeito ✓/✗ · detalhamento ✓/✗)\n'+
  '## Comentários por Parágrafo (cite o trecho)\n'+
  '## Pontos Fortes\n'+
  '## Pontos Fracos\n'+
  '## Desvios de Norma Culta (erro → correção; no máximo 10, os mais graves e recorrentes)\n'+
  '## Sugestões de Melhoria\n\n'+
  'REDAÇÃO ('+text.length+' chars):\n\n'+text.slice(0,30000);
}

// ★ v2.15.82: extracção partilhada das competências ENEM (1ª ocorrência de
// cada C1–C5 no formato "N/200") — usada pela nota e pela coerência do texto.
function redacaoEnemParts21582(resp){
  const seen={}; let sum=0, found=0;
  const re=/\bC([1-5])\b[^0-9\n]{0,60}?(\d{1,3})\s*\/\s*200/g; let mm;
  while((mm=re.exec(resp))){ if(!seen[mm[1]]){ seen[mm[1]]=1; sum+=parseInt(mm[2],10); found++; } }
  return {sum:sum, found:found};
}
// ★ v2.15.82: coerência do texto exibido/salvo — se o modelo escreveu a linha
// "## Nota Total: N/1000" com N diferente da soma das 5 competências, a linha
// é reescrita com a soma (que é a nota oficial). Sem as 5 competências
// extraíveis, ou sem a linha, o texto fica intacto.
function redacaoEnemCoerceTotal21582(respText){
  const resp=String(respText||'');
  const parts=redacaoEnemParts21582(resp);
  if(parts.found!==5) return resp;
  return resp.replace(/(#{2,3}\s*Nota\s*Total\s*:?\s*)(\d{1,4})(\s*\/\s*1000)/i,
    function(m,p1,n,p3){ return parseInt(n,10)===parts.sum ? m : p1+parts.sum+p3; });
}
function redacaoExtractScore21575(banca,respText){
  const resp=String(respText||'');
  if(redacaoIsEnem21575(banca)){
    // ★ v2.15.82: no INEP a Nota Total É a soma das 5 competências. Com as
    // cinco extraíveis, a SOMA calculada manda — o modelo pode escrever um
    // total errado no esqueleto (provado ao vivo 2026-11-23: 5×200 com
    // "Nota Total: 920/1000" → oficial 1000). O total escrito só é usado
    // quando alguma competência não for extraível.
    const parts=redacaoEnemParts21582(resp);
    if(parts.found===5) return String(parts.sum);
    const mt=resp.match(/nota\s*total\s*:?\s*(\d{1,4})\s*(?:\/\s*1000)?/i);
    if(mt) return mt[1];
    if(parts.found>=3) return String(parts.sum);
  }
  const _rp21587=redacaoProfile21587(banca);
  if(_rp21587&&_rp21587.p.kind==='verdict'){ if(/\bINAPTO\b/i.test(resp)) return 'INAPTO'; if(/\bAPTO\b/i.test(resp)) return 'APTO'; }
  const m=resp.match(/nota\s*geral\s*:?\s*(\d+[,.]?\d*)/i);
  return m?m[1]:'—';
}

async function handleRedacaoCorrect(request){
  const cors={'Access-Control-Allow-Origin':'*','Content-Type':'application/json;charset=UTF-8'};
  const user=await gdiSessionUser(request);
  if(!user)return new Response(JSON.stringify({ok:false,error:'auth'}),{status:401,headers:cors});
  let text='',banca='',tipo='',mode='',tema='';
  const ct=request.headers.get('content-type')||'';
  if(ct.includes('multipart/form-data')){
    const fd=await request.formData();
    const file=fd.get('file');
    mode=fd.get('mode')||'ocr';
    banca=fd.get('banca')||'';
    tipo=fd.get('tipo')||'';
    tema=fd.get('tema')||'';
    if(file){
      try{
        const buf=await file.arrayBuffer();
        if(file.type && file.type.startsWith('text/')){
          text=new TextDecoder().decode(buf);
        }else{
          // ★ TODO: integrar @cf/llava quando binding de visão estiver habilitado
          return new Response(JSON.stringify({ok:false,error:'OCR não disponível neste servidor. Cole o texto da redação manualmente ou habilite um modelo de visão no Cloudflare AI.'}),{status:400,headers:cors});
        }
      }catch(e){return new Response(JSON.stringify({ok:false,error:'Falha ao processar arquivo: '+e.message}),{status:400,headers:cors});}
    }
  }else{
    let body;
    try{body=await request.json();}catch(_){return new Response(JSON.stringify({ok:false,error:'invalid json'}),{status:400,headers:cors});}
    text=body.text||'';
    banca=body.banca||'';
    tipo=body.tipo||'';
    tema=body.tema||'';
  }
  if(!text||text.length<50)return new Response(JSON.stringify({ok:false,error:'Texto muito curto (mín 50 chars)'}),{status:400,headers:cors});
  const prompt=redacaoBuildPrompt21575(banca,tipo,tema,text);
  const aiResp=await callUnifiedAi([{role:'user',content:prompt}],request,{timeout:90000,retry:true}); // ★ main-port: correção longa precisa de timeout maior
  if(!aiResp.ok)return new Response(JSON.stringify({ok:false,error:aiResp.error}),{status:502,headers:cors});
  const score=redacaoExtractScore21575(banca,aiResp.response);
  if(redacaoIsEnem21575(banca)) aiResp.response=redacaoEnemCoerceTotal21582(aiResp.response); // ★ v2.15.82: texto exibido/salvo coerente com a soma (a nota oficial)
  let essaySaved = true;  // ★ v1.0.102 FIX (Agent 7 Bug 7-11): track se save do MD falhou
  try{
    const md='---\nbanca: "'+banca+'"\ntipo: "'+tipo+'"\ndata: '+new Date().toISOString()+'\nscore: '+score+(tema?'\ntema: "'+String(tema).replace(/"/g,'\\"')+'"':'')+'\n---\n\n# Redação Corrigida\n\n## Original\n\n'+text.slice(0,30000)+'\n\n## Correção\n\n'+aiResp.response+'\n';  // ★ v1.0.87 FIX BUG 1: era 4000 — perdia conteúdo da redação no MD salvo
    await gdiSaveEssayMD(request,md,banca,tipo,score);
  }catch(e){  // ★ v1.0.102 FIX (Agent 7 Bug 7-11): era catch(_){} silencioso — agora loga + marca saved:false
    console.warn('[Redacao] save failed:', e.message);
    essaySaved = false;
  }
  return new Response(JSON.stringify({ok:true,correction:aiResp.response,score,saved:essaySaved}),{headers:{...cors,'Cache-Control':'no-store'}});  // ★ v1.0.102: adicionado campo saved
}

// ── Salva MD da redação corrigida na pasta individual do aluno ──
async function gdiSaveEssayMD(request,markdown,banca,tipo,score){
  const gd0=gds[0];
  if(!gd0)return false;
  const user=await gdiSessionUser(request);
  if(!user)return false;
  const folderId=await gdiUserFolderId(gd0);
  if(!folderId)return false;
  const safeBanca=(banca||'banca').replace(/[^a-zA-Z0-9_-]/g,'_').slice(0,30);
  const dateStr=new Date().toISOString().slice(0,19).replace(/[:T]/g,'-');
  const fileName='redacao_'+safeBanca+'_'+dateStr+'_'+String(score||'s').replace(/[^0-9a-zA-Z]/g,'')+'.md';
  const q="'"+folderId+"' in parents and name = 'redacoes' and trashed = false";
  const opts=await gd0.requestOptions();
  const r=await fetch('https://www.googleapis.com/drive/v3/files?'+enQuery({includeItemsFromAllDrives:'true',supportsAllDrives:'true',q,fields:'files(id)',pageSize:'1'}),opts);
  let subId=null;
  if(r.ok){const j=await r.json();if(j.files&&j.files[0])subId=j.files[0].id;}
  if(!subId){
    const co=await gd0.requestOptions({'Content-Type':'application/json'},'POST');
    co.body=JSON.stringify({name:'redacoes',mimeType:'application/vnd.google-apps.folder',parents:[folderId]});
    const cr=await fetch('https://www.googleapis.com/drive/v3/files?supportsAllDrives=true',co);
    if(!cr.ok)return false;
    subId=(await cr.json()).id;
  }
  const boundary='gdiessay'+Date.now();
  const body='--'+boundary+'\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n'+JSON.stringify({name:fileName,parents:[subId]})+'\r\n--'+boundary+'\r\nContent-Type: text/markdown; charset=UTF-8\r\n\r\n'+markdown+'\r\n--'+boundary+'--';
  const uo=await gd0.requestOptions({'Content-Type':'multipart/related; boundary='+boundary},'POST');
  const ur=await fetch('https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&supportsAllDrives=true',{method:'POST',headers:uo.headers,body});
  return ur.ok;
}

// ═══ v1.0.220: POST /api/ai/redacao/correct-full ═══
// Aceita: multipart/form-data com file (PDF/imagem/texto) + banca + tipo
// Fluxo: 1) extrai texto (PDF→pdf.js no client, imagem→CF vision OCR, texto→direto)
//        2) corrige com LLM (callUnifiedAi)
//        3) salva MD na pasta redacoes/
//        4) retorna {ok, correction, score, text, saved, ocrUsed}
async function handleRedacaoCorrectFull(request){
  const cors={'Access-Control-Allow-Origin':'*','Content-Type':'application/json;charset=UTF-8'};
  const user=await gdiSessionUser(request);
  if(!user)return new Response(JSON.stringify({ok:false,error:'auth'}),{status:401,headers:cors});
  const ct=request.headers.get('content-type')||'';
  let text='',banca='',tipo='',fileName='',fileType='',ocrUsed=false,tema='';
  if(ct.includes('multipart/form-data')){
    const fd=await request.formData();
    const file=fd.get('file');
    banca=fd.get('banca')||'default';
    tipo=fd.get('tipo')||'dissertativa';
    tema=fd.get('tema')||'';
    if(file){
      fileName=file.name||'redacao';
      fileType=file.type||'';
      const buf=await file.arrayBuffer();
      if(fileType.startsWith('text/')){
        text=new TextDecoder().decode(buf);
      }else if(fileType.startsWith('image/')){
        // ★ OCR com CF Workers AI vision (llama-3.2-11b-vision)
        const cfAI=getAI();
        if(!cfAI||typeof cfAI.run!=='function'){
          return new Response(JSON.stringify({ok:false,error:'OCR não disponível neste servidor. O binding AI do Cloudflare não está configurado.'}),{status:503,headers:cors});
        }
        try{
          const bytes=new Uint8Array(buf);
          // ★ v2.2: OCR via resolver on-demand (role 'vision' — avança sozinho se depreciar)
          const ocrRes=await callCfAi('vision',{image:bytes,prompt:'Transcreva TODO o texto manuscrito ou digitado desta imagem de redação, preservando parágrafos e pontuação. Responda apenas com o texto transcrito, sem comentários.',max_tokens:4096});
          let ocrText=(ocrRes&&ocrRes.ok&&ocrRes.response)||'';
          if(!ocrText)console.warn('[RedacaoFull] OCR falhou:',ocrRes&&ocrRes.error);
          if(!ocrText||ocrText.length<30){
            return new Response(JSON.stringify({ok:false,error:'Não foi possível extrair texto da imagem. Tente enviar como texto ou PDF.'}),{status:400,headers:cors});
          }
          text=ocrText;
          ocrUsed=true;
        }catch(e){
          return new Response(JSON.stringify({ok:false,error:'OCR falhou: '+e.message}),{status:502,headers:cors});
        }
      }else if(fileType==='application/pdf'){
        // ★ PDF: o worker não tem pdf.js, retorna erro orientando
        return new Response(JSON.stringify({ok:false,error:'Para PDFs, use o chat da Meggy (anexar arquivo) que extrai o texto no navegador com pdf.js.'}),{status:400,headers:cors});
      }else{
        // Tentar decodificar como texto
        try{text=new TextDecoder().decode(buf);}catch(_){return new Response(JSON.stringify({ok:false,error:'Formato não suportado: '+fileType}),{status:400,headers:cors});}
      }
    }
  }else{
    let body;
    try{body=await request.json();}catch(_){return new Response(JSON.stringify({ok:false,error:'invalid json'}),{status:400,headers:cors});}
    text=body.text||'';
    banca=body.banca||'default';
    tipo=body.tipo||'dissertativa';
    tema=body.tema||'';
  }
  if(!text||text.length<50)return new Response(JSON.stringify({ok:false,error:'Texto muito curto (mín 50 chars). Envie um arquivo ou cole o texto.'}),{status:400,headers:cors});
  const prompt=redacaoBuildPrompt21575(banca,tipo,tema,text);
  const aiResp=await callUnifiedAi([{role:'user',content:prompt}],request,{timeout:90000,retry:true}); // ★ main-port: correção longa precisa de timeout maior
  if(!aiResp.ok)return new Response(JSON.stringify({ok:false,error:aiResp.error}),{status:502,headers:cors});
  const score=redacaoExtractScore21575(banca,aiResp.response);
  if(redacaoIsEnem21575(banca)) aiResp.response=redacaoEnemCoerceTotal21582(aiResp.response); // ★ v2.15.82: texto exibido/salvo coerente com a soma (a nota oficial)
  let essaySaved=true;
  try{
    const md='---\nbanca: "'+banca+'"\ntipo: "'+tipo+'"\ndata: '+new Date().toISOString()+'\nscore: '+score+(tema?'\ntema: "'+String(tema).replace(/"/g,'\\"')+'"':'')+'\nocr: '+(ocrUsed?'sim':'não')+'\n---\n\n# Redação Corrigida\n\n## Original\n\n'+text.slice(0,30000)+'\n\n## Correção\n\n'+aiResp.response+'\n';
    await gdiSaveEssayMD(request,md,banca,tipo,score);
  }catch(e){console.warn('[RedacaoFull] save failed:',e.message);essaySaved=false;}
  return new Response(JSON.stringify({ok:true,correction:aiResp.response,score,saved:essaySaved,text:text.slice(0,5000),ocrUsed,fileName}),{headers:{...cors,'Cache-Control':'no-store'}});
}

async function handleEssaySave(request){
  const cors={'Access-Control-Allow-Origin':'*','Content-Type':'application/json;charset=UTF-8'};
  const user=await gdiSessionUser(request);
  if(!user)return new Response(JSON.stringify({ok:false,error:'auth'}),{status:401,headers:cors});
  let body;
  try{body=await request.json();}catch(_){return new Response(JSON.stringify({ok:false,error:'invalid json'}),{status:400,headers:cors});}
  const md=String(body.markdown||'').slice(0,100000);
  if(!md)return new Response(JSON.stringify({ok:false,error:'no markdown'}),{status:400,headers:cors});
  const ok=await gdiSaveEssayMD(request,md,body.banca||'',body.tipo||'',body.score||'');
  return new Response(JSON.stringify({ok}),{status:ok?200:502,headers:cors});
}

// ── Helper: chama AI unificada (Meggy/NVIDIA/OpenAI/CF) — wrapper ──

// ═══════════════════════════════════════════════════════════════════════
// ★ v2.2 MEGGY / CF WORKERS AI — RESOLUÇÃO ON-DEMAND POR FUNÇÃO
// A Meggy usa por padrão as IAs gratuitas do Cloudflare (binding `ai`,
// sem chave). Os nomes dos modelos NÃO são fixos no código de chamada:
// cada função ('text', 'chat', 'resumo', 'questoes', 'matematica',
// 'vision', 'ocr') tem uma lista ordenada de candidatos gratuitos;
// resolveCfModel() devolve o modelo atualmente saudável (cache KV 24h em
// cfmodel:<role>) e, se ele falhar por depreciação/remoção, callCfAi()
// avança sozinho para o próximo da lista e atualiza o cache — nenhum
// deploy é necessário quando um modelo sai de linha. Mesmo padrão do
// auto-discovery da NVIDIA (v1.0.187), aplicado ao Workers AI.
// Provedores externos (NVIDIA/Groq/Zhipu/OpenRouter/OpenAI/LLM7/
// Pollinations) continuam como fallback, DEPOIS do CF.
// ═══════════════════════════════════════════════════════════════════════
const CF_MODELS_BY_ROLE = {
  text:       ['@cf/meta/llama-3.3-70b-instruct-fp8-fast', '@cf/meta/llama-3.1-8b-instruct-fp8', '@cf/meta/llama-3.2-3b-instruct', '@cf/qwen/qwen2.5-7b-instruct', '@cf/google/gemma-3-12b-it'],
  chat:       ['@cf/meta/llama-3.1-8b-instruct-fp8', '@cf/meta/llama-3.2-3b-instruct', '@cf/meta/llama-3.2-1b-instruct', '@cf/meta/llama-4-scout-17b-16e-instruct'],
  resumo:     ['@cf/meta/llama-3.1-70b-instruct', '@cf/meta/llama-4-scout-17b-16e-instruct', '@cf/meta/llama-3.2-3b-instruct'],
  questoes:   ['@cf/qwen/qwq-32b', '@cf/meta/llama-3.1-70b-instruct', '@cf/qwen/qwen2.5-coder-32b-instruct'],
  matematica: ['@cf/deepseek-ai/deepseek-r1-distill-qwen-32b', '@cf/qwen/qwq-32b', '@cf/meta/llama-3.1-70b-instruct'],
  vision:     ['@cf/meta/llama-3.2-11b-vision-instruct', '@cf/meta/llama-3.2-17b-vision-instruct', '@cf/llava-hf/llava-1.5-7b-hf'],
  ocr:        ['@cf/meta/llama-3.1-8b-instruct-fp8', '@cf/meta/llama-3.2-3b-instruct', '@cf/meta/llama-3.2-1b-instruct'],
};
const CF_MODEL_CACHE_TTL = 86400; // 24h
function cfModelKv(){ try{ if(typeof meggyKvBinding==='function'){ const kv=meggyKvBinding(); if(kv) return kv; } }catch(_){} try{ return (typeof globalThis.MEGGY_CACHE!=='undefined'&&globalThis.MEGGY_CACHE)||null; }catch(_){ return null; } }
function cfModelIsGone(e){ const m=String((e&&e.message)||e||''); return /deprecat|not found|unknown model|no such model|does not exist|5028|\b410\b|\b404\b/i.test(m); }
// ★ v2.15.13-D1a-falha-permanente-vs-transitoria: o loop CF do runBackend
//   marcava QUALQUER exceção como morta por 1h (ver D1b) — um 502
//   transitório do qwq-32b bastava p/ o tirar de jogo por 1 hora, e numa
//   tempestade de geração em cadeia os 3 modelos de 'questoes' podiam
//   ficar todos mortos (Passo 17: Questões 0/3, HTTP 502). Só é
//   PERMANENTE o que o modelo nunca mais vai resolver sozinho: modelo
//   removido/depreciado (cfModelIsGone: 410/404/deprecat/...) ou auth
//   (401/403). Transitório é tudo o resto: 502/503/429/timeout/rede/
//   resposta vazia — o modelo volta a estar saudável minutos depois.
function cfModelFailureKind(e){ const m=String((e&&e.message)||e||''); if(/HTTP 401|HTTP 403/i.test(m)) return 'permanent'; if(cfModelIsGone(e)) return 'permanent'; return 'transient'; }
// ★ v2.15.15-A1a-guarda-8192-formas-reais: a guarda Q3d só casava 4 formas
//   (/max_tokens|too many tokens|token.*(limit|exceed)|exceed.*token/) —
//   NENHUMA casa a forma documentada da rejeição real do Workers AI:
//   "max_completion_tokens is too large: 1310720. This model supports at
//   most 1048576 completion tokens." ("max_completion_tokens" NÃO contém
//   "max_tokens"; "supports at most" NÃO contém limit/exceed). Se o CF
//   rejeitar 8192 com essa redação, o retry p/ 4096 nunca dispara e o
//   modelo é declarado falhado — o CF sai de jogo p/ questoes em TODA a
//   request (Passo 19: 3x 502). A lista passa a casar as formas
//   documentadas (max_completion_tokens, too large, supports at most,
//   max output) e o erro 3007/timeout, cujo remédio documentado é
//   também "Lower max_tokens" (uma saída de 8192 tokens num modelo de
//   raciocínio 32B/70B pode exceder o tempo da plataforma).
function cfShouldRetry4096(e){ const m=String((e&&e.message)||e||''); return /max_tokens|max_completion_tokens|too many tokens|too large|supports at most|token.*(limit|exceed)|exceed.*token|max output|\b3007\b|timeout|timed out/i.test(m); }
// ★ v2.15.15-A2a-cota-diaria-3036: um 429 do Workers AI com código 3036
//   NÃO é transitório de 60 s — é a cota diária gratuita de 10.000
//   Neurons esgotada, que só volta às 00:00 UTC. A D1d marcava-o como
//   'transient' (60 s) e o código voltava a tentar a cada minuto o dia
//   inteiro, sempre a falhar, e a reportar um 502 genérico. Detetado
//   à parte (A2b/A2c) com TTL até à meia-noite UTC e mensagem própria.
function cfQuotaError(e){ const m=String((e&&e.message)||e||''); return /3036|\bquota\b|daily.*neuron|neuron.*(exhaust|limit|quota)|free.*allowance/i.test(m); }
function secondsToMidnightUTC(){ const n=new Date(); return Math.max(60, 86400-(n.getUTCHours()*3600+n.getUTCMinutes()*60+n.getUTCSeconds())); }
function _cfModelMem(){ return globalThis.__cfModelMem || (globalThis.__cfModelMem = {}); } // ★ v2.15.43 (CF-6): cache em memória do isolate (60s) p/ cfmodel:* — lazy em globalThis (sem declaração de módulo; extracções/harnesses podem reiniciá-lo)
async function resolveCfModel(role){
  const list=CF_MODELS_BY_ROLE[role]||CF_MODELS_BY_ROLE.text;
  const _mem=_cfModelMem()[role];
  if(_mem && (Date.now()-_mem.at)<60000 && list.includes(_mem.model)) return _mem.model;
  const kv=cfModelKv();
  if(kv){ try{ const hit=await kv.get('cfmodel:'+role); if(hit&&list.includes(hit)){ _cfModelMem()[role]={model:hit,at:Date.now()}; return hit; } }catch(_){} }
  return list[0];
}
async function cfModelNoteGood(role,model){
  // ★ v2.15.43 (CF-7): só escreve quando o modelo MUDA — antes era
  //   1 put por chamada CF bem-sucedida (quota de escrita KV: 1.000/dia).
  const _mem=_cfModelMem()[role];
  if(_mem && _mem.model===model){ _mem.at=Date.now(); return; }
  _cfModelMem()[role]={model:model,at:Date.now()};
  const kv=cfModelKv(); if(!kv) return;
  try{ await kv.put('cfmodel:'+role,model,{expirationTtl:CF_MODEL_CACHE_TTL}); }catch(_){}
}
// ★ v2.4: resposta degenerada (curta demais ou texto de erro) NÃO é sucesso:
//   avança para o próximo modelo em vez de devolver lixo e travar o retry no
//   mesmo modelo (o resolver marcava o modelo como bom por 24h). skipModels
//   (ex.: do retry do edital) pula modelos que já falharam. Um "ok" com lixo
//   bloqueava os fallbacks da cascata.
function cfRespIsDegenerate(t){
  const s=String(t||'').trim();
  if(s.length<20) return true;
  return /^(error|erro|unauthorized|forbidden|rate limit|too many requests|bad request|service unavailable|model .* (not found|does not exist|unknown))/i.test(s);
}
async function callCfAi(role,params,skipModels){
  const ai=(typeof getAI==='function')?getAI():null;
  if(!ai||typeof ai.run!=='function') return {ok:false,error:'CF AI binding ausente'};
  const list=CF_MODELS_BY_ROLE[role]||CF_MODELS_BY_ROLE.text;
  const skip=new Set((skipModels||[]).map(function(m){ return String(m||'').replace(/^cf:/,''); }));
  const first=await resolveCfModel(role);
  const order=[first].concat(list.filter(function(m){ return m!==first; })).filter(function(m){ return !skip.has(m); });
  if(!order.length) return {ok:false,error:'CF AI falhou: todos os modelos pulados'};
  const errors=[];
  for(const m of order){
    try{
      const r=await ai.run(m,params);
      const text=(r&&(r.response||(r.result&&r.result.response)))||'';
      if(text && !cfRespIsDegenerate(text)){ await cfModelNoteGood(role,m); return {ok:true,response:text,model:'cf:'+m}; }
      errors.push(m+': resposta degenerada ('+String(text||'').trim().length+' chars)');
    }catch(e){ errors.push(m+': '+(((typeof cfQuotaError==='function')&&cfQuotaError(e))?'cota diária gratuita esgotada (3036) — volta às 00:00 UTC':e.message)); /* ★ v2.15.15-A2c-cota-diaria-callCfAi (ver A2a) ★ v2.15.13-D2-callCfAi-continua: o break antigo parava a lista após o PRIMEIRO modelo em QUALQUER erro transitório (502/503/timeout) — a cascata CF morria sem tentar os outros 2-4 modelos gratuitos da lista (callUnifiedAi/batalhão caíam logo p/ os externos ou falhavam). Agora continua sempre p/ o próximo modelo, permanente ou transitório: o modelo "gone" também não serve, e o transitório pode ser só desse modelo. */ }
  }
  return {ok:false,error:'CF AI falhou: '+errors.join('; ')};
}

// ★ v2.2: extração robusta de JSON array da resposta da IA.
// O parse antigo usava regex gulosa + JSON.parse direto: se a IA truncasse
// a resposta (max_tokens) no meio de uma string, o erro era "Unterminated
// string in JSON" e o concurso ficava sem disciplinas. Agora: localiza o
// primeiro '[', faz scan balanceado respeitando strings/escapes; se a
// resposta estiver truncada, tenta reparar fechando string/array abertos e
// descartando o último item incompleto; valida que o resultado é um array
// não-vazio de objetos (validador opcional por item).
function extractAiJsonArray(text,isValidItem){
  if(!text) return null;
  const valid=isValidItem||function(it){ return it&&typeof it==='object'&&typeof it.nome==='string'; };
  const isValid=function(v){ return Array.isArray(v)&&v.length>0&&v.every(valid); };
  const tryParse=function(str){ try{ const v=JSON.parse(str); return isValid(v)?v:null; }catch(_){ return null; } };
  let s=String(text).replace(/```(?:json)?\s*/gi,'').replace(/```/g,'');
  const start=s.indexOf('[');
  if(start<0) return null;
  const scan=function(str){
    const stack=[]; let inStr=false,esc=false;
    for(let i=0;i<str.length;i++){
      const c=str[i];
      if(inStr){ if(esc)esc=false; else if(c==='\\')esc=true; else if(c==='"')inStr=false; continue; }
      if(c==='"')inStr=true;
      else if(c==='['||c==='{')stack.push(c);
      else if(c===']'||c==='}'){
        const open=stack.pop();
        if((c===']'&&open!=='[')||(c==='}'&&open!=='{')) return {bad:true};
        if(stack.length===0) return {end:i,stack:stack,inStr:false};
      }
    }
    return {end:-1,stack:stack,inStr:inStr};
  };
  const full=scan(s.slice(start));
  if(full.end>0){ const v=tryParse(s.slice(start,start+full.end+1)); if(v) return v; }
  if(full.bad) return null;
  let fixed=s.slice(start);
  const st=scan(fixed);
  if(st.bad) return null;
  if(st.inStr) fixed+='"';
  const closers={'[':']','{':'}'};
  for(let i=st.stack.length-1;i>=0;i--) fixed+=closers[st.stack[i]];
  const v=tryParse(fixed); if(v) return v;
  for(let k=0;k<8;k++){
    const idx=fixed.lastIndexOf('},');
    if(idx<0) break;
    fixed=fixed.slice(0,idx+1)+']';
    const v2=tryParse(fixed); if(v2) return v2;
  }
  const m=s.match(/\[[\s\S]*\]/);
  if(m){ const v3=tryParse(m[0]); if(v3) return v3; }
  return null;
}

async function callUnifiedAi(messages,request,opts){
  const errors=[];
  // ★ v1.0.224-port (main): opts {timeout, retry} — timeout default 45000; retry aceite (no main é parseado mas sem uso no corpo, mantido igual)
  const timeout=opts&&opts.timeout||45000;
  const retry=opts&&opts.retry||false;
  const maxTokens=opts&&opts.maxTokens||4096;
  // ★ v2.2: CF Workers AI (grátis, binding `ai`) é o PADRÃO — primeiro, com
  // resolução on-demand por função (resolveCfModel avança sozinho se o modelo depreciar).
  try{
    const cf=await callCfAi((opts&&opts.role)||'text',{messages,max_tokens:maxTokens},(opts&&opts.skipModels)||null);
    if(cf&&cf.ok)return {ok:true,response:cf.response,model:cf.model};
    errors.push(cf?('CF: '+cf.error):'CF: sem resposta');
  }catch(e){errors.push('CF: '+e.message);}

  // ★ v1.0.194: modelos atualizados — antes usava @cf/meta/llama-3.1-8b-instruct (deprecated 5028) + NVIDIA meta/llama-3.1-8b (410)
  // ★ 1ª tentativa: OpenRouter em paralelo (race entre modelos free)
  if(globalThis.OPENROUTER_API_KEY){
    try{
      const r = await callOpenRouterParallel(messages, {models: ['google/gemini-flash-1.5','mistralai/mistral-7b-instruct:free','qwen/qwen-2.5-7b-instruct:free']});
      if(r && r.content) return {ok:true, response:r.content, model:r.model};
      errors.push('OpenRouter: sem resposta vencedora');
    }catch(e){errors.push('OpenRouter: '+e.message);}
  }
  // ★ v1.0.194: Pollinations (free, sem key) — adicionado como 2ª tentativa
  try{
    const ctrl=new AbortController();const to=setTimeout(()=>ctrl.abort(),timeout);
    const r=await fetch('https://text.pollinations.ai/openai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({model:'openai',messages,max_tokens:maxTokens,temperature:0.6,stream:false}),signal:ctrl.signal});
    clearTimeout(to);
    if(r.ok){const d=await r.json();if(d.choices&&d.choices[0]&&d.choices[0].message&&d.choices[0].message.content)return {ok:true,response:d.choices[0].message.content,model:'pollinations:openai'};}
    errors.push('Pollinations HTTP '+r.status);
  }catch(e){errors.push('Pollinations: '+e.message);}
  // ★ v2.2: LLM7 (free, sem cadastro — chave literal 'unused', OpenAI-compatible).
  // Fontes com probe ao vivo (ago/2026): anônimo, ~30 RPM. Best-effort: se falhar,
  // a cascata continua nos próximos backends. Mantém NVIDIA/OpenRouter como backends com chave.
  try{
    const ctrl=new AbortController();const to=setTimeout(()=>ctrl.abort(),timeout);
    const r=await fetch('https://api.llm7.io/v1/chat/completions',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer unused'},body:JSON.stringify({model:'gpt-oss-20b',messages,max_tokens:maxTokens,temperature:0.6,stream:false}),signal:ctrl.signal});
    clearTimeout(to);
    if(r.ok){const d=await r.json();if(d.choices&&d.choices[0]&&d.choices[0].message&&d.choices[0].message.content)return {ok:true,response:d.choices[0].message.content,model:'llm7:gpt-oss-20b'};}
    errors.push('LLM7 HTTP '+r.status);
  }catch(e){errors.push('LLM7: '+e.message);}

  // ★ v1.0.194: Groq (2 keys, round-robin) — 3ª tentativa
  const groqKeys=[];
  if(globalThis.GROQ_API_KEY)groqKeys.push(globalThis.GROQ_API_KEY);
  if(globalThis.GROQ_API_KEY_2)groqKeys.push(globalThis.GROQ_API_KEY_2);
  for(const gk of groqKeys){
    try{
      const ctrl=new AbortController();const to=setTimeout(()=>ctrl.abort(),timeout);
      const r=await fetch('https://api.groq.com/openai/v1/chat/completions',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+gk},body:JSON.stringify({model:'llama-3.3-70b-versatile',messages,max_tokens:maxTokens,temperature:0.6,stream:false}),signal:ctrl.signal});
      clearTimeout(to);
      if(r.ok){const d=await r.json();if(d.choices&&d.choices[0]&&d.choices[0].message&&d.choices[0].message.content)return {ok:true,response:d.choices[0].message.content,model:'groq:llama-3.3-70b'};}
      errors.push('Groq HTTP '+r.status);
    }catch(e){errors.push('Groq: '+e.message);}
  }
  if(globalThis.ZHIPU_API_KEY){
    let to;
    try{
      const ctrl=new AbortController();to=setTimeout(()=>ctrl.abort(),timeout);
      const r=await fetch('https://open.bigmodel.cn/api/paas/v4/chat/completions',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+globalThis.ZHIPU_API_KEY},body:JSON.stringify({model:globalThis.AI_MODEL||'glm-4-flash',messages,max_tokens:maxTokens,temperature:0.6,stream:false}),signal:ctrl.signal});
      if(r.ok){const d=await r.json();if(d.choices&&d.choices[0]&&d.choices[0].message)return {ok:true,response:d.choices[0].message.content};
      }
      errors.push('Meggy HTTP '+r.status);
    }catch(e){errors.push('Meggy: '+e.message);}
    finally{ if(to) clearTimeout(to); }
  }
  if(globalThis.NVIDIA_API_KEY){
    // ★ v1.0.194: modelos NVIDIA atualizados (antes: meta/llama-3.1-8b-instruct = 410 deprecated)
    const nvidiaModels=['nvidia/nemotron-3-ultra-550b-a55b','openai/gpt-oss-20b','deepseek-ai/deepseek-v4.1-flash'];
    for(const nm of nvidiaModels){
      let to;
      try{
        const ctrl=new AbortController();to=setTimeout(()=>ctrl.abort(),timeout);
        const r=await fetch('https://integrate.api.nvidia.com/v1/chat/completions',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+globalThis.NVIDIA_API_KEY},body:JSON.stringify({model:nm,messages,max_tokens:maxTokens,temperature:0.6,stream:false}),signal:ctrl.signal});
        if(r.ok){const d=await r.json();const msg=d.choices&&d.choices[0]&&d.choices[0].message;if(msg&&(msg.content||msg.reasoning_content))return {ok:true,response:msg.content||msg.reasoning_content};}
        errors.push('NVIDIA '+nm+': HTTP '+r.status);
      }catch(e){errors.push('NVIDIA '+nm+': '+e.message);}
      finally{ if(to) clearTimeout(to); }
    }
  }
  if(globalThis.OPENAI_API_KEY){
    const url=globalThis.OPENAI_API_URL||'https://api.openai.com/v1/chat/completions';
    let to;
    try{
      const ctrl=new AbortController();to=setTimeout(()=>ctrl.abort(),timeout);
      const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+globalThis.OPENAI_API_KEY},body:JSON.stringify({model:globalThis.AI_MODEL||'gpt-4o-mini',messages,max_tokens:maxTokens,temperature:0.6,stream:false}),signal:ctrl.signal});
      if(r.ok){const d=await r.json();if(d.choices&&d.choices[0]&&d.choices[0].message)return {ok:true,response:d.choices[0].message.content};
      }
      errors.push('OpenAI HTTP '+r.status);
    }catch(e){errors.push('OpenAI: '+e.message);}
    finally{ if(to) clearTimeout(to); }
  }
  return {ok:false,error:'Todos os backends falharam: '+errors.join('; ')};
}

// ═══ FLASHCARDS COMPARTILHADOS — pool entre alunos da mesma matéria ═══
const ISA_SHARED_FC_FILE='isa_shared_flashcards.json';
async function gdiSharedFlashcardsRead(gd0,folderId){
  const q="'"+folderId+"' in parents and name = '"+ISA_SHARED_FC_FILE+"' and trashed = false";
  const opts=await gd0.requestOptions();
  const r=await fetch('https://www.googleapis.com/drive/v3/files?'+enQuery({includeItemsFromAllDrives:'true',supportsAllDrives:'true',q,fields:'files(id)',pageSize:'1'}),opts);
  if(!r.ok)return [];
  const j=await r.json();
  if(!j.files||!j.files[0])return [];
  const fr=await fetch("https://www.googleapis.com/drive/v3/files/"+j.files[0].id+"?alt=media&supportsAllDrives=true",opts);
  if(!fr.ok)return [];
  try{const arr=JSON.parse(await fr.text());return Array.isArray(arr)?arr:[];}catch(_){return [];}
}

