      const q=await _d1.prepare("SELECT author, COUNT(*) as n FROM shared_flashcards WHERE statement IS NOT NULL GROUP BY author").all();
      const map={};
      (s.results||[]).forEach(r=>{ if(!r.author)return; map[r.author]=map[r.author]||{author:r.author,summaries:0,flashcards:0,questions:0}; map[r.author].summaries+=r.n||0; });
      (f.results||[]).forEach(r=>{ if(!r.author)return; map[r.author]=map[r.author]||{author:r.author,summaries:0,flashcards:0,questions:0}; map[r.author].flashcards+=r.n||0; });
      (q.results||[]).forEach(r=>{ if(!r.author)return; map[r.author]=map[r.author]||{author:r.author,summaries:0,flashcards:0,questions:0}; map[r.author].questions+=r.n||0; });
      const _byRole21563={};
