        const authors=Array.from(Object.values(_byRoleF21563)).sort(function(a,b){ return String(a.author).localeCompare(String(b.author),'pt-BR'); });  // ★ v2.15.63: idem, por PAPEL
        return new Response(JSON.stringify({ok:true,authors:authors,fallback:true}),{headers:cors});
