  let coursePath = (url.searchParams.get('coursePath') || '').trim().slice(0, 500);
  let lessonName = (url.searchParams.get('lessonName') || '').trim().slice(0, 200);
  if(!lessonName && coursePath){
    const seg = coursePath.split('/').filter(Boolean);
    if(seg.length > 1 && /\.[a-z0-9]{2,5}$/i.test(seg[seg.length - 1])){ lessonName = seg[seg.length - 1]; coursePath = '/' + seg.slice(0, -1).join('/'); }
  }
  if(!lessonName) return new Response(JSON.stringify({ok:false, error:'no lessonName', reason:'missing_lesson'}), {status:400, headers:cors});
  const normLesson21589 = lessonName.replace(/\.[a-z0-9]{2,5}$/i, '').trim().toLowerCase();
  const likeEsc21589 = function(s){ return String(s || '').replace(/[%_]/g, '\\$&'); };
