          const _srcLike = '%' + likeEsc21589(lessonName.replace(/\.[a-z0-9]{2,5}$/i, '')) + '%';
          const _all = await _d1b.prepare('SELECT subject, front, back, statement, options, correct, type, explanation, legal_text, fundamentacao, topic, source, date FROM shared_flashcards WHERE statement IS NOT NULL AND source LIKE ? ESCAPE "\\" ORDER BY date DESC LIMIT 200').bind(_srcLike).all();
          bankRows = _all.results || [];
