const USERS_REGISTRY_FILE = '.gdi_users.json';

// ★ v2.15.43 (SEC-6): rate-limit de login por utilizador+IP (KV) —
//   10 falhas / 15 min => 429. Só FALHAS contam; o sucesso limpa.
//   Sem KV, fica desactivado (fail-open como o resto da plataforma).
const LOGIN_FAIL_MAX = 10;
const LOGIN_FAIL_TTL_S = 900;
async function loginFailCount(key){
  try{ const kv = (typeof meggyKvBinding === 'function') ? meggyKvBinding() : null; if(!kv) return 0;
    const raw = await kv.get('loginfail:' + key); const n = raw ? Number(raw) : 0; return isFinite(n) ? n : 0;
  }catch(_){ return 0; }
}
async function loginFailNote(key){
  try{ const kv = (typeof meggyKvBinding === 'function') ? meggyKvBinding() : null; if(!kv) return;
    const n = (await loginFailCount(key)) + 1;
    await kv.put('loginfail:' + key, String(n), { expirationTtl: LOGIN_FAIL_TTL_S });
  }catch(_){}
}
async function loginFailClear(key){
  try{ const kv = (typeof meggyKvBinding === 'function') ? meggyKvBinding() : null; if(!kv) return; await kv.delete('loginfail:' + key); }catch(_){}
}
function loginRateKey(request, username){
  let ip = '';
  try{ ip = (request.headers.get('cf-connecting-ip') || request.headers.get('x-forwarded-for') || '').split(',')[0].trim(); }catch(_){}
  return String(username || '').toLowerCase() + '|' + ip;
}
async function hashPassword(password, salt) {
  const enc = new TextEncoder();
  const buf = await crypto.subtle.digest('SHA-256', enc.encode(salt + ':' + password));
  return Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, '0')).join('');
}

async function gdiRegistryFolderId() {
  if (globalThis.__regFolderId) return globalThis.__regFolderId;
  const parentId = (authConfig.roots[USERSTATE_PARENT_DRIVE] || authConfig.roots[0]).id;
  const q = `'${parentId}' in parents and name = '${USERSTATE_FOLDER}' and trashed = false`;
  const opts = await drive.requestOptions();
  const lr = await fetch('https://www.googleapis.com/drive/v3/files?' + enQuery({ includeItemsFromAllDrives: 'true', supportsAllDrives: 'true', q, fields: 'files(id)', pageSize: '1' }), opts);
  if (lr.ok) {
    const lj = await lr.json();
    if (lj.files && lj.files[0]) { globalThis.__regFolderId = lj.files[0].id; return globalThis.__regFolderId; }
  }
  const cOpts = await drive.requestOptions({ 'Content-Type': 'application/json' }, 'POST');
  cOpts.body = JSON.stringify({ name: USERSTATE_FOLDER, mimeType: 'application/vnd.google-apps.folder', parents: [parentId] });
  const cr = await fetch('https://www.googleapis.com/drive/v3/files?supportsAllDrives=true', cOpts);
  if (!cr.ok) return null;
  const cj = await cr.json();
  globalThis.__regFolderId = cj.id || null;
  return globalThis.__regFolderId;
}

async function gdiRegistryFileId(folderId) {
  const q = `'${folderId}' in parents and name = '${USERS_REGISTRY_FILE}' and trashed = false`;
  const opts = await drive.requestOptions();
  const r = await fetch('https://www.googleapis.com/drive/v3/files?' + enQuery({ includeItemsFromAllDrives: 'true', supportsAllDrives: 'true', q, fields: 'files(id)', pageSize: '1' }), opts);
  if (!r.ok) return null;
  const j = await r.json();
  return (j.files && j.files[0]) ? j.files[0].id : null;
}

async function gdiLoadDynamicUsers() {
  if (globalThis.__dynUsers && globalThis.__dynUsersAt && (Date.now() - globalThis.__dynUsersAt) < 60000) return globalThis.__dynUsers;
  // ★ v2.2: novos alunos no D1 (tabela users). O registro no Drive vira fallback legado.
  const d1 = meggyD1Binding();
  if (d1) {
    try {
      await d1EnsureSchema();
      const res = await d1.prepare('SELECT username, salt, password_hash, created FROM users ORDER BY created ASC').all();
      const rows = (res.results || []).map(r => ({ username: r.username, salt: r.salt, password_hash: r.password_hash, created: r.created }));
      if (rows.length) { globalThis.__dynUsers = rows; globalThis.__dynUsersAt = Date.now(); return rows; }
      // D1 vazio: migra 1x os usuários do registro legado no Drive (sem apagar o Drive).
      // ★ v2.15.29-C: FALLBACK ÚNICO E MARCADO (login) — seed 1x, só quando
      //   o D1 existe mas está vazio; depois disso o Drive nunca mais é lido.
      if (!globalThis.__dynUsersMigrated) {
        globalThis.__dynUsersMigrated = true;
        try {
          const legacy = await gdiLoadDynamicUsersFromDrive();
          if (legacy.length) {
            for (const u of legacy) { try { await d1.prepare('INSERT OR IGNORE INTO users (username, salt, password_hash, created) VALUES (?,?,?,?)').bind(u.username, u.salt, u.password_hash, u.created || Date.now()).run(); } catch (_) {} }
            globalThis.__dynUsers = legacy; globalThis.__dynUsersAt = Date.now();
            return legacy;
          }
        } catch (_) {}
      }
    } catch (_) {}
  }
  // ★ v2.15.29-C: CORTE D1 — sem D1 não há fallback silencioso p/ o Drive.
  console.warn('[v2.15.29-C] gdiLoadDynamicUsers sem D1 — 0 usuários dinâmicos');
  globalThis.__dynUsers = globalThis.__dynUsers || [];
  globalThis.__dynUsersAt = Date.now();
  return globalThis.__dynUsers;
}
async function gdiLoadDynamicUsersFromDrive() {
  try {
    const folderId = await gdiRegistryFolderId();
    if (!folderId) return globalThis.__dynUsers || [];
    const fileId = await gdiRegistryFileId(folderId);
    let users = [];
    if (fileId) {
      const opts = await drive.requestOptions();
      const r = await fetch(`https://www.googleapis.com/drive/v3/files/${fileId}?alt=media&supportsAllDrives=true`, opts);
      if (r.ok) { const j = await r.json(); if (j && Array.isArray(j.users)) users = j.users; }
    }
    return users;
  } catch (_) { return globalThis.__dynUsers || []; }
}

async function gdiSaveDynamicUsers(users) {
  // ★ v2.2: salva no D1; se o D1 falhar, cai para o Drive (comportamento anterior).
  const d1 = meggyD1Binding();
  if (d1) {
    try {
      await d1EnsureSchema();
      await d1.prepare('DELETE FROM users').run();
      for (const u of (users || [])) {
        await d1.prepare('INSERT OR REPLACE INTO users (username, salt, password_hash, created) VALUES (?,?,?,?)').bind(u.username, u.salt, u.password_hash, u.created || Date.now()).run();
      }
      globalThis.__dynUsers = users; globalThis.__dynUsersAt = 0;
      return true;
    } catch (e) { console.warn('[Users] D1 save falhou:', e.message); }
  }
  // ★ v2.15.29-C: CORTE D1 — sem escrita do registro de usuários no
  //   Drive. Falha no D1 = falha no save (o chamador decide); o arquivo
  //   legado no Drive fica intocado.
  return false;
}

async function gdiVerifyUser(username, password) {
  // ★ Versão pública: SÓ o D1 autentica. Não há usuário-semente em
  //   código: os usuários de demonstração vivem no D1 (ver
  //   demoUsersSeed) e morrem quando o deployer os apaga no painel.
  //   Hash só corre quando o usuário existe (sem oráculo de timing p/
  //   usuário inexistente).
  const dyn = await gdiLoadDynamicUsers();
  const u = dyn.find(x => x.username === username);
  if (u) {
    const h = await hashPassword(password, u.salt || '');
    return h === u.password_hash;
  }
  return false;
}


async function gdiUsernameExists(username) {
  if (authConfig.users_list.some(u => u.username === username)) return true;
  const dyn = await gdiLoadDynamicUsers();
  return dyn.some(u => u.username === username);
}
