async function admDeleteUser(username) {
  if (!username || !/^[a-zA-Z0-9@._-]{1,200}$/.test(username)) throw new Error('username inválido');
  const d1 = meggyD1Binding();
  const env = (typeof globalThis.ENV !== 'undefined' && globalThis.ENV) ? globalThis.ENV : null;
  const out = { username, deleted: { user_courses: 0, shared_summaries: 0, shared_flashcards: 0, history_watched: 0, history_events: 0, history_migrations: 0, env_keys: [] } };
  if (d1) {
    await d1EnsureSchema();
    let r;
    try { r = await d1.prepare('DELETE FROM user_courses WHERE username = ?').bind(username).run(); out.deleted.user_courses = (r && r.meta && r.meta.changes) || 0; } catch (_) {}
    try { r = await d1.prepare('DELETE FROM shared_summaries WHERE author = ?').bind(username).run(); out.deleted.shared_summaries = (r && r.meta && r.meta.changes) || 0; try{ await d1PeerMirrorOps21563([{ id: fbOpId(), ts: Date.now(), table: 'shared_summaries', action: 'delete', key: { author: username } }]); }catch(_){} } catch (_) {}  // ★ v2.15.63: delete dual
    try { r = await d1.prepare('DELETE FROM shared_flashcards WHERE author = ?').bind(username).run(); out.deleted.shared_flashcards = (r && r.meta && r.meta.changes) || 0; try{ await d1PeerMirrorOps21563([{ id: fbOpId(), ts: Date.now(), table: 'shared_flashcards', action: 'delete', key: { author: username } }]); }catch(_){} } catch (_) {}  // ★ v2.15.63: delete dual
    try { r = await d1.prepare('DELETE FROM user_watched WHERE username = ?').bind(username).run(); out.deleted.history_watched = (r && r.meta && r.meta.changes) || 0; } catch (_) {}
    try { r = await d1.prepare('DELETE FROM user_history_events WHERE username = ?').bind(username).run(); out.deleted.history_events = (r && r.meta && r.meta.changes) || 0; } catch (_) {}
    try { r = await d1.prepare('DELETE FROM history_migrations WHERE username = ?').bind(username).run(); out.deleted.history_migrations = (r && r.meta && r.meta.changes) || 0; } catch (_) {}
  }
  if (env) {
    for (const k of [username, username + '_session', username + '_ip']) {
      try { await env.delete(k); out.deleted.env_keys.push(k); } catch (_) {}
    }
  }
  out.ok = true;
  return out;
}

