// ─── backup (export / restore D1) ───────────────────────────────────────────
async function admExportD1() {
  const d1 = meggyD1Binding();
  if (!d1) return { ok: false, error: 'D1 não vinculado' };
  try{ await d1EnsureSchema(); }catch(_){}
  const out = { ok: true, exportedAt: new Date().toISOString(), tables: {}, totals: {} };
  for (const t of ['lessons', 'shared_summaries', 'shared_flashcards', 'user_courses', 'materials_meta']) {
    try {
      const r = await d1.prepare('SELECT * FROM ' + t).all();
      out.tables[t] = r.results || [];
      out.totals[t] = (r.results || []).length;
    } catch (e) {
      const _s = await loadTableSnapshot(t);
      if (_s) { out.tables[t] = _s; out.totals[t] = _s.length; out.fallback = true; }
      else {
        out.tables[t] = [];
        out.totals[t] = -1;
        out['_' + t + '_error'] = String(e.message || e).slice(0, 200);
      }
    }
  }
  return out;
}

async function admRestoreD1(payload) {
  const d1 = meggyD1Binding();
  if (!d1) return { ok: false, error: 'D1 não vinculado' };
  if (!payload || !payload.tables) return { ok: false, error: 'payload inválido (esperado {tables:{...}})' };
  await d1EnsureSchema();
  const restored = {};
  const errors = [];
  const colSpec = {
    lessons: ['id','course_hash','course_path','lesson_path','lesson_name','lesson_type','mime_type','ext','size','drive_index','parent_folder_path','has_summary','has_questions','has_flashcards','has_simulado','has_pilulas','scanned_at','created_at','updated_at'],
    shared_summaries: ['id','lesson_name','summary','questions','author','course_path','date'],
    shared_flashcards: ['id','subject','front','back','statement','options','correct','explanation','legal_text','fundamentacao','type','author','date','topic','source','qfp'],
    user_courses: ['id','username','course_path','course_name','pdf_count','icon','color','added_at'],
    materials_meta: ['id','course_hash','lesson_path','material_type','file','generated_at','generated_by']
  };
  for (const t of Object.keys(colSpec)) {
    const rows = Array.isArray(payload.tables[t]) ? payload.tables[t] : [];
    if (!rows.length) { restored[t] = 0; continue; }
    let n = 0;
    const cols = colSpec[t];
    const placeholders = cols.map(() => '?').join(',');
    for (const row of rows) {
      try {
        const vals = cols.map(c => (row && row[c] !== undefined) ? row[c] : null);
        await d1.prepare('INSERT OR REPLACE INTO ' + t + ' (' + cols.join(',') + ') VALUES (' + placeholders + ')').bind(...vals).run();
        n++;
      } catch (e) {
        if (errors.length < 20) errors.push(t + ': ' + String(e.message || e).slice(0, 120));
      }
    }
    restored[t] = n;
  }
  return { ok: true, restored, errors };
}

