  if(!d1) return { ok: false, kind: 'nod1', applied: 0, parts: 0 };
  try{ await d1EnsureSchema(); }catch(e){ return { ok: false, kind: 'schema', applied: 0, parts: 0, error: String(e.message || e).slice(0, 120) }; }
  let applied = 0, doneParts = 0;
