  try{ parts = await fbJournalListParts(true); }
  catch(e){ return admErr('Drive falhou ao listar o journal: ' + String(e.message || e).slice(0, 160), 502); }
  if(dryRun){
    let total = 0; const perPart = [];
    for(const p of parts){
      let ops = [];
      try{ ops = await fbJournalPartOps(p); }catch(_){ ops = []; }
      perPart.push({ name: p.name, ops: ops.length });
      total += ops.length;
    }
    return admJson({ ok: true, dryRun: true, parts: parts.length, ops: total, perPart: perPart });
  }
  const r = await fbReplayApplyParts21572(parts, null);
