async function fbFeaturedAdd(request){
  const clone = fbReqClone(request);
  const resp = await handleFeaturedAdd(request);
  if(resp.status < 500) return resp;
  try{
    const body = await fbCloneJson(clone);
    if(!body) return resp;
    let coursePath = String(body.coursePath || '').slice(0, 500);
    try{ coursePath = canonicalCoursePath(coursePath); }catch(_){}
    const courseName = String(body.courseName || '').slice(0, 200);
    const icon = String(body.icon || '').slice(0, 60);
    const color = String(body.color || '').slice(0, 30);
    const coverUrl = String(body.coverUrl || '').trim().slice(0, 2000);
    if(!coursePath || !coursePath.startsWith('/')) return resp;
    if(coverUrl && !/^https?:\/\//i.test(coverUrl)) return resp;
    const rows = await fbMergedRows('featured_courses');
    const existing = rows.find(function(r){ return r.course_path === coursePath; });
    const now = Date.now();
    let sortOrder, createdAt;
    if(existing){ sortOrder = existing.sort_order; createdAt = existing.created_at; }
    else{ let mx = -1; for(const r of rows){ if(typeof r.sort_order === 'number' && r.sort_order > mx) mx = r.sort_order; } sortOrder = mx + 1; createdAt = now; }
    const row = { course_path: coursePath, course_name: courseName, icon: icon, color: color, cover_url: coverUrl || null, sort_order: sortOrder, created_at: createdAt };
    if(await fbJournalAppend([{ id: fbOpId(), ts: now, table: 'featured_courses', action: 'insert', key: { course_path: coursePath }, row: row }])) return fbJsonResp({ ok: true, fallback: true, queued: false });
  }catch(_){}
  return resp;
}
