async function fbFeaturedMove(request){
  const clone = fbReqClone(request);
  const resp = await handleFeaturedMove(request);
  if(resp.status < 500) return resp;
  try{
    const body = await fbCloneJson(clone);
    if(!body || body.id == null) return resp;
    const id = Number(body.id);
    const direction = body.direction === 'up' ? 'up' : (body.direction === 'down' ? 'down' : null);
    if(!Number.isFinite(id) || !direction) return resp;
    const rows = (await fbMergedRows('featured_courses')).slice().sort(function(a, b){ return ((a.sort_order || 0) - (b.sort_order || 0)) || ((a.created_at || 0) - (b.created_at || 0)); });
    const idx = rows.findIndex(function(r){ return Number(r.id) === id; });
    if(idx < 0) return resp;
    const nIdx = direction === 'up' ? idx - 1 : idx + 1;
    if(nIdx < 0 || nIdx >= rows.length) return fbJsonResp({ ok: true, moved: false, fallback: true });
    const a = rows[idx], b = rows[nIdx];
    const now = Date.now();
    const ok = await fbJournalAppend([
      { id: fbOpId(), ts: now, table: 'featured_courses', action: 'update', key: { course_path: a.course_path }, row: { sort_order: b.sort_order } },
      { id: fbOpId(), ts: now, table: 'featured_courses', action: 'update', key: { course_path: b.course_path }, row: { sort_order: a.sort_order } }
    ]);
    if(ok) return fbJsonResp({ ok: true, moved: true, fallback: true });
  }catch(_){}
  return resp;
}
