async function fbCourseRemove(request){
  const clone = fbReqClone(request);
  const resp = await handleCourseRemove(request);
  // 502 = escrita falhou; 404 pode ser espúrio (a leitura interna falhou
  // com o D1 em baixo e o handler conclui "não encontrado") — o merge
  // decide: sem linha correspondente no estado mergeado, devolve o 404.
  if(resp.status !== 502 && resp.status !== 404) return resp;
  try{
    const user = await gdiSessionUser(request);
    const body = await fbCloneJson(clone);
    if(!user || !body) return resp;
    const _norm = function(s){ let x = String(s || ''); try{ x = decodeURIComponent(x); }catch(_){} return x.trim().toLowerCase().replace(/\/+$/, ''); };
    const target = _norm(body.coursePath || body.path || '');
    if(!target) return resp;
    const rows = (await fbMergedRows('user_courses')).filter(function(r){ return r.username === user && _norm(r.course_path) === target; });
    if(!rows.length) return resp;
    const now = Date.now();
    const ops = rows.map(function(r){ return { id: fbOpId(), ts: now, table: 'user_courses', action: 'delete', key: { username: user, course_path: r.course_path } }; });
    if(await fbJournalAppend(ops)){
      try{ const kv = meggyKvBinding(); if(kv) await removeFromBackfillQueue(kv, rows[0].course_path); }catch(_){}
      return fbJsonResp({ ok: true, removed: true, fullyDeleted: true, deleted: true, fallback: true });
    }
  }catch(_){}
  return resp;
}
