async function fbConcursoSourcePatch(request, url){
  const clone = fbReqClone(request);
  let resp = null;
  try{ resp = await handleConcursoSourcePatch(request, url); }catch(_){ resp = null; }
  if(resp) return resp;
  try{
    const parts = url.pathname.split('/');
    const concursoId = parts[3]; const sid = Number(parts[5]);
    const body = await fbCloneJson(clone);
    if(concursoId && Number.isFinite(sid) && body){
      const row = {};
      if(typeof body.name === 'string' && body.name.trim()) row.name = body.name.trim().slice(0, 120);
      if(typeof body.sortOrder === 'number' && Number.isFinite(body.sortOrder)) row.sort_order = Math.round(body.sortOrder);
      if(typeof body.intensivo === 'boolean') row.intensivo = body.intensivo ? 1 : 0;
      if(Object.keys(row).length){
        const op = { id: fbOpId(), ts: Date.now(), table: 'concurso_sources', action: 'update', note: 'source-patch', key: { id: sid, concurso_id: concursoId }, row: row };
        if(await fbJournalAppend([op])){
          const src = { id: sid };
          if(row.name !== undefined) src.name = row.name;
          if(row.sort_order !== undefined) src.sortOrder = row.sort_order;
          if(row.intensivo !== undefined) src.intensivo = !!row.intensivo;
          return fbJsonResp({ ok: true, fallback: true, source: src });
        }
      }
    }
  }catch(_){}
  return fbJsonResp({ ok: false, error: 'patch failed' }, 500);
}
async function fbConcursoSourcesReorder(request, url){
  const clone = fbReqClone(request);
  let resp = null;
  try{ resp = await handleConcursoSourcesReorder(request, url); }catch(_){ resp = null; }
  if(resp) return resp;
  try{
    const concursoId = url.pathname.split('/')[3];
    const body = await fbCloneJson(clone);
    if(concursoId && body && Array.isArray(body.order) && body.order.length){
      const order = body.order.map(function(x){ return Number(x); });
      if(order.every(function(n){ return Number.isFinite(n); })){
        const rows = (await fbMergedRows('concurso_sources')).filter(function(r){ return String(r.concurso_id) === String(concursoId); });
        if(rows.length){
          const cur = new Set(rows.map(function(r){ return Number(r.id); }));
          const want = new Set(order);
          let same = cur.size === want.size;
          if(same){ for(const n of want){ if(!cur.has(n)){ same = false; break; } } }
          if(!same) return fbJsonResp({ ok: false, error: 'order inválido', fallback: true }, 400);
        }
        const now = Date.now();
        const ops = order.map(function(id, i){ return { id: fbOpId(), ts: now, table: 'concurso_sources', action: 'update', key: { id: id, concurso_id: concursoId }, row: { sort_order: i } }; });
        if(await fbJournalAppend(ops)) return fbJsonResp({ ok: true, fallback: true });
      }
    }
  }catch(_){}
  return fbJsonResp({ ok: false, error: 'reorder failed' }, 500);
}
