async function scanListFiles(url){
  // GET /admin?api=scan-list-files&path=...&pageToken=...&pageSize=...
  // UMA chamada files.list ao Drive por invocação (sem retry — o
  // orquestrador retenta a página). Inclui subpastas (isFolder) p/ o
  // Python recursar; pastas .gdi-*/.meggy.ai e nomes ocultos (.password,
  // dotfiles) nunca saem daqui (paridade c/ o scanner interno).
  const path = String((url && url.searchParams.get('path')) || '').trim();
  if(!path) return admErr('parâmetro "path" obrigatório', 400);
  const parsed = parseCoursePath(path);
  if(!parsed || parsed.driveIndex < 0 || parsed.driveIndex >= (typeof gds !== 'undefined' ? gds.length : 0)) return admErr('caminho inválido', 400);
  const gd = gds[parsed.driveIndex];
  if(!gd) return admErr('drive não disponível', 503);
  let pageSize = 100;
  const psRaw = url.searchParams.get('pageSize');
  if(psRaw !== null && psRaw !== ''){
    const n = Number(psRaw);
    if(!Number.isInteger(n) || n < 1 || n > 100) return admErr('pageSize inválido (1–100)', 400);
    pageSize = n;
  }
  const pageToken = url.searchParams.get('pageToken') || null;
  if(pageToken && pageToken.length > 2000) return admErr('pageToken inválido', 400);
  if(typeof gd.findPathId !== 'function') return admErr('drive não disponível', 503);
  const cleanPath = '/' + (parsed.subPath || '');
  let folderId;
  try{ folderId = await gd.findPathId(cleanPath); }
  catch(e){ return admErr('Drive indisponível: ' + String(e.message || e).slice(0, 120), 502); }
  if(folderId === undefined || folderId === null) return admErr('pasta não encontrada: ' + path, 404);
  let opts;
  try{ opts = await gd.requestOptions(); }
  catch(e){ return admErr('Drive indisponível: ' + String(e.message || e).slice(0, 120), 502); }
  const params = { includeItemsFromAllDrives: 'true', supportsAllDrives: 'true', q: "'" + folderId + "' in parents and trashed = false", fields: 'files(id,name,mimeType,size,modifiedTime),nextPageToken', pageSize: String(pageSize), orderBy: 'folder,name' };
  if(pageToken) params.pageToken = pageToken;
  let r;
  try{ r = await fetch('https://www.googleapis.com/drive/v3/files?' + enQuery(params), opts); }
  catch(e){ return admErr('Drive indisponível: ' + String(e.message || e).slice(0, 120), 502); }
  if(!r.ok) return admErr('Drive HTTP ' + r.status, 502);
  const j = await r.json();
  const files = [];
  for(const f of (j.files || [])){
    if(isHiddenName(f.name)) continue;
    const isFolder = f.mimeType === 'application/vnd.google-apps.folder';
    if(isFolder && (String(f.name || '').startsWith('.gdi-') || f.name === '.meggy.ai')) continue;
    files.push({ id: f.id, name: f.name, mimeType: f.mimeType || '', size: (f.size === undefined ? null : f.size), modifiedTime: f.modifiedTime || null, isFolder });
  }
  return admJson({ ok: true, path, folderId, files, nextPageToken: (j.nextPageToken || null) });
}


// ═══════════════════════════════════════════════════════════════════════
// ★ v2.15.36-A: Fix A + Fix B + buffer no Drive + replay (scan-replay-buffer)
//   Fix A: COUNT(*) e scan_status só em complete||dryRun; nas chamadas por
//     pasta a resposta OMITE totalLessonsForCourse (o scanner mantém o
//     total anterior) e devolve scanStatus estático sem ler o D1.
//   Fix B: scanWriteLessonRows conta inserted/replaced a partir dos
//     resultados REAIS do d1.batch e regista writeErrors (nunca engole).
//   Buffer: quando a escrita no D1 falha, o WORKER guarda as linhas
//     EXATAS de buildLessonRow em .meggy.ai/courses/<hash>/scan-buffer/
//     (partes de 2500 linhas, só-criação) + acumulador KV; o replay
//     re-envia-as pelo MESMO scanWriteLessonRows e só apaga cada parte
//     depois de confirmar as linhas no D1. O D1 continua a ser a fonte
//     da verdade (§6): o buffer é temporário e nunca é lido como dados.
//   Nota Fix B vs buffer: o 500 de "upsert D1 falhou" do Fix B aplica-se
//     onde NÃO há buffer — no replay (que pára na parte que falhar) e
//     quando o próprio buffer falha. No upsert, a falha total de escrita
//     vai para o buffer (ok:true, buffered:true) em vez de 500, e o
//     sucesso parcial vai para o buffer só com as linhas que falharam.
// ★ v2.15.38 ("modo novo"): a ESCRITA do buffer ancora SEMPRE no
//     drive 0 (nos drives só-leitura do meuc a criação do .meggy.ai
//     na raiz do curso falha e o buffer morria com 502); o replay LÊ
//     das duas âncoras (drive 0 nova + drive do curso legada) e o
//     scan-upsert-lessons ganha o modo bufferOnly ("só guardar":
//     salta o D1 por completo; o D1 só é gravado no fim, via replay).
// ═══════════════════════════════════════════════════════════════════════

// ═══════════════════════════════════════════════════════════════════════
// ★ v2.15.71: scan-download-file / scan-upload-file — canal de bytes do
//   conversor local PDF→MD (ordem do Elton 2026-11-23). O scanner
//   externo só lista; estas duas APIs dão ao token de scanner a leitura
//   dos bytes de um ficheiro e a gravação do MD convertido EXACTAMENTE
//   ao lado do PDF de origem (mesma pasta — nunca subpasta separada).
//   Portão: o mesmo das outras APIs de scan (SCAN_API_NAMES ∩ scope).
//   Download: GET ?api=scan-download-file&path=<ficheiro> (ou
//   fileId+drive); tecto de 80 MB; pastas recusadas.
//   Upload: POST ?api=scan-upload-file&path=<ficheiro .md>, corpo em
//   texto; upsert por nome na pasta pai; tecto de 8 MB; só .md.
// ═══════════════════════════════════════════════════════════════════════
const SCAN_FILE_DOWNLOAD_MAX = 80 * 1024 * 1024;
const SCAN_FILE_UPLOAD_MAX = 8 * 1024 * 1024;

async function scanFindChildFile(gd, parentId, name){
  const opts = await gd.requestOptions();
  const q = "'" + parentId + "' in parents and name = '" + driveEscape(name) + "' and trashed = false";
  const r = await fetch('https://www.googleapis.com/drive/v3/files?' + enQuery({ includeItemsFromAllDrives: 'true', supportsAllDrives: 'true', q, fields: 'files(id,name,mimeType,size)', pageSize: '1' }), opts);
  if(!r.ok) throw new Error('Drive list falhou: HTTP ' + r.status);
  const j = await r.json();
  return (j.files && j.files[0]) ? j.files[0] : null;
}

async function scanUpsertTextFile(gd, parentId, name, text, contentType){
  const existing = await scanFindChildFile(gd, parentId, name);
  if(existing){
    const po = await gd.requestOptions({ 'Content-Type': contentType }, 'PATCH');
    const pr = await fetch('https://www.googleapis.com/upload/drive/v3/files/' + existing.id + '?uploadType=media&supportsAllDrives=true', { method: 'PATCH', headers: po.headers, body: text });
    if(!pr.ok) throw new Error('Drive patch ' + name + ' falhou: HTTP ' + pr.status);
    return { id: existing.id, updated: true };
  }
  const boundary = 'gdiscanmd' + Date.now();
  const mp = '--' + boundary + '\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n' + JSON.stringify({ name, parents: [parentId] }) + '\r\n--' + boundary + '\r\nContent-Type: ' + contentType + '\r\n\r\n' + text + '\r\n--' + boundary + '--';
  const uo = await gd.requestOptions({ 'Content-Type': 'multipart/related; boundary=' + boundary }, 'POST');
  const ur = await fetch('https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&supportsAllDrives=true', { method: 'POST', headers: uo.headers, body: mp });
  if(!ur.ok) throw new Error('Drive create ' + name + ' falhou: HTTP ' + ur.status);
  const j = await ur.json().catch(() => ({}));
  return { id: (j && j.id) || null, updated: false };
}

async function scanDownloadFile(url){
  const path = String((url && url.searchParams.get('path')) || '').trim();
  const fileIdParam = String((url && url.searchParams.get('fileId')) || '').trim();
  let gd = null, fileId = fileIdParam, meta = null;
  if(path){
    const parsed = parseCoursePath(path);
    if(!parsed || parsed.driveIndex < 0 || parsed.driveIndex >= (typeof gds !== 'undefined' ? gds.length : 0)) return admErr('caminho inválido', 400);
    gd = gds[parsed.driveIndex];
    if(!gd || typeof gd.findPathId !== 'function') return admErr('drive não disponível', 503);
    if(!fileId){
      const parts = String(parsed.subPath || '').split('/').filter(Boolean);
      if(!parts.length) return admErr('caminho inválido', 400);
      const name = parts[parts.length - 1];
      const parentSub = parts.slice(0, -1).join('/');
      try{
        const parentId = await gd.findPathId('/' + parentSub);
        if(parentId === undefined || parentId === null) return admErr('ficheiro não encontrado: ' + path, 404);
        meta = await scanFindChildFile(gd, parentId, name);
      }catch(e){ return admErr('Drive indisponível: ' + String(e.message || e).slice(0, 120), 502); }
      if(!meta) return admErr('ficheiro não encontrado: ' + path, 404);
      fileId = meta.id;
    }
  } else if(fileId){
    const drv = Number(url.searchParams.get('drive'));
    if(!Number.isInteger(drv) || drv < 0 || drv >= (typeof gds !== 'undefined' ? gds.length : 0)) return admErr('parâmetro "drive" obrigatório com fileId', 400);
    gd = gds[drv];
    if(!gd) return admErr('drive não disponível', 503);
  } else {
    return admErr('parâmetro "path" ou "fileId" obrigatório', 400);
  }
  let opts;
  try{ opts = await gd.requestOptions(); }
  catch(e){ return admErr('Drive indisponível: ' + String(e.message || e).slice(0, 120), 502); }
  if(!meta){
    let mr;
    try{ mr = await fetch('https://www.googleapis.com/drive/v3/files/' + encodeURIComponent(fileId) + '?' + enQuery({ supportsAllDrives: 'true', fields: 'id,name,mimeType,size' }), opts); }
    catch(e){ return admErr('Drive indisponível: ' + String(e.message || e).slice(0, 120), 502); }
    if(!mr.ok) return admErr('Drive HTTP ' + mr.status, mr.status === 404 ? 404 : 502);
    meta = await mr.json().catch(() => null);
    if(!meta) return admErr('Drive: metadata inválida', 502);
  }
  if(meta.mimeType === 'application/vnd.google-apps.folder') return admErr('o caminho é uma pasta, não um ficheiro', 400);
  const declared = (meta.size !== undefined && meta.size !== null) ? Number(meta.size) : NaN;
  if(Number.isFinite(declared) && declared > SCAN_FILE_DOWNLOAD_MAX) return admErr('ficheiro demasiado grande p/ esta via', 413);
  let r;
  try{ r = await fetch('https://www.googleapis.com/drive/v3/files/' + encodeURIComponent(fileId) + '?alt=media&supportsAllDrives=true', opts); }
  catch(e){ return admErr('Drive indisponível: ' + String(e.message || e).slice(0, 120), 502); }
  if(!r.ok) return admErr('Drive HTTP ' + r.status, 502);
  const headers = new Headers();
  headers.set('Content-Type', meta.mimeType || r.headers.get('Content-Type') || 'application/octet-stream');
  if(Number.isFinite(declared)) headers.set('Content-Length', String(declared));
  headers.set('X-File-Id', fileId);
  headers.set('X-File-Name', encodeURIComponent(meta.name || ''));
  return new Response(r.body, { status: 200, headers });
}

async function scanUploadFile(request, url){
  const path = String((url && url.searchParams.get('path')) || '').trim();
  if(!path) return admErr('parâmetro "path" obrigatório', 400);
  const parsed = parseCoursePath(path);
  if(!parsed || parsed.driveIndex < 0 || parsed.driveIndex >= (typeof gds !== 'undefined' ? gds.length : 0)) return admErr('caminho inválido', 400);
  const parts = String(parsed.subPath || '').split('/').filter(Boolean);
  if(!parts.length || parts.some(p => p === '..' || p === '.')) return admErr('caminho inválido', 400);
  const name = parts[parts.length - 1];
  if(!/\.md$/i.test(name)) return admErr('só ficheiros .md (o conversor só produz MarkDown)', 400);
  if(isHiddenName(name)) return admErr('nome não permitido', 400);
  const gd = gds[parsed.driveIndex];
  if(!gd || typeof gd.findPathId !== 'function') return admErr('drive não disponível', 503);
  let text;
  try{ text = await request.text(); }catch(_){ return admErr('corpo ilegível', 400); }
  if(!text) return admErr('corpo vazio', 400);
  const bytes = new TextEncoder().encode(text).length;
  if(bytes > SCAN_FILE_UPLOAD_MAX) return admErr('ficheiro demasiado grande p/ esta via', 413);
  const parentSub = parts.slice(0, -1).join('/');
  let parentId;
  try{ parentId = await gd.findPathId('/' + parentSub); }
  catch(e){ return admErr('Drive indisponível: ' + String(e.message || e).slice(0, 120), 502); }
  if(parentId === undefined || parentId === null) return admErr('pasta pai não encontrada: ' + path, 404);
  try{
    const out = await scanUpsertTextFile(gd, parentId, name, text, 'text/markdown; charset=UTF-8');
    return admJson({ ok: true, id: out.id, name, path, size: bytes, updated: out.updated });
  }catch(e){ return admErr('Drive indisponível: ' + String(e.message || e).slice(0, 120), 502); }
}

const SCAN_BUFFER_PART_MAX_ROWS = 2500;
const SCAN_REPLAY_ROWS_PER_CALL = 240;
const SCAN_BUFFER_KV_PREFIX = 'scan-buffer-state:';
const SCAN_BUFFER_MARKER_NAME = 'scan-buffer-complete.json';

function scanBufferKvKey(courseHash){ return SCAN_BUFFER_KV_PREFIX + courseHash; }
function scanBufferPartName(run, part){ return 'part-' + run + '-' + String(part).padStart(4, '0') + '.json'; }

// Pré-leitura dos ids já no D1, em blocos de 100 (limite de variáveis do
// SQLite). LANÇA em caso de erro — o chamador decide: no upsert a falta
// da pré-leitura só faz tudo contar como inserted; no replay é 500 e
// nada é apagado.
async function scanPreReadExisting(d1, rows){
  const existing = new Set();
  for(let i = 0; i < rows.length; i += 100){
    const block = rows.slice(i, i + 100);
    const placeholders = block.map(() => '?').join(',');
    const r = await d1.prepare('SELECT id FROM lessons WHERE id IN (' + placeholders + ')').bind(...block.map(x => x.id)).all();
    for(const x of (r.results || [])) existing.add(x.id);
  }
  return existing;
}

// ★ Fix B: o ÚNICO caminho de escrita de linhas — usado pelo upsert E
//   pelo replay. Conta inserted/replaced a partir dos resultados REAIS
//   do d1.batch (res.error → writeErrors, truncado a 200 chars);
//   fallback individual quando o batch lança, registando cada erro.
//   failedRows = linhas que falharam (p/ o buffer do upsert).
async function scanWriteLessonRows(d1, rows, existing){
  let inserted = 0, replaced = 0;
  const writeErrors = [];
  const failedRows = [];
  if(!rows || !rows.length) return { inserted: 0, replaced: 0, writeErrors, failedRows };
  const stmts = rows.map(row => d1.prepare('INSERT OR REPLACE INTO lessons (id, course_hash, course_path, lesson_path, lesson_name, lesson_type, mime_type, ext, size, drive_index, parent_folder_path, scanned_at, created_at, updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)').bind(row.id, row.course_hash, row.course_path, row.lesson_path, row.lesson_name, row.lesson_type, row.mime_type, row.ext, row.size, row.drive_index, row.parent_folder_path, row.scanned_at, row.created_at, row.updated_at));
  for(let i = 0; i < stmts.length; i += D1_LESSON_BATCH){
    const chunk = stmts.slice(i, i + D1_LESSON_BATCH);
    const chunkRows = rows.slice(i, i + D1_LESSON_BATCH);
    try{
      const results = await d1.batch(chunk);
      const list = results || [];
      list.forEach((res, j) => {
        if(j >= chunkRows.length) return;
        if(res && res.error){ writeErrors.push(String(res.error).slice(0, 200)); failedRows.push(chunkRows[j]); }
        else if(existing.has(chunkRows[j].id)) replaced++; else inserted++;
      });
      // O batch devolver menos resultados que o chunk também é falha:
      // as linhas sem resultado NÃO contam como escritas.
      for(let j = list.length; j < chunkRows.length; j++){ writeErrors.push('sem resultado do batch p/ linha ' + String(chunkRows[j].id).slice(0, 80)); failedRows.push(chunkRows[j]); }
    }catch(e){
      for(let j = 0; j < chunk.length; j++){
        try{ await chunk[j].run(); if(existing.has(chunkRows[j].id)) replaced++; else inserted++; }
        catch(ie){ writeErrors.push(String((ie && ie.message) || ie).slice(0, 200)); failedRows.push(chunkRows[j]); }
      }
    }
  }
  return { inserted, replaced, writeErrors, failedRows };
}

// ── Buffer no Drive: ficheiros JSON em .meggy.ai/courses/<hash>/ ──────────
// (mesmos padrões de gdiSaveCourseLessons/gdiSaveScanCursor: find-or-create
// de pastas + multipart só-criação ou PATCH p/ upsert; alt=media p/ ler.)

async function scanBufferDriveFileId(gd0, parentId, name){
  const opts = await gd0.requestOptions();
  const q = "'" + parentId + "' in parents and name = '" + driveEscape(name) + "' and trashed = false";
  const r = await fetch('https://www.googleapis.com/drive/v3/files?' + enQuery({ includeItemsFromAllDrives: 'true', supportsAllDrives: 'true', q, fields: 'files(id,name,size)', pageSize: '1' }), opts);
  if(!r.ok) throw new Error('Drive list falhou: HTTP ' + r.status);
  const j = await r.json();
  return (j.files && j.files[0]) ? j.files[0] : null;
}

async function scanBufferCreateJsonFile(gd0, parentId, name, jsonText){
  const boundary = 'gdiscanbuf' + Date.now();
  const mp = '--' + boundary + '\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n' + JSON.stringify({ name, parents: [parentId] }) + '\r\n--' + boundary + '\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n' + jsonText + '\r\n--' + boundary + '--';
  const uo = await gd0.requestOptions({ 'Content-Type': 'multipart/related; boundary=' + boundary }, 'POST');
  const ur = await fetch('https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&supportsAllDrives=true', { method: 'POST', headers: uo.headers, body: mp });
  if(!ur.ok) throw new Error('Drive create ' + name + ' falhou: HTTP ' + ur.status);
  const j = await ur.json().catch(() => ({}));
  return (j && j.id) || null;
}

async function scanBufferUpsertJsonFile(gd0, parentId, name, jsonText){
  const existing = await scanBufferDriveFileId(gd0, parentId, name);
  if(existing){
    const po = await gd0.requestOptions({ 'Content-Type': 'application/json; charset=UTF-8' }, 'PATCH');
    const pr = await fetch('https://www.googleapis.com/upload/drive/v3/files/' + existing.id + '?uploadType=media&supportsAllDrives=true', { method: 'PATCH', headers: po.headers, body: jsonText });
    if(!pr.ok) throw new Error('Drive patch ' + name + ' falhou: HTTP ' + pr.status);
    return existing.id;
  }
  return scanBufferCreateJsonFile(gd0, parentId, name, jsonText);
}

async function scanBufferDownloadJson(gd0, fileId){
  const opts = await gd0.requestOptions();
  const r = await fetch('https://www.googleapis.com/drive/v3/files/' + fileId + '?alt=media&supportsAllDrives=true', opts);
  if(!r.ok) throw new Error('Drive download falhou: HTTP ' + r.status);
  const text = await r.text();
  return JSON.parse(text);
}

async function scanBufferDeleteFile(gd0, fileId){
  const delOpts = await gd0.requestOptions({}, 'DELETE');
  const r = await fetch('https://www.googleapis.com/drive/v3/files/' + fileId + '?supportsAllDrives=true', { method: 'DELETE', headers: delOpts.headers });
  if(!r.ok) throw new Error('Drive delete falhou: HTTP ' + r.status);
  return true;
}

// Resolve .meggy.ai/courses/<hash>/scan-buffer/ (cria o que faltar).
async function scanBufferResolve(gd0, courseHash){
  const coursesId = await gdiSharedMeggySubfolderId(gd0, 'courses');
  if(!coursesId) return null;
  const hashId = await gdiSharedMeggyDeepSubfolderId(gd0, coursesId, courseHash);
  if(!hashId) return null;
  const bufferId = await gdiSharedMeggyDeepSubfolderId(gd0, hashId, 'scan-buffer');
  if(!bufferId) return null;
  return { coursesId, hashId, bufferId };
}

async function scanBufferStateLoad(kv, courseHash){
  if(!kv) throw new Error('KV não vinculado (MEGGY_CACHE)');
  const raw = await kv.get(scanBufferKvKey(courseHash));
  if(!raw) return null;
  try{ const s = JSON.parse(raw); if(s && typeof s === 'object' && Array.isArray(s.rows)) return s; }catch(_){}
  return null;
}

async function scanBufferStateSave(kv, courseHash, state){
  state.updatedAt = Date.now();
  await kv.put(scanBufferKvKey(courseHash), JSON.stringify(state));
}

async function scanBufferFlushPart(gd0, bufferId, coursePath, courseHash, run, part, rows){
  const envelope = { version: 1, coursePath, courseHash, run, part, bufferedAt: Date.now(), rows };
  const name = scanBufferPartName(run, part);
  await scanBufferCreateJsonFile(gd0, bufferId, name, JSON.stringify(envelope));
  return name;
}

// Acumula rows no KV (scan-buffer-state:<hash> = {run, part, rows})
// e descarrega partes de 2500 linhas no Drive à medida que enchem.
// Com complete=true descarrega o resto e escreve o marcador
// scan-buffer-complete.json na pasta do curso. LANÇA com o erro real
// quando o Drive/KV falha — o chamador devolve 500 (nunca ok:true).
// Devolve {run, bufferedFile, bufferedRows, parts, flushed, pendingRows};
// bufferedFile é a última parte descarregada, ou o nome da parte em
// acumulação no KV quando ainda nada foi descarregado.
async function scanBufferStore(gd0, courseHash, coursePath, rows, complete){
  const kv = (typeof meggyKvBinding === 'function') ? meggyKvBinding() : null;
  if(!kv) throw new Error('KV não vinculado (MEGGY_CACHE)');
  if(!gd0) throw new Error('drive do curso não disponível');
  const resolved = await scanBufferResolve(gd0, courseHash);
  if(!resolved) throw new Error('não foi possível resolver a pasta scan-buffer no Drive');
  let state = await scanBufferStateLoad(kv, courseHash);
  if(!state) state = { run: Date.now().toString(36), part: 0, rows: [] };
  if(!state.run) state.run = Date.now().toString(36);
  if(!Number.isInteger(state.part)) state.part = 0;
  if(!Array.isArray(state.rows)) state.rows = [];
  state.rows.push(...rows);
  let bufferedFile = null;
  let flushed = false;
  while(state.rows.length >= SCAN_BUFFER_PART_MAX_ROWS){
    const partRows = state.rows.splice(0, SCAN_BUFFER_PART_MAX_ROWS);
    bufferedFile = await scanBufferFlushPart(gd0, resolved.bufferId, coursePath, courseHash, state.run, state.part, partRows);
    state.part++;
    flushed = true;
  }
  if(complete){
    if(state.rows.length){
      bufferedFile = await scanBufferFlushPart(gd0, resolved.bufferId, coursePath, courseHash, state.run, state.part, state.rows);
      state.rows = [];
      state.part++;
      flushed = true;
    }
    const marker = { coursePath, courseHash, run: state.run, bufferedAt: Date.now(), parts: state.part };
    await scanBufferUpsertJsonFile(gd0, resolved.hashId, SCAN_BUFFER_MARKER_NAME, JSON.stringify(marker));
  }
  await scanBufferStateSave(kv, courseHash, state);
  return { run: state.run, bufferedFile: bufferedFile || scanBufferPartName(state.run, state.part), bufferedRows: rows.length, parts: state.part, flushed, pendingRows: state.rows.length };
}

// Buffer de recurso do upsert: guarda rows no Drive e devolve a resposta
// buffered. Se o próprio buffer falhar → 500 com o erro real (nunca ok:true).
async function scanUpsertBufferOrFail(o){
  // ★ v2.15.38: âncora do buffer = drive 0 (NÃO o drive do curso — nos
  //   drives só-leitura do meuc a criação do .meggy.ai falha e o buffer
  //   morria com 502; o drive 0 resolve nos dois workers).
  const gd0 = (typeof gds !== 'undefined' && gds) ? gds[0] : null;
  const firstErr = (o.writeErrors && o.writeErrors[0]) || 'D1 falhou';
  if(!gd0) return admErr('upsert D1 falhou e não há drive p/ o buffer: ' + firstErr, 500);
  try{
    const b = await scanBufferStore(gd0, o.courseHash, o.coursePath, o.rows, !!o.complete);
    return admJson({ ok: true, buffered: true, bufferedFile: b.bufferedFile, bufferedRows: b.bufferedRows, coursePath: o.coursePath, folderPath: o.folderPath, received: o.received, inserted: 0, replaced: 0, skipped: o.skipped, writeErrors: (o.writeErrors || []).slice(0, 3), writeErrorCount: (o.writeErrors || []).length, scanStatus: { status: 'scanning', lessons: 0, completedAt: null, updatedAt: null } });
  }catch(be){
    return admErr('upsert D1 falhou e o buffer falhou: ' + firstErr + ' / buffer: ' + String(be.message || be).slice(0, 200), 500);
  }
}


async function scanReplayBuffer(request, url){
  // GET ?api=scan-replay-buffer&coursePath=...&dryRun=0&part=...&offset=0&limit=240
  // POST JSON {coursePath, dryRun, part, offset, limit}
  // Por omissão dryRun=true (só lista — sem escrever/apagar). Corrida
  // real só com dryRun=0/false. Por cada parte, por ordem: download,
  // re-envio pelo MESMO scanWriteLessonRows em fatias de 240 linhas,
  // e só depois o DELETE da parte. Na primeira parte que falhar:
  // PÁRA (500, parte em quarentena).
  // ★ v2.15.67 (C2): SEM confirmação por re-leitura — a re-leitura
  //   pós-escrita via linhas ainda não visíveis (read-after-write
  //   do D1 não é instantâneo) e devolvia "confirmação falhou" com
  //   a escrita boa (writeErrors=0), desperdiçando leituras e
  //   despoletando retentativas do cliente sobre partes já
  //   consumidas (o 404 da janela 2026-11-22 21:05). Confia-se no
  //   resultado da escrita (writeErrors por statement); a
  //   verificação passa a ser a sonda amostral do driver. E parte
  //   nomeada já consumida → 404 com partGone:true no corpo
  //   (contrato com o driver: no-op limpo, nunca erro duro).
  // No fim de todas as partes: se existir scan-buffer-complete.json,
  // markScanDone + apaga o marcador; limpa o acumulador KV.
  // ★ v2.15.38: lê partes/marcadores de DUAS âncoras — drive 0 (nova) e
  // drive do curso (legada); o flush do acumulador vai p/ a primária.
  const fail = (msg, status, part, offset) => admJson({ ok: false, error: msg, part: part || null, offset: offset || 0 }, status || 500);
  let body = {};
  const qp = (k) => url.searchParams.get(k);
  if(request.method === 'POST'){ try{ body = await request.json(); }catch(_){ return admErr('json inválido', 400); } }
  const coursePathRaw = String((body && body.coursePath) || qp('coursePath') || '').trim();
  if(!coursePathRaw) return admErr('campo "coursePath" obrigatório', 400);
  const coursePath = scanCanonicalOrNull(coursePathRaw);
  if(!parseCoursePath(coursePath)) return admErr('coursePath inválido', 400);
  const dryRun = (request.method === 'GET')
    ? !(qp('dryRun') === '0' || qp('dryRun') === 'false')
    : !(body.dryRun === false || body.dryRun === 0 || body.dryRun === '0' || body.dryRun === 'false');
  const partParam = String((body && body.part !== undefined && body.part !== null ? body.part : qp('part')) || '').trim();
  let offset = parseInt((body && body.offset !== undefined && body.offset !== null ? body.offset : qp('offset')) || '0', 10);
  if(!Number.isFinite(offset) || offset < 0) offset = 0;
  let limit = parseInt((body && body.limit !== undefined && body.limit !== null ? body.limit : qp('limit')) || String(SCAN_REPLAY_ROWS_PER_CALL), 10);
  if(!Number.isFinite(limit) || limit < 1) limit = SCAN_REPLAY_ROWS_PER_CALL;
  if(limit > SCAN_REPLAY_ROWS_PER_CALL) limit = SCAN_REPLAY_ROWS_PER_CALL;
  const courseHash = courseHashFromPath(coursePath);
  const mIdx = String(coursePath).match(/^\s*\/(\d+):/);
  const courseIdx = mIdx ? Number(mIdx[1]) : 0;
  // ★ v2.15.38: leitura em DUAS âncoras — a nova (drive 0) e a legada
  //   (drive do curso, onde o staging-c já tem buffer: /2: no drive 2,
  //   /9: no drive 9). Uma âncora que não resolve conta como vazia
  //   (nunca 502 por si só); 502 só quando NENHUMA resolve. O
  //   acumulador KV (scan-buffer-state:<hash>) é partilhado e a chave
  //   NÃO muda.
  const gdAnchor = (typeof gds !== 'undefined' && gds) ? gds[0] : null;
  const gdCourse = (typeof gds !== 'undefined' && gds) ? gds[courseIdx] : null;
  if(!gdAnchor && !gdCourse) return admErr('drive do curso não disponível', 503);
  const d1 = meggyD1Binding();
  if(!d1) return admErr('D1 não vinculado', 503);
  const kv = (typeof meggyKvBinding === 'function') ? meggyKvBinding() : null;
  let pendingState = null;
  try{ pendingState = kv ? await scanBufferStateLoad(kv, courseHash) : null; }
  catch(e){ return admErr('KV falhou: ' + String(e.message || e).slice(0, 200), 500); }
  const pendingBufferedRows = pendingState ? (pendingState.rows || []).length : 0;
  let resPrimary = null, resLegacy = null;
  if(gdAnchor){ try{ resPrimary = await scanBufferResolve(gdAnchor, courseHash); }catch(_){ resPrimary = null; } }
  if(gdCourse && courseIdx !== 0){ try{ resLegacy = await scanBufferResolve(gdCourse, courseHash); }catch(_){ resLegacy = null; } }
  if(!resPrimary && !resLegacy) return admErr('não foi possível resolver a pasta scan-buffer no Drive', 502);
  const primary = resPrimary ? { gd: gdAnchor, resolved: resPrimary, anchor: 'drive0' } : { gd: gdCourse, resolved: resLegacy, anchor: 'legacy' };
  const anchors = [];
  if(resPrimary) anchors.push({ gd: gdAnchor, resolved: resPrimary, anchor: 'drive0' });
  if(resLegacy) anchors.push({ gd: gdCourse, resolved: resLegacy, anchor: 'legacy' });
  // Corrida real: descarrega o resto do acumulador KV como parte final
  // (na âncora primária — drive 0, ou a legada se só ela resolveu).
  if(!dryRun && pendingState && pendingState.rows && pendingState.rows.length){
    try{
      await scanBufferFlushPart(primary.gd, primary.resolved.bufferId, coursePath, courseHash, pendingState.run, pendingState.part, pendingState.rows);
      pendingState.rows = [];
      pendingState.part++;
      await scanBufferStateSave(kv, courseHash, pendingState);
    }catch(e){ return admErr('flush do acumulador falhou: ' + String(e.message || e).slice(0, 200), 500); }
  }
  // Lista as partes das DUAS âncoras (orderBy name → ordem de
  // criação); cada parte fica etiquetada com a sua âncora (gd +
  // anchor) p/ o download e o delete caírem na pasta certa.
  let parts = [];
  try{
    const seenPartIds = new Set();
    for(const a of anchors){
      const opts = await a.gd.requestOptions();
      let pageToken = null;
      do{
        const q = "'" + a.resolved.bufferId + "' in parents and trashed = false and mimeType != 'application/vnd.google-apps.folder'";
        const params = { includeItemsFromAllDrives: 'true', supportsAllDrives: 'true', q, fields: 'files(id,name,size)', orderBy: 'name', pageSize: '100' };
        if(pageToken) params.pageToken = pageToken;
        const r = await fetch('https://www.googleapis.com/drive/v3/files?' + enQuery(params), opts);
        if(!r.ok) throw new Error('Drive list falhou: HTTP ' + r.status);
        const j = await r.json();
        for(const f of (j.files || [])){
          // Dedup por id: se as duas âncoras resolverem p/ a MESMA
          // pasta (raízes coincidentes), a parte conta uma só vez.
          if(seenPartIds.has(f.id)) continue;
          seenPartIds.add(f.id);
          parts.push(Object.assign({}, f, { __gd: a.gd, __anchor: a.anchor }));
        }
        pageToken = j.nextPageToken || null;
      }while(pageToken);
    }
  }catch(e){ return admErr('Drive falhou: ' + String(e.message || e).slice(0, 200), 502); }
  parts = parts.filter(f => /^part-.*\.json$/.test(f.name || '')).sort((a, b) => String(a.name).localeCompare(String(b.name)));
  // Marcadores de complete (só leitura aqui) — um por âncora, no máx.
  const markers = [];
  for(const a of anchors){
    try{
      const mFile = await scanBufferDriveFileId(a.gd, a.resolved.hashId, SCAN_BUFFER_MARKER_NAME);
      if(mFile && !markers.some(mk => mk.fileId === mFile.id)){
        let mBody = null;
        try{ mBody = await scanBufferDownloadJson(a.gd, mFile.id); }catch(_){ mBody = { unreadable: true }; }
        markers.push(Object.assign({ fileId: mFile.id, __gd: a.gd, __anchor: a.anchor }, mBody || {}));
      }
    }catch(_){ /* âncora sem marcador legível conta como sem marcador */ }
  }
  const marker = markers.length ? markers[0] : null;
  if(dryRun){
    const partInfo = [];
    for(const p of parts){
      try{
        const env = await scanBufferDownloadJson(p.__gd, p.id);
        partInfo.push({ name: p.name, size: Number(p.size || 0), rows: Array.isArray(env && env.rows) ? env.rows.length : 0, run: (env && env.run) || null, part: (env && typeof env.part === 'number') ? env.part : null, anchor: p.__anchor });
      }catch(e){ partInfo.push({ name: p.name, size: Number(p.size || 0), rows: null, anchor: p.__anchor, error: String(e.message || e).slice(0, 200) }); }
    }
    return admJson({ ok: true, dryRun: true, coursePath, courseHash, parts: partInfo, marker: marker ? { run: marker.run || null, parts: marker.parts || null, bufferedAt: marker.bufferedAt || null } : null, pendingBufferedRows, totalBufferedRows: partInfo.reduce((a, x) => a + (x.rows || 0), 0) + pendingBufferedRows });
  }
  try{ await d1EnsureSchema(); }catch(e){ return fail('D1 falhou: ' + String(e.message || e).slice(0, 200), 500, null, 0); }
  let startIdx = 0;
  if(partParam){
    if(/^\d+$/.test(partParam)){ startIdx = Math.min(parseInt(partParam, 10), parts.length); }
    else{
      const fi = parts.findIndex(p => p.name === partParam);
      // ★ v2.15.67: parte já consumida (apagada por uma chamada
      //   anterior — ex.: retentativa do cliente após um 500 a meio
      //   da corrida) NÃO é erro duro: 404 com partGone:true p/ o
      //   driver tratar como no-op e avançar o cursor.
      if(fi < 0) return admJson({ ok: false, error: 'parte não encontrada: ' + partParam, part: partParam, offset: 0, partGone: true }, 404);
      startIdx = fi;
    }
  }
  const replayedParts = [];
  let rowsReplayed = 0, insertedTotal = 0, replacedTotal = 0;
  for(let pi = startIdx; pi < parts.length; pi++){
    const p = parts[pi];
    let env;
    try{ env = await scanBufferDownloadJson(p.__gd, p.id); }
    catch(e){ return fail('download da parte falhou: ' + String(e.message || e).slice(0, 200), 500, p.name, 0); }
    const rows = (env && Array.isArray(env.rows)) ? env.rows : null;
    if(!rows) return fail('parte inválida (sem rows): ' + p.name, 500, p.name, 0);
    let confirmed = (pi === startIdx) ? Math.min(offset, rows.length) : 0;
    const startConfirmed = confirmed; // resume: só o que falta conta como reposto
    let partInserted = 0, partReplaced = 0;
    while(confirmed < rows.length){
      const slice = rows.slice(confirmed, confirmed + limit);
      let existing;
      try{ existing = await scanPreReadExisting(d1, slice); }
      catch(e){ return fail('D1 falhou na pré-leitura: ' + String(e.message || e).slice(0, 200), 500, p.name, confirmed); }
      let w;
      try{ w = await scanWriteLessonRows(d1, slice, existing); }
      catch(e){ return fail('D1 falhou na escrita: ' + String(e.message || e).slice(0, 200), 500, p.name, confirmed); }
      if(w.writeErrors.length) return fail('replay falhou na parte ' + p.name + ': ' + w.writeErrors[0], 500, p.name, confirmed);
      // ★ v2.15.67 (C2): sem re-leitura de confirmação — writeErrors
      //   vazio = fatia escrita (ver o cabeçalho da função).
      partInserted += w.inserted; partReplaced += w.replaced;
      confirmed += slice.length;
    }
    try{ await scanBufferDeleteFile(p.__gd, p.id); }
    catch(e){ return fail('delete da parte falhou: ' + String(e.message || e).slice(0, 200), 500, p.name, confirmed); }
    const partReplayed = confirmed - startConfirmed;
    replayedParts.push({ name: p.name, rows: partReplayed, inserted: partInserted, replaced: partReplaced });
    rowsReplayed += partReplayed;
    insertedTotal += partInserted; replacedTotal += partReplaced;
  }
  let completeMarked = false;
  if(marker && marker.fileId){
    try{
      const r = await d1.prepare('SELECT COUNT(*) AS n FROM lessons WHERE course_hash = ?').bind(courseHash).all();
      const total = Number((r.results && r.results[0] && r.results[0].n) || 0);
      await markScanDone(d1, coursePath, total);
      completeMarked = true;
    }catch(e){ return fail('markScanDone falhou: ' + String(e.message || e).slice(0, 200), 500, null, 0); }
    for(const mk of markers){ try{ await scanBufferDeleteFile(mk.__gd, mk.fileId); }catch(_){ /* o marcador fica; o próximo replay volta a tentar */ } }
  }
  try{ if(kv) await kv.delete(scanBufferKvKey(courseHash)); }catch(_){}
  return admJson({ ok: true, coursePath, courseHash, done: true, part: null, nextOffset: 0, replayedParts, rowsReplayed, inserted: insertedTotal, replaced: replacedTotal, remainingParts: parts.length - startIdx - replayedParts.length, completeMarked, pendingBufferedRows: 0 });
}

async function scanUpsertLessons(request){
  // ★ v2.15.36-A: scan-upsert-lessons — Fix A + Fix B + buffer.
  // POST /admin?api=scan-upsert-lessons {coursePath, folderPath,
  //   files:[{id,name,mimeType,size,modifiedTime}], complete, dryRun}
  // Constrói as linhas com buildLessonRow (o MESMO código do scanner
  // interno — byte-equivalentes) e grava c/ INSERT OR REPLACE em lotes
  // d1.batch() de 8, via scanWriteLessonRows (o MESMO caminho do replay).
  // Idempotente; sem deletes; só toca `lessons` e `scan_status`.
  // Fix A: COUNT(*) + escrita 'scanning' + SELECT final de scan_status
  //   SÓ quando complete||dryRun. Nas chamadas por pasta a resposta
  //   OMITE totalLessonsForCourse (o scanner mantém o total anterior)
  //   e devolve scanStatus estático sem ler o D1.
  // Fix B: inserted/replaced vêm dos resultados REAIS do batch;
  //   writeErrors volta na resposta (writeErrors.slice(0,3) +
  //   writeErrorCount). Falha total de escrita → buffer no Drive
  //   (ok:true, buffered:true); sucesso parcial → buffer só das linhas
  //   que falharam. dryRun NUNCA escreve nem faz buffer.
  // ★ v2.15.38: bufferOnly:true salta o D1 por completo e guarda as
  //   linhas no buffer (âncora drive 0) — ver o ramo no corpo.
  // As linhas são construídas ANTES de qualquer chamada D1 que possa
  // lançar — se o D1 falhar (incl. d1EnsureSchema), o buffer guarda
  // exatamente estas linhas. complete:true com D1 em falha descarrega
  // o resto do acumulador e escreve scan-buffer-complete.json.
  let body;
  try{ body = await request.json(); }catch(_){ return admErr('json inválido', 400); }
  const coursePathRaw = String((body && body.coursePath) || '').trim();
  const folderPathRaw = String((body && body.folderPath) || '').trim();
  if(!coursePathRaw) return admErr('campo "coursePath" obrigatório', 400);
  // ★ v2.15.38: em bufferOnly os ficheiros vêm em "folders" (lotes de
  //   várias pastas) — folderPath/files soltos só são exigidos fora
  //   desse modo (ou como forma de uma pasta dentro dele).
  if(!body || body.bufferOnly !== true){
    if(!folderPathRaw) return admErr('campo "folderPath" obrigatório', 400);
    if(!Array.isArray(body.files)) return admErr('campo "files" obrigatório (array)', 400);
    if(body.files.length > 100) return admErr('máx. 100 ficheiros por chamada', 400);
  }
  const complete = body.complete === true;
  const dryRun = body.dryRun === true;
  // ★ v2.15.38: modo "só guardar" (bufferOnly) — o scanner externo em
  //   --save-only envia lotes de VÁRIAS pastas e o worker guarda as
  //   linhas no buffer do Drive (âncora drive 0) SEM tocar no D1: a
  //   scan deixa de gastar quota D1 e o replay grava tudo no fim.
  //   Corpo: {coursePath, bufferOnly:true, folders:[{folderPath,
  //   files:[...]}], complete, dryRun} — ou a forma de uma só pasta
  //   (folderPath+files). dryRun valida e conta, não guarda nada.
  //   Falha do buffer → 500 com o erro real (nunca ok:true).
  if(body.bufferOnly === true){
    const bCoursePath = scanCanonicalOrNull(coursePathRaw);
    if(!parseCoursePath(bCoursePath)) return admErr('coursePath inválido', 400);
    const bHash = courseHashFromPath(bCoursePath);
    const bMIdx = String(bCoursePath).match(/^\s*\/(\d+):/);
    const bIdx = bMIdx ? Number(bMIdx[1]) : 0;
    const bPrefix = normalizeCoursePath(bCoursePath).replace(/\/+$/, '');
    const bCpNorm = normScanPath(bCoursePath);
    let bFolders = null;
    if(Array.isArray(body.folders)) bFolders = body.folders;
    else if(folderPathRaw) bFolders = [{ folderPath: folderPathRaw, files: body.files }];
    if(!bFolders) return admErr('campo "folders" obrigatório (array) no modo bufferOnly', 400);
    if(!bFolders.length && !complete) return admErr('folders vazio só é aceite com complete:true (flush final)', 400);
    let bTotalFiles = 0;
    for(const bf of bFolders){ if(bf && Array.isArray(bf.files)) bTotalFiles += bf.files.length; }
    if(bTotalFiles > 600) return admErr('máx. 600 ficheiros por chamada em bufferOnly', 400);
    const bNow = Date.now();
    const bRows = [];
    let bSkipped = 0;
    for(const bf of bFolders){
      if(!bf || typeof bf !== 'object') return admErr('folders: entrada inválida', 400);
      const bFpRaw = String(bf.folderPath || '').trim();
      if(!bFpRaw) return admErr('folders: folderPath obrigatório', 400);
      if(!Array.isArray(bf.files)) return admErr('folders: files obrigatório (array)', 400);
      const bFp = scanCanonicalOrNull(bFpRaw);
      if(!parseCoursePath(bFp)) return admErr('folders: folderPath inválido', 400);
      const bFpNorm = normScanPath(bFp);
      if(bFpNorm !== bCpNorm && bFpNorm.indexOf(bCpNorm + '/') !== 0) return admErr('folders: folderPath fora do curso', 400);
      const bCtx = { coursePath: bCoursePath, courseHash: bHash, courseIdx: bIdx, coursePrefix: bPrefix, folderPath: bFp, scannedAt: bNow, now: bNow };
      for(const f of bf.files){
        if(!f || typeof f !== 'object' || !f.name || !f.id){ bSkipped++; continue; }
        const cls = scanClassifyFile(String(f.name), (f.mimeType || ''));
        if(!cls.type){ bSkipped++; continue; }
        const row = buildLessonRow({ id: String(f.id), name: String(f.name), type: cls.type, mimeType: (f.mimeType || ''), ext: cls.ext, size: (f.size === undefined ? null : f.size) }, bCtx);
        if(!row){ bSkipped++; continue; }
        bRows.push(row);
      }
    }
    if(dryRun) return admJson({ ok: true, bufferOnly: true, dryRun: true, coursePath: bCoursePath, received: bTotalFiles, wouldSaveRows: bRows.length, skipped: bSkipped });
    const bGd = (typeof gds !== 'undefined' && gds) ? gds[0] : null;
    if(!bGd) return admErr('drive 0 não disponível p/ o buffer', 503);
    try{
      const b = await scanBufferStore(bGd, bHash, bCoursePath, bRows, complete);
      return admJson({ ok: true, buffered: true, bufferOnly: true, coursePath: bCoursePath, received: bTotalFiles, savedRows: b.bufferedRows, bufferedRows: b.bufferedRows, bufferedFile: b.bufferedFile, parts: b.parts, pendingRows: b.pendingRows, flushed: b.flushed, skipped: bSkipped, scanStatus: { status: 'scanning', lessons: 0, completedAt: null, updatedAt: null } });
    }catch(be){
      return admErr('bufferOnly falhou: ' + String(be.message || be).slice(0, 200), 500);
    }
  }
  const d1 = meggyD1Binding();
  if(!d1) return admErr('D1 não vinculado', 503);
  const coursePath = scanCanonicalOrNull(coursePathRaw);
  if(!parseCoursePath(coursePath)) return admErr('coursePath inválido', 400);
  const folderPath = scanCanonicalOrNull(folderPathRaw);
  if(!parseCoursePath(folderPath)) return admErr('folderPath inválido', 400);
  const cpNorm = normScanPath(coursePath);
  const fpNorm = normScanPath(folderPath);
  if(fpNorm !== cpNorm && fpNorm.indexOf(cpNorm + '/') !== 0) return admErr('folderPath fora do curso', 400);
  const courseHash = courseHashFromPath(coursePath);
  const mIdx = String(coursePath).match(/^\s*\/(\d+):/);
  const courseIdx = mIdx ? Number(mIdx[1]) : 0;
  const coursePrefix = normalizeCoursePath(coursePath).replace(/\/+$/, '');
  const now = Date.now();
  const ctx = { coursePath, courseHash, courseIdx, coursePrefix, folderPath, scannedAt: now, now };
  const rows = [];
  let skipped = 0;
  for(const f of body.files){
    if(!f || typeof f !== 'object' || !f.name || !f.id){ skipped++; continue; }
    // ★ v2.15.33-A: ficheiro cru do Drive → classifica como o scanner
    //   (gdiScanDistributed só faz push c/ type); sem type é skipped.
    //   A linha é depois construída por buildLessonRow (partilhada).
    const cls = scanClassifyFile(String(f.name), (f.mimeType || ''));
    if(!cls.type){ skipped++; continue; }
    const row = buildLessonRow({ id: String(f.id), name: String(f.name), type: cls.type, mimeType: (f.mimeType || ''), ext: cls.ext, size: (f.size === undefined ? null : f.size) }, ctx);
    if(!row){ skipped++; continue; }
    rows.push(row);
  }
  // ★ v2.15.36-A: secção D1 em try/catch — qualquer exceção aqui (schema,
  //   pré-leitura fatal, escrita) leva as linhas p/ o buffer, nunca mente.
  let existing = new Set();
  let inserted = 0, replaced = 0;
  let writeErrors = [];
  let d1Failed = null;
  try{
    await d1EnsureSchema();
    if(rows.length){
      try{ existing = await scanPreReadExisting(d1, rows); }
      catch(_){ existing = new Set(); /* sem a pré-leitura, tudo conta como inserted */ }
    }
    if(dryRun){
      for(const row of rows){ if(existing.has(row.id)) replaced++; else inserted++; }
    }else if(rows.length){
      const w = await scanWriteLessonRows(d1, rows, existing);
      inserted = w.inserted; replaced = w.replaced; writeErrors = w.writeErrors;
      if(writeErrors.length && inserted + replaced === 0){
        // Falha total de escrita → buffer com TODAS as linhas.
        return scanUpsertBufferOrFail({ coursePath, folderPath, courseHash, courseIdx, rows, skipped, writeErrors, complete, received: body.files.length });
      }
      if(w.failedRows.length){
        // Sucesso parcial: só as linhas que falharam vão p/ o buffer.
        const gd0p = (typeof gds !== 'undefined' && gds) ? gds[0] : null; // ★ v2.15.38: âncora drive 0
        if(!gd0p) return admErr('upsert D1 falhou parcialmente e não há drive p/ o buffer: ' + writeErrors[0], 500);
        try{
          const b = await scanBufferStore(gd0p, courseHash, coursePath, w.failedRows, complete);
          return admJson({ ok: true, buffered: true, bufferedFile: b.bufferedFile, bufferedRows: b.bufferedRows, coursePath, folderPath, received: body.files.length, inserted, replaced, skipped, writeErrors: writeErrors.slice(0, 3), writeErrorCount: writeErrors.length, scanStatus: { status: 'scanning', lessons: 0, completedAt: null, updatedAt: null } });
        }catch(be){ return admErr('upsert D1 falhou parcialmente e o buffer falhou: ' + writeErrors[0] + ' / buffer: ' + String(be.message || be).slice(0, 200), 500); }
      }
    }
  }catch(e){
    d1Failed = e;
  }
  if(d1Failed){
    // dryRun NUNCA faz buffer: a falha do D1 é 500 com o erro real.
    if(dryRun || !rows.length) return admErr('D1 falhou: ' + String(d1Failed.message || d1Failed).slice(0, 200), 500);
    return scanUpsertBufferOrFail({ coursePath, folderPath, courseHash, courseIdx, rows, skipped, writeErrors: [String(d1Failed.message || d1Failed).slice(0, 200)], complete, received: body.files.length });
  }
  // ★ Fix A: COUNT(*) + scan_status SÓ quando complete||dryRun.
  let totalLessonsForCourse;
  let scanStatus = { status: 'scanning', lessons: 0, completedAt: null, updatedAt: null };
  if(complete || dryRun){
    try{
      const r = await d1.prepare('SELECT COUNT(*) AS n FROM lessons WHERE course_hash = ?').bind(courseHash).all();
      totalLessonsForCourse = Number((r.results && r.results[0] && r.results[0].n) || 0);
    }catch(_){ totalLessonsForCourse = 0; }
    if(!dryRun && complete){
      await markScanDone(d1, coursePath, totalLessonsForCourse);
    }else if(!dryRun){
      // 'scanning' informativo — NUNCA toca num done nem numa quarentena
      // (error/not_found/empty): o cron continua a respeitá-los.
      try{
        const cur = await d1.prepare('SELECT status, completed_at, last_error, fail_count FROM scan_status WHERE course_path = ?').bind(coursePath).first();
        if(!cur || cur.status === 'scanning'){
          const keepDone = cur ? cur.completed_at : null;
          const keepErr = cur ? cur.last_error : null;
          const keepFc = cur ? (cur.fail_count || 0) : 0;
          try{
            await d1.prepare(`INSERT OR REPLACE INTO scan_status (course_path, status, lessons, completed_at, updated_at, last_error, fail_count) VALUES (?,'scanning',?,?,?,?,?)`).bind(coursePath, totalLessonsForCourse, keepDone, now, keepErr, keepFc).run();
          }catch(e){
            if(/no such column/i.test(String(e && e.message || e))){
              await d1.prepare(`INSERT OR REPLACE INTO scan_status (course_path, status, lessons, completed_at, updated_at) VALUES (?,'scanning',?,?,?)`).bind(coursePath, totalLessonsForCourse, keepDone, now).run();
            }else throw e;
          }
        }
      }catch(_){ /* scan_status é informativo; o upsert já foi feito */ }
    }
    try{
      const cur = await d1.prepare('SELECT status, lessons, completed_at, updated_at FROM scan_status WHERE course_path = ?').bind(coursePath).first();
      scanStatus = cur ? { status: cur.status, lessons: cur.lessons || 0, completedAt: cur.completed_at || null, updatedAt: cur.updated_at || null } : { status: 'not_started', lessons: 0, completedAt: null, updatedAt: null };
    }catch(_){ scanStatus = { status: 'unknown', lessons: totalLessonsForCourse, completedAt: null, updatedAt: null }; }
  }
  const resp = { ok: true, coursePath, folderPath, received: body.files.length, inserted, replaced, skipped, writeErrors: writeErrors.slice(0, 3), writeErrorCount: writeErrors.length, scanStatus };
  if(totalLessonsForCourse !== undefined) resp.totalLessonsForCourse = totalLessonsForCourse;
  return admJson(resp);
}

async function featuredRequireAdmin(request) {
  const user = await gdiSessionUser(request);
  if (!user || !ADMIN_USERS.includes(user)) return null;
  return user;
}

async function handleFeaturedList(request) {
  const user = await gdiSessionUser(request);
  if (!user) return new Response(JSON.stringify({ ok: false, error: 'auth' }), { status: 401, headers: CORS_JSON });
  // ★ v2.15.39: leitura do D1 a falhar (quota 7500) → snapshot do Drive
  //   com fallback:true; sem snapshot válido → o erro original (500).
  const featuredFallback = async (errMsg) => {
    try{ const _t = await loadTableSnapshot('featured_courses'); if(_t){ const courses = _t.slice().sort(function(a,b){ return ((a.sort_order||0)-(b.sort_order||0)) || ((a.created_at||0)-(b.created_at||0)); }).map(function(x){ return { id: x.id, coursePath: x.course_path, courseName: x.course_name, icon: x.icon, color: x.color, coverUrl: x.cover_url || null, sortOrder: x.sort_order, addedAt: x.created_at }; }); return new Response(JSON.stringify({ ok: true, courses: courses, fallback: true }), { headers: CORS_JSON }); } }catch(_){}
    const snap = await fallbackSnapshotLoad('featured-courses.json');
    if (snap) return new Response(JSON.stringify(Object.assign({}, snap, { fallback: true })), { headers: CORS_JSON });
    return new Response(JSON.stringify({ ok: false, error: errMsg }), { status: 500, headers: CORS_JSON });
  };
  try { await d1EnsureSchema(); } catch (e) { return featuredFallback(String(e.message || e)); }
  const d1 = meggyD1Binding();
  if (!d1) return new Response(JSON.stringify({ ok: false, error: 'D1 não vinculado' }), { status: 503, headers: CORS_JSON }); // ★ v2.15.43 (QA-4): erro de configuração não é 'sem dados'
  try {
    const r = await d1.prepare('SELECT id, course_path, course_name, icon, color, cover_url, sort_order, created_at FROM featured_courses ORDER BY sort_order ASC, created_at ASC').all();
    let _frows = r.results || [];
    try{ if(typeof fbMergeTableRows==='function') _frows = await fbMergeTableRows('featured_courses', _frows); }catch(_){}
    const courses = _frows.map(x => ({ id: x.id, coursePath: x.course_path, courseName: x.course_name, icon: x.icon, color: x.color, coverUrl: x.cover_url || null, sortOrder: x.sort_order, addedAt: x.created_at }));
    return new Response(JSON.stringify({ ok: true, courses }), { headers: CORS_JSON });
  } catch (e) {
    return featuredFallback(String(e.message || e));
  }
}

async function handleFeaturedAdd(request) {
  if (!await featuredRequireAdmin(request)) return new Response(JSON.stringify({ ok: false, error: 'admin only' }), { status: 403, headers: CORS_JSON });
  let body;
  try { body = await request.json(); } catch (_) { return new Response(JSON.stringify({ ok: false, error: 'invalid json' }), { status: 400, headers: CORS_JSON }); }
  let coursePath = String(body.coursePath || '').slice(0, 500);
  // ★ v2.15.7 (dedup): o destaque nasce canônico (D1 + fila do backfill).
  try { if (typeof canonicalCoursePath === 'function') coursePath = canonicalCoursePath(coursePath) || coursePath; } catch (_) {}
  const courseName = String(body.courseName || '').slice(0, 200);
  const icon = String(body.icon || '').slice(0, 60);
  const color = String(body.color || '').slice(0, 30);
  // ★ v2.15.6: foto de capa — URL http(s) (thumbnail do Drive ou URL
  //   externa); vazio = sem capa (NULL). Outro esquema é rejeitado (não
  //   vira <img src> no admin nem nos APKs).
  const coverUrl = String(body.coverUrl || '').trim().slice(0, 2000);
  if (coverUrl && !/^https?:\/\//i.test(coverUrl)) return new Response(JSON.stringify({ ok: false, error: 'coverUrl inválido (use uma URL http(s), ex.: https://drive.google.com/thumbnail?id=...&sz=w1600)' }), { status: 400, headers: CORS_JSON });
  if (!coursePath || !coursePath.startsWith('/')) return new Response(JSON.stringify({ ok: false, error: 'coursePath inválido (use o caminho da pasta no Drive, ex.: /0:/Nome do Curso)' }), { status: 400, headers: CORS_JSON });
  await d1EnsureSchema();
  const d1 = meggyD1Binding();
  if (!d1) return new Response(JSON.stringify({ ok: false, error: 'D1 não vinculado' }), { status: 502, headers: CORS_JSON });
  try {
    // ★ v2.15.8 (D — capas): o upsert por ON CONFLICT só casa a grafia
    //   EXATA — linhas legadas (ex.: '/11:/CURSOS%202026') não casam com
    //   o canônico '/9:/CURSOS%202026' e o save DUPLICAVA o destaque em
    //   vez de editar. Procura o gêmeo canônico e atualiza POR ID (e
    //   re-grava o caminho já canônico — auto-cura a grafia legada).
    try {
      const _rows = await d1.prepare('SELECT id, course_path FROM featured_courses').all();
      let _twin = null;
      for (const _r of ((_rows && _rows.results) || [])) {
        let _ck = null;
        try { _ck = (typeof canonicalCoursePath === 'function') ? canonicalCoursePath(_r.course_path) : String(_r.course_path || ''); } catch (_) { _ck = String(_r.course_path || ''); }
        if (_ck === coursePath) { _twin = _r; break; }
      }
      if (_twin) {
        await d1.prepare('UPDATE featured_courses SET course_path=?, course_name=?, icon=?, color=?, cover_url=? WHERE id=?').bind(coursePath, courseName, icon, color, coverUrl || null, _twin.id).run();
        let queued = false;
        try { const kv = meggyKvBinding(); if (kv) queued = await enqueueBackfillCourse(kv, coursePath); } catch (_) {}
        return new Response(JSON.stringify({ ok: true, queued, updated: _twin.id }), { headers: CORS_JSON });
      }
    } catch (_) {}
    const mx = await d1.prepare('SELECT COALESCE(MAX(sort_order), -1) AS m FROM featured_courses').first();
    const order = (mx && typeof mx.m === 'number') ? mx.m + 1 : 0;
    await d1.prepare('INSERT INTO featured_courses (course_path, course_name, icon, color, cover_url, sort_order, created_at) VALUES (?,?,?,?,?,?,?) ON CONFLICT(course_path) DO UPDATE SET course_name=excluded.course_name, icon=excluded.icon, color=excluded.color, cover_url=excluded.cover_url').bind(coursePath, courseName, icon, color, coverUrl || null, order, Date.now()).run();
    // ★ v2.7: entra na fila do backfill — o cron escaneia (com resume) até completar
    let queued = false;
    try { const kv = meggyKvBinding(); if (kv) queued = await enqueueBackfillCourse(kv, coursePath); } catch (_) {}
    return new Response(JSON.stringify({ ok: true, queued }), { headers: CORS_JSON });
  } catch (e) {
    return new Response(JSON.stringify({ ok: false, error: String(e.message || e) }), { status: 500, headers: CORS_JSON });
  }
}

async function handleFeaturedDelete(request) {
  if (!await featuredRequireAdmin(request)) return new Response(JSON.stringify({ ok: false, error: 'admin only' }), { status: 403, headers: CORS_JSON });
  let body;
  try { body = await request.json(); } catch (_) { return new Response(JSON.stringify({ ok: false, error: 'invalid json' }), { status: 400, headers: CORS_JSON }); }
  await d1EnsureSchema();
  const d1 = meggyD1Binding();
  if (!d1) return new Response(JSON.stringify({ ok: false, error: 'D1 não vinculado' }), { status: 502, headers: CORS_JSON });
  try {
    // ★ v2.15.2 (A3): precisa do coursePath p/ tirar da fila — por id, busca antes de apagar.
    let removedPath = body.coursePath ? String(body.coursePath) : null;
    if (!removedPath && body.id != null) {
      try { const row = await d1.prepare('SELECT course_path FROM featured_courses WHERE id = ?').bind(Number(body.id)).first(); if (row) removedPath = row.course_path; } catch (_) {}
    }
    let r;
    if (body.id != null) r = await d1.prepare('DELETE FROM featured_courses WHERE id = ?').bind(Number(body.id)).run();
    else if (body.coursePath) r = await d1.prepare('DELETE FROM featured_courses WHERE course_path = ?').bind(String(body.coursePath)).run();
    else return new Response(JSON.stringify({ ok: false, error: 'id ou coursePath obrigatório' }), { status: 400, headers: CORS_JSON });
    try { if (removedPath) { const kv = meggyKvBinding(); if (kv) await removeFromBackfillQueue(kv, removedPath); } } catch (_) {}
    return new Response(JSON.stringify({ ok: true, deleted: (r && r.meta && r.meta.changes) || 0 }), { headers: CORS_JSON });
  } catch (e) {
    return new Response(JSON.stringify({ ok: false, error: String(e.message || e) }), { status: 500, headers: CORS_JSON });
  }
}

async function handleFeaturedMove(request) {
  if (!await featuredRequireAdmin(request)) return new Response(JSON.stringify({ ok: false, error: 'admin only' }), { status: 403, headers: CORS_JSON });
  let body;
  try { body = await request.json(); } catch (_) { return new Response(JSON.stringify({ ok: false, error: 'invalid json' }), { status: 400, headers: CORS_JSON }); }
  const id = Number(body.id);
  const direction = String(body.direction || '');
  if (!id || (direction !== 'up' && direction !== 'down')) return new Response(JSON.stringify({ ok: false, error: 'id e direction (up/down) obrigatórios' }), { status: 400, headers: CORS_JSON });
  await d1EnsureSchema();
  const d1 = meggyD1Binding();
  if (!d1) return new Response(JSON.stringify({ ok: false, error: 'D1 não vinculado' }), { status: 502, headers: CORS_JSON });
  try {
    const row = await d1.prepare('SELECT id, sort_order FROM featured_courses WHERE id = ?').bind(id).first();
    if (!row) return new Response(JSON.stringify({ ok: false, error: 'não encontrado' }), { status: 404, headers: CORS_JSON });
    const op = direction === 'up' ? '<' : '>';
    const ord = direction === 'up' ? 'DESC' : 'ASC';
    const nb = await d1.prepare('SELECT id, sort_order FROM featured_courses WHERE sort_order ' + op + ' ? ORDER BY sort_order ' + ord + ' LIMIT 1').bind(row.sort_order).first();
    if (!nb) return new Response(JSON.stringify({ ok: true, moved: false }), { headers: CORS_JSON });
    await d1.prepare('UPDATE featured_courses SET sort_order = ? WHERE id = ?').bind(nb.sort_order, row.id).run();
    await d1.prepare('UPDATE featured_courses SET sort_order = ? WHERE id = ?').bind(row.sort_order, nb.id).run();
    return new Response(JSON.stringify({ ok: true, moved: true }), { headers: CORS_JSON });
  } catch (e) {
    return new Response(JSON.stringify({ ok: false, error: String(e.message || e) }), { status: 500, headers: CORS_JSON });
  }
}

