// ═══ ADMIN PANEL (PROFESSIONAL) ═══
// ════════════════════════════════════════════════════════════════════════════
// MEGGY — Painel de Administrador Profissional
// Arquivo: admin_panel.js
// Task ID: ADMIN-PANEL-CREATE
//
// DESCRIÇÃO
//   Função `handleAdmin(request, url)` que serve um painel admin completo
//   (HTML+CSS+JS inline, sem dependências externas) na rota /admin do worker.
//   Substitui o handleAdmin existente (worker.js ~L1977) por um
//   painel de infraestrutura com 7 seções: Dashboard, Usuários, Cursos,
//   IA, Scanner, Backup e Configurações.
//
// TEMA
//   Dark Meggy: #0d1119 (bg), #ff8b9f (pink), #5ddeda (cyan).
//
// INTEGRAÇÃO (NÃO modifica o worker.js automaticamente — feito pelo usuário)
//   1. Cole o conteúdo deste arquivo no worker.js (module scope, ao lado das
//      outras funções handleXxx) — OU faça `import`/require se estiver usando
//      es-modules. As funções helper abaixo são prefixadas com `adm` para
//      evitar colisão de nomes.
//   2. Substitua o corpo do handleAdmin existente (dentro de handleRequest,
//      ~L1977-2106) por uma chamada: `return await handleAdmin(request, url);`
//      e remova o handleAdmin interno. (O handleAdmin deste arquivo é
//      module-scoped e referencia os mesmos helpers module-scoped:
//      gdiSessionUser, ADMIN_USERS, meggyD1Binding, meggyD1Backend,
//      meggyKvBinding, meggyCacheBackend, getAI, d1EnsureSchema, gds,
//      globalThis.ENV — todos definidos no worker.)
//   3. Mantenha a rota `/admin` apontando para handleAdmin (já existe em
//      handleRequest ~L1977: `if(path==='/admin') return handleAdmin(...)`).
//
// SEGURANÇA
//   - Auth: cookie de sessão → gdiSessionUser → ADMIN_USERS.includes(user).
//     Bloqueio 403 idêntico ao handleAdmin original.
//   - Todas as ações de escrita (delete-user, delete-course, restore-d1)
//     rodam dentro do mesmo gate de admin.
//   - Config nunca expõe valores de secrets — apenas "set: true/false" + length.
//
// API INTERNA (mesma rota /admin, via ?api=)
//   GET  /admin                      → HTML do painel
//   GET  /admin?api=metrics          → {d1, kv, env, ai, scanner, ts}
//   GET  /admin?api=users            → [{username, courses, summaries, flashcards, last}]
//   POST /admin?api=delete-user      {user}                  → {deleted:{...}}
//   GET  /admin?api=courses          → [{username, course_path, course_name, pdf_count, added_at}]
//   POST /admin?api=delete-course    {username, coursePath}  → {deleted:N}
//   GET  /admin?api=export-d1        → JSON dump de todas as tabelas (download)
//   POST /admin?api=restore-d1       {tables:{...}}          → {restored:{...}}
//   GET  /admin?api=config           → {bindings, vars} (vars mascaradas)
//   GET  /admin?api=migrate-drive-to-d1 ?dry-run=1&username=&maxUsers=&maxRows=&maxCoursesPerUser= → dry-run (só contagens, nada escrito)
//   POST /admin?api=migrate-drive-to-d1 {username?, dryRun?, maxUsers?, maxRows?, maxCoursesPerUser?} → migração real (resumível, idempotente)
//
// ENDPOINTS EXTERNOS REUTILIZADOS (já existentes no worker, auth por cookie)
//   GET  /api/d1/status              → counts (fallback/validação)
//   GET  /api/d1/cron-progress       → progresso do scanner (KV)
//   POST /api/d1/cron-backfill       → dispara backfill manual
//   POST /api/d1/backfill            → backfill summaries+flashcards do Drive
//   POST /api/courses/rescan         {coursePath} → força rescan
//   GET  /api/ai/status              → {enabled, provider, cfAiAvailable}
//   GET  /api/ai/test?provider=all   → [{provider, ok, latency_ms, ...}]
// ════════════════════════════════════════════════════════════════════════════

// ─── dispatcher da API interna (?api=) ──────────────────────────────────────
async function admHandleApi(request, url) {
  const api = url.searchParams.get('api');
  const method = request.method;

  // CORS preflight para ações POST
  if (method === 'OPTIONS') {
    return new Response(null, {
      status: 204,
      headers: {
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Methods': 'GET,POST,OPTIONS',
        'Access-Control-Allow-Headers': 'Content-Type',
        'Access-Control-Max-Age': '86400'
      }
    });
  }

  try {
    if (api === 'metrics' && method === 'GET') {
      try { return admJson({ ok: true, metrics: await admGatherMetrics() }); }
      catch (e) { console.warn('[admin] metrics fatal:', String(e && e.message || e).slice(0, 160)); return admErr('metrics: ' + String(e && e.message || e).slice(0, 160), 500); } // ★ v2.15.43 (diagnóstico 6)
    }
    if (api === 'users' && method === 'GET') {
      return admJson({ ok: true, users: await admListUsers() });
    }
    if (api === 'delete-user' && method === 'POST') {
      let body; try { body = await request.json(); } catch (_) { return admErr('json inválido', 400); }
      if (!body || !body.user) return admErr('campo "user" obrigatório', 400);
      const res = await fbAdmDeleteUser(String(body.user));
      return admJson(res);
    }
    if (api === 'student-history' && method === 'GET') {
      const u = String(url.searchParams.get('user') || '').trim();
      if (!u) return admErr('parâmetro "user" obrigatório', 400);
      return admJson(await admStudentHistory(meggyD1Binding(), u));
    }
    if (api === 'history-backfill' && method === 'POST') {
      let body = {}; try { body = await request.json(); } catch (_) {}
      return admJson(await historyBackfill(meggyD1Binding(), { username: body && body.username ? String(body.username) : null }));
    }
    // ★ v2.15.29 (B): migração Drive → D1 (estado por usuário). GET = dry-run
    //   por omissão (?dry-run=0 desliga); POST sem dryRun = run. Dentro do
    //   gate de admin de handleAdmin — sem auth nova.
    if (api === 'migrate-drive-to-d1' && (method === 'GET' || method === 'POST')) {
      let body = {}; if (method === 'POST') { try { body = await request.json(); } catch (_) {} }
      const qp = (k) => url.searchParams.get(k);
      const dry = (method === 'GET') ? (qp('dry-run') !== '0') : (qp('dry-run') === '1' || body.dryRun === true);
      const num = (v, d, lo, hi) => { const n = parseInt(v, 10); return Number.isFinite(n) ? Math.min(hi, Math.max(lo, n)) : d; };
      return admJson(await driveMigrateAll(meggyD1Binding(), {
        username: (qp('username') || (body && body.username) || null),
        dryRun: dry,
        maxUsers: num(qp('maxUsers') || (body && body.maxUsers), DRIVE_MIGRATE_MAX_USERS, 1, 5),
        maxRows: num(qp('maxRows') || (body && body.maxRows), HISTORY_MAX_ROWS_PER_RUN, 1, 1000),
        maxCoursesPerUser: num(qp('maxCoursesPerUser') || (body && body.maxCoursesPerUser), DRIVE_MIGRATE_MAX_COURSES_PER_USER, 1, 20)
      }));
    }
    if (api === 'courses' && method === 'GET') {
      return admJson({ ok: true, courses: await admListAllCourses() });
    }
    // ★ v2.14.1 Drive-picker: navegar nos Drives p/ escolher a pasta do curso
    if (api === 'drive-browse' && method === 'GET') {
      const path = String(url.searchParams.get('path') || '').trim();
      if (!path) {
        return admJson({ ok: true, path: '', drives: (authConfig.roots || []).map((r, i) => ({ index: i, name: r.name })) });
      }
      const parsed = parseCoursePath(path);
      if (!parsed || parsed.driveIndex < 0 || parsed.driveIndex >= (typeof gds !== 'undefined' ? gds.length : 0)) return admErr('caminho inválido', 400);
      const gd = gds[parsed.driveIndex];
      if (!gd) return admErr('drive não disponível', 503);
      const cleanPath = '/' + (parsed.subPath || '');
      // ★ v2.14.8: distingue "pasta não existe" de "pasta vazia" — antes as duas
      //   devolviam {ok:true, folders:[]} e o picker mostrava "Pasta vazia" para
      //   uma pasta inexistente (ou que falhou ao resolver). findPathId aqui não
      //   custa fetch extra: ele popula o cache que request_list_of_files reusa.
      //   (Só quando o gd tem findPathId — fakes sem ele seguem a listagem como antes.)
      if (typeof gd.findPathId === 'function') {
        let _pid;
        try { _pid = await gd.findPathId(cleanPath); }
        catch (e) { return admErr('Drive indisponível: ' + (e.message || e), 502); }
        if (_pid === undefined || _pid === null) return admErr('pasta não encontrada: ' + path, 404);
      }
      let result;
      try { result = await gd.request_list_of_files(cleanPath, null, 0); }
      catch (e) { return admErr('Drive indisponível: ' + (e.message || e), 502); }
      const files = (result && result.data && result.data.files) || [];
      const base = path.replace(/\/$/, '');
      const folders = files.filter(f => f.mimeType === 'application/vnd.google-apps.folder')
        .map(f => ({ name: f.name, path: base + '/' + f.name }))
        .sort((a, b) => a.name.localeCompare(b.name, 'pt-BR'));
      // ★ v2.15.6: imagens da pasta (p/ a foto de capa do destaque) — só id
      //   e nome; a URL da capa é montada no cliente (thumbnail do Drive).
      // ★ v2.15.7 (D — capas): imagens além da 1ª página — a listagem do
      //   Drive é paginada (100/página, pastas primeiro) e o picker só pedia
      //   a página 0: numa pasta com +100 itens, a página 0 é só pastas e
      //   qualquer imagem atrás dela era invisível ("Nenhuma imagem nesta
      //   pasta" mesmo com imagem na pasta). As PASTAS seguem só da 1ª
      //   página (o picker não pagina pastas); as IMAGENS são coletadas nas
      //   páginas seguintes até o teto (5 páginas / 200 imagens — 1 fetch
      //   por página, longe do teto de subrequests). Falha numa página extra
      //   não quebra a resposta: o que já foi visto volta com
      //   hasMoreFiles=true (honesto).
      const _isImg = f => f.mimeType && String(f.mimeType).indexOf('image/') === 0 && f.id;
      const images = files.filter(_isImg)
        .map(f => ({ id: f.id, name: f.name }));
      let _examined = files.length;
      let _pages = 1;
      let _next = (result && result.nextPageToken) || null;
      while (_next && _pages < 5 && images.length < 200) {
        let _r;
        try { _r = await gd.request_list_of_files(cleanPath, _next, _pages); }
        catch (e) { break; }
        const _fs = (_r && _r.data && _r.data.files) || [];
        _examined += _fs.length;
        _pages++;
        for (const _f of _fs) { if (images.length >= 200) break; if (_isImg(_f)) images.push({ id: _f.id, name: _f.name }); }
        _next = (_r && _r.nextPageToken) || null;
        if (!_next) break;
      }
      const _hasMoreFiles = !!_next;
      images.sort((a, b) => a.name.localeCompare(b.name, 'pt-BR'));
      return admJson({ ok: true, path, folders, images, total: _examined, pages: _pages, hasMoreFiles: _hasMoreFiles });
    }
    // ★ v2.15.33-A: scanner externo híbrido (a auth já foi feita no
    //   portão — sessão admin OU token Bearer c/ scope; ver handleAdminV23).
    if (api === 'scan-courses' && method === 'GET') {
      return scanListCourses();
    }
    if (api === 'scan-list-files' && method === 'GET') {
      return scanListFiles(url);
    }
    if (api === 'scan-download-file' && method === 'GET') {
      return scanDownloadFile(url);
    }
    if (api === 'scan-upload-file' && method === 'POST') {
      return scanUploadFile(request, url);
    }
    if (api === 'scan-upsert-lessons' && method === 'POST') {
      return scanUpsertLessons(request);
    }
    if (api === 'scan-replay-buffer' && (method === 'GET' || method === 'POST')) {
      return scanReplayBuffer(request, url);
    }
    if (api === 'fallback-save' && method === 'POST') {
      return scanFallbackSave(request);
    }
    if (api === 'fallback-replay' && method === 'POST') {
      return scanFallbackReplay(request, url);
    }
    if (api === 'scan-token-issue' && method === 'GET') {
      return scanTokenIssue(request);
    }
    if (api === 'scan-token-revoke' && method === 'GET') {
      return scanTokenRevoke(request, url);
    }
    if (api === 'concursos' && method === 'GET') {
      return admJson(await admListConcursos());
    }
    if (api === 'delete-course' && method === 'POST') {
      let body; try { body = await request.json(); } catch (_) { return admErr('json inválido', 400); }
      if (!body || !body.username || !body.coursePath) return admErr('username e coursePath obrigatórios', 400);
      const res = await fbAdmDeleteCourse(String(body.username), String(body.coursePath));
      return admJson(res);
    }
    if (api === 'export-d1' && method === 'GET') {
      return admJson(await admExportD1());
    }
    if (api === 'restore-d1' && method === 'POST') {
      let body; try { body = await request.json(); } catch (_) { return admErr('json inválido', 400); }
      const res = await admRestoreD1(body);
      return admJson(res);
    }
    if (api === 'config' && method === 'GET') {
      // ★ v2.15.79: bindings.drives = nº REAL de drives (tabela
      //   admin_drives — a mesma fonte do separador Drives). Antes era
      //   gds.length (12, o seed legado em código) e a configuração
      //   contradizia a lista de 16. Fallback: snapshot da tabela;
      //   último recurso: o comportamento antigo (gds).
      let _dc = null;
      try {
        const _d1 = meggyD1Binding();
        if (_d1 && meggyD1Backend() !== 'off') {
          try { await d1EnsureSchema(); } catch (_) {}
          const _c = await _d1.prepare('SELECT COUNT(*) AS n FROM admin_drives').first();
          if (_c && typeof _c.n === 'number') _dc = _c.n;
        }
      } catch (_) {}
      if (_dc === null) { try { const _s = await loadTableSnapshot('admin_drives'); if (Array.isArray(_s)) _dc = _s.length; } catch (_) {} }
      return admJson(admViewConfig(_dc));
    }
    return admErr('api desconhecida: ' + api, 404);
  } catch (e) {
    return admErr(String(e.message || e), 500);
  }
}

// ─── cliente JS (stringificado e injetado no HTML) ───────────────────────────
//   Escrito como função real para poder usar template literals livremente;
//   o .toString() retorna o código-fonte sem avaliar ${...} (interpolação
//   não é recursiva), então é seguro embutir no template HTML do servidor.
function admClient() {
  const PINK = '#ff8b9f', CYAN = '#5ddeda';
  let init = null;
  let pollTimer = null;
  let currentTab = 'dashboard';

  function $(sel, root) { return (root || document).querySelector(sel); }
  function $all(sel, root) { return Array.prototype.slice.call((root || document).querySelectorAll(sel)); }
  function el(tag, attrs, html) {
    const e = document.createElement(tag);
    if (attrs) for (const k in attrs) {
      if (k === 'class') e.className = attrs[k];
      else if (k === 'style') e.setAttribute('style', attrs[k]);
      else e.setAttribute(k, attrs[k]);
    }
    if (html != null) e.innerHTML = html;
    return e;
  }
  function esc(s) {
    return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }
  function fmtDate(ts) {
    if (!ts) return '—';
    try { return new Date(ts).toLocaleString('pt-BR', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' }); }
    catch (_) { return String(ts); }
  }
  function relTime(ts) {
    if (!ts) return '—';
    const d = Date.now() - ts;
    if (d < 60000) return Math.floor(d / 1000) + 's atrás';
    if (d < 3600000) return Math.floor(d / 60000) + 'min atrás';
    if (d < 86400000) return Math.floor(d / 3600000) + 'h atrás';
    return Math.floor(d / 86400000) + 'd atrás';
  }
  function toast(msg, kind) {
    const t = el('div', { class: 'adm-toast ' + (kind || 'info') }, esc(msg));
    $('#adm-toasts').appendChild(t);
    setTimeout(() => { t.classList.add('out'); setTimeout(() => t.remove(), 300); }, 3500);
  }
  async function apiGet(path) {
    const r = await fetch(path, { credentials: 'same-origin', headers: { 'Accept': 'application/json' } });
    return r.json();
  }
  async function apiPost(path, body) {
    const r = await fetch(path, {
      method: 'POST', credentials: 'same-origin',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body || {})
    });
    return r.json();
  }

  // ── Dashboard ───────────────────────────────────────────────────────────
  function renderDashboard(m) {
    const root = $('#tab-dashboard');
    root.innerHTML = '';
    const d1 = m.d1, kv = m.kv, env = m.env, ai = m.ai, sc = m.scanner;

    const cards = el('div', { class: 'adm-cards' });
    const counts = d1.counts || {};
    function card(label, value, sub, accent) {
      const c = el('div', { class: 'adm-card' + (accent ? ' acc-' + accent : '') });
      c.innerHTML = '<div class="v">' + esc(value) + '</div><div class="l">' + esc(label) + '</div>' + (sub ? '<div class="s">' + esc(sub) + '</div>' : '');
      cards.appendChild(c);
    }
    card('Lessons (D1)', counts.lessons != null ? counts.lessons : '—', d1.bound ? 'backend: ' + d1.backend : 'D1 não vinculado', 'cyan');
    card('Resumos', counts.shared_summaries != null ? counts.shared_summaries : '—', 'shared_summaries', 'pink');
    card('Flashcards', counts.shared_flashcards != null ? counts.shared_flashcards : '—', 'shared_flashcards', 'pink');
    card('Cursos de usuários', counts.user_courses != null ? counts.user_courses : '—', d1.distinctUsers + ' usuários · ' + d1.distinctCourses + ' cursos únicos', 'cyan');
    card('Materiais meta', counts.materials_meta != null ? counts.materials_meta : '—', 'materials_meta');
    card('Usuários ativos', d1.distinctUsers || 0, 'com cursos cadastrados', 'pink');
    root.appendChild(cards);

    // status row
    const status = el('div', { class: 'adm-status-row' });
    function chip(label, ok, detail) {
      const c = el('div', { class: 'adm-chip ' + (ok ? 'ok' : 'bad') });
      c.innerHTML = '<span class="dot"></span><b>' + esc(label) + '</b> ' + (ok ? 'online' : 'offline') + (detail ? '<span class="d">' + esc(detail) + '</span>' : '');
      status.appendChild(c);
    }
    chip('D1', d1.bound, d1.bound ? d1.backend : '');
    chip('KV (MEGGY_CACHE)', kv.bound, kv.bound ? kv.backend : '');
    chip('ENV (sessões)', env.bound, '');
    chip('AI', ai.enabled, ai.enabled ? ai.provider : 'nenhum backend');
    root.appendChild(status);

    if (d1.error) {
      root.appendChild(el('div', { class: 'adm-warn' }, '⚠ Erro D1: ' + esc(d1.error)));
    }

    // AI backends
    const aiBox = el('div', { class: 'adm-box' });
    aiBox.innerHTML = '<h3>Backends de IA configurados</h3>';
    const aiList = el('div', { class: 'adm-backend-grid' });
    const order = ['cf-workers-ai', 'meggy-blacktie (zhipu)', 'nvidia-nim', 'openai', 'openrouter'];
    for (const name of order) {
      const on = !!(ai.backends && ai.backends[name]);
      const b = el('div', { class: 'adm-backend ' + (on ? 'on' : 'off') });
      b.innerHTML = '<div class="bk-name">' + esc(name) + '</div><div class="bk-state">' + (on ? '● ativo' : '○ não configurado') + '</div>';
      aiList.appendChild(b);
    }
    aiBox.appendChild(aiList);
    aiBox.appendChild(el('p', { class: 'adm-hint' }, 'Provider ativo (prioridade): ' + (ai.provider || '—') + '. Use a aba “IA” para testar latência.'));
    root.appendChild(aiBox);

    // Scanner progress
    const scBox = el('div', { class: 'adm-box' });
    scBox.innerHTML = '<h3>Scanner / Cron Backfill</h3>';
    const p = sc.progress;
    if (p && typeof p === 'object') {
      const done = p.done || p.processed || 0;
      const total = p.total || p.found || 0;
      const pct = total > 0 ? Math.min(100, Math.round((done / total) * 100)) : (p.complete ? 100 : 0);
      const bar = el('div', { class: 'adm-progress' }, '<div class="fill" style="width:' + pct + '%"></div><div class="lbl">' + pct + '%</div>');
      scBox.appendChild(bar);
      const meta = el('div', { class: 'adm-scanner-meta' });
      meta.innerHTML =
        '<span><b>Processados:</b> ' + esc(done) + '/' + esc(total || '—') + '</span>' +
        '<span><b>Última execução:</b> ' + esc(relTime(p.startedAt || p.updatedAt || p.ts)) + '</span>' +
        '<span><b>Estado:</b> ' + esc(p.complete ? 'completo' : (p.running ? 'rodando' : 'parado')) + '</span>' +
        (p.lastError ? '<span class="err"><b>Erro:</b> ' + esc(String(p.lastError).slice(0, 120)) + '</span>' : '');
      scBox.appendChild(meta);
    } else {
      scBox.appendChild(el('p', { class: 'adm-dim' }, 'Sem progresso de scanner registrado no KV.' + (sc.error ? ' (erro: ' + esc(sc.error) + ')' : '')));
    }
    scBox.appendChild(el('p', { class: 'adm-hint' }, 'Progresso lido de KV <code>cron-backfill:progress</code>. Veja a aba “Scanner” para forçar execução.'));
    // ★ v2.15.7 (P1, fix 8f): linha de bloqueados no dashboard — lê o
    //   snapshot (m.scanner, que já vem no /admin?api=metrics). NÃO
    //   busca /api/d1/cron-progress aqui (regra v2.15.5 item 8: sem
    //   re-fetch no render do dashboard; o detalhe fica na aba Scanner).
    { const scD = (m && m.scanner) || {}; const bD = (typeof scD.blockedCount === 'number') ? scD.blockedCount : 0; const qD = (typeof scD.queueLength === 'number') ? scD.queueLength : (((scD.progress) && Array.isArray(scD.progress.queue)) ? scD.progress.queue.length : 0); if (bD || qD) scBox.appendChild(el('p', { class: bD ? 'adm-warn' : 'adm-hint' }, bD ? ('🛑 ' + bD + ' curso(s) bloqueado(s) — ver aba Scanner') : (qD + ' curso(s) na fila de backfill'))); }
    root.appendChild(scBox);

    root.appendChild(el('div', { class: 'adm-foot' }, 'Atualizado: ' + fmtDate(m.ts)));
  }

  // ── Usuários ────────────────────────────────────────────────────────────
  async function loadUsers() {
    const root = $('#tab-users');
    root.innerHTML = '<div class="adm-loading">carregando usuários…</div>';
    const data = await apiGet('/admin?api=users');
    if (!data.ok) { root.innerHTML = '<div class="adm-warn">Erro: ' + esc(data.error) + '</div>'; return; }
    const users = data.users || [];
    const bar = el('div', { class: 'adm-toolbar' });
    bar.innerHTML = '<button class="adm-btn" id="usr-refresh">↻ Atualizar</button>' +
      '<a class="adm-btn ghost" href="/signup" target="_blank">+ Criar usuário (via /signup)</a>' +
      '<span class="adm-count">' + users.length + ' usuário(s)</span>';
    root.innerHTML = '';
    root.appendChild(bar);
    if (!users.length) {
      root.appendChild(el('p', { class: 'adm-dim' }, 'Nenhum usuário encontrado no D1 (user_courses + autores de resumos/flashcards).'));
      return;
    }
    const tbl = el('table', { class: 'adm-table' });
    tbl.innerHTML = '<thead><tr><th>Usuário</th><th>Cursos</th><th>Resumos</th><th>Flashcards</th><th>Última atividade</th><th></th></tr></thead>';
    const tb = el('tbody');
    for (const u of users) {
      const tr = el('tr');
      tr.innerHTML = '<td class="mono">' + esc(u.username) + '</td>' +
        '<td>' + esc(u.courses) + '</td>' +
        '<td>' + esc(u.summaries) + '</td>' +
        '<td>' + esc(u.flashcards) + '</td>' +
        '<td>' + esc(fmtDate(u.last)) + ' <span class="muted">(' + esc(relTime(u.last)) + ')</span></td>' +
        '<td><button class="adm-btn danger sm" data-user="' + esc(u.username) + '">Excluir</button></td>';
      tb.appendChild(tr);
    }
    tbl.appendChild(tb);
    root.appendChild(tbl);
    $('#usr-refresh').onclick = loadUsers;
    $all('[data-user]', tb).forEach(btn => {
      btn.onclick = async () => {
        const u = btn.getAttribute('data-user');
        if (!confirm('Excluir usuário "' + u + '"?\n\nIsto remove:\n• cursos dele no D1 (user_courses)\n• resumos e flashcards de autoria dele\n• sessão/IP no KV ENV\n\nNÃO remove o arquivo <user>.json no Drive.')) return;
        btn.disabled = true; btn.textContent = '…';
        const r = await apiPost('/admin?api=delete-user', { user: u });
        if (r.ok) { toast('Usuário ' + u + ' excluído: ' + JSON.stringify(r.deleted), 'ok'); loadUsers(); }
        else { toast('Erro: ' + (r.error || 'unknown'), 'err'); btn.disabled = false; btn.textContent = 'Excluir'; }
      };
    });
  }

  // ── Cursos ──────────────────────────────────────────────────────────────
  async function loadCourses() {
    const root = $('#tab-courses');
    root.innerHTML = '<div class="adm-loading">carregando cursos…</div>';
    const data = await apiGet('/admin?api=courses');
    if (!data.ok) { root.innerHTML = '<div class="adm-warn">Erro: ' + esc(data.error) + '</div>'; return; }
    const courses = data.courses || [];
    const bar = el('div', { class: 'adm-toolbar' });
    bar.innerHTML = '<button class="adm-btn" id="crs-refresh">↻ Atualizar</button>' +
      '<span class="adm-count">' + courses.length + ' registro(s) · limite 500</span>';
    root.innerHTML = '';
    root.appendChild(bar);
    if (!courses.length) {
      root.appendChild(el('p', { class: 'adm-dim' }, 'Nenhum curso no D1 (tabela user_courses vazia).'));
      return;
    }
    const tbl = el('table', { class: 'adm-table' });
    tbl.innerHTML = '<thead><tr><th>Usuário</th><th>Curso</th><th>PDFs</th><th>Adicionado</th><th></th><th></th></tr></thead>';
    const tb = el('tbody');
    for (const c of courses) {
      const tr = el('tr');
      const name = c.course_name || c.course_path || '';
      tr.innerHTML = '<td class="mono">' + esc(c.username) + '</td>' +
        '<td title="' + esc(c.course_path) + '">' + esc(name) + '</td>' +
        '<td>' + esc(c.pdf_count || 0) + '</td>' +
        '<td>' + esc(fmtDate(c.added_at)) + '</td>' +
        '<td><button class="adm-btn sm" data-rescan="' + esc(c.course_path) + '">Rescan</button></td>' +
        '<td><button class="adm-btn danger sm" data-del-user="' + esc(c.username) + '" data-del-path="' + esc(c.course_path) + '">Excluir</button></td>';
      tb.appendChild(tr);
    }
    tbl.appendChild(tb);
    root.appendChild(tbl);
    $('#crs-refresh').onclick = loadCourses;
    $all('[data-rescan]', tb).forEach(btn => {
      btn.onclick = async () => {
        const path = btn.getAttribute('data-rescan');
        if (!confirm('Forçar rescan do curso?\n\n' + path + '\n\nIsto dispara /api/courses/rescan (navega o Drive e re-escaneia a árvore).')) return;
        btn.disabled = true; btn.textContent = '…';
        try {
          const r = await apiPost('/api/courses/rescan', { coursePath: path });
          if (r.ok) { toast('Rescan disparado para: ' + path, 'ok'); }
          else { toast('Rescan erro: ' + (r.error || 'unknown'), 'err'); }
        } catch (e) { toast('Rescan falhou: ' + e, 'err'); }
        btn.disabled = false; btn.textContent = 'Rescan';
      };
    });
    $all('[data-del-path]', tb).forEach(btn => {
      btn.onclick = async () => {
        const u = btn.getAttribute('data-del-user');
        const p = btn.getAttribute('data-del-path');
        if (!confirm('Remover este curso do usuário no D1?\n\nUsuário: ' + u + '\nCurso: ' + p + '\n\n(Remove apenas o registro em user_courses; não apaga arquivos no Drive.)')) return;
        btn.disabled = true; btn.textContent = '…';
        const r = await apiPost('/admin?api=delete-course', { username: u, coursePath: p });
        if (r.ok) { toast('Curso removido (' + r.deleted + ' linha(s))', 'ok'); loadCourses(); }
        else { toast('Erro: ' + (r.error || 'unknown'), 'err'); btn.disabled = false; btn.textContent = 'Excluir'; }
      };
    });
  }

  // ── IA ──────────────────────────────────────────────────────────────────
  async function loadAi() {
    const root = $('#tab-ai');
    root.innerHTML = '';
    const bar = el('div', { class: 'adm-toolbar' });
    bar.innerHTML = '<button class="adm-btn" id="ai-refresh">↻ Atualizar status</button>' +
      '<button class="adm-btn primary" id="ai-test">⚡ Testar backends</button>' +
      '<span class="adm-hint" id="ai-hint">Testa CF + NVIDIA + OpenRouter com prompt curto (sujeito a rate-limit de 30/h).</span>';
    root.appendChild(bar);

    const statusBox = el('div', { class: 'adm-box' });
    statusBox.innerHTML = '<h3>Status</h3><div class="adm-loading">carregando…</div>';
    root.appendChild(statusBox);

    const resBox = el('div', { class: 'adm-box' });
    resBox.innerHTML = '<h3>Resultado dos testes</h3><p class="adm-dim">Clique em “Testar backends”.</p>';
    root.appendChild(resBox);

    async function refreshStatus() {
      statusBox.innerHTML = '<h3>Status</h3><div class="adm-loading">carregando…</div>';
      const s = await apiGet('/api/ai/status');
      if (!s.ok && s.error === 'auth') { statusBox.innerHTML = '<h3>Status</h3><div class="adm-warn">Não autenticado.</div>'; return; }
      const m = init && init.ai ? init.ai : { backends: {}, provider: s.provider };
      let html = '<div class="adm-backend-grid">';
      const order = ['cf-workers-ai', 'meggy-blacktie (zhipu)', 'nvidia-nim', 'openai', 'openrouter'];
      for (const name of order) {
        const on = !!(m.backends && m.backends[name]);
        html += '<div class="adm-backend ' + (on ? 'on' : 'off') + '"><div class="bk-name">' + esc(name) + '</div><div class="bk-state">' + (on ? '● ativo' : '○ não configurado') + '</div></div>';
      }
      html += '</div>';
      html += '<p class="adm-hint">Provider ativo: <b>' + esc(s.provider || '—') + '</b> · CF AI binding: ' + (s.cfAiAvailable ? 'sim' : 'não') + ' · habilitado: ' + (s.enabled ? 'sim' : 'não') + '</p>';
      statusBox.innerHTML = '<h3>Status</h3>' + html;
    }

    $('#ai-refresh').onclick = refreshStatus;
    $('#ai-test').onclick = async () => {
      const btn = $('#ai-test'); btn.disabled = true; btn.textContent = 'Testando…';
      $('#ai-hint').textContent = 'Aguardando respostas dos backends (pode levar ~10-20s)…';
      resBox.innerHTML = '<h3>Resultado dos testes</h3><div class="adm-loading">executando testes…</div>';
      try {
        const r = await apiGet('/api/ai/test?provider=all&prompt=Responda%20apenas%3A%20OK');
        if (!r.ok) { resBox.innerHTML = '<h3>Resultado dos testes</h3><div class="adm-warn">Erro: ' + esc(r.error) + '</div>'; }
        else {
          const results = r.results || [];
          if (!results.length) { resBox.innerHTML = '<h3>Resultado dos testes</h3><p class="adm-dim">Nenhum resultado.</p>'; }
          else {
            let html = '<table class="adm-table"><thead><tr><th>Backend</th><th>OK</th><th>Latência</th><th>Modelo</th><th>Preview / Erro</th></tr></thead><tbody>';
            for (const x of results) {
              html += '<tr>' +
                '<td class="mono">' + esc(x.provider) + '</td>' +
                '<td>' + (x.ok ? '<span class="ok-badge">✓</span>' : '<span class="bad-badge">✗</span>') + '</td>' +
                '<td>' + esc(x.latency_ms != null ? x.latency_ms + 'ms' : '—') + '</td>' +
                '<td class="mono sm">' + esc(x.model || '—') + '</td>' +
                '<td class="sm">' + esc(x.ok ? (x.responsePreview || '') : (x.error || '')) + '</td>' +
                '</tr>';
            }
            html += '</tbody></table>';
            resBox.innerHTML = '<h3>Resultado dos testes</h3>' + html;
          }
        }
      } catch (e) { resBox.innerHTML = '<h3>Resultado dos testes</h3><div class="adm-warn">Falha: ' + esc(e) + '</div>'; }
      btn.disabled = false; btn.textContent = '⚡ Testar backends';
      $('#ai-hint').textContent = 'Testa CF + NVIDIA + OpenRouter com prompt curto (sujeito a rate-limit de 30/h).';
    };
    refreshStatus();
  }

  // ── Scanner ─────────────────────────────────────────────────────────────
  async function loadScanner() {
    const root = $('#tab-scanner');
    root.innerHTML = '';
    const bar = el('div', { class: 'adm-toolbar' });
    bar.innerHTML = '<button class="adm-btn" id="sc-refresh">↻ Atualizar</button>' +
      '<button class="adm-btn primary" id="sc-cron">▶ Forçar cron-backfill</button>' +
      '<button class="adm-btn" id="sc-backfill">▶ Backfill summaries/flashcards</button>';
    root.appendChild(bar);

    const box = el('div', { class: 'adm-box' });
    box.innerHTML = '<h3>Progresso (KV: cron-backfill:progress)</h3><div class="adm-loading">carregando…</div>';
    root.appendChild(box);

    const log = el('div', { class: 'adm-box' });
    log.innerHTML = '<h3>Eventos</h3><div id="sc-log" class="adm-log"></div>';
    root.appendChild(log);

    async function refresh() {
      box.innerHTML = '<h3>Progresso (KV: cron-backfill:progress)</h3><div class="adm-loading">carregando…</div>';
      const data = await apiGet('/api/d1/cron-progress');
      const lg = $('#sc-log');
      if (!data.ok) {
        box.innerHTML = '<h3>Progresso</h3><div class="adm-warn">Erro: ' + esc(data.error) + '</div>';
        return;
      }
      const p = data.progress;
      if (!p) {
        box.innerHTML = '<h3>Progresso</h3><p class="adm-dim">Nenhum progresso registrado no KV. O cron ainda não rodou, ou KV não está vinculado.</p>';
        return;
      }
      const done = p.done || p.processed || 0;
      const total = p.total || p.found || 0;
      const pct = total > 0 ? Math.min(100, Math.round((done / total) * 100)) : (p.complete ? 100 : 0);
      let html = '<div class="adm-progress"><div class="fill" style="width:' + pct + '%"></div><div class="lbl">' + pct + '%</div></div>';
      html += '<div class="adm-scanner-meta">';
      html += '<span><b>Processados:</b> ' + esc(done) + '/' + esc(total || '—') + '</span>';
      html += '<span><b>Estado:</b> ' + esc(p.complete ? 'completo' : (p.running ? 'rodando' : 'parado')) + '</span>';
      if (p.startedAt) html += '<span><b>Início:</b> ' + esc(fmtDate(p.startedAt)) + '</span>';
      if (p.updatedAt || p.ts) html += '<span><b>Atualizado:</b> ' + esc(fmtDate(p.updatedAt || p.ts)) + '</span>';
      if (p.lastCourse) html += '<span><b>Último curso:</b> ' + esc(String(p.lastCourse).slice(0, 80)) + '</span>';
      if (p.lastError) html += '<span class="err"><b>Erro:</b> ' + esc(String(p.lastError).slice(0, 200)) + '</span>';
      html += '</div>';
      // ★ v2.14.9: aviso de destaques/cursos que são raiz de drive (não escaneados)
      if (data.rootPaths && data.rootPaths.length) {
        html += '<div class="adm-warn" style="margin-top:12px"><b>⚠️ Cursos/destaques que são raiz de drive — NÃO são escaneados:</b><br>' +
          data.rootPaths.map(x => esc(x.coursePath) + ' <span class="adm-dim">(' + esc(x.source) + (x.courseName ? ' · ' + esc(x.courseName) : '') + ')</span>').join('<br>') +
          '<br><span class="adm-dim">Um caminho /N:/ é o drive inteiro — o scanner pula esses caminhos. Corrija o caminho no destaque (ou remova-o) para o curso ser escaneado.</span></div>';
      }
      // ★ v2.15.6 (P1): seção de QUARENTENA — qual curso, qual erro,
      //   quantas tentativas, quando volta sozinho (nextRetryAt) ou se só
      //   volta por re-enfileiramento manual (fail_count>=3 — o admin
      //   corrige o cadastro e re-adiciona o curso).
      const qList = Array.isArray(data.quarantined) ? data.quarantined : [];
      if (qList.length) {
        html += '<div class="adm-box" style="margin-top:12px"><h3>🛑 Cursos em quarentena (' + qList.length + ')</h3>' +
          qList.map(q => '<div style="font-size:12px;padding:6px 0;border-bottom:1px solid #21262d;"><b>' + esc(q.coursePath) + '</b> <span class="err">' + (q.fail_count || 1) + 'ª quarentena</span><br><span class="adm-dim">' + esc(q.last_error || 'erro desconhecido') + ' · ' + (q.nextRetryAt ? ('volta em ' + esc(fmtDate(q.nextRetryAt))) : 'requer re-enfileiramento manual') + '</span></div>').join('') + '</div>';
      } else {
        html += '<div class="adm-dim" style="margin-top:12px;font-size:12px;">Nenhum curso em quarentena.</div>';
      }
      // ★ v2.15.7 (P1): BLOCKED (quarentena + travados) + FILA legível — o
      //   admin não precisa mais abrir o JSON bruto p/ ver o que está
      //   preso, com quantas tentativas e qual erro. `blocked` é um
      //   superconjunto do `quarantined` antigo (que segue acima).
      // ★ v2.15.10-A7: idem A5 no render antigo — 'cycling' não conta
      //   como bloqueado; vai p/ a seção 'Em progresso' (cList). O
      //   fallback de quarantined (kind 'error') nunca é 'cycling', então
      //   o filtro é no-op nele.
      const bList = (Array.isArray(data.blocked) ? data.blocked : qList.map(q => ({ coursePath: q.coursePath, kind: 'error', last_error: q.last_error, fail_count: q.fail_count, nextRetryAt: q.nextRetryAt }))).filter(b => b && b.kind !== 'cycling');
      const cList = Array.isArray(data.cycling) ? data.cycling : (Array.isArray(data.blocked) ? data.blocked : []).filter(b => b && b.kind === 'cycling');
      if (bList.length) {
        html += '<div class="adm-box" style="margin-top:12px"><h3>🛑 Cursos bloqueados (' + bList.length + ')</h3>' +
          bList.map(b => '<div style="font-size:12px;padding:6px 0;border-bottom:1px solid #21262d;"><b>' + esc(b.coursePath) + '</b> <span class="err">' + esc(b.kind === 'cycling' ? 'em progresso' : (b.kind || b.status || 'error')) + '</span>' + (b.fail_count != null ? ' <span class="adm-dim">' + esc(b.fail_count) + 'ª quarentena</span>' : '') + (b.inQueue ? ' <span class="adm-dim">na fila · ' + esc(b.retries || 0) + ' tentativas · ' + esc(b.cycles || 0) + ' ciclos</span>' : '') + '<br><span class="adm-dim">' + esc(((b.progress && b.progress.note) || b.last_error || 'erro desconhecido')) + (b.nextRetryAt ? ' · volta em ' + esc(fmtDate(b.nextRetryAt)) : (b.kind === 'stuck' ? ' · travado — sem scan_status' : (b.kind === 'cycling' ? ' · em progresso' : ' · requer re-enfileiramento manual'))) + '</span></div>').join('') + '</div>';
      }
      // ★ v2.15.10-A8: seção própria p/ os cursos EM PROGRESSO (mesmo
      //   motivo de A6: antes contavam como 'bloqueados' no título).
      if (cList.length) {
        html += '<div class="adm-box" style="margin-top:12px"><h3>🔄 Em progresso (' + cList.length + ')</h3>' +
          cList.map(b => '<div style="font-size:12px;padding:6px 0;border-bottom:1px solid #21262d;"><b>' + esc(b.coursePath) + '</b> <span class="adm-dim">em progresso · na fila · ' + esc(b.retries || 0) + ' tentativas · ' + esc(b.cycles || 0) + ' ciclos</span><br><span class="adm-dim">' + esc(((b.progress && b.progress.note) || b.last_error || 'em progresso')) + ' · em progresso</span></div>').join('') + '</div>';
      }
      const qItems = (p && Array.isArray(p.queue)) ? p.queue : [];
      if (qItems.length) {
        html += '<div class="adm-box" style="margin-top:12px"><h3>📋 Fila de backfill (' + qItems.length + ')</h3>' +
          qItems.map(it => '<div style="font-size:12px;padding:6px 0;border-bottom:1px solid #21262d;"><b>' + esc(it.coursePath || '') + '</b> <span class="adm-dim">drive ' + esc(it.driveIndex) + ' · ' + esc(it.retries || 0) + '/3 tentativas · ' + esc(it.cycles || 0) + ' ciclos' + (it.folderId ? ' · folderId ✓' : ' · folderId —') + (it.scanStatus ? ' · ' + esc(it.scanStatus.status || '') : '') + '</span>' + (it.lastError ? '<br><span class="err">' + esc(String(it.lastError).slice(0, 200)) + '</span>' : '') + '</div>').join('') + '</div>';
      } else {
        html += '<div class="adm-dim" style="margin-top:12px;font-size:12px;">Fila vazia — todos os cursos registrados já foram escaneados.</div>';
      }
      html += '<details class="adm-raw"><summary>JSON bruto</summary><pre>' + esc(JSON.stringify(p, null, 2)) + '</pre></details>';
      box.innerHTML = '<h3>Progresso (KV: cron-backfill:progress)</h3>' + html;
    }

    $('#sc-refresh').onclick = refresh;
    $('#sc-cron').onclick = async () => {
      const btn = $('#sc-cron'); btn.disabled = true; btn.textContent = 'Executando…';
      $('#sc-log').innerHTML = '<div class="adm-loading">disparando /api/d1/cron-backfill …</div>';
      const r = await apiPost('/api/d1/cron-backfill', {});
      if (r.ok) {
        toast('Cron backfill executado.', 'ok');
        $('#sc-log').innerHTML = '<pre>' + esc(JSON.stringify(r.stats || r, null, 2)) + '</pre>';
      } else {
        toast('Erro: ' + (r.error || 'unknown'), 'err');
        $('#sc-log').innerHTML = '<div class="adm-warn">' + esc(r.error || 'erro') + '</div>';
      }
      btn.disabled = false; btn.textContent = '▶ Forçar cron-backfill';
      refresh();
      // ★ v2.15.8 (A): o dashboard do admClient tem refreshDashboard() (com
      //   auto-poll) mas o clique do backfill nunca o chamava — o overview
      //   ficava no snapshot do load até o reload. (O V23 vivo usa
      //   refreshOverview(); este cliente é código morto, patchado por
      //   convenção da v2.15.7.)
      refreshDashboard();
    };
    $('#sc-backfill').onclick = async () => {
      const btn = $('#sc-backfill'); btn.disabled = true; btn.textContent = 'Executando…';
      $('#sc-log').innerHTML = '<div class="adm-loading">disparando /api/d1/backfill …</div>';
      const r = await apiPost('/api/d1/backfill', {});
      if (r.ok) {
        toast('Backfill concluído.', 'ok');
        $('#sc-log').innerHTML = '<pre>' + esc(JSON.stringify(r.stats || r, null, 2)) + '</pre>';
      } else {
        toast('Erro: ' + (r.error || 'unknown'), 'err');
        $('#sc-log').innerHTML = '<div class="adm-warn">' + esc(r.error || 'erro') + '</div>';
      }
      btn.disabled = false; btn.textContent = '▶ Backfill summaries/flashcards';
    };
    refresh();
    // ★ v2.15.8 (A): o backfill de summaries/flashcards também muda as
    //   contagens do D1 — atualiza o dashboard junto (v. c9).
    refreshDashboard();
  }

  // ── Backup ──────────────────────────────────────────────────────────────
  function loadBackup() {
    const root = $('#tab-backup');
    root.innerHTML = '';
    const box = el('div', { class: 'adm-box' });
    box.innerHTML = '<h3>Exportar D1 → JSON</h3>' +
      '<p class="adm-hint">Gera um dump completo de todas as tabelas (lessons, shared_summaries, shared_flashcards, user_courses, materials_meta) e baixa como <code>meggy-d1-backup-YYYYMMDD.json</code>.</p>' +
      '<button class="adm-btn primary" id="bk-export">⬇ Exportar agora</button>' +
      '<div id="bk-export-status" class="adm-dim"></div>';
    root.appendChild(box);

    const res = el('div', { class: 'adm-box' });
    res.innerHTML = '<h3>Restaurar D1 ← JSON</h3>' +
      '<p class="adm-hint">Selecione um arquivo de backup (.json). Será feito <code>INSERT OR REPLACE</code> em todas as tabelas. <b>Isto sobrescreve registros existentes com a mesma PK.</b></p>' +
      '<input type="file" id="bk-file" accept="application/json,.json" />' +
      '<button class="adm-btn" id="bk-restore" disabled>⬆ Restaurar</button>' +
      '<div id="bk-restore-status" class="adm-dim"></div>';
    root.appendChild(res);

    $('#bk-export').onclick = async () => {
      const btn = $('#bk-export'); btn.disabled = true; btn.textContent = 'Gerando…';
      $('#bk-export-status').textContent = 'Baixando dump (pode levar alguns segundos para bases grandes)…';
      try {
        const r = await fetch('/admin?api=export-d1', { credentials: 'same-origin' });
        const blob = await r.blob();
        const a = el('a');
        const d = new Date();
        const stamp = '' + d.getFullYear() + String(d.getMonth() + 1).padStart(2, '0') + String(d.getDate()).padStart(2, '0');
        a.href = URL.createObjectURL(blob);
        a.download = 'meggy-d1-backup-' + stamp + '.json';
        document.body.appendChild(a); a.click(); a.remove();
        setTimeout(() => URL.revokeObjectURL(a.href), 5000);
        const j = JSON.parse(await blob.text());
        $('#bk-export-status').innerHTML = 'Exportado: ' + esc(JSON.stringify(j.totals || {}));
        toast('Backup exportado.', 'ok');
      } catch (e) {
        $('#bk-export-status').textContent = 'Erro: ' + e;
        toast('Falha no export: ' + e, 'err');
      }
      btn.disabled = false; btn.textContent = '⬇ Exportar agora';
    };

    let restorePayload = null;
    $('#bk-file').onchange = async (ev) => {
      const f = ev.target.files[0];
      if (!f) { $('#bk-restore').disabled = true; restorePayload = null; return; }
      try {
        const txt = await f.text();
        restorePayload = JSON.parse(txt);
        $('#bk-restore').disabled = false;
        const totals = restorePayload.totals || {};
        $('#bk-restore-status').innerHTML = 'Arquivo carregado: ' + esc(f.name) + ' · tabelas: ' + esc(Object.keys(restorePayload.tables || {}).join(', ')) + ' · totais: ' + esc(JSON.stringify(totals));
      } catch (e) {
        restorePayload = null;
        $('#bk-restore').disabled = true;
        $('#bk-restore-status').innerHTML = '<span class="bad">JSON inválido: ' + esc(e) + '</span>';
      }
    };
    $('#bk-restore').onclick = async () => {
      if (!restorePayload) return;
      if (!confirm('Confirmar restauração? Isto fará INSERT OR REPLACE nos registros do backup.')) return;
      const btn = $('#bk-restore'); btn.disabled = true; btn.textContent = 'Restaurando…';
      const r = await apiPost('/admin?api=restore-d1', restorePayload);
      if (r.ok) {
        $('#bk-restore-status').innerHTML = '<span class="ok">Restaurado: ' + esc(JSON.stringify(r.restored)) + '</span>' + (r.errors && r.errors.length ? '<br><span class="bad">Erros: ' + esc(r.errors.join(' | ')) + '</span>' : '');
        toast('Restauração concluída.', 'ok');
      } else {
        $('#bk-restore-status').innerHTML = '<span class="bad">Erro: ' + esc(r.error) + '</span>';
        toast('Falha na restauração: ' + (r.error || ''), 'err');
      }
      btn.disabled = false; btn.textContent = '⬆ Restaurar';
    };
  }

  // ── Config ──────────────────────────────────────────────────────────────
  async function loadConfig() {
    const root = $('#tab-config');
    root.innerHTML = '<div class="adm-loading">carregando…</div>';
    const c = await apiGet('/admin?api=config');
    if (!c.ok) { root.innerHTML = '<div class="adm-warn">Erro: ' + esc(c.error) + '</div>'; return; }
    let html = '<div class="adm-box"><h3>Bindings do Worker</h3><table class="adm-table"><thead><tr><th>Binding</th><th>Estado</th><th>Detalhe</th></tr></thead><tbody>';
    const b = c.bindings;
    html += '<tr><td class="mono">MEGGY_D1</td><td>' + (b.MEGGY_D1 ? '<span class="ok-badge">vinculado</span>' : '<span class="bad-badge">—</span>') + '</td><td>backend: ' + esc(b.d1_backend) + '</td></tr>';
    html += '<tr><td class="mono">MEGGY_CACHE</td><td>' + (b.MEGGY_CACHE ? '<span class="ok-badge">vinculado</span>' : '<span class="bad-badge">—</span>') + '</td><td>backend: ' + esc(b.cache_backend) + '</td></tr>';
    html += '<tr><td class="mono">ENV</td><td>' + (b.ENV ? '<span class="ok-badge">vinculado</span>' : '<span class="bad-badge">—</span>') + '</td><td>sessões / usuários (KV)</td></tr>';
    html += '<tr><td class="mono">AI</td><td>' + (b.AI ? '<span class="ok-badge">vinculado</span>' : '<span class="bad-badge">—</span>') + '</td><td>env.ai (CF Workers AI)</td></tr>';
    html += '<tr><td class="mono">gds[]</td><td>' + (b.drives > 0 ? '<span class="ok-badge">' + b.drives + ' drive(s)</span>' : '<span class="bad-badge">0</span>') + '</td><td>Google Drive roots</td></tr>';
    html += '</tbody></table></div>';

    html += '<div class="adm-box"><h3>Variáveis de ambiente (mascaradas)</h3>';
    html += '<p class="adm-hint">Apenas indica se a var está definida e seu tamanho. Valores NUNCA são exibidos.</p>';
    html += '<table class="adm-table"><thead><tr><th>Variável</th><th>Definida</th><th>Tamanho</th><th>Preview</th></tr></thead><tbody>';
    for (const k of Object.keys(c.vars)) {
      const v = c.vars[k];
      html += '<tr><td class="mono">' + esc(k) + '</td>' +
        '<td>' + (v.set ? '<span class="ok-badge">sim</span>' : '<span class="bad-badge">não</span>') + '</td>' +
        '<td>' + (v.set ? esc(v.length) + ' chars' : '—') + '</td>' +
        '<td class="mono">' + (v.set ? esc(v.preview) : '—') + '</td></tr>';
    }
    html += '</tbody></table></div>';

    html += '<div class="adm-box"><h3>Notas</h3>' +
      '<p class="adm-hint">• Variáveis de ambiente são <b>imutáveis em runtime</b> no Cloudflare Workers. Para alterar valores, edite <code>wrangler.toml</code> (seção <code>[vars]</code>) ou use <code>wrangler secret put NOME</code> para secrets, e re-deploy.</p>' +
      '<p class="adm-hint">• <code>D1_BACKEND</code>: <code>off</code> | <code>dual</code> | <code>d1</code>. <code>CACHE_BACKEND</code>: <code>both</code> | <code>kv</code> | <code>drive</code>.</p>' +
      '<p class="adm-hint">• Para editar <code>ADMIN_USERS</code>, altere a variável ADMIN_USERS no wrangler.toml ([vars]) e re-deploy.</p>' +
      '</div>';
    root.innerHTML = html;
  }

  // ── tabs ─────────────────────────────────────────────────────────────────
  const TABS = [
    { id: 'dashboard', label: 'Dashboard', load: null },
    { id: 'users', label: 'Usuários', load: loadUsers },
    { id: 'courses', label: 'Cursos', load: loadCourses },
    { id: 'ai', label: 'IA', load: loadAi },
    { id: 'scanner', label: 'Scanner', load: loadScanner },
    { id: 'backup', label: 'Backup', load: loadBackup },
    { id: 'config', label: 'Config', load: loadConfig }
  ];

  function switchTab(id) {
    currentTab = id;
    $all('.adm-tab-btn').forEach(b => b.classList.toggle('active', b.getAttribute('data-tab') === id));
    $all('.adm-tab-pane').forEach(p => p.style.display = (p.id === 'tab-' + id ? 'block' : 'none'));
    const t = TABS.find(x => x.id === id);
    if (t && t.load) t.load();
    if (id === 'dashboard' && init) renderDashboard(init);
  }

  async function refreshDashboard() {
    try {
      const r = await apiGet('/admin?api=metrics');
      if (r.ok && r.metrics) { init = r.metrics; if (currentTab === 'dashboard') renderDashboard(init); }
    } catch (_) {}
  }

  function boot() {
    try {
      init = JSON.parse($('#adm-init').textContent);
    } catch (_) { init = null; }
    renderDashboard(init);
    $all('.adm-tab-btn').forEach(b => b.onclick = () => switchTab(b.getAttribute('data-tab')));
    $('#adm-refresh').onclick = refreshDashboard;
    $('#adm-poll').onchange = (ev) => {
      if (ev.target.checked) {
        if (pollTimer) return;
        pollTimer = setInterval(refreshDashboard, 15000);
        toast('Auto-refresh ligado (15s).', 'info');
      } else {
        if (pollTimer) { clearInterval(pollTimer); pollTimer = null; toast('Auto-refresh desligado.', 'info'); }
      }
    };
    // auto-poll dashboard quando aberto
    pollTimer = setInterval(refreshDashboard, 15000);
    $('#adm-poll').checked = true;
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
  else boot();
}

// ─── entry point ────────────────────────────────────────────────────────────
// ═══════════════════════════════════════════════════════════════════════════
// ★ v2.3: ADMIN PROFISSIONAL + CURSOS EM DESTAQUE
//   - /admin passa a servir um único painel profissional (handleAdminV23).
//     O /admin antigo (tabela simples, handler aninhado em handleRequest) e
//     o ramo ?panel=pro (que chamava handleAdminPro, inexistente) morrem.
//   - Cursos em destaque: o admin cadastra (nome + pasta do Drive + ícone /
//     cor) e o curso aparece na Home de TODOS os alunos (tabela D1
//     featured_courses). Cursos normais continuam per-user (user_courses).
//   - GET /api/featured-courses é só para logados; os POSTs /api/admin/*
//     são só para ADMIN_USERS. Nenhum valor de segredo passa por aqui.
// ═══════════════════════════════════════════════════════════════════════════


// ═══════════════════════════════════════════════════════════════════════════
// ★ Ronda 13 Frente A: DRIVES DO ADMIN POR ID (GET /api/admin-drives,
//   POST /api/admin/admin-drives/add|update|delete) + GET /api/me +
//   POST /api/drive/by-id. Contrato do app (Ronda 10 B/C, já publicado
//   nas releases Meggy 2.7.29 / BiBi 2.1.28 / Vovó 1.0.28):
//   - GET /api/admin-drives → {ok, drives:[{id, driveId, name, targetApps,
//     coverUrl, subCoverUrl, subfolderCovers, source, rootIndex}]}
//     (só logados, 401 sem sessão; o app filtra por targetApps).
//   - POST /api/admin/admin-drives/add {driveId, name, targetApps[],
//     coverUrl?, subCoverUrl?, subfolderCovers?} → {ok, id}
//     (upsert por drive_id: re-adicionar actualiza sem duplicar).
//   - POST /api/admin/admin-drives/update {id, name?, targetApps?,
//     coverUrl?, subCoverUrl?, subfolderCovers?} → {ok, id}
//     (parcial: só os campos presentes mudam; null limpa a capa).
//   - POST /api/admin/admin-drives/delete {id} → {ok, deleted}
//     (apaga SÓ o registo D1 — NUNCA a pasta no Drive nem as aulas).
//   - GET /api/me → {ok, user, isAdmin} (401 sem sessão).
//   - POST /api/drive/by-id {folderId, pageToken?, pageIndex?} → mesmo
//     envelope do listFolder: {ok, folderId, folderName, data:{files},
//     nextPageToken, curPageIndex}. A pasta é verificada primeiro com
//     files.get (404 honesto em vez de lista vazia); a listagem usa a
//     MESMA maquinaria do listFolder (gd._list_gdrive_files: mesma query,
//     mesmos retries, mesmo filtro de nomes ocultos, mesmos campos).
//   Gate: escrita só p/ ADMIN_USERS (featuredRequireAdmin, 403);
//   GET /api/admin-drives, /api/me e /api/drive/by-id só p/ logados.
// ═══════════════════════════════════════════════════════════════════════════
async function handleAdminDrivesList(request) {
  const user = await gdiSessionUser(request);
  if (!user) return new Response(JSON.stringify({ ok: false, error: 'auth' }), { status: 401, headers: CORS_JSON });
  try{ await d1EnsureSchema(); }catch(_){}
  const d1 = meggyD1Binding();
  if (!d1) return new Response(JSON.stringify({ ok: false, error: 'D1 não vinculado' }), { status: 503, headers: CORS_JSON }); // ★ v2.15.43 (QA-4)
  try {
    const r = await d1.prepare('SELECT id, drive_id, name, target_apps, cover_url, sub_cover_url, subfolder_covers, source, root_index, created_by, created_at, updated_at FROM admin_drives ORDER BY root_index IS NULL, root_index ASC, id ASC').all();
    const drives = (r.results || []).map(adminDrivesRowToJson);
    return new Response(JSON.stringify({ ok: true, drives }), { headers: CORS_JSON });
  } catch (e) {
    const _snap=await loadTableSnapshot('admin_drives');
    if(_snap){
      const drives=_snap.slice().sort(function(a,b){ const an=(a.root_index==null)?1:0, bn=(b.root_index==null)?1:0; if(an!==bn) return an-bn; if((a.root_index||0)!==(b.root_index||0)) return (a.root_index||0)-(b.root_index||0); return (a.id||0)-(b.id||0); }).map(adminDrivesRowToJson);
      return new Response(JSON.stringify({ ok: true, drives: drives, fallback: true }), { headers: CORS_JSON });
    }
    return new Response(JSON.stringify({ ok: false, error: String(e.message || e) }), { status: 500, headers: CORS_JSON });
  }
}

async function handleAdminDrivesAdd(request) {
  const adminUser = await featuredRequireAdmin(request);
  if (!adminUser) return new Response(JSON.stringify({ ok: false, error: 'admin only' }), { status: 403, headers: CORS_JSON });
  let body;
  try { body = await request.json(); } catch (_) { return new Response(JSON.stringify({ ok: false, error: 'invalid json' }), { status: 400, headers: CORS_JSON }); }
  const driveId = String(body.driveId || body.drive_id || '').trim().slice(0, 200);
  const name = String(body.name || '').trim().slice(0, 200);
  if (!driveId) return new Response(JSON.stringify({ ok: false, error: 'driveId obrigatório (id da pasta no Drive)' }), { status: 400, headers: CORS_JSON });
  if (!/^[A-Za-z0-9_-]+$/.test(driveId)) return new Response(JSON.stringify({ ok: false, error: 'driveId inválido (só letras, números, _ e -)' }), { status: 400, headers: CORS_JSON });
  if (!name) return new Response(JSON.stringify({ ok: false, error: 'name obrigatório' }), { status: 400, headers: CORS_JSON });
  const targets = adminDrivesParseTargets((body.targetApps !== undefined) ? body.targetApps : body.target_apps);
  if (!targets.length) return new Response(JSON.stringify({ ok: false, error: 'targetApps obrigatório (um ou mais de: meggy, bibi, vovo)' }), { status: 400, headers: CORS_JSON });
  const urlErr = adminDrivesCheckCovers(body);
  if (urlErr) return new Response(JSON.stringify({ ok: false, error: urlErr }), { status: 400, headers: CORS_JSON });
  const coverUrl = String((body.coverUrl !== undefined ? body.coverUrl : body.cover_url) || '').trim() || null;
  const subCoverUrl = String((body.subCoverUrl !== undefined ? body.subCoverUrl : body.sub_cover_url) || '').trim() || null;
  let coversJson = '{}';
  const cov = (body.subfolderCovers !== undefined) ? body.subfolderCovers : body.subfolder_covers;
  if (cov && typeof cov === 'object' && !Array.isArray(cov)) coversJson = JSON.stringify(cov);
  await d1EnsureSchema();
  const d1 = meggyD1Binding();
  if (!d1) return new Response(JSON.stringify({ ok: false, error: 'D1 não vinculado' }), { status: 502, headers: CORS_JSON });
  try {
    const now = Date.now();
    await d1.prepare('INSERT INTO admin_drives (drive_id, name, target_apps, cover_url, sub_cover_url, subfolder_covers, source, root_index, created_by, created_at, updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(drive_id) DO UPDATE SET name=excluded.name, target_apps=excluded.target_apps, cover_url=excluded.cover_url, sub_cover_url=excluded.sub_cover_url, subfolder_covers=excluded.subfolder_covers, updated_at=excluded.updated_at').bind(driveId, name, JSON.stringify(targets), coverUrl, subCoverUrl, coversJson, 'admin', null, adminUser, now, now).run();
    const row = await d1.prepare('SELECT id FROM admin_drives WHERE drive_id = ?').bind(driveId).first();
    return new Response(JSON.stringify({ ok: true, id: row ? row.id : null }), { headers: CORS_JSON });
  } catch (e) {
    // ★ v2.15.61 (Fase 3.1): drive novo não se perde com o D1 morto
    //   — journal (a linha não tem credenciais; fbOpForbidden é a
    //   segunda linha de defesa §1).
    if (d1QuotaErrorTest21560(e)){
      const _now = Date.now();
      const _row = { drive_id: driveId, name: name, target_apps: JSON.stringify(targets), cover_url: coverUrl, sub_cover_url: subCoverUrl, subfolder_covers: coversJson, source: 'admin', root_index: null, created_by: adminUser, created_at: _now, updated_at: _now };
      if (await fbJournalAppend([{ id: fbOpId(), ts: _now, table: 'admin_drives', action: 'insert', key: { drive_id: driveId }, row: _row }])) return new Response(JSON.stringify({ ok: true, id: null, fallback: true }), { headers: CORS_JSON });
    }
    return new Response(JSON.stringify({ ok: false, error: fbErrorText21561(e) }), { status: 500, headers: CORS_JSON });
  }
}

async function handleAdminDrivesUpdate(request) {
  const adminUser = await featuredRequireAdmin(request);
  if (!adminUser) return new Response(JSON.stringify({ ok: false, error: 'admin only' }), { status: 403, headers: CORS_JSON });
  let body;
  try { body = await request.json(); } catch (_) { return new Response(JSON.stringify({ ok: false, error: 'invalid json' }), { status: 400, headers: CORS_JSON }); }
  const id = Number(body.id);
  if (!id) return new Response(JSON.stringify({ ok: false, error: 'id obrigatório' }), { status: 400, headers: CORS_JSON });
  const sets = [];
  const vals = [];
  if (body.name !== undefined) {
    const nm = String(body.name || '').trim().slice(0, 200);
    if (!nm) return new Response(JSON.stringify({ ok: false, error: 'name não pode ser vazio' }), { status: 400, headers: CORS_JSON });
    sets.push('name=?'); vals.push(nm);
  }
  if (body.targetApps !== undefined || body.target_apps !== undefined) {
    const targets = adminDrivesParseTargets((body.targetApps !== undefined) ? body.targetApps : body.target_apps);
    if (!targets.length) return new Response(JSON.stringify({ ok: false, error: 'targetApps obrigatório (um ou mais de: meggy, bibi, vovo)' }), { status: 400, headers: CORS_JSON });
    sets.push('target_apps=?'); vals.push(JSON.stringify(targets));
  }
  if (body.coverUrl !== undefined || body.cover_url !== undefined) {
    const v = (body.coverUrl !== undefined) ? body.coverUrl : body.cover_url;
    if (v !== null && String(v).trim() !== '' && !adminDrivesValidUrl(String(v).trim())) return new Response(JSON.stringify({ ok: false, error: 'coverUrl inválido (use uma URL http(s))' }), { status: 400, headers: CORS_JSON });
    sets.push('cover_url=?'); vals.push((v === null || String(v).trim() === '') ? null : String(v).trim());
  }
  if (body.subCoverUrl !== undefined || body.sub_cover_url !== undefined) {
    const v = (body.subCoverUrl !== undefined) ? body.subCoverUrl : body.sub_cover_url;
    if (v !== null && String(v).trim() !== '' && !adminDrivesValidUrl(String(v).trim())) return new Response(JSON.stringify({ ok: false, error: 'subCoverUrl inválido (use uma URL http(s))' }), { status: 400, headers: CORS_JSON });
    sets.push('sub_cover_url=?'); vals.push((v === null || String(v).trim() === '') ? null : String(v).trim());
  }
  if (body.subfolderCovers !== undefined || body.subfolder_covers !== undefined) {
    const cov = (body.subfolderCovers !== undefined) ? body.subfolderCovers : body.subfolder_covers;
    if (cov !== null && (typeof cov !== 'object' || Array.isArray(cov))) return new Response(JSON.stringify({ ok: false, error: 'subfolderCovers inválido (use um objeto {caminho: url})' }), { status: 400, headers: CORS_JSON });
    const urlErr = adminDrivesCheckCovers(body);
    if (urlErr) return new Response(JSON.stringify({ ok: false, error: urlErr }), { status: 400, headers: CORS_JSON });
    sets.push('subfolder_covers=?'); vals.push(cov ? JSON.stringify(cov) : '{}');
  }
  if (!sets.length) return new Response(JSON.stringify({ ok: false, error: 'nada para atualizar (envie name, targetApps, coverUrl, subCoverUrl ou subfolderCovers)' }), { status: 400, headers: CORS_JSON });
  await d1EnsureSchema();
  const d1 = meggyD1Binding();
  if (!d1) return new Response(JSON.stringify({ ok: false, error: 'D1 não vinculado' }), { status: 502, headers: CORS_JSON });
  try {
    const row = await d1.prepare('SELECT id FROM admin_drives WHERE id = ?').bind(id).first();
    if (!row) return new Response(JSON.stringify({ ok: false, error: 'não encontrado' }), { status: 404, headers: CORS_JSON });
    sets.push('updated_at=?'); vals.push(Date.now());
    const _stmt = d1.prepare('UPDATE admin_drives SET ' + sets.join(', ') + ' WHERE id=?');
    await _stmt.bind.apply(_stmt, vals.concat([id])).run();
    return new Response(JSON.stringify({ ok: true, id: id }), { headers: CORS_JSON });
  } catch (e) {
    // ★ v2.15.61 (Fase 3.1): edição não se perde com o D1 morto —
    //   op update journalada (o merge aplica os campos por id; se
    //   a linha não existir no D1, o replay é um no-op seguro).
    if (d1QuotaErrorTest21560(e)){
      const _row = {};
      for (let i = 0; i < sets.length; i++){ _row[sets[i].split('=')[0]] = vals[i]; }
      if (_row.updated_at === undefined) _row.updated_at = Date.now();
      if (await fbJournalAppend([{ id: fbOpId(), ts: Date.now(), table: 'admin_drives', action: 'update', key: { id: id }, row: _row }])) return new Response(JSON.stringify({ ok: true, id: id, fallback: true }), { headers: CORS_JSON });
    }
    return new Response(JSON.stringify({ ok: false, error: fbErrorText21561(e) }), { status: 500, headers: CORS_JSON });
  }
}

async function handleAdminDrivesDelete(request) {
  const adminUser = await featuredRequireAdmin(request);
  if (!adminUser) return new Response(JSON.stringify({ ok: false, error: 'admin only' }), { status: 403, headers: CORS_JSON });
  let body;
  try { body = await request.json(); } catch (_) { return new Response(JSON.stringify({ ok: false, error: 'invalid json' }), { status: 400, headers: CORS_JSON }); }
  await d1EnsureSchema();
  const d1 = meggyD1Binding();
  if (!d1) return new Response(JSON.stringify({ ok: false, error: 'D1 não vinculado' }), { status: 502, headers: CORS_JSON });
  try {
    if (body.id == null) return new Response(JSON.stringify({ ok: false, error: 'id obrigatório' }), { status: 400, headers: CORS_JSON });
    const r = await d1.prepare('DELETE FROM admin_drives WHERE id = ?').bind(Number(body.id)).run();
    return new Response(JSON.stringify({ ok: true, deleted: (r && r.meta && r.meta.changes) || 0 }), { headers: CORS_JSON });
  } catch (e) {
    // ★ v2.15.61 (Fase 3.1): remoção journalada com o D1 morto.
    if (d1QuotaErrorTest21560(e) && body.id != null){
      if (await fbJournalAppend([{ id: fbOpId(), ts: Date.now(), table: 'admin_drives', action: 'delete', key: { id: Number(body.id) } }])) return new Response(JSON.stringify({ ok: true, fallback: true }), { headers: CORS_JSON });
    }
    return new Response(JSON.stringify({ ok: false, error: fbErrorText21561(e) }), { status: 500, headers: CORS_JSON });
  }
}

