const GENERAL_COURSES_FILE='general_courses.json';

// ════════════════════════════════════════════════════════════════════════
// ★ FIX 2/3/4 (Task 19): SHARED MEGGY FOLDER helpers
// Drive folder structure (visible in Google Drive, shared across ALL students):
//
//   drive 0 root/
//     └─ .meggy.ai/                              ← shared Meggy memory folder
//        ├─ courses/                             ← general_courses.json + per-course subfolders
//        │  ├─ general_courses.json              ← shared catalog (FIX 2)
//        │  ├─ <courseHash1>/                    ← per-course folder (FIX 3)
//        │  │  ├─ lessons.json                   ← shared scan results
//        │  │  └─ user-<username>.json           ← per-student progress (FIX 4)
//        │  └─ <courseHash2>/
//        │     ├─ lessons.json
//        │     └─ user-<username>.json
//        ├─ resumos/  (per-user .meggy.ai — created by gdiSaveMaterialToSubfolder FIX 1)
//        ├─ cards/
//        ├─ pilulas/
//        ├─ questoes/
//        ├─ simulados/
//        ├─ brain/
//        └─ progress/                            ← shared-progress MD files (existing)
//
// All shared helpers below cache folder IDs on the gd0 instance to avoid
// redundant Drive API calls within the same request lifecycle.
// ════════════════════════════════════════════════════════════════════════

// ★ FIX 2/3/4 (Task 19): find or create .meggy.ai in drive 0's ROOT (shared across all students).
// Cached per gd0 instance.
async function gdiSharedMeggyFolderId(gd0){
  if(gd0.__sharedMegaId)return gd0.__sharedMegaId;
  const rootId = (gd0.root && gd0.root.id) || gd0.rid || gd0.rootId;
  if(!rootId)return null;
  const opts = await gd0.requestOptions();
  const q = "'"+rootId+"' in parents and name = '.meggy.ai' and trashed = false and mimeType = 'application/vnd.google-apps.folder'";
  const r = await fetch('https://www.googleapis.com/drive/v3/files?'+enQuery({includeItemsFromAllDrives:'true',supportsAllDrives:'true',q,fields:'files(id)',pageSize:'1'}), opts);
  let id = null;
  if(r.ok){const j=await r.json();if(j.files&&j.files[0])id=j.files[0].id;}
  if(!id){
    const co = await gd0.requestOptions({'Content-Type':'application/json'},'POST');
    co.body = JSON.stringify({name:'.meggy.ai', mimeType:'application/vnd.google-apps.folder', parents:[rootId]});
    const cr = await fetch('https://www.googleapis.com/drive/v3/files?supportsAllDrives=true', co);
    if(!cr.ok)return null;
    id = (await cr.json()).id || null;
  }
  gd0.__sharedMegaId = id;
  return id;
}

// ★ FIX 2/3/4 (Task 19): find or create <subName> subfolder inside .meggy.ai (drive 0 root).
// Cached per gd0 instance + subName.
async function gdiSharedMeggySubfolderId(gd0, subName){
  if(!gd0.__sharedMegaSub)gd0.__sharedMegaSub = {};
  if(gd0.__sharedMegaSub[subName])return gd0.__sharedMegaSub[subName];
  const megaId = await gdiSharedMeggyFolderId(gd0);
  if(!megaId)return null;
  // ★ v1.0.103 Task 20-1 Fix #5: escape subName no query do Drive — antes, um subName
  // contendo aspa simples (ex.: "course's folder") quebrava o query string e podia causar
  // query injection. Cache key permanece com subName cru (não vai pro Drive); só o query
  // precisa de escape. Reusa driveEscape (escapa backslash + single quote, padrão já usado
  // nos outros sites do worker).
  const safeSubName = driveEscape(subName);
  const opts = await gd0.requestOptions();
  const q = "'"+megaId+"' in parents and name = '"+safeSubName+"' and trashed = false and mimeType = 'application/vnd.google-apps.folder'";
  const r = await fetch('https://www.googleapis.com/drive/v3/files?'+enQuery({includeItemsFromAllDrives:'true',supportsAllDrives:'true',q,fields:'files(id)',pageSize:'1'}), opts);
  let id = null;
  if(r.ok){const j=await r.json();if(j.files&&j.files[0])id=j.files[0].id;}
  if(!id){
    const co = await gd0.requestOptions({'Content-Type':'application/json'},'POST');
    co.body = JSON.stringify({name:subName, mimeType:'application/vnd.google-apps.folder', parents:[megaId]});  // JSON.stringify escapa automaticamente
    const cr = await fetch('https://www.googleapis.com/drive/v3/files?supportsAllDrives=true', co);
    if(!cr.ok)return null;
    id = (await cr.json()).id || null;
  }
  gd0.__sharedMegaSub[subName] = id;
  return id;
}

// ★ FIX 2/3/4 (Task 19): find or create a subfolder inside .meggy.ai/<parent>/.
// Used for per-course-hash subfolders (.meggy.ai/courses/<courseHash>/).
async function gdiSharedMeggyDeepSubfolderId(gd0, parentId, subName){
  if(!gd0.__sharedMegaDeep)gd0.__sharedMegaDeep = {};
  const key = parentId + '/' + subName;
  if(gd0.__sharedMegaDeep[key])return gd0.__sharedMegaDeep[key];
  // ★ v1.0.103 Task 20-1 Fix #5: escape subName no query do Drive — mesmo motivo que
  // gdiSharedMeggySubfolderId: aspa simples ou backslash em subName quebrava o query
  // string do Drive (name='..\'..'). Cache key permanece cru; só query é escapado.
  const safeSubName = driveEscape(subName);
  const opts = await gd0.requestOptions();
  const q = "'"+parentId+"' in parents and name = '"+safeSubName+"' and trashed = false and mimeType = 'application/vnd.google-apps.folder'";
  const r = await fetch('https://www.googleapis.com/drive/v3/files?'+enQuery({includeItemsFromAllDrives:'true',supportsAllDrives:'true',q,fields:'files(id)',pageSize:'1'}), opts);
  let id = null;
  if(r.ok){const j=await r.json();if(j.files&&j.files[0])id=j.files[0].id;}
  if(!id){
    const co = await gd0.requestOptions({'Content-Type':'application/json'},'POST');
    co.body = JSON.stringify({name:subName, mimeType:'application/vnd.google-apps.folder', parents:[parentId]});  // JSON.stringify escapa automaticamente
    const cr = await fetch('https://www.googleapis.com/drive/v3/files?supportsAllDrives=true', co);
    if(!cr.ok)return null;
    id = (await cr.json()).id || null;
  }
  gd0.__sharedMegaDeep[key] = id;
  return id;
}

// ════════════════════════════════════════════════════════════════════════
// ★ v1.0.96 (ENG-SCANNER-DISTRIBUTED): DOTFILE HELPERS
// Atomic, per-folder upserts/reads of .gdi-*.json dotfiles inside any Drive
// folder. Mirror fallback for read-only drives via .meggy.ai/mirror/<courseHash>/.
// Spec: PROJETO_ENG_SCANNER_DISTRIBUIDO.md, Sections 4.1-4.3.
// ════════════════════════════════════════════════════════════════════════

// ★ Section 4.1: writes (or updates) a dotfile (.gdi-*.json) inside a Drive folder.
// Returns {ok:true, fileId, mode:'patch'|'create'} or {ok:false, reason:'permission'|'invalid'|'exception'|'unknown', error?}.
// Caller falls back to mirror on reason='permission'.
// ★ v1.0.223: Cleanup old non-dotted scanner files from previous versions
// Removes: gdi-course.json, gdi-lessons.json, gdi-scan-state.json, progress_cache.json
// (the current scanner uses .gdi-course.json, .gdi-lessons.json, etc. with leading dot)
async function gdiCleanupOldDotfiles(gd, folderId){
  if(!folderId) return {ok:false, reason:'no folderId'};
  const opts = await gd.requestOptions();
  const oldNames = ['gdi-course.json', 'gdi-lessons.json', 'gdi-scan-state.json', 'progress_cache.json'];
  let deleted = 0;
  for(const name of oldNames){
    try{
      const safeName = driveEscape(name);
      const q = "'"+folderId+"' in parents and name = '"+safeName+"' and trashed = false";
      const r = await fetch('https://www.googleapis.com/drive/v3/files?'+enQuery({
        includeItemsFromAllDrives:'true', supportsAllDrives:'true',
        q, fields:'files(id)', pageSize:'5'
      }), opts);
      if(r.ok){
        const j = await r.json();
        if(j.files){
          for(const f of j.files){
            try{
              await fetch('https://www.googleapis.com/drive/v3/files/'+f.id+'?supportsAllDrives=true&trashed=true',{
                method:'PATCH', headers:opts.headers
              });
              deleted++;
            }catch(_){}
          }
        }
      }
    }catch(_){}
  }
  return {ok:true, deleted};
}

// ★ v1.0.224 FASE 3: Clean up old dotfiles from subfolders after root consolidation
// Recursively walks subfolders and trashes .gdi-lessons.json + .gdi-scan-state.json
// Best-effort: errors are silently ignored. Non-blocking (called with .catch()).
async function cleanupOldSubfolderDotfiles(gd, folderId, coursePath, courseHash, isRoot){
  // ★ MERGE (staging) — desvio documentado do main v1.0.224: o main chama esta função com a
  // pasta-RAIZ do curso, mas o corpo apaga .gdi-lessons.json/.gdi-scan-state.json da PRÓPRIA
  // pasta antes de recursar — ou seja, apagaria o arquivo consolidado que a FASE 1 acabou de
  // escrever na raiz, anulando a FASE 2. Com isRoot=true pula-se só a autolimpeza; a recursão
  // nas subpastas (chamadas sem o 5º arg) continua idêntica ao main.
  const opts = await gd.requestOptions();
  if(!isRoot){ // ★ MERGE: não apagar os dotfiles consolidados da própria raiz
    let pageToken = null;
    const filesToDelete = [];
    do {
      const params = {
        includeItemsFromAllDrives:'true', supportsAllDrives:'true',
        q: `'${folderId}' in parents and trashed = false and (name = '.gdi-lessons.json' or name = '.gdi-scan-state.json')`,
        fields: 'files(id,name),nextPageToken', pageSize: '100'
      };
      if(pageToken) params.pageToken = pageToken;
      const r = await fetch('https://www.googleapis.com/drive/v3/files?'+enQuery(params), opts);
      if(!r.ok) return;
      const j = await r.json();
      if(j.files) filesToDelete.push(...j.files);
      pageToken = j.nextPageToken;
    } while(pageToken);

    // Trash each old dotfile
    for(const f of filesToDelete){
      try {
        await fetch(`https://www.googleapis.com/drive/v3/files/${f.id}?supportsAllDrives=true&trashed=true`, {
          method:'PATCH', headers:opts.headers
        });
      } catch(_) { /* ignore */ }
    }
  }

  // Also walk subfolders (1 level deep) and clean their dotfiles
  const subResp = await fetch('https://www.googleapis.com/drive/v3/files?'+enQuery({
    includeItemsFromAllDrives:'true', supportsAllDrives:'true',
    q: `'${folderId}' in parents and mimeType = 'application/vnd.google-apps.folder' and trashed = false`,
    fields: 'files(id,name)', pageSize: '200'
  }), opts);
  if(!subResp.ok) return;
  const subJ = await subResp.json();
  if(subJ.files){
    for(const sf of subJ.files.slice(0, 50)){ // cap at 50 subfolders to avoid subrequest limits
      try {
        await cleanupOldSubfolderDotfiles(gd, sf.id, coursePath, courseHash);
      } catch(_) { /* ignore */ }
    }
  }
}

async function gdiWriteFolderDotfile(gd, folderId, fileName, jsonStr){
  if(!folderId || !fileName || !jsonStr) return {ok:false, reason:'invalid'};
  const opts = await gd.requestOptions();
  // 1. Search for an existing dotfile by name inside folderId.
  // ★ v1.0.98 FIX: escape single quotes in fileName to prevent Drive API query injection
  const safeFileName = driveEscape(fileName);  // ★ v1.0.103 Task 20-11 Fix #11: driveEscape (escapa backslash + single quote) — antes só escapava single quote
  const q = "'"+folderId+"' in parents and name = '"+safeFileName+"' and trashed = false";
  const r = await fetch('https://www.googleapis.com/drive/v3/files?'+enQuery({
    includeItemsFromAllDrives:'true', supportsAllDrives:'true',
    q, fields:'files(id)', pageSize:'1'
  }), opts);
  let existingId = null;
  if(r.ok){ const j = await r.json(); if(j.files && j.files[0]) existingId = j.files[0].id; }
  // 2. Upsert: PATCH if exists, POST (multipart) if not.
  try{
    if(existingId){
      const po = await gd.requestOptions({'Content-Type':'application/json; charset=UTF-8'},'PATCH');
      const pr = await fetch("https://www.googleapis.com/upload/drive/v3/files/"+existingId+"?uploadType=media&supportsAllDrives=true",{
        method:'PATCH', headers:po.headers, body:jsonStr
      });
      if(pr.ok) return {ok:true, fileId:existingId, mode:'patch'};
      // 403 = no write permission — caller will fall back to mirror.
      if(pr.status === 403) return {ok:false, reason:'permission'};
      return {ok:false, reason:'http_'+pr.status};
    } else {
      const boundary = 'gdidot'+Date.now();
      const mp = '--'+boundary+'\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n'+JSON.stringify({name:fileName, parents:[folderId]})+'\r\n--'+boundary+'\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n'+jsonStr+'\r\n--'+boundary+'--';
      const uo = await gd.requestOptions({'Content-Type':'multipart/related; boundary='+boundary},'POST');
      const ur = await fetch('https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&supportsAllDrives=true',{
        method:'POST', headers:uo.headers, body:mp
      });
      if(ur.ok){ const uj = await ur.json(); return {ok:true, fileId:uj.id, mode:'create'}; }
      if(ur.status === 403) return {ok:false, reason:'permission'};
      return {ok:false, reason:'http_'+ur.status};
    }
  }catch(e){ return {ok:false, reason:'exception', error:e.message}; }
}

// ★ Section 4.2: reads a dotfile from a Drive folder.
// Returns {ok:true, data, fileId, modifiedTime} or {ok:false, reason:'not_found'|'permission'|'parse_error'|'http_NNN'|'invalid'}.
// 'not_found' = no dotfile in this folder (normal — folder never scanned).
// 'permission' = drive is read-only (caller should try mirror).
async function gdiReadFolderDotfile(gd, folderId, fileName){
  if(!folderId || !fileName) return {ok:false, reason:'invalid'};
  const opts = await gd.requestOptions();
  // ★ v1.0.98 FIX: escape single quotes in fileName to prevent Drive API query injection
  const safeFileName = driveEscape(fileName);  // ★ v1.0.103 Task 20-11 Fix #11: driveEscape (escapa backslash + single quote) — antes só escapava single quote
  const q = "'"+folderId+"' in parents and name = '"+safeFileName+"' and trashed = false";
  const r = await fetch('https://www.googleapis.com/drive/v3/files?'+enQuery({
    includeItemsFromAllDrives:'true', supportsAllDrives:'true',
    q, fields:'files(id,modifiedTime)', pageSize:'1'
  }), opts);
  if(!r.ok){
    if(r.status === 403) return {ok:false, reason:'permission'};
    return {ok:false, reason:'http_'+r.status};
  }
  const j = await r.json();
  if(!j.files || !j.files[0]) return {ok:false, reason:'not_found'};
  const fileId = j.files[0].id;
  const fr = await fetch("https://www.googleapis.com/drive/v3/files/"+fileId+"?alt=media&supportsAllDrives=true", opts);
  if(!fr.ok){
    if(fr.status === 403) return {ok:false, reason:'permission'};
    return {ok:false, reason:'http_'+fr.status};
  }
  const txt = await fr.text();
  try{ return {ok:true, data:JSON.parse(txt), fileId, modifiedTime:j.files[0].modifiedTime}; }
  catch(e){ return {ok:false, reason:'parse_error', raw:txt.slice(0,200)}; }
}

// ★ Section 4.3: resolves (or creates) the mirror folder for a read-only drive.
// Layout: .meggy.ai/mirror/<courseHash>/<relPath>/
//   where relPath = folderPath with the coursePath prefix stripped.
// Returns the folderId of the deepest mirror folder, or null on failure.
async function gdiResolveMirrorFolder(gd0, courseHash, folderPath){
  if(!gd0 || !courseHash) return null;  // ★ CYCLE-1 Fix Bug #2: removed `|| !folderPath` — root folder's relPath is '' (empty). The old guard rejected empty folderPath, returning null, which silently broke mirror fallback for the ROOT folder of a course (gdiScanDistributed line ~3453, gdiReadCourseDistributedLessons line ~3741). Now we resolve to courseMirrorId when folderPath is empty (the for-loop over `parts` simply doesn't execute).
  // ★ v1.0.103 Task 20-2 Fix #9: path-level cache — gdiResolveMirrorFolder é chamado 1×
  // por folder scan (gdiScanDistributed ~linha 3331, gdiReadCourseDistributedLessons
  // ~linha 3578, handleMaterialsSaveInFolder ~linha 4761, handleMaterialsLoadFromFolder
  // ~linha 4852, etc). Cada call navega 3+níveis de subpastas no mirror (.meggy.ai/mirror/
  // <courseHash>/<part1>/<part2>/...) = 3-5 subrequests por call. Em um scan distribuído
  // que processa 4 folders, isso são 4×5 = 20 subrequests só de mirror resolution. Cache
  // por (courseHash, folderPath) elimina re-resolução dentro do mesmo request. Só cacheia
  // sucesso (não cacheia null para permitir retry em falhas transientórias).
  gd0.__mirrorPathCache = gd0.__mirrorPathCache || {};
  const cacheKey = courseHash + '/' + (folderPath || '');
  if (gd0.__mirrorPathCache[cacheKey]) return gd0.__mirrorPathCache[cacheKey];
  // 1. .meggy.ai/
  const megaId = await gdiSharedMeggyFolderId(gd0);
  if(!megaId) return null;
  // 2. .meggy.ai/mirror/
  const mirrorId = await gdiSharedMeggySubfolderId(gd0, 'mirror');
  if(!mirrorId) return null;
  // 3. .meggy.ai/mirror/<courseHash>/
  const courseMirrorId = await gdiSharedMeggyDeepSubfolderId(gd0, mirrorId, courseHash);
  if(!courseMirrorId) return null;
  // 4. Walk relPath components — create-or-find each subfolder.
  //    relPath is the path INSIDE the course (without /driveIdx:/ prefix and without coursePath).
  //    For the ROOT folder, relPath is '' — the loop below doesn't execute, and we return courseMirrorId.
  const parts = String(folderPath || '').split('/').filter(Boolean);
  let currentId = courseMirrorId;
  for(const part of parts){
    const next = await gdiSharedMeggyDeepSubfolderId(gd0, currentId, part);
    if(!next) return null;
    currentId = next;
  }
  gd0.__mirrorPathCache[cacheKey] = currentId;  // ★ cache hit na próxima call
  return currentId;
}

// ★ Section 4.3 util: strips the coursePath prefix from a folderPath.
// "/11:/TJ SP Escrevente/Módulo 1/Português" + "/11:/TJ SP Escrevente"
//   → "Módulo 1/Português"
function folderPathRelativeToCourse(folderPath, coursePath){
  if(!folderPath || !coursePath) return '';
  // ★ CYCLE-1 Fix Bug #1: strip drive prefix (e.g. '/0:/') from BOTH paths before
  // comparing. Before this fix, when `folderPath` lacked the drive prefix (e.g. the
  // root folder's path passed by gdiScanCourseDistributedBatch is `startPath` which is
  // `parsed.subPath` = 'TJ SP' without '/0:/'), `rel.startsWith(cp)` was false and the
  // function returned the full folderPath instead of the relative path. This caused
  // gdiResolveMirrorFolder to create an extra subfolder (e.g. .meggy.ai/mirror/<hash>/
  // TJ SP/ instead of .meggy.ai/mirror/<hash>/) for the ROOT folder, breaking mirror
  // fallback for read-only drives on the course root.
  const stripDrive = s => String(s).replace(/^\/\d+:\/*/, '');
  let rel = stripDrive(folderPath);
  const cp = stripDrive(coursePath);
  if(rel.startsWith(cp)) rel = rel.slice(cp.length);
  return rel.replace(/^\/+/, '');
}

// ★ v2.15.8 (A): leitura de dotfile da RAIZ do curso com fallback p/ o
//   mirror (drive read-only). A escrita JÁ caía p/ o mirror no 403
//   (v1.0.117), mas TODAS as leituras só tentavam o mirror em erro de
//   PERMISSÃO — num drive read-only a leitura direta devolve 'not_found'
//   (o arquivo existe, mas no mirror), nunca 403. Resultado: o meta
//   (.gdi-course.json, o cursor pending) e o consolidado parcial nunca
//   eram reencontrados, o batch recomeçava da raiz a cada run e a fila
//   ciclava p/ sempre sem erro (o /9: e o /10: ao vivo: cycles 24/23,
//   retries 1/2, "erro desconhecido"). O probe do mirror só acontece
//   quando a leitura direta FALHA (drive gravável: 0 fetches extras;
//   read-only: +3 resolve +2 leitura, 1× por run p/ o meta — o resolve
//   é cacheado por request). Retorna {ok, data, source, reason}.
//   `directRes` (opcional) = resultado de uma leitura direta já feita
//   pelo chamador — evita reler o direto 2× (o probe do mirror segue).
async function gdiReadCourseRootDotfile(gd, courseHash, folderId, fileName, counter, directRes){
  const _ctr = counter || { value: 0 };
  let res = directRes;
  if (res === undefined) {
    try { res = await gdiReadFolderDotfile(gd, folderId, fileName); } catch (_) { res = { ok: false, reason: 'exception' }; }
    _ctr.value += 2;
  }
  if (res && res.ok) return { ok: true, data: res.data, source: 'direct', reason: null };
  const mirrorable = !res || !res.ok;
  if (!mirrorable) return { ok: false, data: null, source: null, reason: (res && res.reason) || 'unknown' };
  const rsn = (res && res.reason) || 'not_found';
  if (rsn !== 'not_found' && rsn !== 'permission' && rsn !== 'http_403' && rsn !== 'http_401') return { ok: false, data: null, source: null, reason: rsn };
  try {
    const gd0 = (typeof gds !== 'undefined' && gds) ? gds[0] : null;
    if (!gd0 || gd0 === gd) return { ok: false, data: null, source: null, reason: rsn };
    const mirrorId = await gdiResolveMirrorFolder(gd0, courseHash, '');
    _ctr.value += 3; // resolve da raiz (prefixo cacheado no request; R4)
    if (!mirrorId) return { ok: false, data: null, source: null, reason: rsn };
    const mres = await gdiReadFolderDotfile(gd0, mirrorId, fileName);
    _ctr.value += 2;
    if (mres && mres.ok) return { ok: true, data: mres.data, source: 'mirror', reason: null };
    return { ok: false, data: null, source: null, reason: rsn };
  } catch (_) {
    return { ok: false, data: null, source: null, reason: rsn };
  }
}

// ════════════════════════════════════════════════════════════════════════
// ★ v1.0.96 (ENG-SCANNER-DISTRIBUTED): SCAN DISTRIBUTED FUNCTIONS
// Scan 1 folder → dotfiles; batch up to SCAN_MAX_SUBREQ folders; read all
// dotfiles recursively with legacy fallback.
// Spec: PROJETO_ENG_SCANNER_DISTRIBUIDO.md, Sections 4.4-4.6.
// ════════════════════════════════════════════════════════════════════════

// ★ Section 4.4: scans ONE folder. Writes .gdi-lessons.json only.
// ★ v2.15.5 (R1): o .gdi-scan-state.json POR PASTA não é mais escrito —
//   NENHUM resume o lê (o resume lê .gdi-course.json + .gdi-lessons.json);
//   era 2 fetches por pasta fresca sem leitor. O state da RAIZ no done
//   (legado p/ clientes antigos) é mantido no batch.
// Returns: { ok, lessons, childFolders, status, mode:'direct'|'mirror'|'cached', stale, scannedAt? }.
// status ∈ {'cached','done','pending','error'}.
// ★ v2.15.2 (A): versão dos dotfiles do scanner. O batch antigo marcava
//   pastas como escaneadas sem escrever o dotfile (dotfilesSkipped) e a
//   leitura podava a subárvore delas — cursos fecharam "done" com aulas
//   faltando. Meta/consolidado sem esta versão (ou com outra) NÃO é
//   confiável: o batch recomeça da raiz e o consolidado é refeito.
const SCAN_DOTFILE_VERSION = 'v2.15.3';
// ★ v2.15.3 (W1/W3/W6): rebase canônico de caminho de Drive.
//   O mesmo id de pasta pode aparecer sob índices diferentes — dentro de um
//   worker (roots gêmeas /9:×/11: no staging-c) E ENTRE workers (o staging-c
//   escreve dotfiles com paths /11: dentro da pasta física; o meuc lê esses
//   dotfiles sob /6: e juntava '/6:/' + '/11:/…' = '/6://11:/…', 156 linhas
//   no D1 meggy-meuc sob o curso REGISTRADO /6:/CURSOS%202026).
//   Regra: NUNCA concatenar prefixo com path que já traz prefixo —
//   rebaseDrivePath tira QUALQUER prefixo /^\/\d+:\/* / (repetido, ex.
//   '/9://11:/X') e reaplica o do drive corrente; colapsa '//' e tira a
//   barra final (exceto a raiz '/N:').
function rebaseDrivePath(p, driveIdx){
  let idx = (driveIdx === undefined || driveIdx === null || isNaN(Number(driveIdx))) ? 0 : Number(driveIdx);
  if (!isFinite(idx) || idx < 0) idx = 0; // ★ v2.15.3: gd fora de gds dá indexOf -1 — nunca gerar '/-1:/'
  let s = String(p || '').trim();
  s = s.replace(/^\/+/, '');
  while (/^\d+:\/*/.test(s)) s = s.replace(/^\d+:\/*/, '');
  s = s.replace(/\/{2,}/g, '/').replace(/\/+$/, '');
  return s ? '/' + idx + ':/' + s : '/' + idx + ':';
}
// ★ v2.15.3 (W3): identidade canônica de um drive físico — o MENOR índice
//   entre os roots com o mesmo id de pasta. No staging-c, roots[9] e
//   roots[11] têm o mesmo id → canônico é 9 ('/11:' mapeia para '/9:').
//   No meuc o id aparece 1× (índice 6) → canônico é 6 (no-op); a
//   contaminação cross-worker (/6://11:/) NÃO se resolve aqui (não há
//   /11: no meuc) e sim pelo rebase (W1) + normalização na ingestão (W2).
function canonicalDriveIndex(idx){
  try{
    const roots = (typeof authConfig !== 'undefined' && authConfig && Array.isArray(authConfig.roots)) ? authConfig.roots : null;
    if(!roots || idx === undefined || idx === null) return idx;
    const id = roots[Number(idx)] && roots[Number(idx)].id;
    if(!id) return idx;
    let best = Number(idx);
    for(let i = 0; i < roots.length; i++){ if(roots[i] && roots[i].id === id && i < best) best = i; }
    return best;
  }catch(_){ return idx; }
}
// ★ v2.15.3 (W3): reescreve um course_path para a identidade canônica do
//   drive físico (prefixo + driveIndex).
// ★ v2.15.7 (dedup): grafia LEGADA '/11:/CURSOS%202026' — até a F-04
//   (v2.15.6-conn-audit, 2026-11-15) as raízes 9 e 11 apontavam p/ a MESMA
//   pasta (1pqts…); o D1 ficou com 180 linhas sob '/11:' + 53 sob
//   '/9:/CURSOS 2026' (cru) p/ o mesmo conteúdo. A F-04 separou as raízes
//   (11 = OAB), então o código NÃO pode mais deduzir o gêmeo pelo id do
//   drive: esta tabela é a ponte explícita, só p/ esse curso, e só vale
//   enquanto houver linhas legadas no D1. Depois da limpeza v2.15.7
//   (NOTES.md — reescreve as linhas p/ a grafia canônica + user_courses),
//   APAGAR esta tabela: canonicalCoursePath volta a ser só índice+encode.
const LEGACY_COURSE_PATH_REBASE = { '/11:/CURSOS%202026': '/9:/CURSOS%202026' };
function legacyCoursePathRebase(p){
  try{
    const n = (typeof normalizeCoursePath === 'function' ? normalizeCoursePath(p) : String(p || '').trim()).replace(/\/+$/, '');
    for (const k in LEGACY_COURSE_PATH_REBASE) {
      if (n === k || n.indexOf(k + '/') === 0) return LEGACY_COURSE_PATH_REBASE[k] + n.slice(k.length);
    }
    return n;
  }catch(_){ return String(p || '').trim(); }
}
// ★ v2.15.3 (W3): reescreve um course_path para a identidade canônica do
//   drive físico (prefixo + driveIndex).
// ★ v2.15.7 (dedup): UMA grafia canônica — '/<idx>:/<seg1>/<seg2>...',
//   idx = menor índice gêmeo do drive, segmentos codificados
//   (encodeURIComponent), SEM barra final. É o que d1InsertLessons grava,
//   o que o backfill enfileira e o que unified/by-course/busca leem.
//   Ex.: '/11:/CURSOS%202026', '/9:/CURSOS 2026', '/9:/CURSOS 2026/'
//   → '/9:/CURSOS%202026'; '/9:/CURSOS%202026/isolada-direito-penal/'
//   → '/9:/CURSOS%202026/isolada-direito-penal'.
function canonicalCoursePath(p){
  const m = String(p || '').match(/^\s*\/(\d+):\/?(.*)$/);
  if(!m) return String(p || '').trim();
  const canon = canonicalDriveIndex(Number(m[1]));
  const rebased = rebaseDrivePath('/' + canon + ':/' + (m[2] || ''), canon);
  let out = rebased;
  try { if (typeof normalizeCoursePath === 'function') out = normalizeCoursePath(rebased).replace(/\/+$/, ''); } catch (_) {}
  if (typeof legacyCoursePathRebase === 'function') { try { out = legacyCoursePathRebase(out); } catch (_) {} }
  return out;
}
// ★ v2.15.7 (dedup): 1 aula = 1 pasta de aula — chave da pasta de uma
//   linha de lessons. dirname(lesson_path) com '/material' final colapsado
//   (o material mora numa subpasta da Aula); arquivo solto NA RAIZ do curso
//   conta 1 por arquivo de mídia (vídeo/áudio) e 0 por arquivo não-mídia
//   (README/requirements soltos não são aulas). lessonType pode vir vazio
//   (front/progresso) — sem tipo, o arquivo solto conta como aula.
//   Ex.: jornada = 230 linhas → 74 aulas; CURSOS 2026 = 233 → 75;
//   isolada = 385 → 127; TJ Oficial = 97 → 33; total 715 → 235.
function lessonFolderKey(lessonPath, coursePath, lessonType){
  try{
    let lp = (typeof normalizeLessonPath === 'function') ? normalizeLessonPath(lessonPath) : String(lessonPath || '').trim();
    if (typeof legacyCoursePathRebase === 'function') { try { lp = legacyCoursePathRebase(lp); } catch (_) {} }
    if(!lp) return null;
    const cp = (typeof canonicalCoursePath === 'function') ? canonicalCoursePath(coursePath) : String(coursePath || '').trim();
    const slash = lp.lastIndexOf('/');
    let d = slash > 0 ? lp.slice(0, slash) : lp;
    if (d.length > 9 && d.slice(-9) === '/material') d = d.slice(0, -9);
    if (cp && d === cp) {
      const t = String(lessonType || '').toLowerCase();
      if (!t) return lp;
      if (t === 'video' || t === 'audio') return lp;
      return null;
    }
    return d || null;
  }catch(_){ return null; }
}

// ★ v2.15.5 (R8): chave FÍSICA de um curso — id REAL da pasta-raiz do
//   drive + subcaminho normalizado (codificado). A dedup por índice
//   canônico (W3) depende da ORDEM de authConfig.roots; a chave física
//   sobrevive a reordenação e colapsa gêmeos mesmo se o índice canônico
//   falhar (authConfig ausente no contexto, root sem id). Usada como
//   chave de dedup em mergeBackfillQueue e na canonicalização da fila.
function physicalDriveKey(p){
  try{
    const m = String(p || '').match(/^\s*\/(\d+):\/?(.*)$/);
    if(!m) return normScanPath(p);
    const idx = Number(m[1]);
    let id = null;
    try{ const roots = (typeof authConfig !== 'undefined' && authConfig && Array.isArray(authConfig.roots)) ? authConfig.roots : null; if(roots && roots[idx]) id = roots[idx].id || null; }catch(_){}
    const sub = normScanPath('/0:/' + (m[2] || '')).replace(/^\/0:\/?/, '');
    return (id ? 'id:' + id : 'idx:' + idx) + '|' + sub;
  }catch(_){ return normScanPath(p); }
}
// ★ v2.15.5 (R2): knownMtime (8º arg, opcional) = modifiedTime da pasta
//   que a LISTAGEM DO PAI já trouxe. Sem ele, o GET de mtime é feito
//   como antes; com ele, 1 fetch a menos por pasta (fresca 6→5, cache 3→2).
//   O mtime vem da mesma listagem que descobriu a pasta — a semântica de
//   staleness não muda (se a pasta mudar depois da listagem, o dotfile
//   guarda o mtime da listagem e o próximo scan vê o mtime novo → stale).
async function gdiScanDistributed(gd, folderId, folderPath, coursePath, courseHash, user, counter, knownMtime, scanOpts){
  const _ctr = counter || { value: 0 };
  const gd0 = gds[0];
  const driveIdx = gd.order !== undefined ? gd.order : (gd.index !== undefined ? gd.index : gds.indexOf(gd));
  // ★ v1.0.96 FIX: CF Worker has a hard 50-subrequest limit per invocation.
  // Each folder scan uses ~6-8 real subrequests (mtime + list + read dotfile + write × 2).
  // Our counter only tracks mtime + list (2 per folder), so we cap at 7 folders per batch
  // to stay safely under 50 (7 × 7 = 49 actual subrequests).
  // ★ v1.0.103 Task 20-2 Fix #5: lowered 14 → 8. Razão: counter conta apenas 2 subrequests
  // por folder (mtime + list), mas o real é 6-8 (incluindo dotfile reads + 2 writes).
  // ★ v1.0.109: Increased from 8 to 16 — each folder uses ~4 real subrequests (mtime + list + 2 writes),
  // so 16 counted = ~8 folders × 4 real = 32 real, with 18 margin for nav + overhead under CF's 50 limit.
  // Previous value of 8 was too conservative — courses with 8000+ folders needed 1000+ batches.
  // ★ v2.15.3 (W5): 16 → 28. A contagem agora é HONESTA (leitura de
  //   dotfile +2, mirror +3/+2 — antes só mtime+lista eram contados, e 16
  //   contados escondiam ~32 reais). 28 contados ≈ 28-32 reais por batch,
  //   com folga para o teto de 50 do CF (o backfill soma margem +8).
  // ★ v2.15.5 (R1/R2/R4): 28 → 32. Pasta fresca agora custa 5 contados
  //   (mtime 1 — ou 0 com mtime herdado — + dotfile 2 + lista 1 + escrita
  //   2; o .gdi-scan-state.json por pasta saiu) e a em cache 2 (dotfile).
  //   32 contados ≈ 32-38 reais por batch; o backfill soma overhead ~5
  //   (token + resolve + meta) e margem +2 — total ≲ 45, teto CF 50.
  const SUBREQ_HARD_LIMIT = 32;
  // 1. Fetch folder modifiedTime (for staleness check).
  // ★ v2.15.5 (R2): mtime herdado da listagem do pai dispensa o GET.
  if(_ctr.value >= SUBREQ_HARD_LIMIT) return {ok:false, reason:'limit', lessons:[], childFolders:[], status:'pending'};
  const opts = await gd.requestOptions();
  let folderMtime = (knownMtime !== undefined && knownMtime !== null && knownMtime !== '') ? knownMtime : null;
  if(folderMtime === null){
    const fr = await fetch("https://www.googleapis.com/drive/v3/files/"+folderId+"?fields=modifiedTime&supportsAllDrives=true", opts);
    _ctr.value++;
    if(fr.ok){ const fj = await fr.json(); folderMtime = fj.modifiedTime || null; }
  }

  // 2. Look for an existing dotfile (direct first; only probe mirror on permission error).
  //    ★ v1.0.96 FIX: probing mirror for every fresh folder blew the 40-subrequest limit.
  //    Only fall back to mirror when direct read returns permission denied (403).
  let dotfileMode = 'direct';
  let dotFolderId = folderId;
  let existing = await gdiReadFolderDotfile(gd, folderId, '.gdi-lessons.json');
  _ctr.value += 2; // ★ v2.15.3 (W5): a leitura do dotfile custa 2 fetches (lista + download) e NÃO era contada
  // ★ v2.15.8 (A): em modo mirror (o meta do curso veio do mirror — o drive
  //   é read-only) o dotfile da pasta também pode viver no mirror: a leitura
  //   direta devolve not_found (nunca 403) e a pasta seria re-escaneada
  //   fresca a cada run (o cache nunca acertava). O probe só roda em modo
  //   mirror; o resolve é cacheado por (hash, relPath) no request.
  if(!existing.ok && existing.reason === 'not_found' && scanOpts && scanOpts.mirror){
    try{
      const mirrorId = await gdiResolveMirrorFolder(gd0, courseHash, folderPathRelativeToCourse(folderPath, coursePath));
      _ctr.value += 3; // resolve (prefixo cacheado; a cauda é 1 fetch/nível)
      if(mirrorId){
        dotfileMode = 'mirror';
        dotFolderId = mirrorId;
        existing = await gdiReadFolderDotfile(gd0, mirrorId, '.gdi-lessons.json');
        _ctr.value += 2;
      }
    }catch(_){}
  }
  if(!existing.ok && (existing.reason === 'permission' || existing.reason === 'http_403' || existing.reason === 'http_401')){
    // Direct read denied — try mirror.
    const mirrorId = await gdiResolveMirrorFolder(gd0, courseHash, folderPathRelativeToCourse(folderPath, coursePath));
    _ctr.value += 8; // ★ v2.15.5 (R4): resolução do mirror ≈ 3 + partes do relPath (o +3 subcontava pastas fundas; o 1º resolve por (courseHash, relPath) navega .meggy.ai/mirror/<hash>/<partes>)
    if(mirrorId){
      dotfileMode = 'mirror';
      dotFolderId = mirrorId;
      existing = await gdiReadFolderDotfile(gd0, mirrorId, '.gdi-lessons.json');
      _ctr.value += 2; // ★ v2.15.3 (W5): leitura do dotfile no mirror
    }
  }

  // 3. Cache hit? (only if not stale)
  if(existing.ok && existing.data){
    const d = existing.data;
    // ★ v1.0.103 Task 20-17 Backward-compat fix: dotfiles .gdi-lessons.json written before
    // v1.0.96 lack BOTH the `childFolders` array AND the `sourceModifiedTime` field (added
    // in v1.0.96 alongside the distributed scanner). Two failure modes if we treat them as
    // fresh cache:
    //   (a) Missing `childFolders` → return value uses `childFolders:[]` (the `||[]` fallback
    //       at line ~3409). gdiScanCourseDistributedBatch (line ~3579) iterates `res.childFolders`
    //       to enqueue sub-subfolders — an empty array means NO subfolders are queued, so the
    //       distributed batch terminates at depth 0 and the user sees only root-level lessons.
    //       Courses with nested module folders appear "empty" despite having thousands of files.
    //   (b) Missing `sourceModifiedTime` → staleness check below always returns falsy
    //       (`folderMtime && undefined && ...` → undefined), so the cache is NEVER invalidated
    //       even when the source Drive folder is modified. New lessons added later are invisible.
    // Fix: treat absence of EITHER field as stale → fall through to re-scan, which writes a
    // modern dotfile (with both fields) on completion. One-time cost per folder; subsequent
    // reads hit the fresh cache normally.
    const hasChildFolders = Array.isArray(d.childFolders);
    const hasSourceMtime = !!d.sourceModifiedTime;
    const isStale = (folderMtime && hasSourceMtime && folderMtime !== d.sourceModifiedTime)
                 || !hasChildFolders;  // ★ pre-v1.0.96 dotfile → re-scan to populate fields
    // ★ v2.15.2 (A): consolidado da raiz de versão antiga NÃO é confiável
    //   (faltam as aulas das pastas puladas pelo dotfilesSkipped) e o
    //   parcial acumulado (partial:true, sem childFolders reais) também não
    //   — ambos caem no re-scan abaixo, que lista os filhos de verdade.
    const versionStale = (d.consolidated === true && d.scannerVersion !== SCAN_DOTFILE_VERSION) || d.partial === true;
    // ★ v2.15.3 (W6): dotfile POR PASTA sem scannerVersion NÃO vale como
    //   cache hit (antes só consolidated/partial eram checados — dotfiles
    //   pré-v2.15.2 voltavam como hit e traziam o veneno gêmeo de volta).
    //   (W1 cross-worker): lições e childFolders vindos do cache são
    //   REBASEADOS para o drive corrente — o dotfile pode ter sido escrito
    //   por OUTRO worker (staging /11: lido pelo meuc /6:) ou sob a
    //   identidade gêmea (/11: lido sob /9:).
    const noVersion = !d.scannerVersion;
    if(!isStale && !versionStale && !noVersion){
      const rbLessons = (d.lessons||[]).map(l => (l && l.path) ? Object.assign({}, l, { path: rebaseDrivePath(l.path, driveIdx) }) : l);
      const rbChildren = (d.childFolders||[]).map(c => (c && c.path) ? Object.assign({}, c, { path: rebaseDrivePath(c.path, driveIdx) }) : c);
      return {
        ok:true, lessons:rbLessons, childFolders:rbChildren,
        status:'cached', mode:dotfileMode, stale:false, scannedAt:d.scannedAt
      };
    }
    // stale or legacy-format → fall through to re-scan below
  }

  // 4. List direct children of the folder (files + subfolders).
  if(_ctr.value >= SUBREQ_HARD_LIMIT) return {ok:false, reason:'limit', lessons:[], childFolders:[], status:'pending'};
  // ★ v2.15.2 (A): reservar o orçamento da ESCRITA antes de listar — uma
  //   pasta listada sem orçamento para os 2 dotfiles (4 subrequests) era
  //   devolvida como 'done' sem persistir nada (dotfilesSkipped) e o batch
  //   a contava como escaneada: as aulas dela se perdiam (a leitura só
  //   descia para subpastas de pastas COM dotfile). Sem orçamento p/ lista
  //   (1) + escritas (4), devolve 'pending' e o batch a re-enfileira.
  // ★ v2.15.5 (R4): reserva lista (1) + escrita (2) = 3 (antes 5, quando a escrita eram 2 dotfiles).
  if(_ctr.value + 3 >= SUBREQ_HARD_LIMIT) return {ok:false, reason:'limit', lessons:[], childFolders:[], status:'pending', dotfilesSkipped:false};
  // ★ v1.0.99: paginate folder listing to handle >200 children
  let allFiles = [];
  let pageToken = null;
  do {
    if(_ctr.value >= SUBREQ_HARD_LIMIT) break;
    const params = {includeItemsFromAllDrives:'true', supportsAllDrives:'true',
      q:"'"+folderId+"' in parents and trashed = false",
      fields:'files(id,name,mimeType,size,modifiedTime),nextPageToken', pageSize:'200'};
    if(pageToken) params.pageToken = pageToken;
    const lr = await fetch('https://www.googleapis.com/drive/v3/files?'+enQuery(params), opts);
    _ctr.value++;
    if(!lr.ok) return {ok:false, reason:'http_'+lr.status, lessons:[], childFolders:[], status:'error'};
    const lj_page = await lr.json();
    if(!lj_page.files || !lj_page.files.length) break;
    allFiles = allFiles.concat(lj_page.files);
    pageToken = lj_page.nextPageToken || null;
    if(allFiles.length >= 2000) break;
  } while(pageToken && _ctr.value < SUBREQ_HARD_LIMIT);
  const lj = {files: allFiles};
  // ★ v2.15.3 (W1): rebase canônico — o guarda antigo só testava o drive
  //   corrente ('/9:/' + '/11:/…' = '/9://11:/…'). O rebase tira qualquer
  //   prefixo embutido e tira a barra final (sem ela, o join abaixo gerava
  //   '/9:/CURSOS 2026//Aula…').
  const basePath = rebaseDrivePath(folderPath || '', driveIdx);
  const lessons = [];
  const childFolders = [];
  for(const f of (lj.files||[])){
    const nm = f.name || '';
    const isFolder = f.mimeType === 'application/vnd.google-apps.folder';
    const childPath = basePath ? basePath + '/' + nm : nm;
    if(isFolder){
      // Skip our own dotfiles / .meggy.ai — they are NOT real childFolders.
      if(nm.startsWith('.gdi-') || nm === '.meggy.ai') continue;
      // ★ v2.15.5 (R2): o modifiedTime vem na listagem do pai — o filho reusa sem novo fetch.
      childFolders.push({id:f.id, name:nm, path:childPath, scanned:false, mtime:f.modifiedTime || null});
    } else {
      // ★ v2.15.33-A: classificação partilhada (scanClassifyFile) — o
      //   endpoint scan-upsert-lessons usa a mesma, p/ linhas idênticas.
      const cls = scanClassifyFile(nm, f.mimeType || '');
      if(cls.type){
        lessons.push({id:f.id, name:nm, path:childPath, type:cls.type, mimeType:f.mimeType || '', ext:cls.ext, size:f.size||null});
      }
    }
  }

  // 5. Write dotfiles (direct or mirror).
  //    ★ v1.0.96 FIX: include childFolders array in lessonsJson too, not just count.
  //    When reading from cache, the batch needs childFolders to enqueue sub-subfolders.
  //    ★ v1.0.96 FIX: count write subrequests against the hard limit (CF 50-subrequest cap).
  const lessonsJson = JSON.stringify({
    schema:'gdi-lessons/v1', folderId, folderPath,
    driveIndex: driveIdx, coursePath, courseHash,
    lessons, childFolders, childFolderCount:childFolders.length, lessonCount:lessons.length,
    scannedAt:Date.now(), scannedBy:user,
    sourceModifiedTime:folderMtime,
    scannerVersion: SCAN_DOTFILE_VERSION
  });
  // ★ v2.15.5 (R1): sem .gdi-scan-state.json por pasta — nenhum resume o
  //   lê; o .gdi-lessons.json acima já carrega lessons, childFolders,
  //   sourceModifiedTime e scannerVersion. (O state da RAIZ no done fica.)
  // Use gd0 for mirror writes, original gd for direct writes.
  const writerGd = dotfileMode === 'mirror' ? gd0 : gd;
  // ★ v2.15.2 (A): rede de segurança — se o orçamento acabou entre a lista
  //   e a escrita (ex.: fallback para o mirror), NUNCA devolver 'done' sem
  //   persistir. O comportamento antigo (ok:true + dotfilesSkipped, "serão
  //   escritos no próximo scan") perdia as aulas da pasta para sempre: o
  //   batch a tirava do pending e ninguém mais a escaneava (repro A do
  //   harness v2.15.2: 9/17 aulas, curso marcado done). Agora devolve
  //   'pending' e o batch re-enfileira a pasta na cabeça.
  // ★ v2.15.5 (R4): reserva só a escrita do .gdi-lessons.json (2) — o state por pasta saiu (R1).
  if(_ctr.value + 2 >= SUBREQ_HARD_LIMIT){
    return {ok:false, reason:'limit', lessons, childFolders, status:'pending', mode:dotfileMode, stale:!!existing.ok, scannedAt:Date.now(), dotfilesSkipped:true};
  }
  const writeRes = await gdiWriteFolderDotfile(writerGd, dotFolderId, '.gdi-lessons.json', lessonsJson);
  _ctr.value += 2;  // estimate: 1 search + 1 patch/post
  // ★ v2.15.6 (P1): a escrita do dotfile da pasta é a ÚNICA forma de as
  //   aulas dela sobreviverem entre batches — o resultado era descartado
  //   e o batch contava a pasta como escaneada mesmo sem persistir nada.
  let writeOk = !!writeRes.ok;
  if(writeRes.ok){
    // ★ v2.15.5 (R1): só o .gdi-lessons.json — o state por pasta saiu.
  } else if(writeRes.reason === 'permission' && dotfileMode === 'direct'){
    // Drive became read-only between read and write — fall back to mirror.
    const mirrorId = await gdiResolveMirrorFolder(gd0, courseHash, folderPathRelativeToCourse(folderPath, coursePath));
    _ctr.value += 8;  // ★ v2.15.5 (R4): mirror resolve ≈ 3 + partes do relPath (v. R4b)
    if(mirrorId){
      dotfileMode = 'mirror';
      const _wm = await gdiWriteFolderDotfile(gd0, mirrorId, '.gdi-lessons.json', lessonsJson);
      if(_wm && _wm.ok) writeOk = true;
      _ctr.value += 2;
      // ★ v2.15.5 (R1): sem .gdi-scan-state.json no mirror tampouco.
    }
  }

  return {ok:true, lessons, childFolders, status:'done', mode:dotfileMode, stale:!!existing.ok, scannedAt:Date.now(), dotfileWriteOk: writeOk};
}

// ★ Section 4.5: batch scan up to SCAN_MAX_SUBREQ folders per call.
// Starts from .gdi-course.json (resume) or from startFolderId (fresh).
// Updates .gdi-course.json with progress + pending queue.
// On done, also writes legacy lessons.json for backward compat with old clients.
async function gdiScanCourseDistributedBatch(gd, coursePath, courseHash, user, startFolderId, startPath, counter, opts){
  const _ctr = counter || { value: 0 };
  // ★ v1.0.109: Increased from 14 to 20 — same reasoning as gdiScanDistributed.
  // ★ v2.15.3 (W5): 20 → 28 (contagem honesta — v. R2).
  // ★ v2.15.5 (R4): 28 → 32 — mesmo teto da pasta (contador compartilhado);
  //   pasta fresca 5, cache 2, reserva 6 p/ as escritas finais (passo 3/3a).
  const SUBREQ_HARD_LIMIT = 32;
  const MAX_DEPTH = 15;  // ★ v1.0.109: prevent scanning too deep (course root → module → discipline → lesson → sub-folder)
  const driveIdx = gd.order !== undefined ? gd.order : (gd.index !== undefined ? gd.index : gds.indexOf(gd));
  let pending = [];
  let scannedCount = 0;
  const allLessons = [];
  let dotfileFailures = 0; // ★ v2.15.6 (P1): pastas cuja escrita do dotfile falhou (v. gdiScanDistributed)

  // ★ v1.0.223: Cleanup old non-dotted scanner files from previous versions
  // ★ v2.15.5 (R3): o backfill passa skipCleanup — o cleanup custa 4 listas
  //   (1 por nome antigo) + 1 PATCH por arquivo achado, e os arquivos
  //   legados sem ponto já não existem há versões; no backfill é custo
  //   puro por run. O scan interativo mantém o cleanup (contado honesto: 4).
  if(!(opts && opts.skipCleanup)){ try { await gdiCleanupOldDotfiles(gd, startFolderId); _ctr.value += 4; } catch(_) {} }

  // 1. Read .gdi-course.json at the course root.
  // ★ v2.15.5 (R3): o backfill já leu este meta (handleCronBackfill) e o
  //   passa em opts.meta — re-lê-lo aqui custava 2 fetches reais e 0
  //   contados por batch. opts.meta === undefined = "não passei nada"
  //   (scan interativo: lê como antes, agora CONTADO); null = "li e não
  //   há meta" (fresh start); objeto = meta já lido. Falha de permissão
  //   NÃO passa meta (o fallback p/ o mirror abaixo precisa rodar).
  let courseMeta = null;
  let metaSource = null; // ★ v2.15.8 (A): 'direct' | 'mirror' | null — de onde veio o meta (o resume)
  if(opts && opts.meta !== undefined){
    courseMeta = opts.meta;
    metaSource = (opts && opts.metaSource) || (courseMeta ? 'direct' : null);
  } else {
    // ★ v2.15.8 (A): a leitura do meta é mirror-aware (v. gdiReadCourseRootDotfile):
    //   num drive read-only o meta vive no mirror — ler só o direto devolvia
    //   not_found e o batch recomeçava da raiz a CADA run (o curso nunca
    //   drenava, sem erro). opts.meta === null = "o backfill já probou direto
    //   + mirror e não achou" → fresh start sem re-probar.
    try{
      const metaRes = await gdiReadCourseRootDotfile(gd, courseHash, startFolderId, '.gdi-course.json', _ctr);
      if(metaRes && metaRes.ok && metaRes.data){ courseMeta = metaRes.data; metaSource = metaRes.source || 'direct'; }
    }catch(_){ /* best-effort read */ }
  }
  let mirrorMode = metaSource === 'mirror'; // ★ v2.15.8 (A): as pastas do curso também leem o mirror (A3)

  // ★ v2.15.2 (A): meta de versão antiga (sem scannerVersion) pode ter
  //   "engolido" pastas sem dotfile (dotfilesSkipped) — o pending salvo não
  //   é confiável. Recomeça da raiz: as pastas com dotfile válido voltam
  //   como 'cached' (barato, 1 subrequest) e só as sem dotfile são
  //   re-escaneadas de verdade.
  const metaVersionOk = courseMeta && courseMeta.scannerVersion === SCAN_DOTFILE_VERSION;
  const freshStart = !(metaVersionOk && Array.isArray(courseMeta.pending) && courseMeta.pending.length > 0 && courseMeta.scanStatus === 'scanning');
  if(!freshStart){
    pending = courseMeta.pending.slice();
    scannedCount = (courseMeta.scanProgress && courseMeta.scanProgress.scanned) || 0;
  } else {
    pending = [{id:startFolderId, path:startPath||coursePath, depth:0}];
  }

  // 2. Process folders up to SUBREQ_HARD_LIMIT subrequests.
  // ★ v2.15.5 (R6): PILHA (depth-first) em vez de fila (BFS). O BFS gastava
  //   dezenas de batches em pastas-contêiner irmãs antes de tocar a 1ª folha
  //   com mídia — e o W4 só insere quando o batch toca folhas (o "0" do
  //   Passo 9). Em DFS o batch desce pelo 1º ramo até a folha: no máx. 2
  //   contêineres (curso → módulo) antes da 1ª Aula, então TODO batch
  //   insere > 0. O total de pastas visitadas é o mesmo; só a ordem muda.
  //   Reserva 6 contados p/ as escritas finais (passo 3a + passo 3):
  //   o loop para antes de o contador estourar no meio delas (antes, as
  //   escritas do meta/consolidado caíam no throw de subrequests e o
  //   pending da run se perdia — próximo run recomeçava do pending antigo).
  while(pending.length > 0 && _ctr.value + 6 < SUBREQ_HARD_LIMIT){
    const folder = pending.pop();
    if(!folder || !folder.id) continue;
    // ★ v1.0.109: Skip folders deeper than MAX_DEPTH — prevents scanning thousands of 
    // deeply nested subfolders that don't contain lesson files
    if(folder.depth > MAX_DEPTH) continue;
    const folderPath = folder.path || '';
    let res;
    try{
      res = await gdiScanDistributed(gd, folder.id, folderPath, coursePath, courseHash, user, _ctr, folder.mtime, { mirror: mirrorMode }); // ★ v2.15.5 (R2): mtime herdado da listagem do pai
    }catch(scanErr){
      console.warn('gdiScanDistributed threw for folder', folder.id, ':', scanErr && scanErr.message);
      // ★ v1.0.96 FIX: if CF threw "Too many subrequests", re-enqueue this folder and break
      // so the next batch invocation can resume. Otherwise we'd lose this folder forever.
      const errMsg = (scanErr && scanErr.message) || '';
      if(errMsg.indexOf('Too many subrequests') >= 0 || errMsg.indexOf('subrequest') >= 0){
        pending.push(folder); // ★ v2.15.5 (R6): volta p/ o TOPO da pilha
        break;
      }
      // Other errors (e.g., network) — skip this folder and continue.
      continue;
    }
    if(!res){
      continue;
    }
    if(!res.ok){
      // Limit hit — re-queue this folder on TOP of the stack and stop the batch.
      if(res.reason === 'limit'){ pending.push(folder); break; }
      // ★ v2.15.6 (P1): RAIZ INACESSÍVEL não é "pasta isolada" — quando o
      //   ROOT falha (pasta apagada, id inválido, 404), engolir o erro
      //   esvazia o pending, done=true com 0 aulas e a FASE 2 do backfill
      //   NÃO marca done (0 lessons → 'incomplete') — o item fica ciclando
      //   p/ sempre com retries congelados (o carácter do P1 no Passo 10).
      //   Falha de raiz vira erro EXPLÍCITO p/ o backfill re-enfileirar o
      //   item (3 strikes → quarentena, com diagnóstico).
      if(folder.id === startFolderId){
        return { ok:false, done:false, scannedCount, totalLessons: allLessons.length, pendingFolders: pending.length, pending: pending.slice(), lessons: allLessons.slice(), lessonsTotal: allLessons.slice(), metaPersisted: false, persistError: null, rootPersisted: false, dotfileFailures, status:'error', error:'root folder unreachable (' + ((res.error && String(res.error).slice(0, 120)) || res.reason || 'unknown') + ')' };
      }
      // Isolated error — skip this folder and continue.
      continue;
    }
    // ★ v2.15.2 (A): defesa em profundidade — pasta devolvida sem dotfile
    //   NÃO conta como escaneada e NÃO enfileira os filhos (eles serão
    //   descobertos quando a pasta for escaneada de verdade). Re-enfileira
    //   na cabeça e encerra o batch (o orçamento acabou mesmo).
    if(res.dotfilesSkipped){
      pending.push(folder); // ★ v2.15.5 (R6): topo da pilha, não cabeça de fila
      break;
    }
    // ★ v2.15.8 (A): a pasta escreveu no mirror (drive read-only) — as
    //   próximas pastas deste batch também leem o mirror (A3).
    if(res && res.mode === 'mirror') mirrorMode = true;
    if(res.status === 'cached' || res.status === 'done'){
      scannedCount++;
      if(res.dotfileWriteOk === false) dotfileFailures++;
      if(Array.isArray(res.lessons)) allLessons.push(...res.lessons);
      if(Array.isArray(res.childFolders)){
        for(const cf of res.childFolders){
          if(!cf.scanned){
            // ★ v2.15.5 (R2): propaga o mtime da listagem (o filho reusa sem GET).
            pending.push({id:cf.id, path:cf.path, depth:(folder.depth||0)+1, mtime:cf.mtime || null});
          }
        }
      }
    }
  }

  // 3a. ★ v2.15.2 (A): acumulador incremental do consolidado da raiz.
  //   O batch antigo só consolidava no fim, lendo TODOS os dotfiles de uma
  //   vez (gdiReadCourseDistributedLessons) — com o teto de 24 subrequests
  //   a leitura truncava em cursos com 12+ pastas e o consolidado saía
  //   parcial, mas era gravado como completo. Agora cada batch soma as
  //   aulas que ESCANEOU (allLessons) ao parcial já gravado na raiz
  //   (1 leitura + 1 escrita) e grava o acumulado — completo quando done.
  //   Dedupe por lesson.path (o re-scan de uma pasta não duplica).
  //   Ordem: o consolidado é gravado ANTES do .gdi-course.json — se a
  //   execução for cortada entre os dois, o próximo batch retoma o pending
  //   antigo e re-escaneia as pastas (cache), sem perder as aulas.
  //   O arquivo é o MESMO .gdi-lessons.json da raiz: parcial (partial:true)
  //   enquanto o scan não termina, consolidado (consolidated:true) no fim.
  //   O leitor e o cache do scanner ignoram o parcial (v. W2/W12/W13).
  let consolidatedLessons = allLessons.slice();
  let rootWriteRes = {ok:false};
  try{
    if(!freshStart){
      // ★ v2.15.8 (A): o parcial também pode viver no mirror (A1) — sem
      //   isto o acumulador recomeçava do zero a cada batch num drive
      //   read-only e o consolidado final saía sem as aulas dos batches
      //   anteriores (o D1 já as tinha pelo W4, mas a leitura da fase 2
      //   ficava parcial).
      const prevRes = await gdiReadCourseRootDotfile(gd, courseHash, startFolderId, '.gdi-lessons.json', _ctr);
      let prev = (prevRes && prevRes.ok) ? { ok: true, data: prevRes.data } : { ok: false, reason: (prevRes && prevRes.reason) || 'not_found' };
      if(prev && prev.ok && prev.data && Array.isArray(prev.data.lessons) && prev.data.scannerVersion === SCAN_DOTFILE_VERSION){
        const seen = new Set(allLessons.map(l => (l && (l.path || l.id)) || ''));
        for(const l of prev.data.lessons){
          // ★ v2.15.3 (W1): o parcial pode trazer paths de outra identidade
          //   (/11: gravado por outro worker) — rebase antes do merge e do
          //   dedupe (senão a mesma aula física entra 2×, uma por prefixo).
          const rb = (l && l.path) ? Object.assign({}, l, { path: rebaseDrivePath(l.path, driveIdx) }) : l;
          const k = (rb && (rb.path || rb.id)) || '';
          if(k && !seen.has(k)){ seen.add(k); consolidatedLessons.push(rb); }
        }
      }
    }
  }catch(_){ /* sem parcial anterior — segue só com as aulas deste batch */ }
  const done = pending.length === 0;
  try{
    const rootLessonsJson = JSON.stringify({
      schema:'gdi-lessons/v1',
      folderId: startFolderId,
      folderPath: coursePath,
      driveIndex: driveIdx,
      coursePath, courseHash,
      lessons: consolidatedLessons,
      childFolders: [],
      childFolderCount: 0,
      lessonCount: consolidatedLessons.length,
      scannedAt: Date.now(),
      scannedBy: user,
      sourceModifiedTime: new Date().toISOString(),
      scannerVersion: SCAN_DOTFILE_VERSION,
      consolidated: done,
      partial: !done
    });
    rootWriteRes = await gdiWriteFolderDotfile(gd, startFolderId, '.gdi-lessons.json', rootLessonsJson);
    _ctr.value += 2; // ★ v2.15.3 (W5): escrita do consolidado da raiz
    if(!rootWriteRes.ok && (rootWriteRes.reason === 'permission' || rootWriteRes.reason === 'http_403')){
      const gd0rw = gds[0];
      if(gd0rw && gd0rw !== gd){
        try{
          const mirrorId = await gdiResolveMirrorFolder(gd0rw, courseHash, '');
          // ★ v2.15.6 (P1): o resultado do mirror era DESCARTADO — a
          //   escrita no mirror valia como persistida mas rootWriteRes
          //   seguia {ok:false} e o cleanup do done era pulado à toa.
          if(mirrorId){ const _mr = await gdiWriteFolderDotfile(gd0rw, mirrorId, '.gdi-lessons.json', rootLessonsJson); if(_mr && _mr.ok) rootWriteRes = _mr; }
        }catch(_){}
      }
    }
  }catch(_){ /* best-effort — o meta abaixo ainda salva o pending */ }

  // 3. Update .gdi-course.json at the course root (best-effort).
  const courseName = (coursePath.split('/').filter(Boolean).slice(1).join('/')) || coursePath;
  const newMeta = {
    schema:'gdi-course/v1', coursePath, courseHash,
    scannerVersion: SCAN_DOTFILE_VERSION,
    courseName,
    driveIndex: driveIdx,
    rootFolderId: startFolderId,
    createdAt: (courseMeta && courseMeta.createdAt) || Date.now(),
    createdBy: (courseMeta && courseMeta.createdBy) || user,
    lastScanAt: Date.now(),
    lastScanBy: user,
    scanStatus: done ? 'done' : 'scanning',
    scanProgress: {
      total: scannedCount + pending.length,
      scanned: scannedCount,
      pending: pending.length
    },
    pending: done ? [] : pending.map(p => ({id:p.id, path:p.path, depth:p.depth, mtime:p.mtime || null})), // ★ v2.15.5 (R2): o mtime persiste p/ o resume não refazer o GET
    version: 1
  };
  // ★ v2.15.6 (P1): a persistência do meta é RASTREADA — o meta É o
  //   cursor (pending) que sobrevive entre runs. Antes, a escrita falhava
  //   em silêncio (só permissão tentava o mirror; outro motivo caía no
  //   vazio) e o batch devolvia ok:true — a run seguinte recomeçava do
  //   pending antigo e o curso nunca drenava.
  let metaPersisted = false;
  let persistError = null;
  try{
    const metaJson = JSON.stringify(newMeta);
    let metaWriteRes = await gdiWriteFolderDotfile(gd, startFolderId, '.gdi-course.json', metaJson);
    _ctr.value += 2; // ★ v2.15.3 (W5): escrita do meta do curso
    metaPersisted = !!metaWriteRes.ok;
    if(!metaWriteRes.ok) persistError = metaWriteRes.reason || 'write failed';
    // ★ v1.0.117 FIX BUG #2B (0 aulas em shared drives): se a escrita falhou por
    // permissão (shared drive read-only), tenta escrever no mirror folder no drive 0.
    // Sem isso, a pending BFS queue é perdida entre polls — cada poll recomeça do
    // zero, re-escaneia as mesmas pastas, nunca avança. Mirror pattern idêntico ao
    // do gdiScanDistributed (linha ~3682) para .gdi-lessons.json.
    if(!metaWriteRes.ok && (metaWriteRes.reason === 'permission' || metaWriteRes.reason === 'http_403' || metaWriteRes.reason === 'http_401')){
      const gd0meta = gds[0];
      if(gd0meta && gd0meta !== gd){
        try{
          const mirrorId = await gdiResolveMirrorFolder(gd0meta, courseHash, '');
          if(mirrorId){
            const _mm = await gdiWriteFolderDotfile(gd0meta, mirrorId, '.gdi-course.json', metaJson);
            if(_mm && _mm.ok){ metaPersisted = true; persistError = null; }
          }
        }catch(_){}
      }
    }
  }catch(_){ /* best-effort write — batch result still valid */ }

  // 4. On done, also persist a consolidated legacy lessons.json for old clients.
  // ★ v1.0.224 FASE 1+2+3: Write consolidated .gdi-lessons.json + .gdi-scan-state.json
  // at COURSE ROOT (not in each subfolder). This eliminates visual pollution in lesson folders.
  if(done){
    try{
      // ★ v2.15.5 (R5): o backfill passa skipLegacy — as escritas legadas
      //   do done (lessons.json p/ clientes antigos + state da raiz,
      //   ~6 fetches, 0 contados) estouravam o teto bem no fim do curso
      //   que acabara de completar. O D1 já é a fonte do backfill (a
      //   fase 2 lê o consolidado da raiz); o scan interativo mantém.
      const gd0 = gds[0];
      if(!(opts && opts.skipLegacy)){
      // ★ v2.15.2 (A): consolidatedLessons já vem do passo 3a (acumulador
      //   incremental) — a leitura de todos os dotfiles aqui truncava em
      //   cursos com 12+ pastas e gravava o consolidado parcial como
      //   completo. Sem re-ler nada neste ponto.

      // Save legacy lessons.json for old clients
      if(gd0){
        const lessonsJson = JSON.stringify({
          coursePath, courseHash, lessons:consolidatedLessons,
          total:consolidatedLessons.length, scannedAt:Date.now(), scannedBy:user, scanComplete:true
        });
        await gdiSaveCourseLessons(gd0, courseHash, lessonsJson);
      }

      // ★ v2.15.2 (A): o consolidado (.gdi-lessons.json) já foi gravado no
      //   passo 3a (consolidated:true, com scannerVersion); aqui só o state.
      const rootStateJson = JSON.stringify({
        schema:'gdi-scan-state/v1',
        folderId: startFolderId,
        folderPath: coursePath,
        coursePath, courseHash,
        status: 'done',
        scannedAt: Date.now(),
        scannedBy: user,
        sourceModifiedTime: new Date().toISOString(),
        scannerVersion: SCAN_DOTFILE_VERSION,
        childFolders: [],
        childFolderCount: 0,
        lessonCount: consolidatedLessons.length,
        consolidated: true
      });
      // Write state to course root (direct or mirror)
      let rootStateRes = await gdiWriteFolderDotfile(gd, startFolderId, '.gdi-scan-state.json', rootStateJson);
      if(!rootStateRes.ok && (rootStateRes.reason === 'permission' || rootStateRes.reason === 'http_403')){
        // Try mirror
        const gd0rw = gds[0];
        if(gd0rw && gd0rw !== gd){
          try{
            const mirrorId = await gdiResolveMirrorFolder(gd0rw, courseHash, '');
            if(mirrorId){
              await gdiWriteFolderDotfile(gd0rw, mirrorId, '.gdi-scan-state.json', rootStateJson);
            }
          }catch(_){}
        }
      }
      } // ★ v2.15.5 (R5): fim do bloco skipLegacy

      // ★ FASE 3: Clean up old dotfiles from subfolders (best-effort, non-blocking)
      // Only clean up if root write succeeded — don't delete old data if new data wasn't saved
      // ★ v2.13.4: o cleanup recursivo (uma lista por subpasta, sem teto)
      // é pulado quando o backfill pede (opts.skipCleanup) — no backfill ele
      // é custo puro: o consolidado já está na raiz. Os chamadores
      // interativos não passam opts e o cleanup continua como antes.
      if(rootWriteRes.ok && !(opts && opts.skipCleanup)){
        cleanupOldSubfolderDotfiles(gd, startFolderId, coursePath, courseHash, true).catch(()=>{}); // ★ MERGE: isRoot=true — limpa só subpastas, preserva o consolidado da raiz (ver função)
      }
    }catch(_){}
  }

  return {
    ok:true, done, scannedCount,
    totalLessons: allLessons.length,
    pendingFolders: pending.length,
    pending: done ? [] : pending,
    lessons: allLessons,
    // ★ v2.15.6 (P8): o TOTAL CUMULATIVO — o consolidado da raiz (aulas
    //   acumuladas de TODOS os batches) é o que o scan-progress devolve.
    lessonsTotal: consolidatedLessons.slice(),
    // ★ v2.15.6 (P1): persistência rastreada, não silenciosa.
    metaPersisted, persistError, rootPersisted: rootWriteRes.ok, dotfileFailures,
    status: done ? 'done' : 'partial',
    // ★ v2.15.8 (A): progresso estruturado p/ o backfill registrar no item
    //   da fila (B4) e p/ a detecção de estagnação — sem isto o 'incomplete'
    //   não deixava nenhum diagnóstico ("erro desconhecido"). freshStart =
    //   o batch recomeçou da raiz (meta ausente/inválido) nesta run.
    scanProgress: { scanned: scannedCount, pending: pending.length, total: scannedCount + pending.length },
    metaSource,
    freshStart
  };
}

// ★ Section 4.6: reads ALL .gdi-lessons.json dotfiles for a course recursively.
// Used when the client wants the full lesson list without re-scanning.
// Falls back to legacy gdiReadCourseLessons if no dotfiles exist.
// Returns: { ok, lessons, byFolder, source:'direct'|'mirror'|'legacy', scanComplete }.
async function gdiReadCourseDistributedLessons(gd, coursePath, courseHash, startFolderId, counter){
  const _ctr = counter || { value: 0 };
  const gd0 = gds[0];
  const driveIdx = gd.order !== undefined ? gd.order : (gd.index !== undefined ? gd.index : gds.indexOf(gd));
  const allLessons = [];
  const byFolder = [];
  const queue = [{id:startFolderId, path:coursePath, depth:0}];
  let source = 'direct';
  const MAX_FOLDERS = 1000; // safety cap (v1.0.110: was 500, increased for large courses like Sou+ with 732+ folders)

  // ★ v1.0.224 FASE 2: Check root-level consolidated .gdi-lessons.json FIRST
  // If it exists (written by FASE 1), use it directly — no need to walk subfolders
  let rootRes = await gdiReadFolderDotfile(gd, startFolderId, '.gdi-lessons.json');
  if(!rootRes.ok){
    // ★ v2.15.8 (A): o consolidado da raiz também pode viver no mirror (A1) —
    //   a leitura direta num drive read-only dá not_found, nunca 403.
    try{
      const _rr = await gdiReadCourseRootDotfile(gd, courseHash, startFolderId, '.gdi-lessons.json', _ctr, rootRes);
      if(_rr && _rr.ok){ rootRes = { ok: true, data: _rr.data }; source = _rr.source || 'mirror'; }
    }catch(_){}
  }
  // ★ v2.15.2 (A): consolidado de versão antiga (ou sem versão) NÃO vale —
  //   foi montado com aulas faltando (dotfilesSkipped). Cai no walk abaixo.
  if(rootRes.ok && rootRes.data && rootRes.data.consolidated === true && rootRes.data.scannerVersion === SCAN_DOTFILE_VERSION && Array.isArray(rootRes.data.lessons)){
    // Root-level consolidated file found — return immediately (no subfolder walking needed)
    // ★ v2.15.3 (W1): rebase defensivo — o consolidado pode ter sido
    //   escrito por outro worker/identidade.
    return {
      ok:true,
      lessons: rootRes.data.lessons.map(l => (l && l.path) ? Object.assign({}, l, { path: rebaseDrivePath(l.path, driveIdx) }) : l),
      byFolder: [{folderPath:coursePath, lessons:rootRes.data.lessons, scannedAt:rootRes.data.scannedAt}],
      source,
      fromRoot: true,  // ★ indicates data came from root consolidation
      // ★ v2.13.5: o consolidado só é escrito quando o scan completou — sem
      // isso o backfill marcava 'incomplete' para sempre um curso já lido.
      scanComplete: true
    };
  }
  // ★ v1.0.110: Increased from 14 to 24. Each folder read = 2 subrequests (dotfile read + subfolder list).
  // 24 counted = 12 folders × 2 real = 24 real subrequests, well under CF's 50 limit.
  // Previous value of 14 only read ~7 folders per call — not enough for courses with 121+ folders.
  const READ_HARD_LIMIT = 24;

  while(queue.length > 0 && _ctr.value < READ_HARD_LIMIT && byFolder.length < MAX_FOLDERS){
    const folder = queue.shift();
    if(!folder || !folder.id) continue;
    // ★ v2.13.5: a leitura do dotfile custa 2 fetches (lista + download) e
    // NÃO era contada — só a lista de subpastas incrementava o contador.
    // O teto de 24 contados virava até 72 reais (24 pastas × 3) e estourava
    // o teto de 50 do CF no meio da leitura (run das 15:50 no TJSP).
    if(_ctr.value + 2 >= READ_HARD_LIMIT) break;
    // Try direct dotfile first.
    let res = await gdiReadFolderDotfile(gd, folder.id, '.gdi-lessons.json');
    _ctr.value += 2; // ★ v2.13.5: conta a leitura do dotfile
    if(!res.ok && (res.reason === 'permission' || res.reason === 'http_403' || res.reason === 'http_401')){
      // Direct read denied — try mirror.
      const mirrorId = await gdiResolveMirrorFolder(gd0, courseHash, folderPathRelativeToCourse(folder.path, coursePath));
      if(mirrorId){
        res = await gdiReadFolderDotfile(gd0, mirrorId, '.gdi-lessons.json');
        _ctr.value += 2; // ★ v2.13.5: conta a leitura do espelho também
        if(res.ok) source = 'mirror';
      }
    }
    // ★ v2.15.2 (A): o dotfile só vale como fonte das aulas quando é um
    //   dotfile POR PASTA — nem parcial acumulado (aulas de outras pastas),
    //   nem consolidado de versão antiga (aulas faltando).
    // ★ v2.15.3 (W6): dotfile por pasta SEM scannerVersion não é fonte
    //   confiável (veneno pré-v2.15.2) — cai no walk do Drive abaixo.
    //   (W1): lições vindas do dotfile são rebasedas para o drive corrente.
    const usable = res.ok && res.data && res.data.partial !== true && res.data.consolidated !== true && !!res.data.scannerVersion;
    if(usable){
      if(Array.isArray(res.data.lessons)){
        for(const _l of res.data.lessons){ allLessons.push((_l && _l.path) ? Object.assign({}, _l, { path: rebaseDrivePath(_l.path, driveIdx) }) : _l); }
        byFolder.push({folderPath:folder.path, lessons:res.data.lessons, scannedAt:res.data.scannedAt});
      }
    }
    // ★ v2.15.2 (A): descobrir as subpastas SEMPRE — antes só as pastas COM
    //   dotfile tinham os filhos listados, então uma pasta pulada pelo bug
    //   do dotfilesSkipped podava a subárvore inteira da leitura (as aulas
    //   dos filhos, mesmo com dotfile, nunca eram lidas). Prefere o
    //   childFolders do dotfile (0 subrequests); sem ele, lista no Drive.
    let subList = null;
    if(usable && Array.isArray(res.data.childFolders)){
      subList = res.data.childFolders;
    } else {
      const opts = await gd.requestOptions();
      if(_ctr.value >= READ_HARD_LIMIT) break;
      // ★ v1.0.99: paginate subfolder listing to handle >200 subfolders
      let allSubs = [];
      let subPageToken = null;
      do {
        if(_ctr.value >= READ_HARD_LIMIT) break;
        const subParams = {
          includeItemsFromAllDrives:'true', supportsAllDrives:'true',
          q:"'"+folder.id+"' in parents and mimeType = 'application/vnd.google-apps.folder' and trashed = false",
          fields:'files(id,name),nextPageToken', pageSize:'200'
        };
        if(subPageToken) subParams.pageToken = subPageToken;
        const lr = await fetch('https://www.googleapis.com/drive/v3/files?'+enQuery(subParams), opts);
        _ctr.value++;
        if(!lr.ok) break;
        const lj_page = await lr.json();
        if(!lj_page.files || !lj_page.files.length) break;
        allSubs = allSubs.concat(lj_page.files);
        subPageToken = lj_page.nextPageToken || null;
        if(allSubs.length >= 2000) break;
      } while(subPageToken && _ctr.value < READ_HARD_LIMIT);
      subList = allSubs;
    }
    for(const sf of (subList || [])){
      if(!sf.id) continue;
      if(sf.name && (sf.name.startsWith('.gdi-') || sf.name === '.meggy.ai')) continue;
      const childPath = rebaseDrivePath(sf.path || (folder.path ? folder.path + '/' + sf.name : sf.name), driveIdx);
      queue.push({id:sf.id, path:childPath, depth:(folder.depth||0)+1});
    }
  }

  // Legacy fallback: if no distributed dotfiles found, read central lessons.json.
  if(allLessons.length === 0 && byFolder.length === 0 && gd0){
    const legacy = await gdiReadCourseLessons(gd0, courseHash);
    if(legacy && Array.isArray(legacy.lessons)){
      return {ok:true, lessons:legacy.lessons, byFolder:[], source:'legacy', scanComplete:legacy.scanComplete};
    }
  }

  // ★ CYCLE-1 Fix Bug #3: scanComplete semantics — was `byFolder.length > 0` which just
  // meant "we got at least one folder's data". The correct semantics: scan is complete
  // only if the BFS queue is empty (we processed ALL folders without hitting READ_HARD_LIMIT
  // or MAX_FOLDERS). When scanComplete is false, the caller should treat the lessons as
  // PARTIAL — some folders were not read. The caller (handleCourseScanProgress cache-hit
  // path) uses this to set a `truncated` flag in the response.
  return {ok:true, lessons:allLessons, byFolder, source, scanComplete: queue.length === 0};
}

// ════════════════════════════════════════════════════════════════════════
// ★ FIX 3 (Task 19): Save scan results to .meggy.ai/courses/<courseHash>/lessons.json
// (shared across all students — first scanner creates the structure, others get the cached scan).
// ════════════════════════════════════════════════════════════════════════
async function gdiSaveCourseLessons(gd0, courseHash, lessonsJson){
  if(!courseHash || !lessonsJson)return false;
  // 1. Resolve .meggy.ai/courses/
  const coursesId = await gdiSharedMeggySubfolderId(gd0, 'courses');
  if(!coursesId)return false;
  // 2. Find or create <courseHash> subfolder inside courses/
  const hashId = await gdiSharedMeggyDeepSubfolderId(gd0, coursesId, courseHash);
  if(!hashId)return false;
  // 3. Upsert lessons.json inside <courseHash>/
  const opts = await gd0.requestOptions();
  const fileName = 'lessons.json';
  const qFile = "'"+hashId+"' in parents and name = '"+fileName+"' and trashed = false";
  const rFile = await fetch('https://www.googleapis.com/drive/v3/files?'+enQuery({includeItemsFromAllDrives:'true',supportsAllDrives:'true',q:qFile,fields:'files(id)',pageSize:'1'}), opts);
  let existingId = null;
  if(rFile.ok){const j = await rFile.json(); if(j.files && j.files[0])existingId = j.files[0].id;}
  if(existingId){
    const po = await gd0.requestOptions({'Content-Type':'application/json; charset=UTF-8'},'PATCH');
    const pr = await fetch("https://www.googleapis.com/upload/drive/v3/files/"+existingId+"?uploadType=media&supportsAllDrives=true",{method:'PATCH',headers:po.headers,body:lessonsJson});
    return pr.ok;
  }
  // create new
  const boundary = 'gdilessons'+Date.now();
  const mp = '--'+boundary+'\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n'+JSON.stringify({name:fileName,parents:[hashId]})+'\r\n--'+boundary+'\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n'+lessonsJson+'\r\n--'+boundary+'--';
  const uo = await gd0.requestOptions({'Content-Type':'multipart/related; boundary='+boundary},'POST');
  const ur = await fetch('https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&supportsAllDrives=true',{method:'POST',headers:uo.headers,body:mp});
  return ur.ok;
}

// ════════════════════════════════════════════════════════════════════════
// ★ WORKER-FIXES-v79: Cursor persistence for incremental scans.
// Saves/loads/deletes scan-state.json in .meggy.ai/courses/<courseHash>/
// so interrupted scans can resume across batches.
// ════════════════════════════════════════════════════════════════════════
async function gdiSaveScanCursor(gd0, courseHash, stateJson){
  if(!courseHash || !stateJson)return false;
  const coursesId = await gdiSharedMeggySubfolderId(gd0, 'courses');
  if(!coursesId)return false;
  const hashId = await gdiSharedMeggyDeepSubfolderId(gd0, coursesId, courseHash);
  if(!hashId)return false;
  const opts = await gd0.requestOptions();
  const fileName = 'scan-state.json';
  const qFile = "'"+hashId+"' in parents and name = '"+fileName+"' and trashed = false";
  const rFile = await fetch('https://www.googleapis.com/drive/v3/files?'+enQuery({includeItemsFromAllDrives:'true',supportsAllDrives:'true',q:qFile,fields:'files(id)',pageSize:'1'}), opts);
  let existingId = null;
  if(rFile.ok){const j = await rFile.json(); if(j.files && j.files[0])existingId = j.files[0].id;}
  if(existingId){
    const po = await gd0.requestOptions({'Content-Type':'application/json; charset=UTF-8'},'PATCH');
    await fetch("https://www.googleapis.com/upload/drive/v3/files/"+existingId+"?uploadType=media&supportsAllDrives=true",{method:'PATCH',headers:po.headers,body:stateJson});
    return true;
  }
  const boundary = 'gdiscanstate'+Date.now();
  const mp = '--'+boundary+'\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n'+JSON.stringify({name:fileName,parents:[hashId]})+'\r\n--'+boundary+'\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n'+stateJson+'\r\n--'+boundary+'--';
  const uo = await gd0.requestOptions({'Content-Type':'multipart/related; boundary='+boundary},'POST');
  await fetch('https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&supportsAllDrives=true',{method:'POST',headers:uo.headers,body:mp});
  return true;
}

async function gdiReadScanCursor(gd0, courseHash){
  if(!courseHash)return null;
  const coursesId = await gdiSharedMeggySubfolderId(gd0, 'courses');
  if(!coursesId)return null;
  const hashId = await gdiSharedMeggyDeepSubfolderId(gd0, coursesId, courseHash);
  if(!hashId)return null;
  const opts = await gd0.requestOptions();
  const qFile = "'"+hashId+"' in parents and name = 'scan-state.json' and trashed = false";
  const rFile = await fetch('https://www.googleapis.com/drive/v3/files?'+enQuery({includeItemsFromAllDrives:'true',supportsAllDrives:'true',q:qFile,fields:'files(id)',pageSize:'1'}), opts);
  if(!rFile.ok)return null;
  const j = await rFile.json();
  if(!j.files || !j.files[0])return null;
  const rContent = await fetch('https://www.googleapis.com/drive/v3/files/'+j.files[0].id+'?alt=media&supportsAllDrives=true',opts);
  if(!rContent.ok)return null;
  const text = await rContent.text();
  try{return JSON.parse(text);}catch(_){return null;}
}

async function gdiDeleteScanCursor(gd0, courseHash){
  if(!courseHash)return false;
  try{
    const coursesId = await gdiSharedMeggySubfolderId(gd0, 'courses');
    if(!coursesId)return false;
    const hashId = await gdiSharedMeggyDeepSubfolderId(gd0, coursesId, courseHash);
    if(!hashId)return false;
    const opts = await gd0.requestOptions();
    const qFile = "'"+hashId+"' in parents and name = 'scan-state.json' and trashed = false";
    const rFile = await fetch('https://www.googleapis.com/drive/v3/files?'+enQuery({includeItemsFromAllDrives:'true',supportsAllDrives:'true',q:qFile,fields:'files(id)',pageSize:'1'}), opts);
    if(!rFile.ok)return false;
    const j = await rFile.json();
    if(!j.files || !j.files[0])return false;
    const delOpts = await gd0.requestOptions({},'DELETE');
    await fetch('https://www.googleapis.com/drive/v3/files/'+j.files[0].id+'?supportsAllDrives=true',{method:'DELETE',headers:delOpts.headers});
    return true;
  }catch(_){return false;}
}

// ════════════════════════════════════════════════════════════════════════
// ★ FIX 4 (Task 19): Save per-user progress to .meggy.ai/courses/<courseHash>/user-<username>.json
// (so each student's progress is visible in Drive alongside the KV cache).
// ════════════════════════════════════════════════════════════════════════
// ═══ Helper: lê lessons.json do Drive (.meggy.ai/courses/<hash>/) ═══
// Retorna null se não existir (primeiro aluno a escanear)
async function gdiReadCourseLessons(gd0, courseHash){
  if(!courseHash)return null;
  try{
    // 1. Resolve .meggy.ai/courses/
    const coursesId = await gdiSharedMeggySubfolderId(gd0, 'courses');
    if(!coursesId)return null;
    // 2. Find <courseHash> subfolder
    const opts = await gd0.requestOptions();
    const qHash = "'"+coursesId+"' in parents and name = '"+courseHash+"' and trashed = false and mimeType = 'application/vnd.google-apps.folder'";
    const rHash = await fetch('https://www.googleapis.com/drive/v3/files?'+enQuery({includeItemsFromAllDrives:'true',supportsAllDrives:'true',q:qHash,fields:'files(id)',pageSize:'1'}), opts);
    if(!rHash.ok)return null;
    const jHash = await rHash.json();
    if(!jHash.files||!jHash.files[0])return null;
    const hashId = jHash.files[0].id;
    // 3. Find lessons.json inside <courseHash>/
    const qFile = "'"+hashId+"' in parents and name = 'lessons.json' and trashed = false";
    const rFile = await fetch('https://www.googleapis.com/drive/v3/files?'+enQuery({includeItemsFromAllDrives:'true',supportsAllDrives:'true',q:qFile,fields:'files(id,name)',pageSize:'1'}), opts);
    if(!rFile.ok)return null;
    const jFile = await rFile.json();
    if(!jFile.files||!jFile.files[0])return null;
    // 4. Download the file content
    const fileId = jFile.files[0].id;
    const dlOpts = await gd0.requestOptions({});
    const dlUrl = 'https://www.googleapis.com/drive/v3/files/'+fileId+'?alt=media&supportsAllDrives=true';
    const dlResp = await fetch(dlUrl, dlOpts);
    if(!dlResp.ok)return null;
    const text = await dlResp.text();
    const data = JSON.parse(text);
    return data;
  }catch(_){return null;}
}


async function gdiSaveUserProgressToDrive(gd0, courseHash, username, userProgressJson){
  if(!courseHash || !username || !userProgressJson)return false;
  // 1. Resolve .meggy.ai/courses/
  const coursesId = await gdiSharedMeggySubfolderId(gd0, 'courses');
  if(!coursesId)return false;
  // 2. Find or create <courseHash> subfolder inside courses/
  const hashId = await gdiSharedMeggyDeepSubfolderId(gd0, coursesId, courseHash);
  if(!hashId)return false;
  // 3. Upsert user-<username>.json inside <courseHash>/
  // Sanitize username to a safe filename (avoid special chars in Drive file names).
  const safeUser = String(username).replace(/[^a-zA-Z0-9_.-]/g,'_').slice(0, 50);
  const fileName = 'user-'+safeUser+'.json';
  const opts = await gd0.requestOptions();
  const qFile = "'"+hashId+"' in parents and name = '"+fileName+"' and trashed = false";
  const rFile = await fetch('https://www.googleapis.com/drive/v3/files?'+enQuery({includeItemsFromAllDrives:'true',supportsAllDrives:'true',q:qFile,fields:'files(id)',pageSize:'1'}), opts);
  let existingId = null;
  if(rFile.ok){const j = await rFile.json(); if(j.files && j.files[0])existingId = j.files[0].id;}
  if(existingId){
    const po = await gd0.requestOptions({'Content-Type':'application/json; charset=UTF-8'},'PATCH');
    const pr = await fetch("https://www.googleapis.com/upload/drive/v3/files/"+existingId+"?uploadType=media&supportsAllDrives=true",{method:'PATCH',headers:po.headers,body:userProgressJson});
    return pr.ok;
  }
  // create new
  const boundary = 'gdiuprog'+Date.now();
  const mp = '--'+boundary+'\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n'+JSON.stringify({name:fileName,parents:[hashId]})+'\r\n--'+boundary+'\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n'+userProgressJson+'\r\n--'+boundary+'--';
  const uo = await gd0.requestOptions({'Content-Type':'multipart/related; boundary='+boundary},'POST');
  const ur = await fetch('https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&supportsAllDrives=true',{method:'POST',headers:uo.headers,body:mp});
  return ur.ok;
}

// ════════════════════════════════════════════════════════════════════════

// ★ FIX 2 (Task 19): gdiGeneralCoursesRead now reads from .meggy.ai/courses/ (SHARED).
// folderId parameter is kept for backward-compat signature, but ignored — the shared
// location (.meggy.ai/courses/general_courses.json in drive 0 root) is the source of truth.
// If the shared location doesn't have the file yet, falls back to the legacy per-folder
// location to migrate existing entries (so students with old data aren't lost).
async function gdiGeneralCoursesRead(gd0, folderId){
  const opts=await gd0.requestOptions();
  // 1. Try shared .meggy.ai/courses/general_courses.json
  try{
    const coursesId = await gdiSharedMeggySubfolderId(gd0, 'courses');
    if(coursesId){
      const q="'"+coursesId+"' in parents and name = '"+GENERAL_COURSES_FILE+"' and trashed = false";
      const r=await fetch('https://www.googleapis.com/drive/v3/files?'+enQuery({includeItemsFromAllDrives:'true',supportsAllDrives:'true',q,fields:'files(id)',pageSize:'1'}),opts);
      if(r.ok){
        const j=await r.json();
        if(j.files&&j.files[0]){
          const fr=await fetch("https://www.googleapis.com/drive/v3/files/"+j.files[0].id+"?alt=media&supportsAllDrives=true",opts);
          if(fr.ok){
            try{const arr=JSON.parse(await fr.text());if(Array.isArray(arr)&&arr.length)return arr;}catch(_){}
          }
        }
      }
    }
  }catch(_){}
  // 2. Fallback: legacy per-folder location (for migration — read old data, will be merged on next write)
  if(folderId){
    const q="'"+folderId+"' in parents and name = '"+GENERAL_COURSES_FILE+"' and trashed = false";
    const r=await fetch('https://www.googleapis.com/drive/v3/files?'+enQuery({includeItemsFromAllDrives:'true',supportsAllDrives:'true',q,fields:'files(id)',pageSize:'1'}),opts);
    if(!r.ok)return [];
    const j=await r.json();
    if(!j.files||!j.files[0])return [];
    const fr=await fetch("https://www.googleapis.com/drive/v3/files/"+j.files[0].id+"?alt=media&supportsAllDrives=true",opts);
    if(!fr.ok)return [];
    try{const arr=JSON.parse(await fr.text());return Array.isArray(arr)?arr:[];}catch(_){return [];}
  }
  return [];
}

// ★ FIX 2 (Task 19): gdiGeneralCoursesWrite now writes to .meggy.ai/courses/ (SHARED).
// folderId parameter is kept for backward-compat signature, but ignored — writes always
// go to the shared .meggy.ai/courses/general_courses.json so all students see the same catalog.
async function gdiGeneralCoursesWrite(gd0, folderId, data){
  const body=JSON.stringify(data);
  const opts=await gd0.requestOptions();
  // Resolve shared courses folder (.meggy.ai/courses/)
  const coursesId = await gdiSharedMeggySubfolderId(gd0, 'courses');
  if(!coursesId){
    // Last-resort fallback: write to legacy per-folder location (so data isn't lost)
    if(!folderId)return false;
    const q="'"+folderId+"' in parents and name = '"+GENERAL_COURSES_FILE+"' and trashed = false";
    const r=await fetch('https://www.googleapis.com/drive/v3/files?'+enQuery({includeItemsFromAllDrives:'true',supportsAllDrives:'true',q,fields:'files(id)',pageSize:'1'}),opts);
    let existingId=null;
    if(r.ok){const j=await r.json();if(j.files&&j.files[0])existingId=j.files[0].id;}
    if(existingId){
      const po=await gd0.requestOptions({'Content-Type':'application/json; charset=UTF-8'},'PATCH');
      const pr=await fetch("https://www.googleapis.com/upload/drive/v3/files/"+existingId+"?uploadType=media&supportsAllDrives=true",{method:'PATCH',headers:po.headers,body});
      return pr.ok;
    }
    const boundary='gdicourses'+Date.now();
    const mp='--'+boundary+'\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n'+JSON.stringify({name:GENERAL_COURSES_FILE,parents:[folderId]})+'\r\n--'+boundary+'\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n'+body+'\r\n--'+boundary+'--';
    const co=await gd0.requestOptions({'Content-Type':'multipart/related; boundary='+boundary},'POST');
    const cr=await fetch('https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&supportsAllDrives=true',{method:'POST',headers:co.headers,body:mp});
    return cr.ok;
  }
  // Upsert in shared .meggy.ai/courses/
  const q="'"+coursesId+"' in parents and name = '"+GENERAL_COURSES_FILE+"' and trashed = false";
  const r=await fetch('https://www.googleapis.com/drive/v3/files?'+enQuery({includeItemsFromAllDrives:'true',supportsAllDrives:'true',q,fields:'files(id)',pageSize:'1'}),opts);
  let existingId=null;
  if(r.ok){const j=await r.json();if(j.files&&j.files[0])existingId=j.files[0].id;}
  if(existingId){
    const po=await gd0.requestOptions({'Content-Type':'application/json; charset=UTF-8'},'PATCH');
    const pr=await fetch("https://www.googleapis.com/upload/drive/v3/files/"+existingId+"?uploadType=media&supportsAllDrives=true",{method:'PATCH',headers:po.headers,body});
    return pr.ok;
  }
  const boundary='gdicourses'+Date.now();
  const mp='--'+boundary+'\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n'+JSON.stringify({name:GENERAL_COURSES_FILE,parents:[coursesId]})+'\r\n--'+boundary+'\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n'+body+'\r\n--'+boundary+'--';
  const co=await gd0.requestOptions({'Content-Type':'multipart/related; boundary='+boundary},'POST');
  const cr=await fetch('https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&supportsAllDrives=true',{method:'POST',headers:co.headers,body:mp});
  return cr.ok;
}

async function handleCourseAdd(request){
  const cors={'Access-Control-Allow-Origin':'*','Content-Type':'application/json;charset=UTF-8'};
  const user=await gdiSessionUser(request);
  if(!user)return new Response(JSON.stringify({ok:false,error:'auth'}),{status:401,headers:cors});
  let body;
  try{body=await request.json();}catch(_){return new Response(JSON.stringify({ok:false,error:'invalid json'}),{status:400,headers:cors});}
  let coursePath=String(body.coursePath||'');
  // ★ v2.15.7 (dedup): o registro nasce canônico (Drive JSON + D1 +
  //   fila do backfill) — nenhuma grafia nova entra no sistema.
  try { if (typeof canonicalCoursePath === 'function') coursePath = canonicalCoursePath(coursePath) || coursePath; } catch (_) {}
  if(coursePath.length>500)return new Response(JSON.stringify({ok:false,error:'coursePath too long (max 500 chars)'}),{status:400,headers:cors});
  const courseName=String(body.courseName||'').slice(0,200);
  const pdfCount=parseInt(body.pdfCount||'0',10);
  const icon=String(body.icon||'').slice(0,60);
  const color=String(body.color||'').slice(0,30);
  if(!coursePath)return new Response(JSON.stringify({ok:false,error:'no coursePath'}),{status:400,headers:cors});
  // ★ v2.15.29-C: CORTE D1 — sem Drive aqui (sem gd0/folderId). O lock
  //   continua a serializar o RMW, agora só sobre o D1.
  return await withGeneralCoursesLock('user-courses:'+user, async () => {
    const data=await gdiUserCoursesRead(null,null,user);  // ★ v2.15.29-C: D1 (sem gd0)
    // encontra curso existente por path
    let entry=data.courses.find(c=>(c.coursePath||'')===coursePath);
    if(!entry){
      entry={coursePath,courseName,pdfCount:pdfCount||0,icon:icon||'',color:color||'',addedAt:Date.now()};
      data.courses.push(entry);
    }else{
      // já existe — atualiza campos se vieram diferentes
      if(courseName)entry.courseName=courseName;
      if(pdfCount)entry.pdfCount=pdfCount;
      if(icon)entry.icon=icon;
      if(color)entry.color=color;
    }
    // limita a 1000 cursos por usuário
    if(data.courses.length>1000)data.courses.sort((a,b)=>(a.addedAt||0)-(b.addedAt||0)).splice(0,data.courses.length-1000);
    // ★ v2.15.29-C: CORTE D1 — escrita SÓ no D1 (upsert de 1 linha).
    //   addedAt = agora (igual ao comportamento D1 anterior, que ligava
    //   Date.now() mesmo em update — a lista ordena por added_at DESC).
    let ok=true;
    const _d1=meggyD1Binding();
    if(!_d1){ ok=false; }
    else{
      try{
        await d1EnsureSchema();
        entry.addedAt=Date.now();
        await _d1.prepare('INSERT OR REPLACE INTO user_courses (username, course_path, course_name, pdf_count, icon, color, added_at) VALUES (?,?,?,?,?,?,?)')
          .bind(user, coursePath, entry.courseName||'', entry.pdfCount||0, entry.icon||'', entry.color||'', entry.addedAt)
          .run();
      }catch(e){ ok=false; console.warn('[v2.15.29-C] user_course save falhou:', e.message); }
    }
    // ★ v2.7: entra na fila do backfill — se o scan do navegador travar, o cron completa sozinho
    try { const kv = meggyKvBinding(); if (kv) await enqueueBackfillCourse(kv, coursePath); } catch (_) {}
    return new Response(JSON.stringify({ok,entry,courseCount:data.courses.length}),{status:ok?200:502,headers:cors});
  });
}

// ═══ v1.0.97 REMOVE: remove o user do curso no general_courses.json ═══
// Body: { coursePath: '/10:/TJ SP...' }
// Comportamento:
//   1. Se curso tem users[] com este user → remove o user da lista.
//   2. Se users[] ficou vazio → remove o curso do general_courses.json inteiro.
//   3. Se curso tem users[] vazio (curso público) → marca user como "hidden" adicionando
//      um campo "hiddenFor":[user] (não remove o curso, pois outros users podem querer).
// Retorna {ok:true, removed:true, fullyDeleted:bool}
//
// ★ v1.0.116: agora remove do arquivo PER-USER (<username>.courses.json). O curso é
// estritamente vinculado ao usuário — remover = deletar do Drive do usuário.
async function handleCourseRemove(request){
  const cors={'Access-Control-Allow-Origin':'*','Content-Type':'application/json;charset=UTF-8'};
  const user=await gdiSessionUser(request);
  if(!user)return new Response(JSON.stringify({ok:false,error:'auth'}),{status:401,headers:cors});
  let body;
  try{body=await request.json();}catch(_){return new Response(JSON.stringify({ok:false,error:'invalid json'}),{status:400,headers:cors});}
  const coursePath=String(body.coursePath||'');
  if(coursePath.length>500)return new Response(JSON.stringify({ok:false,error:'coursePath too long (max 500 chars)'}),{status:400,headers:cors});
  if(!coursePath)return new Response(JSON.stringify({ok:false,error:'no coursePath'}),{status:400,headers:cors});
  // ★ v2.15.29-C: CORTE D1 — sem Drive aqui (sem gd0/folderId).
  return await withGeneralCoursesLock('user-courses:'+user, async () => {
    const data=await gdiUserCoursesRead(null,null,user);  // ★ v2.15.29-C: D1 (sem gd0)
    const idx=data.courses.findIndex(c=>(c.coursePath||'')===coursePath);
    // ★ v2.15.29-C: CORTE D1 — sem escrita no Drive (o ficheiro legado
    //   fica intocado; nada o lê mais, por isso nada ressuscita o curso).
    let deletedList=false;
    if(idx>=0){
      deletedList=true;
      data.courses.splice(idx,1);
    }
    // ★ v2.14.7: o DELETE do D1 roda SEMPRE, antes de qualquer return.
    //   Com D1_BACKEND=d1 o curso nunca foi escrito no arquivo do Drive, então
    //   o early-return antigo (idx<0 → return) pulava o DELETE: o servidor
    //   respondia ok, o cliente só escondia o card no localStorage e o curso
    //   continuava em user_courses (voltava em outro aparelho / após limpar o
    //   armazenamento). O match é por caminho normalizado (decode + minúsculas
    //   + sem '/' final) porque o cliente pode enviar a forma codificada
    //   (/11:/CURSOS%202026) ou a decodificada (/11:/CURSOS 2026).
    let d1Ok=true, deletedD1=false;
    const _d1=meggyD1Binding();
    if(_d1){  // ★ v2.15.29-C: D1 incondicional (sem guarda de backend)
      try{
        await d1EnsureSchema();
        const _norm=(s)=>{let x=String(s||'');try{x=decodeURIComponent(x);}catch(_){}return x.toLowerCase().replace(/\/+$/,'');};
        const _want=_norm(body.coursePath||body.path||'');
        const _rows=await _d1.prepare('SELECT course_path FROM user_courses WHERE username = ?').bind(user).all();
        for(const _row of ((_rows&&_rows.results)||[])){
          if(_norm(_row.course_path)===_want){
            await _d1.prepare('DELETE FROM user_courses WHERE username = ? AND course_path = ?').bind(user,_row.course_path).run();
            deletedD1=true;
          }
        }
        console.log('[Meggy D1] user_course removed:', user, (body.coursePath||body.path||'').slice(0,40));
      }catch(e){ d1Ok=false; console.warn('[Meggy D1] user_course remove failed:', e.message); }
    }
    // ★ v2.15.2 (A3): curso removido sai da fila do backfill — antes ele
    //   ficava lá até a 1ª run (e a purga só o tirava se não fosse registrado).
    try { const _kv = meggyKvBinding(); if (_kv) await removeFromBackfillQueue(_kv, coursePath); } catch (_) {}
    // ★ v2.14.8: resultado honesto — antes respondia ok:true mesmo quando NADA
    //   tinha sido apagado (curso em nenhum store) e o cliente não tinha como
    //   saber que a remoção falhou. deleted=false + ok:false + 404 quando não
    //   há nada para apagar; 502 só quando houve tentativa com falha de store.
    const deleted=deletedList||deletedD1;  // ★ v2.15.29-C: sem Drive
    const ok=d1Ok&&deleted;
    return new Response(JSON.stringify({ok,removed:ok,fullyDeleted:ok,deleted,error:ok?undefined:(deleted?'falha ao remover':'curso não encontrado')}),{status:ok?200:(deleted?502:404),headers:cors});
  });
}

