  const r = await d1.prepare('SELECT id, pergunta, resposta_certa, resposta_aluno, modulo, created_at FROM concurso_errors WHERE username=? AND concurso_id=? ORDER BY created_at DESC LIMIT 50').bind(user, concursoId).all();
