  await d1EnsureSchema();
  const d1 = meggyD1Binding();
  if (!d1) return new Response(JSON.stringify({ ok: false, error: 'D1 não vinculado' }), { status: 502, headers: CORS_JSON });
  const row = await getOwnedConcurso(d1, concursoId, user);
  if (!row) return new Response(JSON.stringify({ ok: false, error: 'Concurso not found' }), { status: 404, headers: CORS_JSON });
