// ★ v2.5: DELETE /api/concursos/:id — remove o concurso do aluno (só o dono).
//   Apaga em cascata: concurso_lessons, concurso_disciplinas, concursos.
//   A pasta no Drive NÃO é apagada (as aulas são só referências); o aluno pode
//   criar o concurso de novo depois. O botão vive na lista (Meus Cursos) e no
//   detalhe do concurso (shell.js).
async function handleConcursoDelete(request, url){
  const user=await gdiSessionUser(request);
  if(!user)return new Response(JSON.stringify({ok:false,error:'auth'}),{status:401,headers:CORS_JSON});
  const concursoId=url.pathname.split('/')[3];
  if(!concursoId)return new Response(JSON.stringify({ok:false,error:'missing id'}),{status:400,headers:CORS_JSON});
  await d1EnsureSchema();
  const d1=meggyD1Binding();
  if(!d1)return new Response(JSON.stringify({ok:false,error:'D1 not available'}),{status:503,headers:CORS_JSON});
  const row=await d1.prepare('SELECT id FROM concursos WHERE id=? AND username=?').bind(concursoId,user).first();
  if(!row)return new Response(JSON.stringify({ok:false,error:'Concurso not found'}),{status:404,headers:CORS_JSON});
  const delL=await d1.prepare('DELETE FROM concurso_lessons WHERE concurso_id=?').bind(concursoId).run();
  const delD=await d1.prepare('DELETE FROM concurso_disciplinas WHERE concurso_id=?').bind(concursoId).run();
  // ★ v2.14.5: apaga também o plano do concurso (antes ficava órfão)
  const delP=await d1.prepare('DELETE FROM study_plans WHERE concurso_id=?').bind(concursoId).run();
  // ★ v2.15.0: apaga também as fontes (módulos) e o caderno de erros
  const delS=await d1.prepare('DELETE FROM concurso_sources WHERE concurso_id=?').bind(concursoId).run();
  const delE=await d1.prepare('DELETE FROM concurso_errors WHERE concurso_id=?').bind(concursoId).run();
  const delC=await d1.prepare('DELETE FROM concursos WHERE id=? AND username=?').bind(concursoId,user).run();
  return new Response(JSON.stringify({ok:true,deleted:{lessons:(delL&&delL.meta&&delL.meta.changes)||0,disciplinas:(delD&&delD.meta&&delD.meta.changes)||0,plans:(delP&&delP.meta&&delP.meta.changes)||0,sources:(delS&&delS.meta&&delS.meta.changes)||0,errors:(delE&&delE.meta&&delE.meta.changes)||0,concursos:(delC&&delC.meta&&delC.meta.changes)||0}}),{headers:CORS_JSON});
}

// GET /api/concursos/list — lista concursos do usuario
async function handleConcursoList(request){
  const user=await gdiSessionUser(request);
  if(!user)return new Response(JSON.stringify({ok:false,error:'auth'}),{status:401,headers:CORS_JSON});
  await d1EnsureSchema();
  const d1=meggyD1Binding();
  if(!d1)return new Response(JSON.stringify({ok:false,error:'D1 not available'}),{status:503,headers:CORS_JSON});
  const rows=await d1.prepare('SELECT * FROM concursos WHERE username=? ORDER BY created_at DESC').bind(user).all();
  const concursos=[];
  for(const r of rows.results||[]){
    const lessonCount=await d1.prepare('SELECT COUNT(*) as cnt FROM concurso_lessons WHERE concurso_id=?').bind(r.id).first();
    const matchedCount=lessonCount?.cnt||0;
    concursos.push({id:r.id,name:r.name,examDate:r.exam_date,dailyHours:r.daily_hours,status:r.status,createdAt:r.created_at,lessonCount:matchedCount});
  }
  return new Response(JSON.stringify({ok:true,concursos}),{headers:{...CORS_JSON,'Cache-Control':'no-store'}});
}

// GET /api/concursos/:id — detalhe do concurso
async function handleConcursoDetail(request, url){
  const user=await gdiSessionUser(request);
  if(!user)return new Response(JSON.stringify({ok:false,error:'auth'}),{status:401,headers:CORS_JSON});
  const concursoId=url.pathname.split('/')[3];
  await d1EnsureSchema();
  const d1=meggyD1Binding();
  const row=await d1.prepare('SELECT * FROM concursos WHERE id=? AND username=?').bind(concursoId,user).first();
  if(!row)return new Response(JSON.stringify({ok:false,error:'Not found'}),{status:404,headers:CORS_JSON});
  // Get disciplinas
  const discRows=await d1.prepare('SELECT * FROM concurso_disciplinas WHERE concurso_id=?').bind(concursoId).all();
  // ★ v2.15.81: UMA query de aulas p/ o concurso inteiro — antes eram
  //   1 por disciplina + 1 de intensivo + 1 de paths (17 statements
  //   sequenciais por GET com 11 disciplinas; a lentidão de 20–30 s
  //   do detalhe). O ORDER BY (disciplina, topico, lesson_name)
  //   preserva a ordem (topico, lesson_name) dentro de cada
  //   disciplina; intensivo e paths derivam das mesmas linhas.
  const _allLesRows21581=(await d1.prepare('SELECT * FROM concurso_lessons WHERE concurso_id=? ORDER BY disciplina, topico, lesson_name').bind(concursoId).all()).results||[];
  const _lesByDisc21581={};
  for(const _l of _allLesRows21581){ (_lesByDisc21581[_l.disciplina]=_lesByDisc21581[_l.disciplina]||[]).push(_l); }
  const disciplinas=[];
  for(const dr of discRows.results||[]){
    const lessons={results:_lesByDisc21581[dr.nome]||[]};
    // ★ v2.15.2 (F): dedupe por lesson_path normalizado — linhas legadas
    //   (crua + codificada) da mesma aula não se repetem na lista.
    const _seen = new Set();
    const _les = [];
    for(const l of (lessons.results || [])){
      const _k = normalizeLessonPath(l.lesson_path || (l.lesson_name || ''));
      if(_seen.has(_k)) continue;
      _seen.add(_k);
      _les.push({path:l.lesson_path,name:l.lesson_name,topico:l.topico,confidence:l.confidence,isIntensivo:l.is_intensivo,folder:lessonFolderLabel(l.lesson_path),displayName:lessonDisplayName(l.lesson_path,l.lesson_name)});
    }
    disciplinas.push({nome:dr.nome,peso:dr.peso,incidencia:dr.incidencia,topicos:JSON.parse(dr.topicos||'[]'),lessons:_les});
  }
  // Get intensivo lessons — ★ v2.15.81: contagem CRUA (sem dedupe)
  //   das mesmas linhas já lidas, igual à query separada de antes.
  const intensivoRows={results:_allLesRows21581.filter(l=>Number(l.is_intensivo)===1)};
  // ★ v2.15.0: módulos (fontes) do concurso + completude por disciplina (item 5)
  const srcRows=await d1.prepare('SELECT * FROM concurso_sources WHERE concurso_id=? ORDER BY sort_order ASC, id ASC').bind(concursoId).all();
  const allPaths=_allLesRows21581.map(r=>r.lesson_path);
  const sources=(srcRows.results||[]).map(s=>{
    let discs=[]; try{discs=JSON.parse(s.disciplinas||'[]');}catch(_){}
    return {id:s.id,coursePath:s.course_path,name:s.name,sortOrder:s.sort_order,intensivo:!!s.intensivo,lessonCount:new Set(allPaths.map(p=>normalizeLessonPath(p)).filter(p=>p.startsWith(s.course_path))).size,disciplinas:discs,addedAt:s.added_at};
  });
  // completude: X/Y aulas vs o edital — Y = nº de tópicos do edital (cada
  // tópico deveria ter >=1 aula); sem tópicos, Y = nº de aulas (X/X, sem
  // referência). gaps = tópicos sem nenhuma aula (match por topico ou por
  // nome da aula).
  const completeness=disciplinas.map(d=>{
    const topics=d.topicos||[];
    const les=d.lessons||[];
    const covered=new Set();
    for(const t of topics){
      const nt=normalizeStr(t);
      if(les.some(l=>normalizeStr(l.topico||'')===nt||normalizeStr(l.name||'').includes(nt)))covered.add(t);
    }
    const gaps=topics.filter(t=>!covered.has(t));
    return {nome:d.nome,lessons:les.length,expected:topics.length||les.length,coveredTopics:covered.size,totalTopics:topics.length,gaps};
  });
  // ★ v2.15.5 (item 2): totais do detalhe calculados das MESMAS linhas
  //   dedupadas que a resposta lista — é o número que o passo 4 e a
  //   prévia passam a igualar (totais vinculados / projetados).
  const _allLinked=[];
  for (const _d of disciplinas) for (const _l of (_d.lessons||[])) _allLinked.push({lesson_path:_l.path,lesson_name:_l.name,disciplina:_d.nome});
  const _linkedTotals=concursoLinkedTotals(_allLinked);
  const errRow=await d1.prepare('SELECT COUNT(*) AS n FROM concurso_errors WHERE username=? AND concurso_id=?').bind(user,concursoId).first();
  return new Response(JSON.stringify({ok:true,concurso:{id:row.id,name:row.name,examDate:row.exam_date,dailyHours:row.daily_hours,status:row.status,createdAt:row.created_at},disciplinas,intensivoCount:(intensivoRows.results||[]).length,sources,completeness,errorsCount:(errRow?.n||0),totalLessons:_linkedTotals.total,totalMinutes:_linkedTotals.minutes,totalHours:_linkedTotals.hours}),{headers:{...CORS_JSON,'Cache-Control':'no-store'}});
}

// Routes for MEUS CONCURSOS — registered in handleRequest

// ═══ v2.6: GET /api/courses/unified — lista ÚNICA de cursos+concursos+em destaque ═══
// Um só endpoint para a área "Meus Cursos": cursos do aluno (D1 user_courses),
// concursos (D1) e cursos em destaque do admin (D1 featured_courses), cada item
// com kind + total de aulas (D1 lessons / concurso_lessons) + progresso assistido
// (KV progress:<user>:<hash>). Dedupe: destaque que o aluno já adicionou aparece
// só como curso do aluno. Limite de subrequests: 4 D1 + 1 KV list + ≤30 KV gets.
// ★ v2.15.86 (B-31): grafias gémeas cross-worker dos cursos de um drive
//   (id PASTA_ID_AQUI): num worker o índice vive sob '/6:' (canónico
//   desse worker, W3), nos outros sob '/9:'. Mapa EXPLÍCITO e pequeno,
//   como o LEGACY_COURSE_PATH_REBASE da .7 — nunca um rebase geral de
//   drive (o '/6:' do outro worker também tem conteúdo de outros
//   drives físicos).
const FB_TWIN_PREFIX_21586 = {
  '/9:/CURSOS%202025': '/6:/CURSOS%202025',
  '/9:/CURSOS%202026': '/6:/CURSOS%202026',
  '/6:/CURSOS%202025': '/9:/CURSOS%202025',
  '/6:/CURSOS%202026': '/9:/CURSOS%202026'
};
function fbTwinSpellings21586(ck){
  const out = [ck];
  for(const k in FB_TWIN_PREFIX_21586){
    if(ck === k || ck.indexOf(k + '/') === 0){
      const t = FB_TWIN_PREFIX_21586[k] + ck.slice(k.length);
      if(out.indexOf(t) < 0) out.push(t);
    }
  }
  return out;
}
// ★ v2.15.86 (B-31): preenche, a partir do D1 DESTE worker, os totais
//   de cursos registados/destaques que os agregados não cobrem (0 ou
//   ausentes). LIMITADO: no máx. 12 cursos, 1 query por curso ancorada
//   no último segmento do path (formas crua e codificada), filtragem
//   exacta em JS por pasta canónica (a grafia gémea conta p/ a chave
//   registada). Só com o D1 vivo (quotaDead salta). Qualquer falha →
//   fica o total dos agregados (0), sem partir a lista.
async function fbFillMissingCourseTotals21586(d1, totals, courses, featured, quotaDead){
  if(!d1 || quotaDead || !totals) return 0;
  const wanted = new Map();
  const consider = function(p){
    if(!p) return;
    let ck = null;
    try{ ck = (typeof canonicalCoursePath === 'function' ? canonicalCoursePath(p) : null) || null; }catch(_){}
    if(!ck || totals[ck]) return;
    if(!wanted.has(ck)) wanted.set(ck, fbTwinSpellings21586(ck));
  };
  (courses || []).forEach(function(c){ consider(c && c.course_path); });
  (featured || []).forEach(function(f){ consider(f && f.course_path); });
  let filled = 0, n = 0;
  for(const entry of wanted){
    if(n++ >= 12) break;
    const ck = entry[0], spellings = entry[1];
    try{
      const lastSeg = ck.split('/').filter(Boolean).pop() || '';
      if(!lastSeg) continue;
      let dec = lastSeg; try{ dec = decodeURIComponent(lastSeg); }catch(_){}
      const pats = ['%' + dec + '%'];
      if(dec !== lastSeg) pats.push('%' + lastSeg + '%');
      const where = pats.map(function(){ return 'lesson_path LIKE ?'; }).join(' OR ');
      const r = await d1.prepare('SELECT course_path, lesson_path, lesson_type FROM lessons WHERE ' + where).bind(...pats).all();
      const rows = (r && r.results) || [];
      if(!rows.length) continue;
      const set = new Set();
      for(const row of rows){
        let fk = null;
        try{ fk = (typeof lessonFolderKey === 'function') ? lessonFolderKey(row.lesson_path, row.course_path, row.lesson_type) : null; }catch(_){}
        if(!fk) continue;
        let fkC = fk;
        try{ fkC = canonicalCoursePath(fk) || fk; }catch(_){}
        for(const sp of spellings){ if(fkC === sp || fkC.indexOf(sp + '/') === 0){ set.add(fkC); break; } }
      }
      if(set.size){ totals[ck] = set.size; filled++; }
    }catch(_){ /* curso a curso: a falha de um não parte os outros */ }
  }
  return filled;
}

async function handleCoursesUnified(request){
  // ★ v2.15.5 (item 5): no-store — a lista pós-remoção era servida do cache
  //   do navegador e a dica + o cartão do curso removido sobreviviam ao reload.
  const cors={'Access-Control-Allow-Origin':'*','Content-Type':'application/json;charset=UTF-8','Cache-Control':'no-store'};
  const user=await gdiSessionUser(request);
  if(!user)return new Response(JSON.stringify({ok:false,error:'auth'}),{status:401,headers:cors});
  const d1=meggyD1Binding();
  if(!d1)return new Response(JSON.stringify({ok:false,error:'no d1'}),{status:502,headers:cors});
  try{ await d1EnsureSchema(); }catch(e){ console.warn('[unified] schema failed:',e.message); }
  const _qd61 = await d1QuotaDeadShared21560();  // ★ v2.15.61 (Fase 4)
  let _fbUsed=false;
  const items=[];
  // 1) cursos do aluno
  let courses=[];
  try{if(_qd61) throw new Error('D1 quota (carimbo .60)'); const r=await d1.prepare('SELECT course_path, course_name, icon, color, pdf_count FROM user_courses WHERE username=? ORDER BY added_at DESC').bind(user).all();courses=r.results||[];}catch(e){console.warn('[unified] user_courses failed:',e.message); const _snap=await loadTableSnapshot('user_courses'); if(_snap){ courses=_snap.filter(function(x){return x.username===user;}).sort(function(a,b){return (b.added_at||0)-(a.added_at||0);}); _fbUsed=true; } }
  // 2) concursos do aluno
  let concursos=[];
  try{if(_qd61) throw new Error('D1 quota (carimbo .60)'); const r=await d1.prepare('SELECT c.id, c.name, c.exam_date, (SELECT COUNT(*) FROM concurso_lessons cl WHERE cl.concurso_id=c.id) AS lessonCount FROM concursos c WHERE username=? ORDER BY c.created_at DESC').bind(user).all();concursos=r.results||[];}catch(e){console.warn('[unified] concursos failed:',e.message); const _cs=await loadTableSnapshot('concursos'); if(_cs){ const _cl=await loadTableSnapshot('concurso_lessons'); const _cnt={}; if(_cl) for(const _l of _cl){ _cnt[_l.concurso_id]=(_cnt[_l.concurso_id]||0)+1; } concursos=_cs.filter(function(x){return x.username===user;}).sort(function(a,b){return (b.created_at||0)-(a.created_at||0);}).map(function(x){return {id:x.id,name:x.name,exam_date:x.exam_date,lessonCount:_cnt[x.id]||0};}); _fbUsed=true; } }
  // 3) em destaque (admin, para todos)
  let featured=[];
  try{if(_qd61) throw new Error('D1 quota (carimbo .60)'); const r=await d1.prepare('SELECT course_path, course_name, icon, color, cover_url FROM featured_courses ORDER BY sort_order ASC, id ASC').all();featured=r.results||[];}catch(e){console.warn('[unified] featured failed:',e.message); const _snap=await loadTableSnapshot('featured_courses'); if(_snap){ featured=_snap.slice().sort(function(a,b){return ((a.sort_order||0)-(b.sort_order||0)) || ((a.id||0)-(b.id||0));}); _fbUsed=true; } }
  // 4) totais de aulas escaneadas por course_path
  // ★ v2.15.43 (diagnóstico/CF-1): a fonte primária passa a ser o
  //   snapshot de AGREGADOS (1 ficheiro no Drive, emitido pelo
  //   fallback-refresh.py) — a rota NUNCA mais materializa a tabela
  //   lessons inteira por pedido (era a causa-raiz do 500 e do 7500:
  //   62 fetches + ~370x o orçamento de CPU no staging). Sem agregados
  //   disponíveis, cai no caminho legado (D1 ou snapshot completo).
  const totals={};
  let _aggAt=0;
  try{
    const _agg=await loadLessonsTotals();
    if(_agg){ const _byC=lessonsTotalsByCanon(_agg); for(const _ck in _byC){ if(_byC[_ck].folders) totals[_ck]=_byC[_ck].folders; } _aggAt=Number(_agg.generatedAt)||0; if(_aggAt) _fbUsed=true; }
  }catch(_){}
  if(!Object.keys(totals).length){
  try{
    const _sets={};
    let _lrows=null;
    try{ const r=await d1.prepare('SELECT course_path, lesson_path, lesson_name, lesson_type FROM lessons').all(); _lrows=r.results||[]; }
    catch(_le){ _lrows=await loadTableSnapshot('lessons'); if(!_lrows) throw _le; _fbUsed=true; }
    for(const row of _lrows){
      let k=null;
      try{ k=(typeof lessonFolderKey==='function')?lessonFolderKey(row.lesson_path,row.course_path,row.lesson_type):null; }catch(_){ k=null; }
      if(!k) continue;
      let ck=row.course_path;
      try{ if(typeof canonicalCoursePath==='function') ck=canonicalCoursePath(row.course_path)||row.course_path; }catch(_){}
      (_sets[ck]=_sets[ck]||new Set()).add(k);
    }
    for(const ck in _sets){ totals[ck]=_sets[ck].size; }
  }catch(e){console.warn('[unified] lessons count failed:',e.message);}
  }

  // ★ v2.15.86 (B-31): cursos que os agregados não cobrem (ex.: aulas
  //   só no D1 deste worker, sob a grafia gémea do índice irmão) —
  //   preencher do D1, limitado e só com o D1 vivo.
  try{ await fbFillMissingCourseTotals21586(d1, totals, courses, featured, _qd61); }catch(_){}

  // 5) progresso assistido — ★ v2.15.29-C: CORTE D1 (era KV
  //   progress:<user>:* — no máx. 30 leituras, com TTL de 90 dias).
  //   user_watched é a fonte; a contagem por pasta (lessonFolderKey) é a
  //   mesma da versão KV (vídeo+áudio da mesma Aula = 1).
  const watchedByHash={};
  try{
    const _d1u=meggyD1Binding();
    if(_d1u){
      await d1EnsureSchema();
      let _wr;
      try{ if(_qd61) throw new Error('D1 quota (carimbo .60)'); _wr=await _d1u.prepare('SELECT lesson_path, course_path FROM user_watched WHERE username=?').bind(user).all(); }
      catch(_we){ const _ws=await loadTableSnapshot('user_watched'); if(!_ws) throw _we; _wr={results:_ws.filter(function(x){return x.username===user;})}; _fbUsed=true; }
      const _byHash={};
      for(const _row of ((_wr&&_wr.results)||[])){
        if(!_row.lesson_path) continue;
        let _cp=_row.course_path||null;
        if(!_cp){ try{ _cp=historyCourseForPath(_row.lesson_path, courses); }catch(_){ _cp=null; } }
        if(!_cp) continue;
        const _h=courseHashFromPath(_cp);
        (_byHash[_h]=_byHash[_h]||[]).push({path:_row.lesson_path,cp:_cp});
      }
      for(const _h in _byHash){
        const _entries=_byHash[_h];
        const _cp=_entries[0].cp;
        const _s=new Set();
        for(const _p of _entries){ try{ const _k=(typeof lessonFolderKey==='function')?lessonFolderKey(_p.path,_cp):null; if(_k) _s.add(_k); }catch(_){} }
        watchedByHash[_h]=_s.size||_entries.length;
      }
    }
  }catch(e){console.warn('[unified] user_watched progress failed:',e.message);}
  const ownPaths=new Set(courses.map(c=>c.course_path));
  // ★ v2.15.8 (D — capas): capa do gêmeo em destaque (por grafia canônica)
  //   + skip do gêmeo por grafia canônica. Antes o curso do aluno (ex.
  //   '/11:/…') nunca recebia a coverUrl do destaque ('/9:/…') e o
  //   destaque gêmeo aparecia como 2º cartão (o skip comparava a grafia
  //   crua). kind 'course' passa a carregar coverUrl.
  // ★ FUS-D01 (fusão v2.15.8): o skip do gêmeo NÃO é canônico — o
  //   front renderiza 'featured' em seção própria (renderCursos v2.14.7
  //   + home do shell), então o destaque gêmeo NÃO é duplicata: ele é
  //   o cartão da seção '⭐ Cursos em destaque'. O skip canônico da
  //   frente D apagaria o destaque p/ quem já tem o curso. Volta o skip
  //   por grafia exata (comportamento v2.15.7); a herança da capa
  //   (coverByCanon → kind 'course') é mantida.
  const coverByCanon={};
  for(const f of featured){ if(!f.cover_url) continue; try{ const _v=(typeof canonicalCoursePath==='function'?canonicalCoursePath(f.course_path):null)||normCanonPath(f.course_path); if(_v && !coverByCanon[_v]) coverByCanon[_v]=f.cover_url; }catch(_){} }
  for(const c of courses){
    // ★ v2.15.3 (W3): o curso registrado como '/11:/X' mostra as aulas
    //   escaneadas sob o canônico '/9:/X' (mesma pasta física).
    const _ck=(function(){ try{ const v=(typeof canonicalCoursePath==='function'?canonicalCoursePath(c.course_path):null)||normCanonPath(c.course_path); return v; }catch(_){ return normCanonPath(c.course_path); } })();
    const total=totals[_ck]||c.pdf_count||0;
    const hash=courseHashFromPath(c.course_path);
    const watched=watchedByHash[hash]||0;
    items.push({kind:'course',name:c.course_name||c.course_path,coursePath:c.course_path,icon:c.icon||'📚',color:c.color||'',total,watched,percent:total>0?Math.round(watched/total*100):0,coverUrl:coverByCanon[_ck]||null});
  }
  for(const c of concursos){
    items.push({kind:'concurso',name:c.name,concursoId:c.id,icon:'📌',examDate:c.exam_date||null,total:c.lessonCount||0,watched:null,percent:null});
  }
  for(const f of featured){
    const _ck=(function(){ try{ const v=(typeof canonicalCoursePath==='function'?canonicalCoursePath(f.course_path):null)||normCanonPath(f.course_path); return v; }catch(_){ return normCanonPath(f.course_path); } })();
    if(ownPaths.has(f.course_path))continue; // ja aparece como curso do aluno (mesma grafia)
    const total=totals[_ck]||0;
    items.push({kind:'featured',name:f.course_name||f.course_path,coursePath:f.course_path,icon:f.icon||'⭐',color:f.color||'',coverUrl:f.cover_url||null,total,watched:null,percent:null});
  }
  // ★ v2.15.10 (B — P2/P8): snapshotAt — a hora (servidor) da leitura do
  //   D1 que gerou estes totais. Sem ela a prévia não podia dizer de
  //   quando era o número — e 88 às 06:04 vs 86 do admin parecia erro
  //   de contagem quando era só deriva entre leituras (o scan insere
  //   linhas entre elas). A UI mostra-o no rodapé de /cursos.
  return new Response(JSON.stringify(Object.assign({ok:true,items,snapshotAt:(_aggAt||Date.now())}, _fbUsed ? {fallback:true} : {})),{headers:cors}); // ★ v2.15.43: snapshotAt = generatedAt dos agregados quando eles são a fonte
}

