async function handleStudyPlanGenerate(request){
  const cors = {'Content-Type':'application/json;charset=UTF-8','Access-Control-Allow-Origin':'*'};
  const user = await gdiSessionUser(request);
  if(!user) return new Response(JSON.stringify({ok:false,error:'auth'}),{status:401,headers:cors});
  let body;
  try{body=await request.json();}catch(_){return new Response(JSON.stringify({ok:false,error:'invalid json'}),{status:400,headers:cors});}
  const goal = body.goal||'Concurso público';
  const examDate = body.examDate||'';
  const dailyHours = body.dailyHours||2;
  // Generate simple weekly plan
  const days = ['Segunda','Terça','Quarta','Quinta','Sexta','Sábado','Domingo'];
  // ★ v2.15.6-banca: o gerador devolvia só `week`, mas o renderPlan lê
  //   `weekSchedule` — o plano gerado nunca aparecia ("Gerar meu plano"
  //   não fazia nada, o bug que o Elton reportou em 2026-11-14). Agora
  //   devolve os dois formatos + os campos que o render usa.
  const week = days.map(d=>({day:d, blocks:[
    {time:'Manhã', subject:'Direito Constitucional', duration: Math.round(dailyHours*60*0.4)+'min'},
    {time:'Tarde', subject:'Direito Administrativo', duration: Math.round(dailyHours*60*0.3)+'min'},
    {time:'Noite', subject:'Questões + Revisão', duration: Math.round(dailyHours*60*0.3)+'min'}
  ]}));
  const _ed = examDate ? new Date(examDate + 'T12:00:00') : null;
  const daysToExam = (_ed && !isNaN(_ed.getTime())) ? Math.max(0, Math.ceil((_ed.getTime() - Date.now()) / 86400000)) : null;
  const plan = {
    goal, examDate, dailyHours,
    generatedAt: Date.now(),
    daysToExam,
    focusSubjects: [
      { name: 'Direito Constitucional', priority: 'alta' },
      { name: 'Direito Administrativo', priority: 'alta' },
      { name: 'Questões + Revisão', priority: 'media' },
    ],
    tips: ['Estude nos blocos do cronograma e revise no 7º dia.', 'Resolva questões todos os dias — é o que mais fixa o conteúdo.'],
    week,
    weekSchedule: week.map(d=>({ day: d.day, tasks: d.blocks.map(b=>({ course: b.subject, hours: Math.round(parseInt(b.duration, 10) / 60 * 2) / 2, note: b.time })) })),
  };
  return new Response(JSON.stringify({ok:true,plan}),{headers:cors});
}

