// ★ v1.0.177: Backfill lessons table — lê cursos do usuário (<username>.courses.json) e usa
// gdiReadCourseDistributedLessons (que já sabe ler .gdi-lessons.json distribuídos + legacy fallback).
// Idempotente (INSERT OR REPLACE na PK lesson.id). Pode ser chamado múltiplas vezes.
// Limitação: processa até 5 cursos por chamada (limite CF 50 subrequests). Para mais, chamar de novo.
async function handleD1BackfillLessons(request, url){
  const cors = {'Content-Type':'application/json;charset=UTF-8','Access-Control-Allow-Origin':'*'};
  const user = await gdiSessionUser(request);
  if(!user) return new Response(JSON.stringify({ok:false,error:'auth'}),{status:401,headers:cors});
  const d1 = meggyD1Binding();
  if(!d1) return new Response(JSON.stringify({ok:false,error:'D1 not bound'}),{status:503,headers:cors});
  const gd0 = gds[0];
  if(!gd0) return new Response(JSON.stringify({ok:false,error:'no drive'}),{status:502,headers:cors});
  const stats = {coursesScanned:0, lessonsInserted:0, errors:[]};
  try{
    await d1EnsureSchema();
    const folderId = await gdiUserFolderId(gd0);
    if(!folderId) return new Response(JSON.stringify({ok:false,error:'no user folder'}),{status:500,headers:cors});

    // ★ v1.0.177: ler cursos do usuário via gdiUserCoursesRead (Drive <username>.courses.json)
    // ★ v1.0.179: FIX — gdiUserCoursesRead retorna {courses:[]}, não array direto.
    // ★ v1.0.181: Em modo "d1", ler do D1 primeiro (handleCourseAdd salva só no D1 em modo d1).
    let userCourses = [];
    const _d1Backend = meggyD1Backend();
    if(d1 && (_d1Backend === 'dual' || _d1Backend === 'd1')){
      try{
        await d1EnsureSchema();
        const results = await d1.prepare('SELECT course_path, course_name, pdf_count, icon, color, added_at FROM user_courses WHERE username = ? ORDER BY added_at DESC').bind(user).all();
        if(results.results && results.results.length){
          userCourses = results.results.map(r => ({
            coursePath: r.course_path,
            courseName: r.course_name || '',
            pdfCount: r.pdf_count || 0
          }));
        }
      }catch(e){ console.warn('[Meggy D1] backfill user_courses read failed:', e.message); }
    }
    // Fallback: se D1 vazio, ler do Drive
    if(!userCourses.length){
      const userData = await gdiUserCoursesRead(gd0, folderId, user);
      userCourses = (userData && Array.isArray(userData.courses)) ? userData.courses : [];
    }
    if(!userCourses.length){
      return new Response(JSON.stringify({ok:true, stats, message:'no courses found for user'}),{headers:cors});
    }

    // ★ v1.0.178: processa 1 curso por chamada (gdiReadCourseDistributedLessons usa até 24 subrequests).
    // Para backfillar todos, chamar /api/d1/backfill-lessons múltiplas vezes.
    // Suporta ?coursePath=<path> para backfillar um curso específico.
    const targetCourse = (url && url.searchParams && url.searchParams.get('coursePath')) || '';
    let coursesToProcess = userCourses;
    if(targetCourse){
      coursesToProcess = userCourses.filter(c => (c.coursePath||c.path||'') === targetCourse);
    }
    for(const course of coursesToProcess.slice(0, 1)){
      let coursePath = course.coursePath || course.path || '';
      try { if (typeof canonicalCoursePath === 'function') coursePath = canonicalCoursePath(coursePath) || coursePath; } catch (_) {}
      if(!coursePath) continue;
      try{
        stats.coursesScanned++;
        const courseHash = courseHashFromPath(coursePath);
        if(!courseHash){ stats.errors.push('hash_'+coursePath.slice(0,40)); continue; }

        // ★ Resolver drive + folderId inicial do coursePath
        // coursePath formato: /<driveIdx>:/<courseName>/...
        const m = coursePath.match(/^\/(\d+):\/?(.*)$/);
        if(!m){ stats.errors.push('path_format_'+coursePath.slice(0,40)); continue; }
        const driveIdx = parseInt(m[1]);
        const gd = gds[driveIdx];
        if(!gd){ stats.errors.push('no_drive_'+driveIdx); continue; }

        // ★ v1.0.183 FIX Bug #1: resolver folderId real do coursePath (antes passava null).
        // gdiReadCourseDistributedLessons precisa do folderId da raiz do curso para traversar a árvore.
        // Sem isso, retorna 0 lessons (pula null folder → fallback legacy → 0-7 lessons).
        let currentFolderId = gd.root && gd.root.id ? gd.root.id : null;
        if(currentFolderId){
          const subParts = (m[2]||'').split('/').filter(Boolean);
          for(const part of subParts){
            try{
              const opts = await gd.requestOptions();
              const q = "'"+currentFolderId+"' in parents and name = '"+driveEscape(decodeURIComponent(part))+"' and trashed = false";
              const r = await fetch('https://www.googleapis.com/drive/v3/files?'+enQuery({includeItemsFromAllDrives:'true',supportsAllDrives:'true',q,fields:'files(id)',pageSize:'1'}), opts);
              if(!r.ok) break;
              const j = await r.json();
              if(!j.files || !j.files[0]) break;
              currentFolderId = j.files[0].id;
            }catch(e){ break; }
          }
        }
        const counter = {value:0};
        const result = await gdiReadCourseDistributedLessons(gd, coursePath, courseHash, currentFolderId, counter);
        if(result && Array.isArray(result.lessons) && result.lessons.length){
          const now = Date.now();
          for(const lesson of result.lessons){
            if(!lesson || !lesson.name) continue;
            // ★ v2.15.3 (W2): normalizar antes do INSERT (v. d1InsertLessons).
            const _normPath = normalizeLessonPath(rebaseDrivePath(lesson.path || (coursePath + '/' + lesson.name), driveIdx));
            if(!_normPath.startsWith(normalizeCoursePath(coursePath).replace(/\/+$/, ''))) { console.warn('[backfill-lessons] lição fora do curso, descartada:', _normPath.slice(0, 80)); continue; }
            try{
              await d1.prepare('INSERT OR REPLACE INTO lessons (id, course_hash, course_path, lesson_path, lesson_name, lesson_type, mime_type, ext, size, drive_index, parent_folder_path, scanned_at, created_at, updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)')
                .bind(
                  lesson.id || (courseHash+'_'+lesson.name),
                  courseHash,
                  coursePath,
                  _normPath,
                  lesson.name,
                  lesson.type || null,
                  lesson.mimeType || null,
                  lesson.ext || null,
                  lesson.size || null,
                  driveIdx,
                  coursePath,
                  result.scannedAt || now,
                  now,
                  now
                ).run();
              stats.lessonsInserted++;
            }catch(e){ /* ignore individual lesson errors */ }
          }
          console.log('[Meggy D1] backfill lessons:', result.lessons.length, 'from', coursePath.slice(0,50));
        }
      }catch(e){ stats.errors.push('course_'+coursePath.slice(0,40)+':'+e.message.slice(0,60)); }
    }

    return new Response(JSON.stringify({ok:true, stats}),{headers:cors});
  }catch(e){
    return new Response(JSON.stringify({ok:false,error:e.message,stats}),{status:500,headers:cors});
  }
}

// ═══════════════════════════════════════════════════════════════
// ★ v1.0.180 OPÇÃO A: Cron Worker — backfill automático de lessons
// Endpoint: POST /api/d1/cron-backfill (trigger manual para testar sem esperar 6h)
// ═══════════════════════════════════════════════════════════════
// ★ v2.15.8 (B): GET /api/drive/folder-status?path=/N:/... — existe a
//   pasta no Drive? (sessão do aluno, sem admin.) O Explorar Drives
//   lista o Drive direto (GDIndex) e não distingue "pasta vazia" de
//   "pasta inexistente": o GDIndex devolve 404 e a listagem volta []
//   (v. gdi-list-worker.js handleList: `if (!r || !r.ok) break;`).
//   Este endpoint resolve a existência com findPathId (o mesmo mecanismo
//   do drive-browse do admin, v2.14.8) + o bloqueio conhecido do scanner
//   (scan_status) + o caminho canônico (gêmeo legado /11:→/9:). Sem ele,
//   /11:/CURSOS%202026 (not-found real — o drive 11, PREPARATÓRIO OAB,
//   não tem a pasta) aparecia como "📁 Pasta vazia" sem explicação.
async function handleDriveFolderStatus(request, url){
  const cors = {'Content-Type':'application/json;charset=UTF-8','Access-Control-Allow-Origin':'*','Cache-Control':'no-store'};
  const user = await gdiSessionUser(request);
  if(!user) return new Response(JSON.stringify({ok:false,error:'auth'}),{status:401,headers:cors});
  const rawPath = String((url.searchParams.get('path') || '')).trim();
  if(!rawPath) return new Response(JSON.stringify({ok:false,error:'missing path'}),{status:400,headers:cors});
  const parsed = (typeof parseCoursePath === 'function') ? parseCoursePath(rawPath) : null;
  if(!parsed || parsed.driveIndex < 0 || parsed.driveIndex >= (typeof gds !== 'undefined' ? gds.length : 0)) return new Response(JSON.stringify({ok:false,error:'caminho inválido'}),{status:400,headers:cors});
  const gd = gds[parsed.driveIndex];
  if(!gd) return new Response(JSON.stringify({ok:false,error:'drive não disponível'}),{status:503,headers:cors});
  const cleanPath = '/' + (parsed.subPath || '');
  let exists = null;
  if(typeof gd.findPathId === 'function'){
    try { const _pid = await gd.findPathId(cleanPath); exists = !(_pid === undefined || _pid === null); }
    catch(e){ return new Response(JSON.stringify({ok:false,error:'Drive indisponível: ' + (e.message || e)}),{status:502,headers:cors}); }
  }
  let canonicalPath = rawPath, canonicalExists = null, canonicalDriveName = null;
  try { if(typeof canonicalCoursePath === 'function') canonicalPath = canonicalCoursePath(rawPath) || rawPath; } catch (_) {}
  if(canonicalPath !== rawPath){
    const cp = (typeof parseCoursePath === 'function') ? parseCoursePath(canonicalPath) : null;
    if(cp && cp.driveIndex >= 0 && cp.driveIndex < (typeof gds !== 'undefined' ? gds.length : 0)){
      const gdc = gds[cp.driveIndex];
      try { if(gdc && typeof gdc.findPathId === 'function'){ const _pid2 = await gdc.findPathId('/' + (cp.subPath || '')); canonicalExists = !(_pid2 === undefined || _pid2 === null); } } catch (_) { canonicalExists = null; }
      try { canonicalDriveName = (typeof authConfig !== 'undefined' && authConfig && Array.isArray(authConfig.roots) && authConfig.roots[cp.driveIndex]) ? authConfig.roots[cp.driveIndex].name : null; } catch (_) {}
    }
  }
  let blocked = null;
  try {
    const d1 = meggyD1Binding();
    if(d1){
      await d1EnsureSchema();
      const aliases = [rawPath, canonicalPath];
      try { aliases.push(decodeURIComponent(rawPath)); } catch (_) {}
      try { aliases.push(decodeURIComponent(canonicalPath)); } catch (_) {}
      const _inList = '(' + aliases.map(function(){ return '?'; }).join(',') + ')';
      let rows = null;
      try {
        let _stmt = d1.prepare('SELECT course_path, status, last_error, fail_count FROM scan_status WHERE course_path IN ' + _inList);
        _stmt = _stmt.bind.apply(_stmt, aliases);
        const qr = await _stmt.all();
        rows = qr.results || [];
      } catch (_) {
        let _stmt2 = d1.prepare('SELECT course_path, status FROM scan_status WHERE course_path IN ' + _inList);
        _stmt2 = _stmt2.bind.apply(_stmt2, aliases);
        const qr2 = await _stmt2.all();
        rows = (qr2.results || []).map(function(x){ return { course_path: x.course_path, status: x.status, last_error: null, fail_count: 0 }; });
      }
      const dead = (rows || []).filter(function(r){ return r && (r.status === 'not_found' || r.status === 'empty' || r.status === 'error'); });
      if(dead.length){ const b = dead[0]; blocked = { coursePath: b.course_path, status: b.status, kind: b.status, last_error: b.last_error || null, fail_count: b.fail_count || 0 }; }
    }
  } catch (_) {}
  let driveName = null;
  try { driveName = (typeof authConfig !== 'undefined' && authConfig && Array.isArray(authConfig.roots) && authConfig.roots[parsed.driveIndex]) ? authConfig.roots[parsed.driveIndex].name : null; } catch (_) {}
  return new Response(JSON.stringify({ok:true, path: rawPath, exists: exists, driveIndex: parsed.driveIndex, driveName: driveName, canonicalPath: canonicalPath, canonicalExists: canonicalExists, canonicalDriveName: canonicalDriveName, blocked: blocked}),{headers:cors});
}

// Endpoint: GET  /api/d1/cron-progress (ver progresso salvo no KV)
// ═══════════════════════════════════════════════════════════════════════
// v2.15.34 — FILA DE GERAÇÃO DE RESUMOS EM SEGUNDO PLANO (GenQueue)
// Inserido antes do bloco do cron do scanner. ADITIVO: não toca em
// scan-courses / scan-list-files / scan-upsert-lessons nem no cron do
// scanner (handleCronBackfill). Reutiliza o MESMO batalhão on-demand
// (battalionGenSummary / Pills / Questions + battalionEnsureSummaryHook)
// e os mesmos destinos (pasta de materiais .gdi-resumos/ + D1/cache +
// partilhados). Fonte NUNCA do vídeo: (1) transcrição MD na pasta da
// aula, (2) texto do cliente (pdf.js, no enqueue) p/ PDFs — o worker
// NÃO tem pdf.js (v80-FIX-WORKER BUG 6; handleRedacaoCorrectFull devolve
// 400 p/ PDF) e a extração binária lê lixo; por isso NÃO há extração de
// PDF no servidor. Ver NOTES.md (front-R14C-genqueue) p/ o desenho todo.
// ═══════════════════════════════════════════════════════════════════════

const GENQUEUE_VERSION = '2.15.34';
const GENQUEUE_TABLE = 'generation_queue';
const GENQUEUE_STATUSES = ['queued', 'running', 'done', 'failed', 'needs_text'];
const GENQUEUE_SOURCES = ['play', 'queue', 'chat'];
const GENQUEUE_MAX_BATCH_PER_RUN = 5;
const GENQUEUE_POPULAR_VIEWS = 3;
const GENQUEUE_SOURCE_TEXT_MAX = 15000;
const GENQUEUE_BACKOFF_BASE_MS = 300000;
const GENQUEUE_BACKOFF_MAX_MS = 3600000;
const GENQUEUE_DAY_TTL_S = 48 * 3600;
const GENQUEUE_RUN_LAST_TTL_S = 7 * 24 * 3600;
const GENQUEUE_DEFAULTS = {
  enabled: true,
  pilot: true,
  pilotCap: 5,
  batchPerRun: 1,
  dailyCap: 5,
  maxAttempts: 3,
  runBudgetMs: 20000,
  sleepBetweenMs: 50000
};

// Puro: backoff exponencial 5min -> 10min -> 20min -> 60min (teto).
function genqueueBackoffMs(attempts){
  const a = Math.max(1, Number(attempts) || 1);
  return Math.min(GENQUEUE_BACKOFF_MAX_MS, GENQUEUE_BACKOFF_BASE_MS * Math.pow(2, a - 1));
}

// Puro: balde de prioridade (1 = mais alta). Ordem do brief:
// (1) cursos em destaque, (2) aulas mais vistas, (3) planos, (4) resto.
function genqueuePriorityRank(isFeatured, views, inPlan){
  if(isFeatured) return 1;
  if((Number(views) || 0) >= GENQUEUE_POPULAR_VIEWS) return 2;
  if(inPlan) return 3;
  return 4;
}

// Puro: chave do contador diário (UTC, como o reset da cota CF 3036).
function genqueueDayKey(nowMs){
  return 'genqueue:day:' + new Date(nowMs || Date.now()).toISOString().slice(0, 10);
}

function genqueueSleep(ms){
  return new Promise(function(r){ setTimeout(r, ms); });
}

function genqueueNum(v, def, min, max){
  let n = Number(v);
  if(!isFinite(n)) return def;
  n = Math.floor(n);
  if(min !== undefined && n < min) n = min;
  if(max !== undefined && n > max) n = max;
  return n;
}

// Config da fila (KV genqueue:config, JSON). Defaults do piloto quando não há nada.
async function genqueueLoadConfig(){
  const cfg = Object.assign({}, GENQUEUE_DEFAULTS);
  try{
    const kv = (typeof meggyKvBinding === 'function') ? meggyKvBinding() : null;
    if(!kv) return cfg;
    const raw = await kv.get('genqueue:config');
    if(!raw) return cfg;
    const saved = JSON.parse(raw);
    if(!saved || typeof saved !== 'object') return cfg;
    if(typeof saved.enabled === 'boolean') cfg.enabled = saved.enabled;
    if(typeof saved.pilot === 'boolean') cfg.pilot = saved.pilot;
    cfg.pilotCap = genqueueNum(saved.pilotCap, cfg.pilotCap, 0, 1000);
    cfg.batchPerRun = genqueueNum(saved.batchPerRun, cfg.batchPerRun, 1, GENQUEUE_MAX_BATCH_PER_RUN);
    cfg.dailyCap = genqueueNum(saved.dailyCap, cfg.dailyCap, 0, 100);
    cfg.maxAttempts = genqueueNum(saved.maxAttempts, cfg.maxAttempts, 1, 5);
    cfg.runBudgetMs = genqueueNum(saved.runBudgetMs, cfg.runBudgetMs, 5000, 120000);
    cfg.sleepBetweenMs = genqueueNum(saved.sleepBetweenMs, cfg.sleepBetweenMs, 0, 120000);
  }catch(_){}
  return cfg;
}

async function genqueueSaveConfig(cfg){
  try{
    const kv = (typeof meggyKvBinding === 'function') ? meggyKvBinding() : null;
    if(!kv) return false;
    await kv.put('genqueue:config', JSON.stringify(cfg));
    return true;
  }catch(_){ return false; }
}

// Pausa por cota CF 3036: as chaves modelhealth:cf:<modelo> com valor
// "quota:<epochMs>" (v2.15.15-A2) dizem que a cota diária morreu até à
// meia-noite UTC. Se alguma estiver viva, o runner NÃO corre (não gasta
// tentativas à toa nem esvazia a geração interativa).
async function genqueueCfQuotaPaused(){
  try{
    const kv = (typeof meggyKvBinding === 'function') ? meggyKvBinding() : null;
    if(!kv || typeof kv.list !== 'function') return { paused: false, until: 0 };
    const page = await kv.list({ prefix: 'modelhealth:cf:' });
    const now = Date.now();
    let until = 0;
    for(const k of ((page && page.keys) || [])){
      const v = String((k && (k.value || k.name)) || '');
      const name = String((k && k.name) || '');
      if(!name) continue;
      let val = '';
      try{ val = String(await kv.get(name) || ''); }catch(_){ val = v; }
      const m = val.match(/^quota:(\d+)/);
      if(m && Number(m[1]) > now && Number(m[1]) > until) until = Number(m[1]);
    }
    return { paused: until > now, until: until };
  }catch(_){ return { paused: false, until: 0 }; }
}

async function genqueueKvInt(key){
  try{
    const kv = (typeof meggyKvBinding === 'function') ? meggyKvBinding() : null;
    if(!kv) return 0;
    return Number(await kv.get(key)) || 0;
  }catch(_){ return 0; }
}

async function genqueueKvIncr(key, ttlS){
  try{
    const kv = (typeof meggyKvBinding === 'function') ? meggyKvBinding() : null;
    if(!kv) return 0;
    const n = (await genqueueKvInt(key)) + 1;
    if(ttlS) await kv.put(key, String(n), { expirationTtl: ttlS });
    else await kv.put(key, String(n));
    return n;
  }catch(_){ return 0; }
}

// Prioridade de uma aula (lê D1: destaques, vistas, planos). Reutilizada
// no enqueue e no reprioritize; o claim ordena pelo valor guardado.
async function genqueueComputePriority(d1, lessonPath, coursePath){
  let featured = false;
  let views = 0;
  let inPlan = false;
  try{
    const r = await d1.prepare('SELECT 1 AS x FROM featured_courses WHERE course_path = ? LIMIT 1').bind(coursePath || '').first();
    featured = !!(r && r.x);
  }catch(_){}
  try{
    const r = await d1.prepare('SELECT COUNT(*) AS n FROM user_watched WHERE lesson_path = ?').bind(lessonPath).first();
    views = Number((r && r.n) || 0);
  }catch(_){}
  try{
    const r = await d1.prepare('SELECT 1 AS x FROM concurso_lessons WHERE lesson_path = ? LIMIT 1').bind(lessonPath).first();
    inPlan = !!(r && r.x);
  }catch(_){}
  return genqueuePriorityRank(featured, views, inPlan);
}

// Resumo válido já existe? Fonte de verdade = materials_meta (o batalhão
// escreve lá; lessons.has_summary nunca é escrito pelo código atual, por
// isso é só um segundo sinal — o runner passa a escrevê-lo).
async function genqueueHasValidSummary(d1, lessonPath){
  try{
    const r = await d1.prepare("SELECT 1 AS x FROM materials_meta WHERE lesson_path = ? AND material_type = 'resumo' LIMIT 1").bind(lessonPath).first();
    if(r && r.x) return true;
  }catch(_){}
  try{
    const r = await d1.prepare('SELECT has_summary FROM lessons WHERE lesson_path = ? LIMIT 1').bind(lessonPath).first();
    if(r && Number(r.has_summary) === 1) return true;
  }catch(_){}
  return false;
}

// Claim atómico: só marca running se ainda estiver queued (o UPDATE com
// guarda + meta.changes resolve a corrida entre dois runners).
async function genqueueClaimJob(d1, lessonPath, now){
  const r = await d1.prepare("UPDATE generation_queue SET status = 'running', updated_at = ? WHERE lesson_path = ? AND status = 'queued'").bind(now, lessonPath).run();
  return !!((r && r.meta && r.meta.changes) === 1);
}

async function genqueueSetJob(d1, lessonPath, fields){
  const now = Date.now();
  const sets = [];
  const args = [];
  if(fields.status !== undefined){ sets.push('status = ?'); args.push(fields.status); }
  if(fields.attempts !== undefined){ sets.push('attempts = ?'); args.push(fields.attempts); }
  if(fields.nextRetryAt !== undefined){ sets.push('next_retry_at = ?'); args.push(fields.nextRetryAt); }
  if(fields.lastError !== undefined){ sets.push('last_error = ?'); args.push(fields.lastError); }
  if(fields.sourceText !== undefined){ sets.push('source_text = ?'); args.push(fields.sourceText); }
  if(fields.result !== undefined){ sets.push('result = ?'); args.push(fields.result); }
  if(fields.priority !== undefined){ sets.push('priority = ?'); args.push(fields.priority); }
  if(!sets.length) return;
  sets.push('updated_at = ?'); args.push(now); args.push(lessonPath);
  await d1.prepare('UPDATE generation_queue SET ' + sets.join(', ') + ' WHERE lesson_path = ?').bind(...args).run();
}

// Garante o drive 0 no contexto do cron (gds nasce vazio no scheduled;
// no fetch o handleRequest já inicializou). Mesmo padrão lazy do
// handleCronBackfill: initRootType é puro (0 fetches), o token é lazy.
async function genqueueEnsureDrive0(){
  try{
    if(typeof gds !== 'undefined' && gds[0]) return gds[0];
    const gd = new googleDrive(authConfig, 0);
    try{ await gd.initRootType(); }catch(_){}
    gds[0] = gd;
    return gd;
  }catch(_){ return (typeof gds !== 'undefined') ? (gds[0] || null) : null; }
}

// ── FONTE DO RESUMO (nunca o vídeo) ──────────────────────────────────────
// PASSO 2A do front (gdi-meggy.js): transcrições .md/.txt com "transcri"
// no nome, >50 chars, usam-se SÓ elas. O runner replica isto no servidor:
// lista os filhos da pasta da aula no Drive e baixa as transcrições por
// alt=media. Ficheiros .md gerados por IA ("resumo IA", "ebook IA") são
// excluídos (mesmo filtro do front) — resumir um resumo não vale.
// PASSO 2B (PDFs via pdf.js) NÃO existe no worker — ver genqueueProcessLesson.
async function genqueueFetchTranscriptionMd(lessonPath){
  const resolved = await _resolveLessonParentFolder(lessonPath);
  if(!resolved || !resolved.ok) return { ok: false, error: (resolved && resolved.error) || 'cannot resolve lesson folder' };
  const gd = resolved.gd;
  const parentId = resolved.parentFolderId;
  let files = [];
  try{
    const opts = await gd.requestOptions();
    const qs = new URLSearchParams({ includeItemsFromAllDrives: 'true', supportsAllDrives: 'true', q: "'" + parentId + "' in parents and trashed = false", fields: 'files(id,name,mimeType)', pageSize: '100' });
    const r = await fetch('https://www.googleapis.com/drive/v3/files?' + qs.toString(), opts);
    if(!r.ok) return { ok: false, error: 'drive list failed: HTTP ' + r.status };
    const j = await r.json();
    files = (j && j.files) || [];
  }catch(e){ return { ok: false, error: 'drive list failed: ' + (e && e.message) }; }
  const isAiMd = function(n){
    const s = String(n || '').toLowerCase();
    if(!(/\.md$|\.txt$/).test(s)) return true;
    return /ebook.*ia|resumo.*ia|gerado.*por.*ia|\bia\b.*gerad|intelig.*artif/i.test(s);
  };
  const cands = files.filter(function(f){
    return /transcri/i.test(String(f.name || '')) && !isAiMd(f.name);
  });
  if(!cands.length){
    const conv = await genqueueFetchConvertedMd(gd, parentId, files);
    if(conv.ok) return conv;
    return { ok: false, error: 'no transcription md in lesson folder', source: 'none' };
  }
  let text = '';
  const used = [];
  for(const f of cands){
    try{
      const opts = await gd.requestOptions();
      const r = await fetch('https://www.googleapis.com/drive/v3/files/' + f.id + '?alt=media&supportsAllDrives=true', opts);
      if(!r.ok) continue;
      const t = String(await r.text() || '');
      if(t.trim().length < 50) continue;
      text += (text ? '\n\n---\n\n' : '') + t;
      used.push(f.name);
      if(text.length >= GENQUEUE_SOURCE_TEXT_MAX) break;
    }catch(_){}
  }
  if(text.trim().length < 50){
    const conv = await genqueueFetchConvertedMd(gd, parentId, files);
    if(conv.ok) return conv;
    return { ok: false, error: 'transcription md too short (<50 chars)', source: 'none' };
  }
  return { ok: true, text: text.slice(0, GENQUEUE_SOURCE_TEXT_MAX), source: 'md', files: used };
}
// ★ v2.15.74: MD convertido dos materiais (pdf2md.py grava
// "<nome> - MarkDown.md" AO LADO do PDF). Procura na pasta da aula e
// na subpasta material/ (onde os PDFs costumam viver). Devolve
// source:'converted-md' p/ o resultado do job provar a fonte usada.
async function genqueueFetchConvertedMd(gd, parentId, files){
  const isConverted = function(n){
    const s = String(n || '');
    if(!/ - MarkDown\.md$/i.test(s)) return false;
    return !/resumo.*ia|gerado.*por.*ia|ebook.*ia/i.test(s.toLowerCase());
  };
  let cands = (files || []).filter(function(f){ return isConverted(f.name); });
  const matFolder = (files || []).find(function(f){
    return f.mimeType === 'application/vnd.google-apps.folder' &&
      /^material$/i.test(String(f.name || '').trim());
  });
  if(matFolder){
    try{
      const opts = await gd.requestOptions();
      const qs = new URLSearchParams({ includeItemsFromAllDrives: 'true', supportsAllDrives: 'true', q: "'" + matFolder.id + "' in parents and trashed = false", fields: 'files(id,name,mimeType)', pageSize: '100' });
      const r = await fetch('https://www.googleapis.com/drive/v3/files?' + qs.toString(), opts);
      if(r.ok){
        const j = await r.json();
        cands = cands.concat(((j && j.files) || []).filter(function(f){ return isConverted(f.name); }));
      }
    }catch(_){}
  }
  if(!cands.length) return { ok: false, error: 'no converted md in lesson folder' };
  let text = '';
  const used = [];
  for(const f of cands){
    try{
      const opts = await gd.requestOptions();
      const r = await fetch('https://www.googleapis.com/drive/v3/files/' + f.id + '?alt=media&supportsAllDrives=true', opts);
      if(!r.ok) continue;
      const t = String(await r.text() || '');
      if(t.trim().length < 50) continue;
      text += (text ? '\n\n---\n\n' : '') + t;
      used.push(f.name);
      if(text.length >= GENQUEUE_SOURCE_TEXT_MAX) break;
    }catch(_){}
  }
  if(text.trim().length < 50) return { ok: false, error: 'converted md too short (<50 chars)' };
  return { ok: true, text: text.slice(0, GENQUEUE_SOURCE_TEXT_MAX), source: 'converted-md', files: used };
}


// ── DESTINO: pasta dos materiais (.gdi-resumos/ na pasta da aula) ────────
// Reutiliza _resolveLessonParentFolder + gdiWriteFolderDotfile — o mesmo
// núcleo do POST /api/materials/save-in-folder (a subpasta .gdi-resumos/
// é criada aqui com o mesmo padrão). Depois regista em materials_meta +
// lessons.has_summary (primeiro escritor desta flag) + espelho D1 do pool
// partilhado + espelho KV 'summary:' (o mesmo que o merge do batalhão faz).
// Se o Drive estiver só-leitura/desconectado, a escrita no Drive falha
// mas a aula NÃO falha: o resumo vive em D1/KV/partilhados e o resultado
// regista driveSaved:false (o admin vê no GET /api/generation/queue).
async function genqueueSaveSummaryToLessonFolder(lessonPath, fileName, summaryText, actorUser, keyPrefix, questions, coursePathArg){
  const out = { driveSaved: false, file: null, metaOk: false, sharedOk: false, kvOk: false };
  const resolved = await _resolveLessonParentFolder(lessonPath);
  if(resolved && resolved.ok){
    try{
      const subfolderName = '.gdi-resumos';
      let subfolderId = null;
      const opts = await resolved.gd.requestOptions();
      const qs = new URLSearchParams({ includeItemsFromAllDrives: 'true', supportsAllDrives: 'true', q: "'" + resolved.parentFolderId + "' in parents and name='" + subfolderName + "' and mimeType='application/vnd.google-apps.folder' and trashed=false", fields: 'files(id)', pageSize: '1' });
      const r = await fetch('https://www.googleapis.com/drive/v3/files?' + qs.toString(), opts);
      if(r.ok){ const j = await r.json(); if(j.files && j.files[0]) subfolderId = j.files[0].id; }
      if(!subfolderId){
        const co = await resolved.gd.requestOptions({ 'Content-Type': 'application/json' }, 'POST');
        co.body = JSON.stringify({ name: subfolderName, mimeType: 'application/vnd.google-apps.folder', parents: [resolved.parentFolderId] });
        const cr = await fetch('https://www.googleapis.com/drive/v3/files?supportsAllDrives=true', co);
        if(cr.ok){ const cj = await cr.json(); subfolderId = cj.id || null; }
      }
      if(subfolderId){
        // gdiWriteFolderDotfile devolve boolean (ur.ok).
        const w = await gdiWriteFolderDotfile(resolved.gd, subfolderId, fileName, summaryText);
        if(w === true){ out.driveSaved = true; out.file = subfolderName + '/' + fileName; }
      }
    }catch(e){ console.warn('[GenQueue] save .gdi-resumos failed:', (e && e.message) || e); }
  }
  try{
    const d1 = (typeof meggyD1Binding === 'function') ? meggyD1Binding() : null;
    const backend = (typeof meggyD1Backend === 'function') ? meggyD1Backend() : 'dual';
    if(d1 && (backend === 'dual' || backend === 'd1')){
      await d1EnsureSchema();
      // coursePath = o da linha lessons (passado pelo caller); fallback =
      // '/<drive>:/<primeira pasta>' (ex.: '/0:/CURSOS 2026').
      const _lp = lessonPath.split('/').filter(Boolean);
      const coursePath = coursePathArg || (_lp.length >= 2 ? '/' + _lp[0] + '/' + _lp[1] : lessonPath);
      const courseHash = courseHashFromPath(coursePath);
      const fileRef = out.file || ('.gdi-resumos/' + fileName);
      await d1.prepare('INSERT OR REPLACE INTO materials_meta (course_hash, lesson_path, material_type, file, generated_at, generated_by) VALUES (?,?,?,?,?,?)').bind(courseHash, lessonPath, 'resumo', fileRef, Date.now(), actorUser || 'genqueue').run();
      out.metaOk = true;
      try{ await d1.prepare('UPDATE lessons SET has_summary = 1, updated_at = ? WHERE lesson_path = ?').bind(Date.now(), lessonPath).run(); }catch(_){}
      try{
        const lessonName = lessonPath.split('/').filter(Boolean).pop() || lessonPath;
        await d1.prepare('DELETE FROM shared_summaries WHERE lesson_name = ? AND author = ?').bind(lessonName, actorUser || 'genqueue').run();
        const _nowGq21563 = Date.now();
        await d1.prepare('INSERT OR REPLACE INTO shared_summaries (lesson_name, summary, questions, author, course_path, date) VALUES (?,?,?,?,?,?)').bind(lessonName, summaryText, questions ? JSON.stringify(questions) : null, actorUser || 'genqueue', coursePath || null, _nowGq21563).run();
        try{ const _grow21563 = { lesson_name: lessonName, summary: summaryText, questions: questions ? JSON.stringify(questions) : null, author: actorUser || 'genqueue', course_path: coursePath || null, date: _nowGq21563 }; await d1PeerMirrorOps21563([ { id: fbOpId(), ts: _nowGq21563, table: 'shared_summaries', action: 'delete', key: { lesson_name: _grow21563.lesson_name, author: actorUser || 'genqueue' } }, { id: fbOpId(), ts: _nowGq21563, table: 'shared_summaries', action: 'insert', key: { lesson_name: _grow21563.lesson_name, author: actorUser || 'genqueue' }, row: _grow21563 } ]); }catch(_){}  // ★ v2.15.63: escrita DUAL
        out.sharedOk = true;
      // ★ v2.15.48: as questões do lote entram no BANCO (disciplina →
      //   assunto, dedup por fingerprint) — best-effort, nunca falha a
      //   gravação do resumo.
      try{
        if(Array.isArray(questions) && questions.length){
          const _bank = await bankUpsertQuestions21548(d1, questions, { author: actorUser || 'genqueue', lessonName: lessonName, coursePath: coursePath, lessonPath: lessonPath, summaryText: summaryText || '' });  // ★ v2.15.54: resumo do lote p/ a cadeia de classificação
          out.bankOk = true; out.bankInserted = _bank.inserted;
        }
      }catch(e){ console.warn('[GenQueue] question bank upsert failed:', (e && e.message) || e); }
      }catch(e){ console.warn('[GenQueue] shared mirror failed:', (e && e.message) || e); }
    }
  }catch(e){ console.warn('[GenQueue] D1 save failed:', (e && e.message) || e); }
  try{
    const kv = (typeof meggyKvBinding === 'function') ? meggyKvBinding() : null;
    if(kv && keyPrefix){
      await kv.put('summary:' + keyPrefix, JSON.stringify({ summary: summaryText, lessonName: lessonPath.split('/').filter(Boolean).pop() || '', author: actorUser || 'genqueue', date: Date.now() }), { expirationTtl: 2592000 }); // ★ v2.15.43 (CF-7): TTL 30d
      out.kvOk = true;
    }
  }catch(_){}
  return out;
}

// ── PROCESSAR UMA AULA (o runner chama isto; nunca o scan) ───────────────
// 1) fonte: source_text do enqueue (texto do cliente, pdf.js) OU
//    transcrição MD na pasta da aula OU MD convertido dos materiais
//    (★ v2.15.74: "<nome> - MarkDown.md" ao lado do PDF, pasta da aula
//    ou subpasta material/). Sem nenhum dos três -> 'needs_text'
//    (NÃO é falha: não incrementa attempts; a R14B/front pode fornecer o
//    texto depois via POST /api/generation/supply-text). PDF binário puro
//    no servidor lê lixo (v80-FIX-WORKER BUG 6) — por isso não há fallback
//    de PDF aqui; a cadeia de IA (callUnifiedAi) é que tem fallbacks.
// 2) geração: O MESMO batalhão — battalionGenSummary (gancho garantido
//    dentro + re-aplicado aqui antes de gravar, como o merge faz) e, como
//    best-effort, Pills + Questions. Só o resumo é obrigatório.
// 3) destino: .gdi-resumos/ + D1/cache + partilhados (ver acima).
async function genqueueProcessLesson(job, actorUser){
  const lessonPath = job.lesson_path;
  const d1 = (typeof meggyD1Binding === 'function') ? meggyD1Binding() : null;
  if(!d1) throw new Error('D1 not bound');
  const lesson = await d1.prepare('SELECT lesson_path, lesson_name, course_path FROM lessons WHERE lesson_path = ? LIMIT 1').bind(lessonPath).first();
  if(!lesson) throw new Error('lesson not indexed (removed from lessons?)');
  if(await genqueueHasValidSummary(d1, lessonPath)) return { alreadyDone: true, source: 'existing' };
  let sourceText = String(job.source_text || '').slice(0, GENQUEUE_SOURCE_TEXT_MAX);
  let sourceKind = 'client';
  if(!sourceText || sourceText.trim().length < 50){
    const md = await genqueueFetchTranscriptionMd(lessonPath);
    if(md.ok && md.text){ sourceText = md.text; sourceKind = (md.source === 'converted-md') ? 'converted-md' : 'md'; }
    else{
      const err = new Error('needs_text: ' + (md.error || 'sem fonte de texto'));
      err.code = 'needs_text';
      err.detail = { mdError: md.error || null, files: md.files || [] };
      throw err;
    }
  }
  const gd0 = await genqueueEnsureDrive0();
  if(!gd0) throw new Error('no drive');
  let folderId = null;
  try{ folderId = await gdiUserFolderId(gd0); }catch(_){}
  const lessonName = String(lesson.lesson_name || lessonPath.split('/').filter(Boolean).pop() || 'aula').slice(0, 200);
  const courseKey = String(job.course_key || lesson.course_path || lessonName).slice(0, 200);
  const pdfName = String(lessonPath.split('/').filter(Boolean).pop() || 'aula').slice(0, 100);
  const keyPrefix = courseKey + '/' + pdfName;
  const gen = await battalionGenSummary(keyPrefix, lessonName, pdfName, sourceText, gd0, folderId);
  if(!gen || !gen.patch || !gen.patch.summary) throw new Error('generate_failed: resumo recusado ou IA sem resposta (todos os fallbacks tentados)');
  let summaryText = String(gen.patch.summary || '');
  if(!isIsaValidContent('summary', summaryText)) throw new Error('generate_failed: resumo inválido/recusado');
  summaryText = battalionEnsureSummaryHook(summaryText, lessonName, pdfName);
  let pillsOk = false;
  let questionsOk = false;
  let questions = null;
  try{
    const pills = await battalionGenPills(keyPrefix, lessonName, pdfName, sourceText, gd0, folderId);
    if(pills && pills.patch && pills.patch.mindmap) pillsOk = true;
  }catch(e){ console.warn('[GenQueue] pills failed (best-effort):', (e && e.message) || e); }
  try{
    const qs = await battalionGenQuestions(keyPrefix, lessonName, pdfName, sourceText, gd0, folderId, { lessonPath: lessonPath, coursePath: lesson.course_path });  // ★ v2.15.48: hint p/ classificação
    if(qs && qs.patch && qs.patch.questions){ questionsOk = true; questions = qs.patch.questions; }
  }catch(e){ console.warn('[GenQueue] questions failed (best-effort):', (e && e.message) || e); }
  const safeLesson = lessonName.replace(/[^a-zA-Z0-9_-]/g, '_').slice(0, 40);
  const fileName = safeLesson + '_' + Date.now() + '.md';
  const saved = await genqueueSaveSummaryToLessonFolder(lessonPath, fileName, summaryText, actorUser || job.requested_by || 'genqueue', keyPrefix, questions, lesson.course_path);
  return { ok: true, source: sourceKind, file: saved.file, driveSaved: saved.driveSaved, metaOk: saved.metaOk, sharedOk: saved.sharedOk, kvOk: saved.kvOk, pillsOk: pillsOk, questionsOk: questionsOk, keyPrefix: keyPrefix };
}

// ── RUNNER ───────────────────────────────────────────────────────────────
// Corre no cron horário (mesmo trigger "0 * * * *" do scanner, via
// ctx.waitUntil separado — NÃO mexe no handleCronBackfill) e no POST
// manual do admin. Uma invocação = no máximo batchPerRun aulas (piloto:
// 1), sequencial, com orçamento de parede (runBudgetMs) e pausa de 50 s
// entre aulas quando o lote > 1 (Pollinations: 1 resposta/45 s).
// Tetos (nunca esvaziar a geração interativa): dailyCap/dia (KV),
// pilotCap total enquanto pilot:true, pausa quando a cota CF 3036 morre
// (modelhealth:cf:* = quota:...) ou quando genqueue:pausedUntil é futuro.
// Cada aula custa 1 unidade do teto diário (não 1 por chamada de IA: o
// batalhão faz 3 chamadas por aula e a cascata decide o backend).
async function handleGenQueueRunner(opts){
  const startedAt = Date.now();
  const trigger = (opts && opts.trigger) || 'cron';
  const limitOverride = (opts && opts.limit) ? genqueueNum(opts.limit, 0, 1, GENQUEUE_MAX_BATCH_PER_RUN) : 0;
  const stats = { ok: true, trigger: trigger, startedAt: startedAt, claimed: 0, done: 0, failed: 0, needsText: 0, skipped: 0, reason: null, quotaPaused: false, pausedUntil: 0 };
  const finish = async function(){
    stats.finishedAt = Date.now();
    stats.ms = stats.finishedAt - startedAt;
    try{
      const kv = (typeof meggyKvBinding === 'function') ? meggyKvBinding() : null;
      if(kv) await kv.put('genqueue:run:last', JSON.stringify(stats), { expirationTtl: GENQUEUE_RUN_LAST_TTL_S });
    }catch(_){}
    return stats;
  };
  try{
    const d1 = (typeof meggyD1Binding === 'function') ? meggyD1Binding() : null;
    if(!d1){ stats.ok = false; stats.reason = 'D1 not bound'; return await finish(); }
    await d1EnsureSchema();
    const cfg = await genqueueLoadConfig();
    stats.config = { pilot: cfg.pilot, pilotCap: cfg.pilotCap, batchPerRun: cfg.batchPerRun, dailyCap: cfg.dailyCap };
    if(!cfg.enabled){ stats.ok = false; stats.reason = 'disabled'; return await finish(); }
    const kv = (typeof meggyKvBinding === 'function') ? meggyKvBinding() : null;
    if(kv){
      try{
        const pu = Number(await kv.get('genqueue:pausedUntil')) || 0;
        if(pu > Date.now()){ stats.reason = 'paused'; stats.pausedUntil = pu; return await finish(); }
      }catch(_){}
    }
    const quota = await genqueueCfQuotaPaused();
    if(quota.paused){ stats.ok = false; stats.reason = 'cf-quota-3036'; stats.quotaPaused = true; stats.pausedUntil = quota.until; return await finish(); }
    const dayKey = genqueueDayKey(startedAt);
    const dailyUsed = await genqueueKvInt(dayKey);
    if(dailyUsed >= cfg.dailyCap){ stats.reason = 'daily-cap'; stats.dailyUsed = dailyUsed; return await finish(); }
    let pilotDone = 0;
    if(cfg.pilot){
      pilotDone = await genqueueKvInt('genqueue:stats:completedTotal');
      if(pilotDone >= cfg.pilotCap){ stats.reason = 'pilot-cap'; stats.pilotCompleted = pilotDone; return await finish(); }
    }
    // O lote desta invocação NUNCA ultrapassa os tetos: o resto é o mínimo
    // entre o teto diário, o teto do piloto e o batchPerRun (o check do
    // início da run não bastava — 2 aulas reclamadas de uma vez com
    // dailyCap=1 fariam as 2).
    let batch = limitOverride || cfg.batchPerRun;
    batch = Math.min(batch, cfg.dailyCap - dailyUsed);
    if(cfg.pilot) batch = Math.min(batch, cfg.pilotCap - pilotDone);
    if(batch <= 0){ stats.reason = cfg.pilot ? 'pilot-cap' : 'daily-cap'; return await finish(); }
    const now = Date.now();
    let rows = [];
    try{
      const r = await d1.prepare("SELECT lesson_path, course_key, video_path, source, requested_by, priority, status, attempts, source_text FROM generation_queue WHERE status = 'queued' AND next_retry_at <= ? ORDER BY priority ASC, created_at ASC LIMIT ?").bind(now, batch).all();
      rows = (r && r.results) || [];
    }catch(e){ stats.ok = false; stats.reason = 'claim select failed: ' + (e && e.message); return await finish(); }
    for(let i = 0; i < rows.length; i++){
      if(Date.now() - startedAt > cfg.runBudgetMs){ stats.reason = 'run-budget'; break; }
      if(i > 0 && cfg.sleepBetweenMs > 0) await genqueueSleep(cfg.sleepBetweenMs);
      const job = rows[i];
      const claimed = await genqueueClaimJob(d1, job.lesson_path, Date.now());
      if(!claimed){ stats.skipped++; continue; }
      stats.claimed++;
      try{
        const res = await genqueueProcessLesson(job, job.requested_by || 'genqueue');
        if(res && res.alreadyDone){
          await genqueueSetJob(d1, job.lesson_path, { status: 'done', lastError: null, result: JSON.stringify({ alreadyDone: true }) });
          stats.done++;
          continue;
        }
        await genqueueSetJob(d1, job.lesson_path, { status: 'done', lastError: null, result: JSON.stringify(res) });
        stats.done++;
        await genqueueKvIncr(dayKey, GENQUEUE_DAY_TTL_S);
        await genqueueKvIncr('genqueue:stats:completedTotal', 0);
      }catch(e){
        const code = (e && e.code) || '';
        if(code === 'needs_text'){
          await genqueueSetJob(d1, job.lesson_path, { status: 'needs_text', lastError: String((e && e.message) || e).slice(0, 500) });
          stats.needsText++;
          continue;
        }
        const attempts = (Number(job.attempts) || 0) + 1;
        const msg = String((e && e.message) || e).slice(0, 500);
        if(typeof cfQuotaError === 'function' && cfQuotaError(e)){
          try{ if(kv) await kv.put('genqueue:pausedUntil', String(Date.now() + secondsToMidnightUTC() * 1000), { expirationTtl: 86400 }); }catch(_){}
          stats.quotaPaused = true;
        }
        if(attempts >= cfg.maxAttempts){
          await genqueueSetJob(d1, job.lesson_path, { status: 'failed', attempts: attempts, lastError: msg });
          stats.failed++;
        }else{
          await genqueueSetJob(d1, job.lesson_path, { status: 'queued', attempts: attempts, nextRetryAt: Date.now() + genqueueBackoffMs(attempts), lastError: msg });
          stats.retried = (stats.retried || 0) + 1;
        }
        if(stats.quotaPaused) break;
      }
    }
    if(!rows.length) stats.reason = 'empty-queue';
    return await finish();
  }catch(e){
    stats.ok = false;
    stats.reason = 'runner error: ' + String((e && e.message) || e).slice(0, 200);
    try{ return await finish(); }catch(_){ return stats; }
  }
}

// ★ v2.15.69 (gerador CLI por API): autenticação MÁQUINA dos endpoints
//   de geração — sessão (comportamento de sempre, intacto) OU Bearer
//   <redacted> scope generation-* do PRÓPRIO endpoint (o mesmo registo
//   KV dos tokens de scanner; ver scanBearerAuth). Nos endpoints
//   só-admin, o scope substitui o ADMIN_USERS apenas nesse endpoint.
//   As acções por token actuam como 'gerador-cli' (requested_by).
const GEN_CLI_USER = 'gerador-cli';
async function genSessionOrToken(request, scopeName){
  const user = await gdiSessionUser(request);
  if(user) return { user: user, viaToken: false };
  const bt = await scanBearerAuth(request);
  if(bt && bt.scope && bt.scope.indexOf(scopeName) >= 0) return { user: GEN_CLI_USER, viaToken: true };
  return null;
}

// ── ENDPOINTS ────────────────────────────────────────────────────────────
// POST /api/generation/enqueue {lessonPath, videoPath?, courseKey?,
//   source?:"play"|"queue"|"chat", materialText?}
//   Sessão do aluno (gdiSessionUser). Idempotente; enfileirar NÃO gera.
//   -> {ok, status:"queued"|"exists"|"running"|"done", lessonPath,
//       priority, jobStatus, attempts, courseKey, source}
//   Mapeamento: aula nova -> "queued"; já queued -> "exists"; a correr ->
//   "running"; resumo válido -> "done". needs_text/failed devolvem
//   "exists" com jobStatus a dizer o estado real (failed re-enfileira e
//   devolve "queued"). O contrato de status do brief é respeitado à risca.
async function handleGenEnqueue(request){
  const cors = { 'Access-Control-Allow-Origin': '*', 'Content-Type': 'application/json;charset=UTF-8' };
  const _gauth = await genSessionOrToken(request, 'generation-enqueue');
  if(!_gauth) return new Response(JSON.stringify({ ok: false, error: 'auth' }), { status: 401, headers: cors });
  const user = _gauth.user;
  let body;
  try{ body = await request.json(); }catch(_){ return new Response(JSON.stringify({ ok: false, error: 'invalid json' }), { status: 400, headers: cors }); }
  const lessonPath = String((body && body.lessonPath) || '').slice(0, 1000);
  const videoPath = String((body && body.videoPath) || '').slice(0, 1000);
  const courseKey = String((body && body.courseKey) || '').slice(0, 500);
  const source = String((body && body.source) || 'queue').slice(0, 20);
  const materialText = String((body && body.materialText) || '').slice(0, GENQUEUE_SOURCE_TEXT_MAX);
  if(!lessonPath) return new Response(JSON.stringify({ ok: false, error: 'missing lessonPath' }), { status: 400, headers: cors });
  if(!GENQUEUE_SOURCES.includes(source)) return new Response(JSON.stringify({ ok: false, error: 'invalid source' }), { status: 400, headers: cors });
  const parsed = (typeof parseCoursePath === 'function') ? parseCoursePath(lessonPath) : null;
  if(!parsed || parsed.driveIndex < 0 || parsed.driveIndex >= gds.length){
    return new Response(JSON.stringify({ ok: false, error: 'invalid lessonPath: drive index out of range' }), { status: 400, headers: cors });
  }
  const d1 = (typeof meggyD1Binding === 'function') ? meggyD1Binding() : null;
  if(!d1) return new Response(JSON.stringify({ ok: false, error: 'D1 not bound' }), { status: 503, headers: cors });
  if((typeof meggyD1Backend === 'function') && meggyD1Backend() === 'off'){
    return new Response(JSON.stringify({ ok: false, error: 'D1 not enabled' }), { status: 503, headers: cors });
  }
  try{ await d1EnsureSchema(); }catch(e){ return new Response(JSON.stringify({ ok: false, error: 'schema init failed: ' + (e && e.message) }), { status: 503, headers: cors }); }
  const now = Date.now();
  const lesson = await d1.prepare('SELECT lesson_path, lesson_name, course_path FROM lessons WHERE lesson_path = ? LIMIT 1').bind(lessonPath).first();
  if(!lesson) return new Response(JSON.stringify({ ok: false, error: 'lesson not indexed' }), { status: 404, headers: cors });
  if(await genqueueHasValidSummary(d1, lessonPath)){
    return new Response(JSON.stringify({ ok: true, status: 'done', lessonPath: lessonPath, priority: null, jobStatus: 'done', attempts: 0, courseKey: courseKey || lesson.course_path, source: source }), { headers: cors });
  }
  const existing = await d1.prepare('SELECT lesson_path, priority, status, attempts FROM generation_queue WHERE lesson_path = ? LIMIT 1').bind(lessonPath).first();
  const effCourseKey = courseKey || lesson.course_path || '';
  if(existing){
    const st = existing.status;
    if(st === 'queued' || st === 'needs_text'){
      return new Response(JSON.stringify({ ok: true, status: 'exists', lessonPath: lessonPath, priority: existing.priority, jobStatus: st, attempts: existing.attempts || 0, courseKey: effCourseKey, source: source }), { headers: cors });
    }
    if(st === 'running'){
      return new Response(JSON.stringify({ ok: true, status: 'running', lessonPath: lessonPath, priority: existing.priority, jobStatus: 'running', attempts: existing.attempts || 0, courseKey: effCourseKey, source: source }), { headers: cors });
    }
    if(st === 'done'){
      return new Response(JSON.stringify({ ok: true, status: 'done', lessonPath: lessonPath, priority: existing.priority, jobStatus: 'done', attempts: existing.attempts || 0, courseKey: effCourseKey, source: source }), { headers: cors });
    }
    const prio = await genqueueComputePriority(d1, lessonPath, lesson.course_path);
    await d1.prepare("UPDATE generation_queue SET status = 'queued', priority = ?, next_retry_at = 0, updated_at = ? WHERE lesson_path = ?").bind(prio, now, lessonPath).run();
    return new Response(JSON.stringify({ ok: true, status: 'queued', lessonPath: lessonPath, priority: prio, jobStatus: 'queued', attempts: existing.attempts || 0, courseKey: effCourseKey, source: source }), { headers: cors });
  }
  const prio = await genqueueComputePriority(d1, lessonPath, lesson.course_path);
  await d1.prepare('INSERT INTO generation_queue (lesson_path, course_key, video_path, source, requested_by, priority, status, attempts, next_retry_at, last_error, source_text, result, created_at, updated_at) VALUES (?,?,?,?,?,?,?,0,0,NULL,?,NULL,?,?)').bind(lessonPath, effCourseKey, videoPath || null, source, user, prio, 'queued', materialText || null, now, now).run();
  return new Response(JSON.stringify({ ok: true, status: 'queued', lessonPath: lessonPath, priority: prio, jobStatus: 'queued', attempts: 0, courseKey: effCourseKey, source: source }), { headers: cors });
}

// POST /api/generation/supply-text {lessonPath, materialText}
//   Aluno fornece o texto extraído no cliente (pdf.js, PASSO 2B) p/ um
//   job em needs_text/queued/failed. Sem isto, PDFs sem transcrição MD
//   ficam em needs_text para sempre (o worker não extrai PDFs).
async function handleGenSupplyText(request){
  const cors = { 'Access-Control-Allow-Origin': '*', 'Content-Type': 'application/json;charset=UTF-8' };
  const user = await gdiSessionUser(request);
  if(!user) return new Response(JSON.stringify({ ok: false, error: 'auth' }), { status: 401, headers: cors });
  let body;
  try{ body = await request.json(); }catch(_){ return new Response(JSON.stringify({ ok: false, error: 'invalid json' }), { status: 400, headers: cors }); }
  const lessonPath = String((body && body.lessonPath) || '').slice(0, 1000);
  const materialText = String((body && body.materialText) || '').slice(0, GENQUEUE_SOURCE_TEXT_MAX);
  if(!lessonPath || materialText.trim().length < 50) return new Response(JSON.stringify({ ok: false, error: 'missing lessonPath or materialText (<50 chars)' }), { status: 400, headers: cors });
  const d1 = (typeof meggyD1Binding === 'function') ? meggyD1Binding() : null;
  if(!d1) return new Response(JSON.stringify({ ok: false, error: 'D1 not bound' }), { status: 503, headers: cors });
  try{ await d1EnsureSchema(); }catch(e){ return new Response(JSON.stringify({ ok: false, error: 'schema init failed' }), { status: 503, headers: cors }); }
  const row = await d1.prepare('SELECT status FROM generation_queue WHERE lesson_path = ? LIMIT 1').bind(lessonPath).first();
  if(!row) return new Response(JSON.stringify({ ok: false, error: 'job not found (enqueue first)' }), { status: 404, headers: cors });
  if(row.status === 'done') return new Response(JSON.stringify({ ok: true, status: 'done', jobStatus: 'done' }), { headers: cors });
  if(row.status === 'running') return new Response(JSON.stringify({ ok: true, status: 'running', jobStatus: 'running' }), { headers: cors });
  await genqueueSetJob(d1, lessonPath, { status: 'queued', nextRetryAt: 0, sourceText: materialText, lastError: null });
  return new Response(JSON.stringify({ ok: true, status: 'queued', jobStatus: 'queued' }), { headers: cors });
}

// GET /api/generation/queue?status=&limit= — só admin. source_text NÃO
// sai na lista (15 KB por linha); hasText diz se existe.
async function handleGenQueueGet(request, url){
  const cors = { 'Access-Control-Allow-Origin': '*', 'Content-Type': 'application/json;charset=UTF-8' };
  const _gauth = await genSessionOrToken(request, 'generation-queue');
  if(!_gauth) return new Response(JSON.stringify({ ok: false, error: 'auth' }), { status: 401, headers: cors });
  const user = _gauth.user;
  if(!_gauth.viaToken && !ADMIN_USERS.includes(user)) return new Response(JSON.stringify({ ok: false, error: 'forbidden: admin only' }), { status: 403, headers: cors });
  const d1 = (typeof meggyD1Binding === 'function') ? meggyD1Binding() : null;
  if(!d1) return new Response(JSON.stringify({ ok: false, error: 'D1 not bound' }), { status: 503, headers: cors });
  let _schemaFailed=false; try{ await d1EnsureSchema(); }catch(e){ _schemaFailed=true; }
  const status = String((url && url.searchParams.get('status')) || '');
  const limit = genqueueNum(url && url.searchParams.get('limit'), 100, 1, 500);
  let jobs = [];
  let _fbJobs = false;
  try{
    await d1ThrowIfStamped21561();
    if(status && GENQUEUE_STATUSES.includes(status)){
      const r = await d1.prepare('SELECT lesson_path, course_key, video_path, source, requested_by, priority, status, attempts, next_retry_at, last_error, (CASE WHEN source_text IS NOT NULL AND length(source_text) > 0 THEN 1 ELSE 0 END) AS hasText, result, created_at, updated_at FROM generation_queue WHERE status = ? ORDER BY priority ASC, created_at ASC LIMIT ?').bind(status, limit).all();
      jobs = (r && r.results) || [];
    }else{
      const r = await d1.prepare('SELECT lesson_path, course_key, video_path, source, requested_by, priority, status, attempts, next_retry_at, last_error, (CASE WHEN source_text IS NOT NULL AND length(source_text) > 0 THEN 1 ELSE 0 END) AS hasText, result, created_at, updated_at FROM generation_queue ORDER BY priority ASC, created_at ASC LIMIT ?').bind(limit).all();
      jobs = (r && r.results) || [];
    }
  }catch(_qe){
    const _snap=await loadTableSnapshot('generation_queue');
    if(!_snap) throw _qe;
    _fbJobs = true;
    let _rows=_snap.slice();
    if(status && GENQUEUE_STATUSES.includes(status)) _rows=_rows.filter(function(r){return r.status===status;});
    _rows.sort(function(a,b){ return ((a.priority||0)-(b.priority||0)) || ((a.created_at||0)-(b.created_at||0)); });
    jobs=_rows.slice(0,limit).map(function(r){ return {lesson_path:r.lesson_path, course_key:r.course_key, video_path:r.video_path, source:r.source, requested_by:r.requested_by, priority:r.priority, status:r.status, attempts:r.attempts, next_retry_at:r.next_retry_at, last_error:r.last_error, hasText:(r.source_text!=null && String(r.source_text).length>0)?1:0, result:r.result, created_at:r.created_at, updated_at:r.updated_at}; });
  }
  try{ if(typeof fbMergeTableRows==='function'){ const _pend=await fbJournalOpsForTable('generation_queue'); if(_pend.length){ const _all=await loadTableSnapshot('generation_queue'); if(_all){ let _ar=_all.slice(); if(status && GENQUEUE_STATUSES.includes(status)) _ar=_ar.filter(function(r){return r.status===status;}); _ar.sort(function(a,b){ return ((a.priority||0)-(b.priority||0)) || ((a.created_at||0)-(b.created_at||0)); }); jobs=_ar.slice(0,limit).map(function(r){ return {lesson_path:r.lesson_path, course_key:r.course_key, video_path:r.video_path, source:r.source, requested_by:r.requested_by, priority:r.priority, status:r.status, attempts:r.attempts, next_retry_at:r.next_retry_at, last_error:r.last_error, hasText:(r.source_text!=null && String(r.source_text).length>0)?1:0, result:r.result, created_at:r.created_at, updated_at:r.updated_at}; }); _fbJobs=true; } } } }catch(_){}
  const counts = {};
  let _fbCounts = false;
  try{
    await d1ThrowIfStamped21561();
    const r = await d1.prepare('SELECT status, COUNT(*) AS n FROM generation_queue GROUP BY status').all();
    for(const row of ((r && r.results) || [])) counts[row.status] = Number(row.n) || 0;
  }catch(_){ const _snap=await loadTableSnapshot('generation_queue'); if(_snap){ _fbCounts = true; for(const row of _snap) counts[row.status] = (counts[row.status] || 0) + 1; } }
  try{ if(_fbJobs){ const _snap2=await loadTableSnapshot('generation_queue'); if(_snap2){ for(const k2 of Object.keys(counts)) delete counts[k2]; for(const row of _snap2) counts[row.status]=(counts[row.status]||0)+1; _fbCounts=true; } } }catch(_){}
  return new Response(JSON.stringify(Object.assign({ ok: true, jobs: jobs, counts: counts }, (_fbJobs || _fbCounts || _schemaFailed) ? { fallback: true } : {})), { headers: cors });
}

// GET /api/generation/status — só admin. Estado da fila + tetos + última run.
async function handleGenStatusGet(request){
  const cors = { 'Access-Control-Allow-Origin': '*', 'Content-Type': 'application/json;charset=UTF-8' };
  const _gauth = await genSessionOrToken(request, 'generation-status');
  if(!_gauth) return new Response(JSON.stringify({ ok: false, error: 'auth' }), { status: 401, headers: cors });
  const user = _gauth.user;
  if(!_gauth.viaToken && !ADMIN_USERS.includes(user)) return new Response(JSON.stringify({ ok: false, error: 'forbidden: admin only' }), { status: 403, headers: cors });
  const d1 = (typeof meggyD1Binding === 'function') ? meggyD1Binding() : null;
  const cfg = await genqueueLoadConfig();
  const counts = {};
  let _fbGenStatus = false;
  if(d1){
    try{ await d1EnsureSchema(); }catch(_){}
    try{
      await d1ThrowIfStamped21561();
      const r = await d1.prepare('SELECT status, COUNT(*) AS n FROM generation_queue GROUP BY status').all();
      for(const row of ((r && r.results) || [])) counts[row.status] = Number(row.n) || 0;
    }catch(_){ const _snap=await loadTableSnapshot('generation_queue'); if(_snap){ _fbGenStatus = true; for(const row of _snap) counts[row.status] = (counts[row.status] || 0) + 1; } }
  }
  const quota = await genqueueCfQuotaPaused();
  const dailyUsed = await genqueueKvInt(genqueueDayKey(Date.now()));
  const pilotCompleted = await genqueueKvInt('genqueue:stats:completedTotal');
  let lastRun = null;
  let pausedUntil = 0;
  try{
    const kv = (typeof meggyKvBinding === 'function') ? meggyKvBinding() : null;
    if(kv){
      const raw = await kv.get('genqueue:run:last');
      if(raw) lastRun = JSON.parse(raw);
      pausedUntil = Number(await kv.get('genqueue:pausedUntil')) || 0;
    }
  }catch(_){}
  return new Response(JSON.stringify({ ok: true, fallback: _fbGenStatus ? true : undefined, version: GENQUEUE_VERSION, config: cfg, counts: counts, dailyUsed: dailyUsed, dailyCap: cfg.dailyCap, pilotCompleted: pilotCompleted, pilotCap: cfg.pilotCap, cfQuotaPaused: quota.paused, cfQuotaUntil: quota.until, pausedUntil: pausedUntil, lastRun: lastRun }), { headers: cors });
}

// POST /api/generation/config {enabled?, pilot?, pilotCap?, batchPerRun?,
//   dailyCap?, maxAttempts?, runBudgetMs?, sleepBetweenMs?} — só admin.
//   É AQUI que o piloto expande: pilot:false + dailyCap/batchPerRun maiores.
//   batchPerRun tem teto de código (5); passar disso exige mudança de
//   código + prova ao vivo (limites de CPU/subrequests do Worker).
async function handleGenConfigPost(request){
  const cors = { 'Access-Control-Allow-Origin': '*', 'Content-Type': 'application/json;charset=UTF-8' };
  const _gauth = await genSessionOrToken(request, 'generation-config');
  if(!_gauth) return new Response(JSON.stringify({ ok: false, error: 'auth' }), { status: 401, headers: cors });
  const user = _gauth.user;
  if(!_gauth.viaToken && !ADMIN_USERS.includes(user)) return new Response(JSON.stringify({ ok: false, error: 'forbidden: admin only' }), { status: 403, headers: cors });
  let body;
  try{ body = await request.json(); }catch(_){ return new Response(JSON.stringify({ ok: false, error: 'invalid json' }), { status: 400, headers: cors }); }
  const cfg = await genqueueLoadConfig();
  if(body && typeof body.enabled === 'boolean') cfg.enabled = body.enabled;
  if(body && typeof body.pilot === 'boolean') cfg.pilot = body.pilot;
  if(body) cfg.pilotCap = genqueueNum(body.pilotCap, cfg.pilotCap, 0, 1000);
  if(body) cfg.batchPerRun = genqueueNum(body.batchPerRun, cfg.batchPerRun, 1, GENQUEUE_MAX_BATCH_PER_RUN);
  if(body) cfg.dailyCap = genqueueNum(body.dailyCap, cfg.dailyCap, 0, 100);
  if(body) cfg.maxAttempts = genqueueNum(body.maxAttempts, cfg.maxAttempts, 1, 5);
  if(body) cfg.runBudgetMs = genqueueNum(body.runBudgetMs, cfg.runBudgetMs, 5000, 120000);
  if(body) cfg.sleepBetweenMs = genqueueNum(body.sleepBetweenMs, cfg.sleepBetweenMs, 0, 120000);
  const ok = await genqueueSaveConfig(cfg);
  return new Response(JSON.stringify({ ok: ok, config: cfg }), { status: ok ? 200 : 503, headers: cors });
}

// POST /api/generation/reprioritize — só admin. Recalcula a prioridade
// de todas as linhas queued (destaques/vistas/planos mudam com o tempo;
// o claim usa o valor guardado, por isso o refresh é explícito).
async function handleGenReprioritizePost(request){
  const cors = { 'Access-Control-Allow-Origin': '*', 'Content-Type': 'application/json;charset=UTF-8' };
  const user = await gdiSessionUser(request);
  if(!user) return new Response(JSON.stringify({ ok: false, error: 'auth' }), { status: 401, headers: cors });
  if(!ADMIN_USERS.includes(user)) return new Response(JSON.stringify({ ok: false, error: 'forbidden: admin only' }), { status: 403, headers: cors });
  const d1 = (typeof meggyD1Binding === 'function') ? meggyD1Binding() : null;
  if(!d1) return new Response(JSON.stringify({ ok: false, error: 'D1 not bound' }), { status: 503, headers: cors });
  try{ await d1EnsureSchema(); }catch(e){ return new Response(JSON.stringify({ ok: false, error: 'schema init failed' }), { status: 503, headers: cors }); }
  let updated = 0;
  let _fbR = false;
  try{
    // ★ v2.15.61 (Fase 3.3): fila lida do snapshot e updates
    //   journalados com o D1 morto; a leitura da aula degrada
    //   para o course_key da própria linha (nunca derruba o lote).
    const _stR = { on: await d1QuotaDeadShared21560(), ops: [] };
    const rows = (await fb61ReadAll(_stR, d1, "SELECT lesson_path, course_key FROM generation_queue WHERE status = 'queued' LIMIT 500", [], 'generation_queue', function(r){ return r.status === 'queued'; })).slice(0, 500);
    for(const row of rows){
      let lesson = null;
      try{ lesson = await d1.prepare('SELECT course_path FROM lessons WHERE lesson_path = ? LIMIT 1').bind(row.lesson_path).first(); }catch(_){}
      const prio = await genqueueComputePriority(d1, row.lesson_path, (lesson && lesson.course_path) || row.course_key || '');
      const _nowR = Date.now();
      await fb61Write(_stR, function(){ return d1.prepare('UPDATE generation_queue SET priority = ?, updated_at = ? WHERE lesson_path = ?').bind(prio, _nowR, row.lesson_path).run(); }, { id: fbOpId(), ts: _nowR, table: 'generation_queue', action: 'update', key: { lesson_path: row.lesson_path }, row: { priority: prio, updated_at: _nowR } });
      updated++;
    }
    if(_stR.ops.length && !(await fb61Flush(_stR))) return new Response(JSON.stringify({ ok: false, error: D1_QUOTA_MSG_21561 }), { status: 503, headers: cors });
    _fbR = _stR.on;
  }catch(e){ return new Response(JSON.stringify({ ok: false, error: fbErrorText21561(e) }), { status: 500, headers: cors }); }
  return new Response(JSON.stringify({ ok: true, updated: updated, fallback: _fbR ? true : undefined }), { headers: cors });
}

// POST /api/generation/run {limit?, wait?} — só admin. Disparo manual do
// runner (piloto sem esperar pelo cron). Por omissão responde já
// ({started:true}, via waitUntil, como o batalhão); com wait:true aguarda
// o fim e devolve as stats (pode demorar minutos — 1 aula ≈ 6 min).
async function handleGenRunPost(request, event){
  const cors = { 'Access-Control-Allow-Origin': '*', 'Content-Type': 'application/json;charset=UTF-8' };
  const _gauth = await genSessionOrToken(request, 'generation-run');
  if(!_gauth) return new Response(JSON.stringify({ ok: false, error: 'auth' }), { status: 401, headers: cors });
  const user = _gauth.user;
  if(!_gauth.viaToken && !ADMIN_USERS.includes(user)) return new Response(JSON.stringify({ ok: false, error: 'forbidden: admin only' }), { status: 403, headers: cors });
  let body = {};
  try{ body = await request.json(); }catch(_){ body = {}; }
  const limit = genqueueNum(body && body.limit, 0, 1, GENQUEUE_MAX_BATCH_PER_RUN);
  const wait = !!(body && body.wait);
  if(wait){
    const stats = await handleGenQueueRunner({ trigger: 'manual', limit: limit || undefined });
    return new Response(JSON.stringify({ ok: true, stats: stats }), { headers: cors });
  }
  if(event && event.waitUntil) event.waitUntil(handleGenQueueRunner({ trigger: 'manual', limit: limit || undefined }));
  else await handleGenQueueRunner({ trigger: 'manual', limit: limit || undefined });
  return new Response(JSON.stringify({ ok: true, started: true }), { headers: cors });
}

// Cron handler: scheduled() → handleCronBackfill() via ctx.waitUntil()
// ═══════════════════════════════════════════════════════════════

// ★ OPÇÃO A: Trigger manual do cron backfill (para testar sem esperar 6h)
async function handleCronBackfillManual(request){
  const cors = {'Content-Type':'application/json;charset=UTF-8','Access-Control-Allow-Origin':'*'};
  const user = await gdiSessionUser(request);
  if(!user) return new Response(JSON.stringify({ok:false,error:'auth'}),{status:401,headers:cors});
  console.log('[Cron Backfill] trigger manual por usuário:', user);
  try{
    const stats = await handleCronBackfill();
    return new Response(JSON.stringify({ok:true, stats}),{headers:cors});
  }catch(e){
    return new Response(JSON.stringify({ok:false,error:e.message}),{status:500,headers:cors});
  }
}

// ★ OPÇÃO A: Ver progresso do cron backfill (lê do KV MEGGY_CACHE:cron-backfill:progress)
async function handleCronProgressGet(request){
  const cors = {'Content-Type':'application/json;charset=UTF-8','Access-Control-Allow-Origin':'*'};
  const user = await gdiSessionUser(request);
  if(!user) return new Response(JSON.stringify({ok:false,error:'auth'}),{status:401,headers:cors});
  const kv = meggyKvBinding();
  if(!kv) return new Response(JSON.stringify({ok:false,error:'KV not bound'}),{status:503,headers:cors});
  try{
    const raw = await kv.get('cron-backfill:progress');
    const progress = raw ? JSON.parse(raw) : null;
    // ★ v2.14.9: destaques/cursos que são RAIZ de drive — nunca entram na fila
    //   de scan (escanear '/0:/' é escanear o drive inteiro). Lista para o admin
    //   corrigir ou remover; as linhas NÃO são apagadas aqui.
    let rootPaths = [];
    try {
      const _isRoot = (typeof isDriveRootCoursePath === 'function') ? isDriveRootCoursePath : (p) => /^\/\d+:\/?$/.test(String(p || '').trim());
      let _ucPaths = null, _featRows = null;
      const d1 = meggyD1Binding();
      if (d1) {
        try { const r1 = await d1.prepare('SELECT DISTINCT course_path FROM user_courses').all(); _ucPaths = Array.from(new Set((r1.results || []).map(x => x.course_path))); } catch (_) {}
        try { const r2 = await d1.prepare('SELECT course_path, course_name FROM featured_courses').all(); _featRows = r2.results || []; } catch (_) {}
      }
      if (!_ucPaths) { const _s = await loadTableSnapshot('user_courses'); if (_s) _ucPaths = Array.from(new Set(_s.map(x => x.course_path))); }
      if (!_featRows) { const _s = await loadTableSnapshot('featured_courses'); if (_s) _featRows = _s; }
      for (const cp of (_ucPaths || [])) if (cp && _isRoot(cp)) rootPaths.push({ coursePath: cp, source: 'user_courses' });
      for (const row of (_featRows || [])) if (row.course_path && _isRoot(row.course_path)) rootPaths.push({ coursePath: row.course_path, source: 'featured', courseName: row.course_name || '' });
    } catch (_) {}
    // ★ v2.15.6 (P1): a QUARENTENA do admin — os cursos em 'error' com
    //   diagnóstico (qual curso, qual erro, quantas tentativas, quando
    //   volta). Sem isto o admin era cego: a aba já renderizava
    //   lastCourse/lastError, mas handleCronBackfill nunca os definia.
    let quarantined = [];
    try {
      const d1q = meggyD1Binding();
      if (d1q) {
        let rows = null;
        let hasCols = false;
        try {
          const qr = await d1q.prepare(`SELECT course_path, status, updated_at, last_error, fail_count FROM scan_status WHERE status='error' ORDER BY updated_at DESC LIMIT 50`).all();
          rows = qr.results || []; hasCols = true;
        } catch (_) {}
        if (!rows) {
          const qr = await d1q.prepare(`SELECT course_path, status, updated_at FROM scan_status WHERE status='error' ORDER BY updated_at DESC LIMIT 50`).all();
          rows = qr.results || [];
        }
        quarantined = rows.map(row => {
          const fc = hasCols ? Math.max(1, Number(row.fail_count) || 1) : 1;
          const at = Number(row.updated_at) || 0;
          return { coursePath: row.course_path, updated_at: at, last_error: hasCols ? (row.last_error || null) : null, fail_count: fc, nextRetryAt: at > 0 && fc < 3 ? at + scanQuarantineBackoffMs(fc) : null };
        });
      }
    } catch (e) { console.warn('[Cron Progress] quarantined failed:', e && e.message); quarantined = [];
      const _s = await loadTableSnapshot('scan_status');
      if (_s) quarantined = _s.filter(row => row.status === 'error').sort((a, b) => (b.updated_at || 0) - (a.updated_at || 0)).slice(0, 50).map(row => { const fc = Math.max(1, Number(row.fail_count) || 1); const at = Number(row.updated_at) || 0; return { coursePath: row.course_path, updated_at: at, last_error: row.last_error || null, fail_count: fc, nextRetryAt: at > 0 && fc < 3 ? at + scanQuarantineBackoffMs(fc) : null }; });
    }
    // ★ v2.15.7 (P1): BLOCKED — o que o admin precisa VER p/ agir: mortos
    //   (error/not_found/empty com diagnóstico) + itens da fila TRAVADOS
    //   (cycles>=10, o 'incomplete' que nunca ganha scan_status). O
    //   `quarantined` antigo (só 'error') é mantido p/ compatibilidade.
    let blocked = [];
    // ★ v2.15.10-A1: 'cycling' (em progresso, com scanProgress) NÃO é
    //   bloqueado — vai p/ o array próprio `cycling[]`, visível na aba
    //   Scanner numa seção à parte. Antes os dois kinds iam p/ o mesmo
    //   blocked[] e a tabela contava 3 enquanto o banner (blockedCount,
    //   que já excluía 'cycling') marcava 2 — Passo 14.
    let cycling = [];
    try {
      const d1b = meggyD1Binding();
      if (d1b) {
        let rows = null;
        let hasColsB = false;
        try {
          // ★ v2.15.7 (P1, fix S3.10): sem filtro de status — a linha
          //   'done' também entra no mapa (p/ a lápide não duplicar
          //   um curso que completou); só mortos entram em blocked[].
          const qr = await d1b.prepare(`SELECT course_path, status, updated_at, last_error, fail_count FROM scan_status ORDER BY updated_at DESC LIMIT 100`).all();
          rows = qr.results || []; hasColsB = true;
        } catch (_) {}
        if (!rows) {
          const qr = await d1b.prepare(`SELECT course_path, status, updated_at FROM scan_status ORDER BY updated_at DESC LIMIT 100`).all();
          rows = qr.results || [];
        }
        const byKeyB = new Map();
        for (const row of rows) {
          const fc = hasColsB ? Math.max(0, Number(row.fail_count) || 0) : 0;
          const at = Number(row.updated_at) || 0;
          const b = { coursePath: row.course_path, kind: row.status === 'error' ? 'error' : (row.status === 'not_found' ? 'not_found' : 'empty'), status: row.status, updated_at: at, last_error: hasColsB ? (row.last_error || null) : null, fail_count: fc, nextRetryAt: (row.status === 'error' && at > 0 && fc < 3) ? at + scanQuarantineBackoffMs(fc) : null, attempts: fc, retries: 0, cycles: 0, inQueue: false };
          byKeyB.set(typeof normCanonPath === 'function' ? normCanonPath(row.course_path) : row.course_path, b);
          if (row.status === 'error' || row.status === 'not_found' || row.status === 'empty') blocked.push(b);
        }
        // ★ v2.15.7 (P1, fix S3.10): lápides KV sem linha D1 (a escrita
        //   D1 falhou) também aparecem em blocked[] — senão a quarentena
        //   fail-closed seria invisível no admin. Só enquanto a lápide
        //   estiver viva (mesma regra do deadSet: backoff p/ fc<3).
        try {
          const kvB = (typeof meggyKvBinding === 'function') ? meggyKvBinding() : null;
          if (kvB) {
            const rawB = await kvB.get(SCAN_DEAD_KV_KEY);
            const listB = rawB ? JSON.parse(rawB) : null;
            if (Array.isArray(listB)) {
              const nowB = Date.now();
              for (const x of listB) {
                if (!x || !x.coursePath) continue;
                const keyB = typeof normCanonPath === 'function' ? normCanonPath(x.coursePath) : x.coursePath;
                if (!keyB || byKeyB.has(keyB)) continue;
                const stB = x.status || 'error';
                const fcB = Math.max(1, Number(x.failCount) || 1);
                const atB = Number(x.at) || 0;
                const aliveB = (stB === 'not_found' || stB === 'empty') || fcB >= 3 || atB <= 0 || nowB < atB + scanQuarantineBackoffMs(fcB);
                if (!aliveB) continue;
                blocked.push({ coursePath: x.coursePath, kind: stB === 'error' ? 'error' : (stB === 'not_found' ? 'not_found' : 'empty'), status: stB, updated_at: atB, last_error: x.lastError || null, fail_count: fcB, nextRetryAt: (stB === 'error' && atB > 0 && fcB < 3) ? atB + scanQuarantineBackoffMs(fcB) : null, attempts: fcB, retries: 0, cycles: 0, inQueue: false, tombstone: true });
              }
            }
          }
        } catch (_) {}
        if (progress && Array.isArray(progress.queue)) {
          for (const it of progress.queue) {
            if (!it || !it.coursePath) continue;
            const key = typeof normCanonPath === 'function' ? normCanonPath(it.coursePath) : it.coursePath;
            const cycles = Number(it.cycles) || 0;
            const ex = byKeyB.get(key);
            if (ex) { ex.inQueue = true; ex.retries = Number(it.retries) || 0; ex.cycles = cycles; ex.attempts = (Number(it.retries) || 0) + cycles; if (!ex.last_error && it.lastError) ex.last_error = it.lastError; if (it.scanProgress) ex.progress = it.scanProgress; if (it.stagnantCycles) ex.stagnantCycles = it.stagnantCycles; continue; }
            if (cycles >= SCAN_STUCK_CYCLES) {
              // ★ v2.15.8 (A): um item que PROGRIDE não é "travado" — 'cycling'
              //   (visível, com o progresso real); 'stuck' é só o estagnado
              //   (sem progresso em ≥2 ciclos) ou o item legado sem dados de
              //   progresso (pré-v2.15.8 — preserva o contrato da v2.15.7).
              //   A quarentena por estagnação (3 ciclos) tira o item da fila
              //   com o motivo real; o 'cycling' drena sozinho.
              const stagnant = Number(it.stagnantCycles) || 0;
              const hasProgress = !!(it.scanProgress && typeof it.scanProgress === 'object');
              const kind = (stagnant >= 2 || !hasProgress) ? 'stuck' : 'cycling';
              const _entry = { coursePath: it.coursePath, kind, status: 'in_queue', updated_at: Number(it.lastAttemptAt) || progress.lastRun || 0, last_error: it.lastError || progress.lastError || null, progress: it.scanProgress || null, fail_count: Number(it.retries) || 0, nextRetryAt: null, attempts: (Number(it.retries) || 0) + cycles, retries: Number(it.retries) || 0, cycles, stagnantCycles: stagnant, inQueue: true, folderId: it.folderId || null, deadWriteFailed: !!it.deadWriteFailed };
              // ★ v2.15.10-A2: uma linha 'em progresso' NÃO é bloqueada —
              //   ela drena sozinha (1 batch/run por desenho). Só 'stuck'
              //   fica em blocked[]; 'cycling' vai p/ cycling[].
              if (kind === 'cycling') cycling.push(_entry); else blocked.push(_entry);
            }
          }
        }
      }
    } catch (e) { console.warn('[Cron Progress] blocked failed:', e && e.message); blocked = []; cycling = [];
      const _s = await loadTableSnapshot('scan_status');
      if (_s) { const _sorted = _s.slice().sort((a, b) => (b.updated_at || 0) - (a.updated_at || 0)).slice(0, 100); for (const row of _sorted) { if (row.status !== 'error' && row.status !== 'not_found' && row.status !== 'empty') continue; const fc = Math.max(0, Number(row.fail_count) || 0); const at = Number(row.updated_at) || 0; blocked.push({ coursePath: row.course_path, kind: row.status === 'error' ? 'error' : (row.status === 'not_found' ? 'not_found' : 'empty'), status: row.status, updated_at: at, last_error: row.last_error || null, fail_count: fc, nextRetryAt: (row.status === 'error' && at > 0 && fc < 3) ? at + scanQuarantineBackoffMs(fc) : null, attempts: fc, retries: 0, cycles: 0, inQueue: false, snapshot: true }); } }
    } // ★ v2.15.10-A3
    // ★ v2.15.6 (P1): enriquece a fila com o status D1 de cada item — o
    //   admin vê de relance o que está travado sem abrir o log.
    try {
      const d1s = meggyD1Binding();
      if (d1s && progress && Array.isArray(progress.queue) && progress.queue.length) {
        let _srows;
        try { const sr = await d1s.prepare(`SELECT course_path, status, lessons, updated_at, last_error, fail_count FROM scan_status`).all(); _srows = sr.results || []; }
        catch (_se) { _srows = await loadTableSnapshot('scan_status'); if (!_srows) throw _se; }
        const byKey = new Map();
        for (const row of _srows) { const k = typeof normCanonPath === 'function' ? normCanonPath(row.course_path) : row.course_path; byKey.set(k, row); }
        progress.queue = progress.queue.map(it => {
          const row = it && it.coursePath ? byKey.get(typeof normCanonPath === 'function' ? normCanonPath(it.coursePath) : it.coursePath) : null;
          if (!row) return { ...(it || {}), scanStatus: null };
          return { ...(it || {}), scanStatus: { status: row.status, lessons: row.lessons || 0, updated_at: row.updated_at || 0, last_error: row.last_error || null, fail_count: row.fail_count || 0 } };
        });
      }
    } catch (_) {}
    // ★ v2.15.2 (A2): "aulas no D1" é o COUNT(*) real — o totalLessons do
    //   KV é um contador HISTÓRICO (383: inclui as 382 aulas raiz já
    //   apagadas do D1) e divergia de Dados/Visão geral (10).
    let lessonsInD1 = null;
    try {
      const d1c = meggyD1Binding();
      if (d1c) {
        try { const cnt = await d1c.prepare('SELECT COUNT(*) AS n FROM lessons').first(); if (cnt && typeof cnt.n === 'number') lessonsInD1 = cnt.n; }
        catch (_) { const _s = await loadTableSnapshot('lessons'); if (_s) lessonsInD1 = _s.length; }
      }
    } catch (_) {}
    // ★ v2.15.2 (A5): no-store — sem ele o GET podia vir do cache do
    //   navegador e o item fantasma só aparecia após reload.
    return new Response(JSON.stringify({ok:true, progress, rootPaths, lessonsInD1, quarantined, blocked, cycling}),{headers:{...cors, 'Cache-Control':'no-store'}}); // ★ v2.15.10-A4
  }catch(e){
    return new Response(JSON.stringify({ok:false,error:e.message}),{status:500,headers:cors});
  }
}


// ★ v2.15.46: predicado dos artefactos de scraping escondidos da
//   listagem do utilizador (ver o filtro em apiRequest). Pastas só
//   caem se forem __pycache__; ficheiros caem pela extensão final
//   (py/pyc/pyo/ps1/bat/cmd/json/txt/md) ou por conterem '.py.' no
//   nome (restos versionados tipo main.py.0). Tudo o resto — vídeos,
//   PDFs, outras extensões, ficheiros sem extensão — passa intacto.
const SCRAPER_EXTS_21546 = { py: 1, pyc: 1, pyo: 1, ps1: 1, bat: 1, cmd: 1, json: 1, sh: 1, bash: 1, zsh: 1 };  // ★ v2.15.64: shell scripts (run_webgui.sh visto pelo Elton em CURSOS 2026) escondidos em todos os níveis
// ★ v2.15.63: md/txt são MATERIAL legítimo (transcrições!) — só se
//   escondem na RAIZ do drive (o lixo .46 vivia nas raízes: dumps e
//   manifestos .md/.txt). Nas subpastas (material/, ...) aparecem e
//   abrem no leitor de MD do front. Scripts/caches e .json ficam
//   escondidos em todo o lado, como na .46.
const ROOT_ONLY_EXTS_21563 = { txt: 1, md: 1 };
function isScraperArtifact21546(file, atRoot21563) {
  const name = (file && file.name != null ? String(file.name) : '').toLowerCase();
  if (!name) return false;
  if (file && file.mimeType === 'application/vnd.google-apps.folder') return name === '__pycache__';
  if (name.indexOf('.py.') !== -1) return true;
  const dot = name.lastIndexOf('.');
  if (dot > 0) {
    const ext = name.slice(dot + 1);
    if (SCRAPER_EXTS_21546[ext]) return true;
    if (atRoot21563 && ROOT_ONLY_EXTS_21563[ext]) return true;  // ★ v2.15.63
  }
  return false;
}

async function apiRequest(request, gd, user_ip) {
  const url = new URL(request.url);
  let path = url.pathname;
  path = path.replace(gd.url_path_prefix, '') || '/';
  // ★ OCULTO: bloqueia listagem via POST da pasta de estado e arquivos ocultos
  if (isHiddenPath(path)) return new Response(JSON.stringify({ error: 'Not found' }), { status: 404, headers: { 'Access-Control-Allow-Origin': '*', 'Content-Type': 'application/json;charset=UTF-8' } });
  const option = { status: 200, headers: { 'Access-Control-Allow-Origin': '*' } };

  if (path.slice(-1) === '/') {  // ★ v1.0.103 Task 20-11 Fix #1: == → === (string compare)
    let requestData;
    try{requestData=await request.json();}catch(_){return new Response(JSON.stringify({error:'invalid json'}),{status:400,headers:{'Content-Type':'application/json;charset=UTF-8','Access-Control-Allow-Origin':'*'}});}
    const list_result = await gd.request_list_of_files(path, requestData.page_token || null, Number(requestData.page_index) || 0);
    // ★ v2.15.46: esconde da LISTAGEM do utilizador os artefactos das
    //   ferramentas de scraping que vivem nas raízes/pastas dos drives
    //   (scripts .py/.ps1/.bat/.cmd, caches __pycache__/.pyc, manifestos
    //   e dumps .json/.txt/.md, restos tipo main.py.0) — nunca são aulas
    //   nem materiais. Só esta rota é filtrada: admin (drive-browse) e
    //   scanner (scan-list-files) continuam a ver tudo, e NADA é apagado
    //   do Drive — é só apresentação.
    if (list_result && list_result.data && Array.isArray(list_result.data.files)) {
      const _atRoot21563 = (path === '/' || path === '');  // ★ v2.15.63: o path aqui já vem sem o prefixo '/N:' — a raiz do drive é '/'
      list_result.data.files = list_result.data.files.filter(f => !isScraperArtifact21546(f, _atRoot21563));
    }
    if (authConfig['enable_password_file_verify']) {
      const password = await gd.password(path);
      if (password && password.replace("\n", "") !== requestData.password) {
        // ★ v1.0.102 FIX (Agent 8 E3): retornar 401 + JSON em vez de 200 + base64 "codeisprotected".
        // Antes, retornava 'Y29kZWlzcHJvdGVjdGVk' (base64 de "codeisprotected") com status 200,
        // obrigando o client a decodificar base64 para detectar o caso de senha. Isso é frágil
        // e impede o client de distinguir erro de "pasta protegida". Agora, status 401 + JSON
        // permite o client diferenciar via HTTP status e parsear o erro.
        return new Response(JSON.stringify({ error: 'password_required' }), { status: 401, headers: { 'Access-Control-Allow-Origin': '*', 'Content-Type': 'application/json;charset=UTF-8' } });
      }
    }
    list_result.data.files = await Promise.all(list_result.data.files.map(async (file) => {
      const { driveId, id, mimeType, ...fileWithoutId } = file;
      const encryptedId = await encryptString(id);
      const encryptedDriveId = await encryptString(driveId);
      let link = null;
      if (mimeType !== 'application/vnd.google-apps.folder') link = await generateLink(id, user_ip);
      return { ...fileWithoutId, id: encryptedId, driveId: encryptedDriveId, mimeType: mimeType, link: link };
    }));
    return new Response(JSON.stringify(list_result), { status: 200, headers: { 'Access-Control-Allow-Origin': '*', 'Content-Type': 'application/json;charset=UTF-8' } });
  } else {
    const file_json = await gd.get_single_file(path);
    if (!file_json) return new Response(JSON.stringify({ error: 'File not found' }), { status: 404, headers: { 'Access-Control-Allow-Origin': '*', 'Content-Type': 'application/json;charset=UTF-8' } });
    const { driveId, id, ...fileWithoutId } = file_json;
    const encryptedId = await encryptString(id);
    const encryptedDriveId = await encryptString(driveId);
    const link = await generateLink(id, user_ip);
    const encryptedFile = { ...fileWithoutId, id: encryptedId, driveId: encryptedDriveId, link: link };
    return new Response(JSON.stringify(encryptedFile), { status: 200, headers: { 'Access-Control-Allow-Origin': '*', 'Content-Type': 'application/json;charset=UTF-8' } });
  }
}

async function handleSearch(request, gd, user_ip = '') {
  const option = { status: 200, headers: { 'Access-Control-Allow-Origin': '*', 'Content-Type': 'application/json;charset=UTF-8' } };
  let requestData;
  try{requestData=await request.json();}catch(_){return new Response(JSON.stringify({error:'invalid json'}),{status:400,headers:{'Content-Type':'application/json;charset=UTF-8','Access-Control-Allow-Origin':'*'}});}
  const q = requestData.q || '';
  const pageToken = requestData.page_token || null;
  const pageIndex = Number(requestData.page_index) || 0;
  if (q === '') return new Response(JSON.stringify({ nextPageToken: null, curPageIndex: 0, data: { files: [] } }), option);  // ★ v1.0.103 Task 20-11 Fix #1: == → === (string compare; q é string após `|| ''`)
  const searchResult = await gd.searchFilesinDrive(q, pageToken, pageIndex);
  if (!searchResult.data || !searchResult.data.files) return new Response(JSON.stringify({ nextPageToken: null, curPageIndex: 0, data: { files: [] } }), option);
  searchResult.data.files = await Promise.all(searchResult.data.files.map(async (file) => {
    const { driveId, id, ...fileWithoutId } = file;
    const encryptedId = await encryptString(id);
    const encryptedDriveId = await encryptString(driveId);
    const link = await generateLink(id, user_ip);
    const driveIdx = driveId ? drive_list.indexOf(driveId) : -1;
    const rootIdx = driveId ? (driveIdx >= 0 ? driveIdx : -2) : -1;
    return { ...fileWithoutId, id: encryptedId, driveId: encryptedDriveId, rootIdx, link: link };
  }));
  return new Response(JSON.stringify(searchResult), option);
}

async function handleId2Path(request, gd) {
  const url = new URL(request.url);
  const option = { status: 200, headers: { "content-type": "application/json", 'Access-Control-Allow-Origin': authConfig.cors_domain, 'Access-Control-Allow-Methods': 'GET,HEAD,POST,OPTIONS' } };
  try {
    const data = await request.json();
    const id = await decryptString(data.id);
    const result = await gd.findPathById(id);
    if (!result || !result[0]) return new Response(JSON.stringify({ path: null }), { status: 404, headers: option.headers });
    const [path, prefix] = result;
    return new Response(JSON.stringify({ path: '/' + prefix + ':' + path }), option);
  } catch (error) {
    const isBadInput = error.name === 'InvalidCharacterError' || error.message?.includes('atob') || error.message?.includes('base64');
    // ★ WORKER-FIXES-v79: do not leak internal error strings to the client.
    return new Response(JSON.stringify({ message: isBadInput ? 'Invalid encrypted ID' : 'Request Failed or Path Not Found' }), { status: isBadInput ? 400 : 500, headers: option.headers });
  }
}

async function findId2Path(gd, url) {
  const id = url.searchParams.get('id');
  const view = url.searchParams.get('view') || 'false';
  if (!id) return new Response(JSON.stringify({ error: 'Missing id parameter' }), { status: 400, headers: { 'Content-Type': 'application/json;charset=UTF-8' } });
  let found_path = null;
  let found_drive_idx = gd.order;
  try { const result = await gd.findPathById(id); if (result && result[0]) { found_path = result[0]; found_drive_idx = (result[1] !== undefined) ? result[1] : gd.order; } } catch (_) {}
  if (!found_path) {
    for (let i = 0; i < gds.length; i++) {
      if (gds[i] === gd) continue;
      try { const result = await gds[i].findPathById(id); if (result && result[0]) { found_path = result[0]; found_drive_idx = (result[1] !== undefined) ? result[1] : i; break; } } catch (_) {}
    }
  }
  if (found_path) {
    const suffix = view === 'true' ? '?a=view' : '';
    return Response.redirect(url.origin + '/' + found_drive_idx + ':' + found_path + suffix, 302);
  }
  try {
    const file = await gd.findItemById(id);
    if (file && file.id) { const encrypted_id = await encryptString(id); return Response.redirect(url.origin + '/fallback?id=' + encodeURIComponent(encrypted_id), 302); }
  } catch (_) {}
  return new Response(JSON.stringify({ error: 'File not found' }), { status: 404, headers: { 'Content-Type': 'application/json;charset=UTF-8' } });
}

class googleDrive {
  constructor(authConfig, order) {
    this.order = order;
    // ★ Versão pública: sem drives-semente, roots pode estar vazio — o
    //   drive fica inerte (sem raiz) em vez de quebrar o arranque.
    this.root = authConfig.roots[order] || { id: '', protect_file_link: false };
    this.root.protect_file_link = this.root.protect_file_link || false;
    this.url_path_prefix = `/${order}:`;
    this.authConfig = authConfig;
    this.paths = [];
    this.files = [];
    this.passwords = [];
    this.paths["/"] = this.root['id'];
    // ★ v1.0.103 Task 20-2 Fix #2: TTL timestamps — paths/files/passwords caches nunca
    // eram invalidados. Após 5 min, força re-fetch (Drive pode ter mudado: renomeação,
    // movimentação, novo .password, etc.). Antes, um path resolvido ficava cached para
    // sempre no isolate, levando a 404s ou acesso a pastas renomeadas.
    this._pathsAt = {};
    this._filesAt = {};
    this._passwordsAt = {};
    this._cacheTtlMs = 5 * 60 * 1000; // 5 minutos
  }
  async init() {
    await getAccessToken();
    if (authConfig.user_drive_real_root_id) return;
    const root_obj = await (gds[0] || this).findItemById('root');
    if (root_obj && root_obj.id) authConfig.user_drive_real_root_id = root_obj.id;
  }
  async initRootType() {
    const root_id = this.root['id'];
    const types = DriveFixedTerms.gd_root_type;
    const explicit_type = this.root.type;
    if (explicit_type === 'shared_drive') { this.root_type = types.share_drive; return; }
    if (explicit_type === 'root' || explicit_type === 'folder') { this.root_type = types.user_drive; return; }
    if (root_id === 'root' || root_id === authConfig.user_drive_real_root_id) this.root_type = types.user_drive;
    else this.root_type = types.share_drive;
  }
  async get_single_file(path) {
    // ★ v1.0.103 Task 20-2 Fix #2: TTL — expira após 5 min, força re-fetch do Drive.
    if (typeof this.files[path] === 'undefined' || (Date.now() - (this._filesAt[path]||0)) > this._cacheTtlMs) {  // ★ v1.0.103 Task 20-11 Fix #1: == → === (typeof result)
      this.files[path] = await this.get_single_file_api(path);
      this._filesAt[path] = Date.now();
    }
    return this.files[path];
  }
  async get_single_file_api(path) {
    const arr = path.split('/');
    let name = arr.pop();
    name = driveEscape(driveSafeDecode21550(name));  // ★ v2.15.50 (Frente B): decode tolerante (a forma antiga era tudo-ou-nada — ver driveSafeDecode21550)  // ★ v1.0.103 Task 20-11 Fix #11: try/catch no decodeURIComponent (URIError em sequências % malformadas como '%zz' ou '%' solto) — antes crashava o request. Fallback: usa nome cru sem decode.
    const dir = arr.join('/') + '/';
    const parent = await this.findPathId(dir);
    let url = 'https://www.googleapis.com/drive/v3/files';
    const params = { includeItemsFromAllDrives: true, supportsAllDrives: true };
    params.q = `'${parent}' in parents and name = '${name}' and trashed = false and mimeType != 'application/vnd.google-apps.shortcut'`;
    params.fields = "files(id, name, mimeType, size ,createdTime, modifiedTime, iconLink, thumbnailLink, driveId, fileExtension)";
    url += '?' + enQuery(params);
    const requestOption = await this.requestOptions();
    let response;
    for (let i = 0; i < 3; i++) { response = await fetch(url, requestOption); if (response.ok) break; await sleep(800 * (i + 1)); }
    if (!response.ok) return undefined;
    const obj = await response.json();
    return obj.files && obj.files[0];
  }
  async request_list_of_files(path, page_token = null, page_index = 0) {
    if (this.path_children_cache === undefined) this.path_children_cache = {};  // ★ v1.0.103 Task 20-11 Fix #1: == → === (undefined check)
    if (this.path_children_cache[path] && this.path_children_cache[path][page_index] && this.path_children_cache[path][page_index].data) {
      const child_obj = this.path_children_cache[path][page_index];
      return { nextPageToken: child_obj.nextPageToken || null, curPageIndex: page_index, data: child_obj.data };
    }
    const id = await this.findPathId(path);
    const result = await this._list_gdrive_files(id, page_token, page_index);
    const data = result.data;
    if (result.nextPageToken && data.files) {
      if (!Array.isArray(this.path_children_cache[path])) this.path_children_cache[path] = [];
      this.path_children_cache[path][Number(result.curPageIndex)] = { nextPageToken: result.nextPageToken, data: data };
    }
    return result;
  }
  async _list_gdrive_files(parent, page_token = null, page_index = 0) {
    if (parent === undefined || parent === null) return { nextPageToken: null, curPageIndex: page_index, data: { files: [] } };  // ★ v1.0.103 Task 20-11 Fix #1: == → === (undefined/null check)
    let obj;
    const params = { includeItemsFromAllDrives: true, supportsAllDrives: true };
    // ★ OCULTO: exclui a pasta de estado e o .gdi_users.json da listagem (nível query do Drive)
    params.q = `'${parent}' in parents and trashed = false AND name !='.password' ${HIDDEN_QUERY_EXCLUDE_LIST} and mimeType != 'application/vnd.google-apps.shortcut' and mimeType != 'application/vnd.google-apps.form' and mimeType != 'application/vnd.google-apps.site'`;
    params.orderBy = 'folder, name, modifiedTime desc';
    params.fields = "nextPageToken, files(id, name, mimeType, size, modifiedTime, driveId, kind, fileExtension)";
    params.pageSize = this.authConfig.files_list_page_size;
    if (page_token) params.pageToken = page_token;
    let url = 'https://www.googleapis.com/drive/v3/files';
    url += '?' + enQuery(params);
    const requestOption = await this.requestOptions();
    let response;
    for (let i = 0; i < 3; i++) { response = await fetch(url, requestOption); if (response.ok) break; await sleep(800 * (i + 1)); }
    // ★ CYCLE2-1 Fix Bug #1: missing `!response.ok` guard. After the 3-retry loop, if all
    // attempts failed (e.g., Drive API 500 with HTML error body), the previous code
    // unconditionally called `await response.json()` which throws SyntaxError on non-JSON
    // bodies. The thrown error propagated to the top-level catch (returning 500 "Internal
    // Server Error" with no CORS-safe JSON body), instead of degrading gracefully to an
    // empty file list. Every other retry-then-parse method in this class already has this
    // guard — `searchFilesinDrive` (line ~6347), `_findDirId` (line ~6435),
    // `get_single_file_api` (line ~6261), `fetchAccessToken` (line ~2787),
    // `_getAccessToken` (line ~6467). This was the ONLY retry-then-parse method missing it.
    if (!response.ok) return { nextPageToken: null, curPageIndex: page_index, data: { files: [] } };
    obj = await response.json();
    if (!obj.files) obj.files = [];
    // ★ OCULTO: pós-filtro em JS (à prova de falha do query do Drive)
    obj.files = obj.files.filter(f => !isHiddenName(f.name));
    return { nextPageToken: obj.nextPageToken || null, curPageIndex: page_index, data: obj };
  }
  async password(path) {
    // ★ v1.0.103 Task 20-2 Fix #2: TTL — expira após 5 min, força re-fetch do .password.
    if (this.passwords[path] !== undefined && (Date.now() - (this._passwordsAt[path]||0)) < this._cacheTtlMs) return this.passwords[path];
    const file = await this.get_single_file(path + '.password');
    if (file === undefined) { this.passwords[path] = null; }  // ★ v1.0.103 Task 20-11 Fix #1: == → === (undefined check)
    else {
      const url = `https://www.googleapis.com/drive/v3/files/${file.id}?alt=media`;
      const requestOption = await this.requestOptions();
      const response = await this.fetch200(url, requestOption);
      this.passwords[path] = await response.text();
    }
    this._passwordsAt[path] = Date.now();
    return this.passwords[path];
  }
  async searchFilesinDrive(origin_keyword, page_token = null, page_index = 0) {
    const types = DriveFixedTerms.gd_root_type;
    const is_user_drive = this.root_type === types.user_drive;
    const is_share_drive = this.root_type === types.share_drive;
    const empty_result = { nextPageToken: null, curPageIndex: page_index, data: null };
    if (!is_user_drive && !is_share_drive) return empty_result;
    const keyword = SearchFunction.formatSearchKeyword(origin_keyword);
    if (!keyword) return empty_result;
    const words = keyword.split(/\s+/);
    const name_search_str = `name contains '${words.join("' AND name contains '")}'`;
    const params = {};
    if (is_user_drive) {
      if (authConfig.search_all_drives) { params.corpora = 'allDrives'; params.includeItemsFromAllDrives = true; params.supportsAllDrives = true; }
      else params.corpora = 'user';
    }
    if (is_share_drive) {
      if (authConfig.search_all_drives) params.corpora = 'allDrives';
      else { params.corpora = 'drive'; params.driveId = this.root.id; }
      params.includeItemsFromAllDrives = true;
      params.supportsAllDrives = true;
    }
    if (page_token) params.pageToken = page_token;
    // ★ OCULTO: exclui pasta de estado e .gdi_users.json dos resultados de busca
    params.q = `trashed = false AND mimeType != 'application/vnd.google-apps.shortcut' and mimeType != 'application/vnd.google-apps.form' and mimeType != 'application/vnd.google-apps.site' AND name !='.password' ${HIDDEN_QUERY_EXCLUDE_SEARCH} AND (${name_search_str})`;
    params.fields = "nextPageToken, files(id, driveId, name, mimeType, size , modifiedTime)";
    params.pageSize = this.authConfig.search_result_list_page_size;
    params.orderBy = 'folder, name, modifiedTime desc';
    let url = 'https://www.googleapis.com/drive/v3/files';
    url += '?' + enQuery(params);
    const requestOption = await this.requestOptions();
    let response;
    for (let i = 0; i < 3; i++) { response = await fetch(url, requestOption); if (response.ok) break; await sleep(800 * (i + 1)); }
    if (!response.ok) return { nextPageToken: null, curPageIndex: page_index, data: { files: [] } };
    const res_obj = await response.json();
    // ★ OCULTO: pós-filtro em JS (à prova de falha do query do Drive)
    res_obj.files = (res_obj.files || []).filter(f => !isHiddenName(f.name));
    return { nextPageToken: res_obj.nextPageToken || null, curPageIndex: page_index, data: res_obj };
  }
  async findParentFilesRecursion(child_id, drive_index_no, contain_myself = true) {
    const gd = this;
    const gd_root_id = gd.root.id;
    const user_drive_real_root_id = authConfig.user_drive_real_root_id;
    const is_user_drive = gd.root_type === DriveFixedTerms.gd_root_type.user_drive;
    const target_top_id = is_user_drive ? user_drive_real_root_id : gd_root_id;
    const parent_files = [];
    let meet_top = false;
    async function addItsFirstParent(file_obj) {
      if (!file_obj) return;
      if (!file_obj.parents) return null;
      if (file_obj.parents.length < 1) return;
      const p_ids = file_obj.parents;
      if (p_ids && p_ids.length > 0) {
        const first_p_id = p_ids[0];
        if (drive_list.includes(first_p_id) || first_p_id === target_top_id) {
          meet_top = true;
          drive_index_no = first_p_id === target_top_id ? gd.order : drive_list.indexOf(first_p_id);
          return drive_index_no;
        }
        const p_file_obj = await gd.findItemById(first_p_id);
        if (p_file_obj && p_file_obj.id) { parent_files.push(p_file_obj); await addItsFirstParent(p_file_obj); }
      }
      return drive_index_no;
    }
    const child_obj = await gd.findItemById(child_id);
    if (contain_myself) parent_files.push(child_obj);
    const drive_id = await addItsFirstParent(child_obj);
    return meet_top ? [parent_files, drive_index_no] : null;
  }
  async findPathById(child_id) {
    let p_files;
    let drive_index_no = 0;
    try { [p_files, drive_index_no] = await this.findParentFilesRecursion(child_id); }
    catch (error) { return null; }
    if (!p_files || p_files.length < 1) return '';
    const cache = [];
    p_files.forEach((value, idx) => {
      const is_folder = idx === 0 ? (p_files[idx].mimeType === DriveFixedTerms.folder_mime_type) : true;
      let path = '/' + p_files.slice(idx).map(it => encodeURIComponent(it.name)).reverse().join('/');
      if (is_folder) path += '/';
      cache.push({ id: p_files[idx].id, path: path });
    });
    return [cache[0].path, drive_index_no];
  }
  async findItemById(id) {
    const url = `https://www.googleapis.com/drive/v3/files/${id}?fields=${DriveFixedTerms.default_file_fields}&supportsAllDrives=true`;
    const requestOption = await this.requestOptions();
    const res = await fetch(url, requestOption);
    if (!res.ok) return null;
    return await res.json();
  }
  async findPathId(path) {
    let c_path = '/';
    let c_id = this.paths[c_path];
    const arr = path.replace(/^\/+|\/+$/g, '').split('/');
    // ★ v1.0.103 Task 20-2 Fix #2: TTL per segment — cada c_path tem seu próprio timestamp.
    // Se um segmento expirou, re-resolve do parent armazenado (mesmo comportamento do cache
    // infinito anterior, mas com re-validação periódica para pegar renomeações/movimentações).
    for (const name of arr) {
      c_path += name + '/';
      if (typeof this.paths[c_path] === 'undefined' || (Date.now() - (this._pathsAt[c_path]||0)) > this._cacheTtlMs) {  // ★ v1.0.103 Task 20-11 Fix #1: == → === (typeof result)
        const id = await this._findDirId(c_id, name);
        // ★ v2.14.8: NUNCA grava null no cache — uma falha transitória do Drive
        //   (500/timeout) envenenava o caminho por 5 min (TTL): o picker mostrava
        //   "Pasta vazia" para pastas que existem, sem nem retentar. null = "não
        //   sei", não "não existe": só ids reais entram no cache.
        if (id !== undefined && id !== null) { this.paths[c_path] = id; this._pathsAt[c_path] = Date.now(); }
        else { delete this.paths[c_path]; delete this._pathsAt[c_path]; }
      }
      c_id = this.paths[c_path];
      if (c_id === undefined || c_id === null) break;  // ★ v1.0.103 Task 20-11 Fix #1: == → === (undefined/null check)
    }
    // ★ v2.14.7: o cache usa chaves COM '/' final ('/A/B/'), mas o retorno lia
    //   só a chave EXATA — caminhos sem '/' final (o picker do admin usa
    //   parseCoursePath(), que tira a '/' final) devolviam undefined → a pasta
    //   parecia vazia e o picker só navegava a 1ª camada.
    if (typeof this.paths[path] !== 'undefined') return this.paths[path];
    const _slashed = this.paths[path.replace(/\/?$/, '/')];
    return _slashed === null ? undefined : _slashed;  // null = pasta inexistente: mantém o contrato antigo (undefined)
  }
  async _findDirId(parent, name) {
    name = driveEscape(driveSafeDecode21550(name));  // ★ v2.15.50 (Frente B): decode tolerante (a forma antiga era tudo-ou-nada — ver driveSafeDecode21550)  // ★ v1.0.103 Task 20-11 Fix #11: try/catch no decodeURIComponent (URIError em sequências % malformadas como '%zz' ou '%' solto) — antes crashava o request. Fallback: usa nome cru sem decode.
    if (parent === undefined) return null;  // ★ v1.0.103 Task 20-11 Fix #1: == → === (undefined check)
    let url = 'https://www.googleapis.com/drive/v3/files';
    const params = { includeItemsFromAllDrives: true, supportsAllDrives: true };
    params.q = `'${parent}' in parents and mimeType = 'application/vnd.google-apps.folder' and name = '${name}'  and trashed = false`;
    params.fields = "nextPageToken, files(id, name, mimeType)";
    url += '?' + enQuery(params);
    const requestOption = await this.requestOptions();
    let response;
    for (let i = 0; i < 3; i++) { response = await fetch(url, requestOption); if (response.ok) break; await sleep(800 * (i + 1)); }
    if (!response.ok) return null;
    const obj = await response.json();
    if (!obj.files || obj.files[0] === undefined) return null;  // ★ v1.0.103 Task 20-11 Fix #1: == → === (undefined check)
    return obj.files[0].id;
  }
  async fetch200(url, requestOption) {
    let response;
    for (let i = 0; i < 3; i++) { response = await fetch(url, requestOption); if (response.ok) break; await sleep(800 * (i + 1)); }
    return response;
  }
  async requestOptions(headers = {}, method = 'GET') {
    const Token = await this._getAccessToken();
    headers['authorization'] = 'Bearer ' + Token;
    return { method: method, headers: headers };
  }
  async _getAccessToken() {
    const c = this.root.client_id && this.root.client_secret && this.root.refresh_token
      ? this.root
      : (this.root.service_account && this.root.service_account_json ? this.root : null);
    if (!c) return getAccessToken();
    if (this._token_expiry && this._token_expiry > Date.now()) return this._access_token;
    const url = 'https://www.googleapis.com/oauth2/v4/token';
    const headers = { 'Content-Type': 'application/x-www-form-urlencoded' };
    let post_data;
    if (c.service_account && c.service_account_json) {
      const jwttoken = await JSONWebToken.generateGCPToken(c.service_account_json);
      post_data = { grant_type: 'urn:ietf:params:oauth:grant-type:jwt-bearer', assertion: jwttoken };
    } else {
      post_data = { client_id: c.client_id, client_secret: c.client_secret, refresh_token: c.refresh_token, grant_type: 'refresh_token' };
    }
    let response;
    for (let i = 0; i < 3; i++) { response = await fetch(url, { method: 'POST', headers, body: enQuery(post_data) }); if (response.ok) break; await sleep(800 * (i + 1)); }
    if (!response.ok) throw new Error(`Per-drive token fetch failed with status ${response.status}`);
    const obj = await response.json();
    if (!obj.access_token) throw new Error('Per-drive token response missing access_token');
    this._access_token = obj.access_token;
    this._token_expiry = Date.now() + 3500 * 1000;
    return this._access_token;
  }
}

const drive = new googleDrive(authConfig, 0);
async function download(id, range = '', inline, exportFmt = null) {
  if (uiConfig.second_domain_for_dl === true) {
    let res = await fetch(cdn_base + '/assets/disable_download.html');
    return new Response(await res.text(), { headers: { "content-type": "text/html;charset=UTF-8" } });
  }
  const requestOption = await drive.requestOptions();
  const file = await drive.findItemById(id);
  if (!file || !file.name) {
    return new Response(`{"error":"Unable to Find this File, Try Again."}`, { status: 404, headers: { "content-type": "application/json", 'Access-Control-Allow-Origin': authConfig.cors_domain } });
  }
  const exportEntry = GDOC_EXPORT_FORMATS[file.mimeType];
  if (exportEntry) {
    const targetFmt = exportFmt ? exportEntry.formats.find(f => f.ext === exportFmt) || exportEntry.formats[0] : exportEntry.formats[0];
    const exportUrl = `https://www.googleapis.com/drive/v3/files/${id}/export?mimeType=${encodeURIComponent(targetFmt.mime)}`;
    const res = await fetch(exportUrl, requestOption);
    if (!res.ok) {
      const details = await res.text();
      return new Response(details, { status: res.status, headers: { "content-type": "text/plain;charset=UTF-8" } });
    }
    const exportRes = new Response(res.body, res);
    const exportName = `${file.name}.${targetFmt.ext}`;
    exportRes.headers.set("Content-Disposition", inline ? `inline; filename*=UTF-8''${encodeURIComponent(exportName)}` : `attachment; filename*=UTF-8''${encodeURIComponent(exportName)}`);  // ★ v2.15.88 (inline21588): inline COM nome — sem filename, o Chrome Android baptiza o PDF com a cauda da URL ("download.aspx")
    exportRes.headers.set("Content-Type", targetFmt.mime);
    authConfig.enable_cors_file_down && exportRes.headers.append('Access-Control-Allow-Origin', '*');
    return exportRes;
  }
  const url = `https://www.googleapis.com/drive/v3/files/${id}?alt=media`;
  if (range) requestOption.headers['Range'] = range;
  let res;
  for (let i = 0; i < 3; i++) { res = await fetch(url, requestOption); if (res.ok) break; await sleep(800 * (i + 1)); }
  if (res.ok) {
    const { headers } = res = new Response(res.body, res);
    headers.set("Content-Disposition", `attachment; filename*=UTF-8''${encodeURIComponent(file.name)}`);
    headers.set("Content-Length", file.size);
    authConfig.enable_cors_file_down && headers.append('Access-Control-Allow-Origin', '*');
    if (inline === true) headers.set("Content-Disposition", `inline; filename*=UTF-8''${encodeURIComponent(file.name)}`);  // ★ v2.15.88 (inline21588): inline COM nome — sem filename, o Chrome Android baptiza o PDF com a cauda da URL ("download.aspx") e o aluno perde a referência do material
    return res;
  } else if (res.status === 404) {  // ★ v1.0.103 Task 20-11 Fix #1: == → === (status code numeric compare)
    return new Response(not_found(), { status: 404, headers: { "content-type": "text/html;charset=UTF-8" } });
  } else if (res.status === 403) {  // ★ v1.0.103 Task 20-11 Fix #1: == → === (status code numeric compare)
    const details = await res.text();
    return new Response(details, { status: 403, headers: { "content-type": "text/html;charset=UTF-8" } });
  } else {
    const details = await res.text();
    return new Response(details, { status: res.status, headers: { "content-type": "text/plain;charset=UTF-8" } });
  }
}

function decodeJwtToken(token) {
  if (!token || typeof token !== 'string') return null;
  try {
    const parts = token.split('.');
    if (parts.length < 2) return null;
    const base64Url = parts[1];
    const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
    const jsonPayload = decodeURIComponent(atob(base64).split('').map(function(c) {
      return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
    }).join(''));
    return JSON.parse(jsonPayload);
  } catch(e) {
    console.warn('decodeJwtToken error:', e.message);
    return null;
  }
}

// ═══════════════════════════════════════════════════════════════
// ★ v1.0.88 FASE 1 — Module Worker format (conservative migration)
// Cloudflare Workers detecta `export default` e usa Module format.
// Isto dá acesso a bindings (env.ai, env.ENV, env.KV) via parameter.
// Dual-path: se env não for passado (fallback Service Worker), usa globalThis.
// ═══════════════════════════════════════════════════════════════
// ★ v1.0.102 NOTE (Agent 20 Bug 1): _env/_ctx são module-scoped. Isto é uma LIMITAÇÃO
// conhecida — em isolates CF que manipulam múltiplas requests simultaneamente, o env
// da request mais recente sobrescreve o da anterior (race). A solução ideal é passar
// env/ctx por toda a cadeia de chamadas (handleRequest → handlers → helpers), mas isso
// exigiria refatorar ~50 funções. Por ora, mantemos o setter abaixo — ele só atualiza
// _env quando muda (evita escrita redundante) e funciona corretamente para o caso
// comum (1 request por isolate por vez, que é o comportamento default do runtime CF).
// Para deploy com alto paralelismo por isolate, considere migrar para passagem explícita.
let _env = null;   // setado pelo export default { fetch }
let _ctx = null;   // setado pelo export default { fetch }

// Helper dual-path para KV (ENV binding):
// - Module format: _env.ENV
// - Service format (fallback): globalThis.ENV
// Retorna o KV namespace ou null.
function getKV() {
  try {
    if (_env && _env.ENV) return _env.ENV;
    if (typeof ENV !== 'undefined' && ENV) return ENV;
  } catch(_) {}
  return null;
}

// Helper dual-path para AI binding (quando existir):
// - Module format: _env.ai
// - Service format: globalThis.AI (legacy, geralmente undefined)
function getAI() {
  try {
    if (_env && _env.ai) return _env.ai;
    if (typeof globalThis.AI !== 'undefined' && globalThis.AI) return globalThis.AI;
  } catch(_) {}
  return null;
}

// ★ Module Worker entry point — Cloudflare detecta `export default` e ativa Module format.
// O addEventListener abaixo fica como fallback (não conflita — Module format tem precedência
// quando export default está presente).

// ═══════════════════════════════════════════════════════════════
// ★ v1.0.180 OPÇÃO A: Cron Worker — backfill automático de lessons
// Roda a cada 6h via [triggers] crons no wrangler.toml.
// Processa 3 cursos por execução, respeitando o limite de 50 subrequests do CF.
// Progresso salvo em KV MEGGY_CACHE:cron-backfill:progress.
// Usa Service Account (authConfig.service_account_json) para acessar TODOS os drives root
// sem depender de login de aluno. Pré-aquece o cache para que novos alunos peguem cache hit.
// Idempotente: INSERT OR REPLACE no D1, dotfiles (.gdi-course.json, .gdi-lessons.json) são upserts.
// NON-BREAKING: roda em background via ctx.waitUntil(), não afeta requests HTTP.
// ═══════════════════════════════════════════════════════════════
// ═══════════════════════════════════════════════════════════════════════════
// ★ v2.4: SCANNER — D1 por batch + backfill com progresso por curso
//   Diagnóstico (2026-11-13): scan-progress não escrevia no D1 (só devolvia
//   as aulas); scan-and-save escrevia mas ninguém o chamava; o cron backfill
//   só listava pastas filhas da raiz (cursos em subpastas nunca entravam) e
//   só salvava o progresso no KV no FIM — se a CPU (10 ms Free) ou os 50
//   subrequests estourassem no meio, a próxima hora recomeçava do mesmo
//   ponto. Inserts no D1 eram seriais, 1 .run() por aula.
//   Correção: (1) cada batch do scan-progress grava no D1 (idempotente, em
//   lotes); (2) scan-and-save e backfill usam o mesmo insert em lote;
//   (3) o backfill mantém uma FILA no KV (filhos da raiz + course_path
//   distintos do user_courses, sem duplicar) e salva o progresso após CADA
//   curso — um corte no meio retoma, não recomeça.
//   d1.batch() com 19 statements falha (v1.0.169) — lotes de 8.
// ═══════════════════════════════════════════════════════════════════════════
// ═══ v2.15.33-A: SCANNER EXTERNO HÍBRIDO — classificação + linha do D1 ═══
//   A classificação (mimeType/ext → type) e a construção da linha de
//   `lessons` vivem aqui, em funções puras, e os DOIS caminhos as chamam:
//   o scanner interno (gdiScanDistributed, gdiScanCourseLessonsIncremental
//   e d1InsertLessons) e o endpoint scan-upsert-lessons. É isto que garante
//   linhas byte-equivalentes — nenhuma lógica duplicada.
//   Regras (verbatim do scanner interno):
//   - type: video se mime video/* ou application/vnd.google-apps.video ou
//     ext mp4/webm/mkv/mov/avi/m4v/ts/m3u8; audio se mime audio/* ou ext
//     mp3/m4a/aac/ogg/wav/flac/m4b; pdf se ext pdf ou mime application/pdf;
//     doc se ext doc/docx/ppt/pptx/odt/odp/txt/md/rtf; senão null — o
//     ficheiro NÃO é aula e é descartado (o scanner só faz push c/ type).
//   - ext = último segmento após '.' em minúsculas (nome sem '.' → o nome
//     inteiro em minúsculas — comportamento verbatim do scanner).
//   - id = file.id || (courseHash + '_' + name); lesson_path =
//     normalizeLessonPath(rebaseDrivePath(path, courseIdx)) + rebase
//     legado; DESCARTADA se não começar pelo prefixo do curso (log).
//   - drive_index = índice do coursePath (não o da pasta);
//     parent_folder_path = coursePath canónico (é o que o scanner grava:
//     a RAIZ do curso, não a pasta imediata); scanned_at/created_at/
//     updated_at = now (scannedAt do ctx quando dado).
//   - size é gravado tal como vem do Drive (string ou null).
function scanClassifyFile(name, mimeType){
  const nm = String(name || '');
  const ext = (nm.split('.').pop() || '').toLowerCase();
  const mt = String(mimeType || '');
  const isVideo = /^video\//.test(mt) || mt === 'application/vnd.google-apps.video' || ['mp4', 'webm', 'mkv', 'mov', 'avi', 'm4v', 'ts', 'm3u8'].includes(ext);
  const isAudio = mt.startsWith('audio/') || ['mp3', 'm4a', 'aac', 'ogg', 'wav', 'flac', 'm4b'].includes(ext);
  const isPdf = ext === 'pdf' || mt === 'application/pdf';
  const isDoc = ['doc', 'docx', 'ppt', 'pptx', 'odt', 'odp', 'txt', 'md', 'rtf'].includes(ext);
  let type = null;
  if(isVideo) type = 'video';
  else if(isAudio) type = 'audio';
  else if(isPdf) type = 'pdf';
  else if(isDoc) type = 'doc';
  return { type, ext, mimeType: mt };
}

function buildLessonRow(file, ctx){
  // file: aula do scanner ({id, name, path, type, mimeType, ext, size})
  //   OU ficheiro já classificado pelo endpoint ({id, name, type, ext,
  //   mimeType, size} — a classificação é feita pelo CHAMADOR, ver nota).
  // ctx: {coursePath, courseHash, courseIdx, coursePrefix, folderPath?,
  //   scannedAt?, now?}. Devolve a linha (ordem das colunas = bind do
  //   INSERT) ou null quando a aula cai fora do curso.
  // ★ NÃO classifica aqui: a aula do scanner já traz `type` (ou null, que
  //   é o que o d1InsertLessons antigo gravava p/ aulas sem type); os
  //   ficheiros crus do Drive são classificados pelo CHAMADOR
  //   (scan-upsert-lessons, via scanClassifyFile) antes de chegarem aqui.
  //   Classificar aqui mudaria o comportamento do scanner p/ aulas sem
  //   `type` (o v2.4-test-scanner prova: 25 aulas sem type entram com
  //   lesson_type null — o classificador olha p/ o NOME, e 'Aula 1' não
  //   tem extensão, por isso seriam descartadas por engano).
  if(!file || !file.name) return null;
  const name = String(file.name);
  const type = file.type || null;
  const ext = (file.ext === undefined || file.ext === null) ? null : String(file.ext);
  const mt = (file.mimeType === undefined || file.mimeType === null) ? '' : String(file.mimeType);
  const coursePath = ctx.coursePath;
  const courseHash = ctx.courseHash;
  const courseIdx = ctx.courseIdx;
  const coursePrefix = ctx.coursePrefix;
  const rawPath = file.path || ((ctx.folderPath || coursePath) + '/' + name);
  let normPath = normalizeLessonPath(rebaseDrivePath(rawPath, courseIdx));
  if(typeof legacyCoursePathRebase === 'function'){ try{ normPath = legacyCoursePathRebase(normPath); }catch(_){} }
  if(coursePrefix && !normPath.startsWith(coursePrefix)){
    console.warn('[d1InsertLessons] lição fora do curso, descartada:', normPath.slice(0, 80), 'curso:', coursePrefix.slice(0, 60));
    return null;
  }
  const now = ctx.now || Date.now();
  const scannedAt = ctx.scannedAt || now;
  return {
    id: file.id || (courseHash + '_' + name),
    course_hash: courseHash,
    course_path: coursePath,
    lesson_path: normPath,
    lesson_name: name,
    lesson_type: type || null,
    mime_type: mt || null,
    ext: ext || null,
    size: (file.size === undefined ? null : file.size) || null,
    drive_index: courseIdx,
    parent_folder_path: coursePath,
    scanned_at: scannedAt,
    created_at: now,
    updated_at: now
  };
}

const D1_LESSON_BATCH = 50; // ★ v2.15.43 (CF-10): 8 → 50 — menos d1.batch por chamada de upsert (200 linhas: 25 → 4)

async function d1InsertLessonsDetailed(d1, courseHash, coursePath, driveIndex, lessons, scannedAt) {
  // ★ v2.15.7 (dedup): UMA grafia na escrita — o course_path gravado é
  //   sempre o canônico (o UNIQUE (course_path, lesson_path) do schema
  //   dedupa o re-scan sob outra grafia; o id do arquivo já dedupava).
  try { if (typeof canonicalCoursePath === 'function') coursePath = canonicalCoursePath(coursePath) || coursePath; } catch (_) {}
  let inserted = 0;
  const now = Date.now();
  const stmts = [];
  const builtRows = [];  // ★ v2.15.61 (Fase 2.3): linhas paralelas aos statements p/ o buffer
  // ★ v2.15.3 (W2): normalizar ANTES do INSERT — o path pode vir mutilado
  //   de um dotfile de outro worker ou da identidade gêmea ('/9://11:/X',
  //   '/6://11:/X'). O índice do drive é o DO CURSO (derivado do
  //   coursePath) — o rebase alinha o lesson_path com ele. O course_path é
  //   gravado verbatim (a UI casa totais por course_path exato); o
  //   lesson_path normalizado casa com ele por prefixo. Lição cujo caminho
  //   não começa com o prefixo do próprio curso é descartada (log), não
  //   inserida — nunca mais entra linha mutilada no D1.
  const mIdx = String(coursePath || '').match(/^\s*\/(\d+):/);
  const courseIdx = mIdx ? Number(mIdx[1]) : driveIndex;
  const coursePrefix = normalizeCoursePath(coursePath).replace(/\/+$/, '');
  // ★ v2.15.33-A: a linha é construída por buildLessonRow (partilhada
  //   com scan-upsert-lessons) — o INSERT aqui não muda (mesmos valores,
  //   mesma ordem de bind, mesmo descarte fora-do-curso).
  const _ctx = { coursePath, courseHash, courseIdx, coursePrefix, scannedAt: scannedAt || now, now };
  for (const lesson of lessons || []) {
    const row = buildLessonRow(lesson, _ctx);
    if (!row) continue;
    builtRows.push(row);
    stmts.push(d1.prepare('INSERT OR REPLACE INTO lessons (id, course_hash, course_path, lesson_path, lesson_name, lesson_type, mime_type, ext, size, drive_index, parent_folder_path, scanned_at, created_at, updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)').bind(
      row.id,
      row.course_hash,
      row.course_path,
      row.lesson_path,
      row.lesson_name,
      row.lesson_type,
      row.mime_type,
      row.ext,
      row.size,
      row.drive_index,
      row.parent_folder_path,
      row.scanned_at,
      row.created_at,
      row.updated_at));
  }
  // ★ v2.15.61 (Fase 2.3): as linhas que nem o retry individual
  //   aceita voltam em failedRows — quem chama (scan-and-save)
  //   manda-as para o buffer do drive 0 em vez de as perder.
  const failedRows = [];
  for (let i = 0; i < stmts.length; i += D1_LESSON_BATCH) {
    const chunk = stmts.slice(i, i + D1_LESSON_BATCH);
    const chunkRows = builtRows.slice(i, i + D1_LESSON_BATCH);
    try {
      await d1.batch(chunk);
      inserted += chunk.length;
    } catch (_) {
      // lote falhou — tenta um a um (best-effort, não derruba o scan)
      for (let j = 0; j < chunk.length; j++) { try { await chunk[j].run(); inserted++; } catch (_) { failedRows.push(chunkRows[j]); } }
    }
  }
  return { inserted, failedRows };
}
async function d1InsertLessons(d1, courseHash, coursePath, driveIndex, lessons, scannedAt) {
  const r = await d1InsertLessonsDetailed(d1, courseHash, coursePath, driveIndex, lessons, scannedAt);
  return r.inserted;
}

const HISTORY_MAX_ROWS_PER_RUN = 240;
const HISTORY_KV_PROGRESS_MAX_KEYS = 30;
const HISTORY_BACKFILL_MAX_USERS = 5;

function historyLessonName(lessonPath) {
  try {
    const clean = String(lessonPath || '').split('?')[0];
    const parts = clean.split('/').filter(Boolean);
    return decodeURIComponent(parts[parts.length - 1] || clean);
  } catch (_) { return String(lessonPath || ''); }
}

function historyCourseForPath(lessonPath, courses) {
  const p = String(lessonPath || '');
  let best = null;
  for (const c of (courses || [])) {
    const cp = String((c && c.course_path) || '');
    if (!cp) continue;
    if (p === cp || p.startsWith(cp.endsWith('/') ? cp : cp + '/')) {
      if (!best || cp.length > best.length) best = cp;
    }
  }
  return best;
}

function historyNormAt(v) {
  const n = Number(v);
  return (Number.isFinite(n) && n > 0) ? Math.floor(n) : 0;
}

async function historyUserCourses(d1, username) {
  try {
    const r = await d1.prepare('SELECT course_path, course_name, pdf_count FROM user_courses WHERE username = ? ORDER BY added_at DESC').bind(username).all();
    return r.results || [];
  } catch (_) {
    const _snap = (typeof loadTableSnapshot === 'function' ? await loadTableSnapshot('user_courses') : null);
    if (_snap) return _snap.filter(r => r.username === username).sort((a, b) => (b.added_at || 0) - (a.added_at || 0))
      .map(r => ({ course_path: r.course_path, course_name: r.course_name, pdf_count: r.pdf_count }));
    return [];
  }
}

// Lê as fontes de histórico de UM aluno. Cada fonte falha sozinha (try/catch
// por fonte) — Drive fora do ar não impede o KV e vice-versa.
async function historyCollectSources(username) {
  const watched = new Map(); // path -> {at, lastPosition}
  const events = []; // {path, at, minutes}
  const sources = { drive: false, kv: false };
  let bytes = 0;
  try {
    const gd0 = (typeof gds !== 'undefined' && gds) ? gds[0] : null;
    if (gd0) {
      const folderId = await gdiUserFolderId(gd0);
      if (folderId) {
        const st = await gdiReadUserState(gd0, folderId, username);
        if (st && typeof st === 'object') {
          sources.drive = true;
          const w = st.watched || {};
          for (const k in w) {
            if (!k) continue;
            watched.set(k, { at: historyNormAt(w[k] && w[k].at), lastPosition: null });
          }
          const r = st.resume || {};
          for (const k in r) {
            if (!k) continue;
            const at = historyNormAt(r[k] && r[k].at);
            const prev = watched.get(k);
            const lp = (r[k] && typeof r[k].t === 'number') ? r[k].t : (prev && prev.lastPosition) || null;
            if (!prev) watched.set(k, { at, lastPosition: lp });
            else if (at && (!prev.at || at > prev.at)) watched.set(k, { at, lastPosition: lp });
            else if (lp != null && prev.lastPosition == null) watched.set(k, { at: prev.at, lastPosition: lp });
          }
          if (st.last && st.last.path && !watched.has(st.last.path)) {
            watched.set(st.last.path, { at: historyNormAt(st.last.at), lastPosition: null });
          }
          const h = Array.isArray(st.history) ? st.history : [];
          for (const ev of h) {
            if (!ev || !ev.path) continue;
            events.push({ path: ev.path, at: historyNormAt(ev.at), minutes: Number(ev.minutes || ev.duration || 0) || 0 });
          }
          try { bytes = JSON.stringify(st).length; } catch (_) {}
        }
      }
    }
  } catch (_) { /* fonte Drive falhou — segue com o resto */ }
  try {
    const kv = (typeof getKV === 'function') ? getKV() : null;
    if (kv) {
      const listed = await kv.list({ prefix: 'progress:' + username + ':' });
      const keys = ((listed && listed.keys) || []).slice(0, HISTORY_KV_PROGRESS_MAX_KEYS);
      for (const k of keys) {
        try {
          const raw = await kv.get(k.name);
          if (!raw) continue;
          const d = JSON.parse(raw);
          sources.kv = true;
          for (const p of (Array.isArray(d.progress) ? d.progress : [])) {
            if (!p || !p.path || !p.watched) continue;
            const prev = watched.get(p.path);
            watched.set(p.path, {
              at: (prev && prev.at) || 0,
              lastPosition: (typeof p.lastPosition === 'number') ? p.lastPosition : (prev && prev.lastPosition) || null
            });
          }
        } catch (_) {}
      }
    }
  } catch (_) { /* fonte KV falhou — segue */ }
  return { watched, events, sources, bytes };
}

async function historyInsertBatch(d1, stmts) {
  let inserted = 0;
  for (let i = 0; i < stmts.length; i += D1_LESSON_BATCH) {
    const chunk = stmts.slice(i, i + D1_LESSON_BATCH);
    try {
      await d1.batch(chunk);
      inserted += chunk.length;
    } catch (_) {
      for (const s of chunk) { try { await s.run(); inserted++; } catch (_) {} }
    }
  }
  return inserted;
}


// ★ v2.15.29 (B) — grava a linha INTEIRA de history_migrations (14 cols)
//   quando o D1 já tem as colunas novas (d1EnsureSchema, ALTER guardado);
//   num D1 antigo sem elas, cai para o INSERT legado (10 cols) — a
//   migração nunca quebra por causa do schema, só perde os contadores novos.
async function driveMigSaveStatus(d1, row) {
  const now = Date.now();
  const r = row || {};
  const full = [r.username, r.status || 'pending',
    r.watched_total || 0, r.watched_done || 0,
    r.events_total || 0, r.events_done || 0,
    r.source_bytes || 0, (r.error == null ? null : String(r.error).slice(0, 200)),
    r.migrated_at || null, now,
    r.courses_total || 0, r.courses_done || 0,
    r.progress_files_total || 0, r.progress_files_done || 0];
  try {
    await d1.prepare(
      'INSERT OR REPLACE INTO history_migrations (username, status, watched_total, watched_done, events_total, events_done, source_bytes, error, migrated_at, updated_at, courses_total, courses_done, progress_files_total, progress_files_done) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)'
    ).bind(...full).run();
    return true;
  } catch (e) {
    try {
      await d1.prepare(
        'INSERT OR REPLACE INTO history_migrations (username, status, watched_total, watched_done, events_total, events_done, source_bytes, error, migrated_at, updated_at) VALUES (?,?,?,?,?,?,?,?,?,?)'
      ).bind(full[0], full[1], full[2], full[3], full[4], full[5], full[6], full[7], full[8], full[9]).run();
      return true;
    } catch (e2) { console.warn('[drive-migrate] status save failed:', e2.message); return false; }
  }
}

// Migra (uma fatia de) o histórico de UM aluno Drive+KV → D1.
// Idempotente: INSERT OR REPLACE / OR IGNORE + offset pelo que JÁ existe no D1
// (COUNT), então re-rodar não duplica nem pula linha. Retorna o progresso.
async function migrateUserHistory(d1, username, opts) {
  opts = opts || {};
  const maxRows = opts.maxRows || HISTORY_MAX_ROWS_PER_RUN;
  username = String(username || '').trim();
  if (!username) return { ok: false, error: 'no username' };
  if (!d1) return { ok: false, error: 'no d1' };
  try { await d1EnsureSchema(); } catch (_) {}
  const now = Date.now();
  let mig = null;
  try {
    mig = await d1.prepare('SELECT * FROM history_migrations WHERE username = ?').bind(username).first();
  } catch (_) {}
  if (mig && mig.status === 'done') {
    return { ok: true, username, done: true, alreadyDone: true, inserted: 0, remaining: 0,
      watched: { done: mig.watched_done || 0, total: mig.watched_total || 0 },
      events: { done: mig.events_done || 0, total: mig.events_total || 0 } };
  }
  let collected;
  try { collected = await historyCollectSources(username); }
  catch (e) { return { ok: false, username, error: 'collect failed: ' + String(e && e.message || e).slice(0, 120) }; }
  const courses = await historyUserCourses(d1, username);
  const watchedRows = [...collected.watched.entries()]
    .map(([path, v]) => ({ path, at: v.at || 0, lastPosition: v.lastPosition }))
    .sort((a, b) => (a.path < b.path ? -1 : (a.path > b.path ? 1 : 0)));
  const eventRows = collected.events.slice()
    .sort((a, b) => (a.at - b.at) || (a.path < b.path ? -1 : (a.path > b.path ? 1 : 0)));
  const totalWatched = watchedRows.length, totalEvents = eventRows.length;
  let haveWatched = 0, haveEvents = 0;
  try { const r = await d1.prepare('SELECT COUNT(*) AS c FROM user_watched WHERE username = ?').bind(username).first(); haveWatched = (r && r.c) || 0; } catch (_) {}
  try { const r = await d1.prepare('SELECT COUNT(*) AS c FROM user_history_events WHERE username = ?').bind(username).first(); haveEvents = (r && r.c) || 0; } catch (_) {}
  let budget = Math.max(0, maxRows), inserted = 0;
  // 1) aulas assistidas (primeiro)
  const wSlice = watchedRows.slice(haveWatched, haveWatched + budget);
  if (wSlice.length) {
    const stmts = wSlice.map(w => d1.prepare(
      'INSERT OR REPLACE INTO user_watched (username, lesson_path, lesson_name, course_path, watched_at, last_position, source, updated_at) VALUES (?,?,?,?,?,?,?,?)'
    ).bind(username, w.path, historyLessonName(w.path), historyCourseForPath(w.path, courses), w.at || null, w.lastPosition, 'drive', now));
    inserted += await historyInsertBatch(d1, stmts);
    budget -= wSlice.length;
  }
  // 2) eventos da timeline
  const eSlice = eventRows.slice(haveEvents, haveEvents + budget);
  if (eSlice.length) {
    const stmts = eSlice.map(ev => d1.prepare(
      'INSERT OR IGNORE INTO user_history_events (username, lesson_path, lesson_name, course_path, event_at, minutes, source, created_at) VALUES (?,?,?,?,?,?,?,?)'
    ).bind(username, ev.path, historyLessonName(ev.path), historyCourseForPath(ev.path, courses), ev.at || now, ev.minutes || 0, 'drive', now));
    inserted += await historyInsertBatch(d1, stmts);
    budget -= eSlice.length;
  }
  const newHaveWatched = haveWatched + wSlice.length;
  const newHaveEvents = haveEvents + eSlice.length;
  const allInserted = (newHaveWatched >= totalWatched) && (newHaveEvents >= totalEvents);
  // Sem fonte (sem arquivo no Drive e sem KV) e nada para migrar: fica 'pending'
  // para tentar de novo no próximo login — aluno novo sem histórico ainda.
  const hasSource = !!(collected.sources.drive || collected.sources.kv || totalWatched > 0 || totalEvents > 0);
  const done = allInserted && hasSource;
  // sem fonte e nada para migrar: 'pending' (tenta de novo no próximo login);
  // com fonte mas incompleto: 'partial' (retoma de onde parou).
  const status = done ? 'done' : (hasSource ? 'partial' : 'pending');
  // ★ v2.15.29 (B): grava via driveMigSaveStatus p/ PRESERVAR os contadores
  //   da migração Drive→D1 (courses_*/progress_files_*) que o INSERT de 10
  //   cols apagava a cada login do admin.
  await driveMigSaveStatus(d1, { username, status, watched_total: totalWatched, watched_done: newHaveWatched, events_total: totalEvents, events_done: newHaveEvents, source_bytes: collected.bytes || 0, error: null, migrated_at: done ? now : null, courses_total: (mig && mig.courses_total) || 0, courses_done: (mig && mig.courses_done) || 0, progress_files_total: (mig && mig.progress_files_total) || 0, progress_files_done: (mig && mig.progress_files_done) || 0 });
  const remaining = Math.max(0, (totalWatched - newHaveWatched) + (totalEvents - newHaveEvents));
  return { ok: true, username, done, inserted, remaining, status,
    watched: { done: newHaveWatched, total: totalWatched },
    events: { done: newHaveEvents, total: totalEvents } };
}

// Backfill: migra o histórico de todos os alunos (ou de um só), respeitando o
// teto de subrequests por chamada (fatia de linhas + máx. de alunos). O admin
// chama repetidamente (poll) até allDone=true.
async function historyBackfill(d1, opts) {
  opts = opts || {};
  if (!d1) return { ok: false, error: 'no d1' };
  try { await d1EnsureSchema(); } catch (_) {}
  let usernames = [];
  if (opts.username) {
    usernames = [String(opts.username).trim()].filter(Boolean);
  } else {
    const set = new Set();
    try { const r = await d1.prepare('SELECT DISTINCT username FROM user_courses').all(); for (const x of (r.results || [])) if (x.username) set.add(x.username); } catch (_) {}
    try { const r = await d1.prepare('SELECT username FROM users').all(); for (const x of (r.results || [])) if (x.username) set.add(x.username); } catch (_) {}
    try { const r = await d1.prepare('SELECT DISTINCT username FROM history_migrations').all(); for (const x of (r.results || [])) if (x.username) set.add(x.username); } catch (_) {}
    try { for (const u of ((typeof authConfig !== 'undefined' && authConfig.users_list) || [])) if (u && u.username) set.add(u.username); } catch (_) {}
    usernames = [...set].sort();
  }
  const budget = opts.maxRows || HISTORY_MAX_ROWS_PER_RUN;
  const maxUsers = opts.maxUsers || HISTORY_BACKFILL_MAX_USERS;
  let used = 0, processed = 0;
  const users = [];
  for (const u of usernames) {
    if (processed >= maxUsers || used >= budget) { users.push({ username: u, done: false, deferred: true }); continue; }
    processed++;
    let res;
    try { res = await migrateUserHistory(d1, u, { maxRows: budget - used }); }
    catch (e) { res = { ok: false, username: u, error: String(e && e.message || e).slice(0, 120) }; }
    used += (res && res.inserted) || 0;
    users.push({ username: u, done: !!(res && res.done), alreadyDone: !!(res && res.alreadyDone),
      watched: res.watched || { done: 0, total: 0 }, events: res.events || { done: 0, total: 0 },
      remaining: (res && res.remaining) || 0, error: (res && res.error) || null });
  }
  return { ok: true, users, allDone: users.every(u => u.done), processed, rowsInserted: used };
}


// ═══════════════════════════════════════════════════════════════════════════
// ★ v2.15.29 (B) — MIGRAÇÃO Drive → D1 (estado por usuário), endpoint admin
//   GET  /admin?api=migrate-drive-to-d1?dry-run=1&username=&maxUsers=&maxRows=&maxCoursesPerUser=
//        → dry-run (omissão no GET): SÓ contagens, NADA escrito.
//   POST /admin?api=migrate-drive-to-d1 {username?, dryRun?, maxUsers?, maxRows?, maxCoursesPerUser?}
//        → run (migração real) salvo dryRun:true.
//   Gate de admin: o mesmo de handleAdmin → admHandleApi (cookie de sessão
//   → ADMIN_USERS). Sem auth nova, sem segredo novo, sem deploy.
//   Fontes (todas SÓ leitura no Drive; escrita SÓ no D1):
//     user_courses ← "AULAS - ESTADO DOS ALUNOS/<u>.courses.json" (per-user,
//       fonte de verdade v1.0.116) + ".meggy.ai/courses/general_courses.json"
//       (legado: entries c/ users[] contendo o usuário e sem ele em
//       hiddenFor[]; o per-user vence em conflito de course_path).
//     user_watched + user_history_events ← "<u>.json" (user state) + KV
//       "progress:<u>:<hash>" (ambos via historyCollectSources, REUTILIZADO)
//       + ".meggy.ai/courses/<hash>/user-<u>.json" (progress[] c/
//       watched=true; at = savedAt do ficheiro).
//   Idempotência: diff por chave contra o D1 antes de escrever (curso
//   ausente OU addedAt do Drive > added_at do D1; watched ausente OU at do
//   Drive > watched_at do D1; evento pela chave path|at, c/ guarda p/ at=0).
//   Re-correr não duplica e o Drive mais recente vence.
//   Resumo: maxUsers usuários + maxRows linhas por invocação; o admin repete
//   a chamada (poll) até allDone=true. progress_files_done conta os hashes
//   já varridos (ordem ordenada; assume a lista de cursos estável entre
//   runs — ver NOTES.md). Erro num usuário → status 'error' em
//   history_migrations e os restantes continuam.
//   NÃO migrado aqui: users, isa_cache.json, isa_shared_*.json (backfill
//   próprio), MDs .meggy.ai/progress/, <u>.plan.json, materiais
//   .meggy.ai/<kind>/, lessons/scan_status/featured_courses, user-<u>.json
//   órfãos fora da lista de cursos do usuário (ver NOTES.md).
// ═══════════════════════════════════════════════════════════════════════════
const DRIVE_MIGRATE_MAX_USERS = 2;
const DRIVE_MIGRATE_MAX_ROWS_PER_USER = 120;
const DRIVE_MIGRATE_MAX_COURSES_PER_USER = 5;
const DRIVE_MIGRATE_MAX_LIST_PAGES = 3;

function driveMigCanon(p) {
  try { if (typeof canonicalCoursePath === 'function') return canonicalCoursePath(p) || p; } catch (_) {}
  return p;
}
function driveMigSafeUser(u) {
  // Mesmo sanitize de gdiSaveUserProgressToDrive (user-<u>.json).
  return String(u || '').replace(/[^a-zA-Z0-9_.-]/g, '_').slice(0, 50);
}

// Lista ficheiros de UMA pasta do Drive (id+nome, até 3 páginas de 100).
// SÓ leitura — nunca cria a pasta.
async function driveMigListStateFolder(gd0, folderId) {
  const out = [];
  let pageToken = null;
  for (let page = 0; page < DRIVE_MIGRATE_MAX_LIST_PAGES; page++) {
    const opts = await gd0.requestOptions();
    const q = "'" + folderId + "' in parents and trashed = false";
    const params = { includeItemsFromAllDrives: 'true', supportsAllDrives: 'true', q, fields: 'files(id,name),nextPageToken', pageSize: '100' };
    if (pageToken) params.pageToken = pageToken;
    const r = await fetch('https://www.googleapis.com/drive/v3/files?' + enQuery(params), opts);
    if (!r.ok) break;
    const j = await r.json();
    for (const f of (j.files || [])) if (f && f.name) out.push({ id: f.id, name: f.name });
    pageToken = (j && j.nextPageToken) || null;
    if (!pageToken) break;
  }
  return out;
}

// Resolver SÓ-leitura de subpasta (nunca cria — ao contrário de
// gdiSharedMeggySubfolderId/gdiSharedMeggyDeepSubfolderId, que criam a
// pasta quando falta). Memo por isolate (inclui null).
async function driveMigFindFolderId(gd0, parentId, name) {
  if (!gd0.__driveMigFolders) gd0.__driveMigFolders = {};
  const key = parentId + '/' + name;
  if (gd0.__driveMigFolders[key] !== undefined) return gd0.__driveMigFolders[key];
  let id = null;
  try {
    const opts = await gd0.requestOptions();
    const q = "'" + parentId + "' in parents and name = '" + driveEscape(name) + "' and trashed = false and mimeType = 'application/vnd.google-apps.folder'";
    const r = await fetch('https://www.googleapis.com/drive/v3/files?' + enQuery({ includeItemsFromAllDrives: 'true', supportsAllDrives: 'true', q, fields: 'files(id)', pageSize: '1' }), opts);
    if (r.ok) { const j = await r.json(); if (j.files && j.files[0]) id = j.files[0].id; }
  } catch (_) {}
  gd0.__driveMigFolders[key] = id;
  return id;
}
async function driveMigFindFileId(gd0, parentId, name) {
  try {
    const opts = await gd0.requestOptions();
    const q = "'" + parentId + "' in parents and name = '" + driveEscape(name) + "' and trashed = false";
    const r = await fetch('https://www.googleapis.com/drive/v3/files?' + enQuery({ includeItemsFromAllDrives: 'true', supportsAllDrives: 'true', q, fields: 'files(id)', pageSize: '1' }), opts);
    if (!r.ok) return null;
    const j = await r.json();
    return (j.files && j.files[0]) ? j.files[0].id : null;
  } catch (_) { return null; }
}
async function driveMigDownload(gd0, fileId) {
  try {
    const opts = await gd0.requestOptions();
    const r = await fetch('https://www.googleapis.com/drive/v3/files/' + fileId + '?alt=media&supportsAllDrives=true', opts);
    if (!r.ok) return null;
    return await r.text();
  } catch (_) { return null; }
}

// Descobre usuários: D1 (user_courses, users, history_migrations) +
// authConfig.users_list + stems de ficheiros no Drive. O stem é o safeName;
// resolve para o username real quando conhecido (o D1 grava o real).
async function driveMigDiscoverUsernames(d1, gd0, folderId) {
  const set = new Set();
  const add = (u) => { u = String(u || '').trim(); if (u) set.add(u); };
  try { const r = await d1.prepare('SELECT DISTINCT username FROM user_courses').all(); for (const x of (r.results || [])) add(x.username); } catch (_) {}
  try { const r = await d1.prepare('SELECT username FROM users').all(); for (const x of (r.results || [])) add(x.username); } catch (_) {}
  try { const r = await d1.prepare('SELECT DISTINCT username FROM history_migrations').all(); for (const x of (r.results || [])) add(x.username); } catch (_) {}
  try { for (const u of ((typeof authConfig !== 'undefined' && authConfig.users_list) || [])) if (u && u.username) add(u.username); } catch (_) {}
  const bySafe = new Map();
  for (const u of set) bySafe.set(String(u).replace(/[^a-zA-Z0-9._@-]/g, '_'), u);
  try {
    const files = await driveMigListStateFolder(gd0, folderId);
    for (const f of files) {
      if (f.name === 'isa_cache.json' || f.name === 'isa_shared_summaries.json' || f.name === 'isa_shared_flashcards.json' || f.name === 'general_courses.json') continue;
      const m = /^(.+?)\.(courses\.json|plan\.json|json)$/.exec(f.name || '');
      if (!m) continue;
      // Stem não-ganancioso: 'ana.courses.json' → 'ana' (não 'ana.courses').
      if (!m) continue;
      add(bySafe.get(m[1]) || m[1]);
    }
  } catch (_) {}
  return [...set].sort();
}

// Cursos de UM usuário no Drive: per-user + general (legado), por
// course_path canónico; o per-user vence em conflito.
async function driveMigUserCoursesFromDrive(gd0, folderId, username, general) {
  const byPath = new Map();
  let perUserFound = false, perUserUpdatedAt = 0;
  try {
    const data = await gdiUserCoursesReadDrive(gd0, folderId, username);  // ★ v2.15.29-fusion: a migração lê o Drive (fonte), não o shim D1
    if (data && Array.isArray(data.courses) && data.courses.length) {
      perUserFound = true;
      perUserUpdatedAt = data.updatedAt || 0;
      for (const c of data.courses) {
        const cp = driveMigCanon(c.coursePath || '');
        if (!cp) continue;
        byPath.set(cp, { coursePath: cp, courseName: c.courseName || '', pdfCount: c.pdfCount || 0, icon: c.icon || '', color: c.color || '', addedAt: c.addedAt || 0, source: 'per-user' });
      }
    }
  } catch (_) {}
  let generalFound = 0;
  for (const c of (general || [])) {
    if (!c || !c.coursePath) continue;
    if (c.hiddenFor && c.hiddenFor.includes(username)) continue;
    if (!c.users || !c.users.length || !c.users.includes(username)) continue;
    const cp = driveMigCanon(c.coursePath);
    if (!cp || byPath.has(cp)) continue;
    generalFound++;
    byPath.set(cp, { coursePath: cp, courseName: c.courseName || '', pdfCount: c.pdfCount || 0, icon: c.icon || '', color: c.color || '', addedAt: c.addedAt || 0, source: 'general' });
  }
  return { courses: [...byPath.values()].sort((a, b) => (a.coursePath < b.coursePath ? -1 : 1)), perUserFound, generalFound, perUserUpdatedAt };
}

// Lê os user-<u>.json de UMA fatia dos cursos do usuário (hashes
// ordenados; skipCount = progress_files_done da run anterior).
// Shape do ficheiro (gdiSaveUserProgressToDrive): {coursePath, courseHash,
// username, progress:[{path, watched, lastPosition}], totalLessons, savedAt}.
async function driveMigUserProgressFiles(gd0, username, courses, skipCount, maxFiles) {
  const watched = new Map();
  const hashes = (courses || []).map((c) => courseHashFromPath(c.coursePath)).filter(Boolean);
  hashes.sort();
  const total = hashes.length;
  const slice = hashes.slice(skipCount || 0, (skipCount || 0) + (maxFiles || DRIVE_MIGRATE_MAX_COURSES_PER_USER));
  const empty = { watched, total, filesFound: 0, filesRead: 0, processed: 0, bytes: 0 };
  if (!slice.length) return empty;
  const rootId = (gd0.root && gd0.root.id) || gd0.rid || gd0.rootId;
  if (!rootId) return empty;
  const megaId = await driveMigFindFolderId(gd0, rootId, '.meggy.ai');
  if (!megaId) return empty;
  const coursesId = await driveMigFindFolderId(gd0, megaId, 'courses');
  if (!coursesId) return empty;
  const safeUser = driveMigSafeUser(username);
  let filesFound = 0, filesRead = 0, bytes = 0;
  for (const hash of slice) {
    const hashId = await driveMigFindFolderId(gd0, coursesId, hash);
    if (!hashId) continue;
    const fileId = await driveMigFindFileId(gd0, hashId, 'user-' + safeUser + '.json');
    if (!fileId) continue;
    filesFound++;
    const txt = await driveMigDownload(gd0, fileId);
    if (!txt) continue;
    bytes += txt.length;
    let d = null;
    try { d = JSON.parse(txt); } catch (_) { continue; }
    if (!d || !Array.isArray(d.progress)) continue;
    filesRead++;
    const at = historyNormAt(d.savedAt);
    for (const p of d.progress) {
      if (!p || !p.path || !p.watched) continue;
      const prev = watched.get(p.path);
      watched.set(p.path, { at: Math.max((prev && prev.at) || 0, at), lastPosition: (typeof p.lastPosition === 'number') ? p.lastPosition : (prev && prev.lastPosition) || null });
    }
  }
  return { watched, total, filesFound, filesRead, processed: slice.length, bytes };
}

// Coleta (só leitura) de UM usuário: cursos + histórico (state + KV +
// ficheiros de progresso) + diff contra o D1. NÃO escreve nada — o dry-run
// usa-a diretamente e o run usa-a antes de escrever.
async function driveMigCollectUser(d1, gd0, folderId, username, general, opts) {
  opts = opts || {};
  const maxFiles = opts.maxCoursesPerUser || DRIVE_MIGRATE_MAX_COURSES_PER_USER;
  let prev = null;
  try { prev = await d1.prepare('SELECT * FROM history_migrations WHERE username = ?').bind(username).first(); } catch (_) {}
  // Dry-run ignora o skip: conta a fatia a partir do início (mesmo teto).
  const skip = opts.ignoreSkip ? 0 : ((prev && prev.progress_files_done) || 0);
  const drv = await driveMigUserCoursesFromDrive(gd0, folderId, username, general);
  let collected;
  try { collected = await historyCollectSources(username); }
  catch (e) { collected = { watched: new Map(), events: [], sources: { drive: false, kv: false }, bytes: 0 }; }
  const prog = await driveMigUserProgressFiles(gd0, username, drv.courses, skip, maxFiles);
  for (const [path, v] of prog.watched) {
    const prevW = collected.watched.get(path);
    if (!prevW) collected.watched.set(path, { at: v.at, lastPosition: v.lastPosition });
    else collected.watched.set(path, { at: Math.max(prevW.at || 0, v.at || 0), lastPosition: (v.lastPosition != null ? v.lastPosition : prevW.lastPosition) });
  }
  const d1Courses = new Map();
  try { const r = await d1.prepare('SELECT course_path, added_at FROM user_courses WHERE username = ?').bind(username).all(); for (const x of (r.results || [])) d1Courses.set(x.course_path, x.added_at || 0); } catch (_) {}
  const d1Watched = new Map();
  try { const r = await d1.prepare('SELECT lesson_path, watched_at FROM user_watched WHERE username = ?').bind(username).all(); for (const x of (r.results || [])) d1Watched.set(x.lesson_path, x.watched_at || 0); } catch (_) {}
  const d1Events = new Set();
  const d1EventPaths = new Set();
  try { const r = await d1.prepare('SELECT lesson_path, event_at FROM user_history_events WHERE username = ?').bind(username).all(); for (const x of (r.results || [])) { d1Events.add(x.lesson_path + '|' + x.event_at); d1EventPaths.add(x.lesson_path); } } catch (_) {}
  const courses = drv.courses.map((c) => ({ ...c, alreadyInD1: d1Courses.has(c.coursePath), fresher: d1Courses.has(c.coursePath) && (c.addedAt || 0) > (d1Courses.get(c.coursePath) || 0) }));
  const watchedRows = [...collected.watched.entries()].map(([path, v]) => ({ path, at: v.at || 0, lastPosition: v.lastPosition })).sort((a, b) => (a.path < b.path ? -1 : 1));
  const eventRows = (collected.events || []).slice().sort((a, b) => (a.at - b.at) || (a.path < b.path ? -1 : 1));
  const toMigrateWatched = watchedRows.filter((w) => !d1Watched.has(w.path) || (w.at || 0) > (d1Watched.get(w.path) || 0));
  // Evento c/ at=0 é gravado no D1 c/ event_at=now (regra de migrateUserHistory),
  // por isso o diff casa-o só pelo path — senão duplicava a cada re-run.
  const toMigrateEvents = eventRows.filter((ev) => !d1Events.has(ev.path + '|' + (ev.at || 0)) && !((ev.at || 0) <= 0 && d1EventPaths.has(ev.path)));
  return { username,
    courses: { total: drv.courses.length, alreadyInD1: courses.filter((c) => c.alreadyInD1 && !c.fresher).length, toMigrate: courses.filter((c) => !c.alreadyInD1 || c.fresher).length, list: courses },
    watched: { total: watchedRows.length, alreadyInD1: watchedRows.length - toMigrateWatched.length, toMigrate: toMigrateWatched.length, rows: watchedRows, toMigrateRows: toMigrateWatched },
    events: { total: eventRows.length, alreadyInD1: eventRows.length - toMigrateEvents.length, toMigrate: toMigrateEvents.length, rows: eventRows, toMigrateRows: toMigrateEvents },
    progressFiles: { total: prog.total, found: prog.filesFound, read: prog.filesRead, processed: skip + prog.processed, unscanned: Math.max(0, prog.total - (skip + prog.processed)) },
    sources: { drive: !!collected.sources.drive, kv: !!collected.sources.kv, perUserCourses: drv.perUserFound, generalCourses: drv.generalFound, progressFilesFound: prog.filesFound },
    bytes: (collected.bytes || 0) + prog.bytes };
}

// Upsert do histórico a partir da coleta (mesmo SQL de migrateUserHistory).
async function driveMigUpsertHistory(d1, username, watchedRows, eventRows, courses, budget) {
  let inserted = 0;
  const now = Date.now();
  const wSlice = (watchedRows || []).slice(0, Math.max(0, budget));
  if (wSlice.length) {
    const stmts = wSlice.map((w) => d1.prepare(
      'INSERT OR REPLACE INTO user_watched (username, lesson_path, lesson_name, course_path, watched_at, last_position, source, updated_at) VALUES (?,?,?,?,?,?,?,?)'
    ).bind(username, w.path, historyLessonName(w.path), historyCourseForPath(w.path, courses), w.at || null, w.lastPosition, 'drive', now));
    inserted += await historyInsertBatch(d1, stmts);
  }
  const left = Math.max(0, budget - wSlice.length);
  const eSlice = (eventRows || []).slice(0, left);
  if (eSlice.length) {
    const stmts = eSlice.map((ev) => d1.prepare(
      'INSERT OR IGNORE INTO user_history_events (username, lesson_path, lesson_name, course_path, event_at, minutes, source, created_at) VALUES (?,?,?,?,?,?,?,?)'
    ).bind(username, ev.path, historyLessonName(ev.path), historyCourseForPath(ev.path, courses), ev.at || now, ev.minutes || 0, 'drive', now));
    inserted += await historyInsertBatch(d1, stmts);
  }
  return { inserted, watchedInserted: wSlice.length, eventsInserted: eSlice.length };
}

// Migra UM usuário (run). Erro de coleta/escrita → status 'error' na linha
// dele, sem abortar os restantes (o orquestrador continua).
async function driveMigRunUser(d1, gd0, folderId, username, general, opts) {
  opts = opts || {};
  const maxRows = opts.maxRows || DRIVE_MIGRATE_MAX_ROWS_PER_USER;
  const now = Date.now();
  let prev = null;
  try { prev = await d1.prepare('SELECT * FROM history_migrations WHERE username = ?').bind(username).first(); } catch (_) {}
  const wasDone = !!(prev && prev.status === 'done');
  let inserted = 0, coursesDone = 0;
  const errStatus = async (status, msg, col) => {
    await driveMigSaveStatus(d1, { username, status, error: msg,
      courses_total: (col && col.courses.total) || (prev && prev.courses_total) || 0,
      courses_done: col ? coursesDone : (prev && prev.courses_done) || 0,
      progress_files_total: (col && col.progressFiles.total) || (prev && prev.progress_files_total) || 0,
      progress_files_done: col ? col.progressFiles.processed : (prev && prev.progress_files_done) || 0 });
  };
  let col;
  try {
    col = await driveMigCollectUser(d1, gd0, folderId, username, general, opts);
  } catch (e) {
    const msg = 'collect failed: ' + String(e && e.message || e).slice(0, 120);
    await errStatus('error', msg, null);
    return { ok: false, username, done: false, error: msg, courses: { total: 0, alreadyInD1: 0, toMigrate: 0 }, watched: { done: 0, total: 0 }, events: { done: 0, total: 0 }, progressFiles: { total: 0, found: 0, read: 0, processed: 0, unscanned: 0 }, remaining: 0 };
  }
  const toMigrateCourses = col.courses.list.filter((c) => !c.alreadyInD1 || c.fresher);
  // Já estava done e nada mudou no Drive → não escreve nada.
  if (wasDone && !toMigrateCourses.length && !col.watched.toMigrate && !col.events.toMigrate && col.progressFiles.unscanned <= 0) {
    return { ok: true, username, done: true, alreadyDone: true, inserted: 0, remaining: 0,
      courses: { total: col.courses.total, alreadyInD1: col.courses.alreadyInD1, toMigrate: 0 },
      watched: { done: col.watched.total - col.watched.toMigrate, total: col.watched.total, alreadyInD1: col.watched.alreadyInD1, toMigrate: 0 },
      events: { done: col.events.total - col.events.toMigrate, total: col.events.total, alreadyInD1: col.events.alreadyInD1, toMigrate: 0 },
      progressFiles: col.progressFiles };
  }
  try {
    // 1) cursos (só ausentes ou mais recentes)
    if (toMigrateCourses.length) {
      const stmts = toMigrateCourses.map((c) => d1.prepare(
        'INSERT OR REPLACE INTO user_courses (username, course_path, course_name, pdf_count, icon, color, added_at) VALUES (?,?,?,?,?,?,?)'
      ).bind(username, c.coursePath, c.courseName || '', c.pdfCount || 0, c.icon || '', c.color || '', c.addedAt || now));
      inserted += await historyInsertBatch(d1, stmts);
    }
    coursesDone = 0;
    // 2) histórico (assistidas + eventos) a partir da coleta única
    const budget = Math.max(0, maxRows - inserted);
    const h = await driveMigUpsertHistory(d1, username, col.watched.toMigrateRows, col.events.toMigrateRows, col.courses.list, budget);
    inserted += h.inserted;
  } catch (e) {
    const msg = 'write failed: ' + String(e && e.message || e).slice(0, 120);
    await errStatus('error', msg, col);
    return { ok: false, username, done: false, error: msg, courses: col.courses, watched: { done: 0, total: col.watched.total }, events: { done: 0, total: col.events.total }, progressFiles: col.progressFiles, remaining: 0 };
  }
  // Cursos feitos = nº de cursos do Drive presentes no D1 (re-lido — o
  // batch pode engolir um erro por statement e o contador de inserted
  // sobre-contar; a releitura é a fonte de verdade).
  try { const r = await d1.prepare('SELECT course_path FROM user_courses WHERE username = ?').bind(username).all(); const have = new Set((r.results || []).map((x) => x.course_path)); coursesDone = col.courses.list.filter((c) => have.has(c.coursePath)).length; } catch (_) {}
  // Contagens finais no D1 (fonte de verdade p/ o status).
  let haveWatched = 0, haveEvents = 0;
  try { const r = await d1.prepare('SELECT COUNT(*) AS c FROM user_watched WHERE username = ?').bind(username).first(); haveWatched = (r && r.c) || 0; } catch (_) {}
  try { const r = await d1.prepare('SELECT COUNT(*) AS c FROM user_history_events WHERE username = ?').bind(username).first(); haveEvents = (r && r.c) || 0; } catch (_) {}
  const hasSource = !!(col.sources.drive || col.sources.kv || col.courses.total > 0 || col.watched.total > 0 || col.events.total > 0 || col.progressFiles.found > 0);
  const done = hasSource && coursesDone >= col.courses.total && haveWatched >= col.watched.total && haveEvents >= col.events.total && col.progressFiles.unscanned <= 0;
  const status = done ? 'done' : (hasSource ? 'partial' : 'pending');
  await driveMigSaveStatus(d1, { username, status, watched_total: col.watched.total, watched_done: haveWatched, events_total: col.events.total, events_done: haveEvents, source_bytes: col.bytes, error: null, migrated_at: done ? now : null, courses_total: col.courses.total, courses_done: coursesDone, progress_files_total: col.progressFiles.total, progress_files_done: col.progressFiles.processed });
  const remaining = Math.max(0, (col.courses.total - coursesDone) + (col.watched.total - haveWatched) + (col.events.total - haveEvents) + col.progressFiles.unscanned);
  return { ok: true, username, done, inserted, remaining, status,
    courses: { total: col.courses.total, alreadyInD1: col.courses.alreadyInD1, toMigrate: toMigrateCourses.length },
    watched: { done: haveWatched, total: col.watched.total, alreadyInD1: col.watched.alreadyInD1, toMigrate: col.watched.toMigrate },
    events: { done: haveEvents, total: col.events.total, alreadyInD1: col.events.alreadyInD1, toMigrate: col.events.toMigrate },
    progressFiles: col.progressFiles };
}

// Orquestrador: todos os usuários (ou um só), N por invocação. O admin
// repete a chamada até allDone=true. Dry-run nunca escreve no D1 (nem
// d1EnsureSchema corre) — as leituras toleram tabelas ausentes (0 linhas).
// ★ v2.15.31 (A) — retoma do bulk: antes do loop, os estados de
//   history_migrations são carregados NUMA só query e os usuários já
//   resolvidos são saltados SEM coletar (sem gastar slots de maxUsers nem
//   orçamento de maxRows): status 'done', e status 'pending' com os quatro
//   totais a zero (a última coleta não achou fonte nem nada p/ migrar).
//   Justificação do salto do 'pending': 'pending' significa que a última
//   coleta não achou nada; dados novos no Drive depois disso são apanhados
//   pelo migrateUserHistory no próximo login do usuário (watched/eventos)
//   e pelo caminho `username` (coleta completa, inclui cursos) — o endpoint
//   bulk serve p/ completar, não p/ sync contínuo. O residual v2.15.29 já
//   regista que drift no Drive após 'done' só se re-migra via endpoint.
//   Sem isto, o orquestrador redescobria a lista alfabética e processava
//   sempre os PRIMEIROS maxUsers por chamada (Passo 27: só o contorno
//   `username` fazia a migração avançar; allDone nunca ficava true em
//   listas >5). O caminho `username` NÃO salta (processa como hoje).
async function driveMigrateAll(d1, opts) {
  opts = opts || {};
  const dryRun = !!opts.dryRun;
  const maxUsers = opts.maxUsers || DRIVE_MIGRATE_MAX_USERS;
  const maxRowsTotal = opts.maxRows || HISTORY_MAX_ROWS_PER_RUN;
  const maxCoursesPerUser = opts.maxCoursesPerUser || DRIVE_MIGRATE_MAX_COURSES_PER_USER;
  if (!d1) return { ok: false, error: 'no d1' };
  const gd0 = (typeof gds !== 'undefined' && gds) ? gds[0] : null;
  if (!gd0) return { ok: false, error: 'no drive' };
  if (!dryRun) { try { await d1EnsureSchema(); } catch (_) {} }
  let folderId = null;
  try { folderId = await gdiUserFolderId(gd0); } catch (_) {}
  if (!folderId) return { ok: false, error: 'no folder' };
  let general = [];
  try { general = await gdiGeneralCoursesRead(gd0, folderId); } catch (_) { general = []; }
  let usernames = [];
  if (opts.username) usernames = [String(opts.username).trim()].filter(Boolean);
  else usernames = await driveMigDiscoverUsernames(d1, gd0, folderId);
  // ★ v2.15.31 (A): estados p/ o salto (só no caminho sem filtro; UMA query).
  //   Tabela/colunas ausentes (D1 antigo, dry-run sem d1EnsureSchema) → mapa
  //   vazio = comportamento atual (nada saltado).
  let migStates = new Map();
  if (!opts.username) {
    try {
      const migRows = await d1.prepare('SELECT username, status, watched_total, watched_done, events_total, events_done, courses_total, courses_done, progress_files_total, progress_files_done FROM history_migrations').all();
      for (const row of ((migRows && migRows.results) || [])) if (row && row.username) migStates.set(row.username, row);
    } catch (_) { migStates = new Map(); }
  }
  let used = 0, processed = 0;
  const users = [];
  for (const u of usernames) {
    // ★ v2.15.31 (A): salto sem coletar (só sem filtro). Não consome slots
    //   de maxUsers nem orçamento de maxRows; `processed` conta só os
    //   processados de facto. O resto do loop fica igual (deferred p/ além
    //   do teto, erro por usuário não aborta os restantes).
    if (!opts.username) {
      const st = migStates.get(u);
      if (st) {
        const n0 = (v) => (v == null ? 0 : v);
        const noTotals = n0(st.courses_total) === 0 && n0(st.watched_total) === 0 && n0(st.events_total) === 0 && n0(st.progress_files_total) === 0;
        if (st.status === 'done' || (st.status === 'pending' && noTotals)) {
          const entry = { ok: true, username: u, done: true, skipped: true, inserted: 0, remaining: 0,
            courses: { total: n0(st.courses_total), done: n0(st.courses_done), toMigrate: 0 },
            watched: { done: n0(st.watched_done), total: n0(st.watched_total), toMigrate: 0 },
            events: { done: n0(st.events_done), total: n0(st.events_total), toMigrate: 0 },
            progressFiles: { total: n0(st.progress_files_total), processed: n0(st.progress_files_done), unscanned: 0 } };
          if (st.status === 'done') entry.alreadyDone = true;
          else entry.nothingToMigrate = true;
          users.push(entry);
          continue;
        }
      }
    }
    if (processed >= maxUsers || used >= maxRowsTotal) { users.push({ username: u, done: false, deferred: true }); continue; }
    processed++;
    let res;
    try {
      if (dryRun) {
        const col = await driveMigCollectUser(d1, gd0, folderId, u, general, { maxCoursesPerUser, ignoreSkip: true });
        res = { ok: true, username: u, done: false, dryRun: true, inserted: 0, remaining: 0,
          courses: { total: col.courses.total, alreadyInD1: col.courses.alreadyInD1, toMigrate: col.courses.toMigrate },
          watched: { done: col.watched.total - col.watched.toMigrate, total: col.watched.total, alreadyInD1: col.watched.alreadyInD1, toMigrate: col.watched.toMigrate },
          events: { done: col.events.total - col.events.toMigrate, total: col.events.total, alreadyInD1: col.events.alreadyInD1, toMigrate: col.events.toMigrate },
          progressFiles: col.progressFiles, sources: col.sources };
        used += col.courses.toMigrate + col.watched.toMigrate + col.events.toMigrate;
      } else {
        res = await driveMigRunUser(d1, gd0, folderId, u, general, { maxRows: Math.max(0, maxRowsTotal - used), maxCoursesPerUser });
        used += (res && res.inserted) || 0;
      }
    } catch (e) {
      res = { ok: false, username: u, error: String(e && e.message || e).slice(0, 120) };
    }
    users.push(res);
  }
  const totals = { courses: 0, watched: 0, events: 0 };
  for (const u of users) { if (!u) continue; totals.courses += (u.courses && u.courses.toMigrate) || 0; totals.watched += (u.watched && u.watched.total) || 0; totals.events += (u.events && u.events.total) || 0; }
  // ★ v2.15.31 (fusão): resolvido = done OU saltado. Um processado c/
  //   done:false e remaining:0 é EXATAMENTE o caso 'pending' sem fonte
  //   (done=false ∧ remaining=0 ⟺ !hasSource) — contá-lo como resolvido
  //   faria um pedido `username` explícito p/ um usuário desconhecido
  //   devolver allDone=true (harness B, X7a). A convergência mantém-se:
  //   o 1º processamento grava a linha 'pending' c/ totais a zero (X7b) e
  //   a chamada seguinte sem filtro salta-o como settled. Deferred ou
  //   com erro → allDone=false.
  return { ok: true, mode: dryRun ? 'dry-run' : 'run', users, allDone: dryRun ? false : users.every((u) => u && (u.done === true || u.skipped === true)), processed, rowsInserted: used, totals };
}

// Leitura para o admin: trajetória de UM aluno a partir do D1 (nunca do Drive).
// Sem migração ainda → migrated:null e o painel mostra "aguardando 1º login".
async function admStudentHistory(d1, username) {
  username = String(username || '').trim();
  if (!username) return { ok: false, error: 'no user' };
  if (!d1) return { ok: false, error: 'no d1' };
  try { await d1EnsureSchema(); } catch (_) {}
  let mig = null;
  try { mig = await d1.prepare('SELECT username, status, watched_total, watched_done, events_total, events_done, source_bytes, migrated_at, updated_at FROM history_migrations WHERE username = ?').bind(username).first(); } catch (_) { const _s = (typeof loadTableSnapshot === 'function' ? await loadTableSnapshot('history_migrations') : null); if (_s) mig = _s.find(r => r.username === username) || null; }
  const courses = await historyUserCourses(d1, username);
  // ★ v2.15.8 (B): total do curso = nº de PASTAS DE AULA (lessonFolderKey)
  //   por caminho CANÔNICO — mesma regra do /api/courses/unified. O GROUP
  //   BY cru contava LINHAS por grafia (o admin mostrava 180 p/
  //   /11:/CURSOS%202026 enquanto a prévia mostrava 78 pastas).
  const totals = {};
  try {
    let _hrows;
    try { const r = await d1.prepare('SELECT course_path, lesson_path, lesson_name, lesson_type FROM lessons').all(); _hrows = r.results || []; }
    catch (_he) { _hrows = (typeof loadTableSnapshot === 'function' ? await loadTableSnapshot('lessons') : null); if (!_hrows) throw _he; }
    const _hSets = {};
    for (const row of _hrows) {
      let _hk = null;
      try { _hk = (typeof lessonFolderKey === 'function') ? lessonFolderKey(row.lesson_path, row.course_path, row.lesson_type) : null; } catch (_) { _hk = null; }
      if (!_hk) continue;
      let _hck = row.course_path;
      try { if (typeof canonicalCoursePath === 'function') _hck = canonicalCoursePath(row.course_path) || row.course_path; } catch (_) {}
      (_hSets[_hck] = _hSets[_hck] || new Set()).add(_hk);
    }
    for (const _hck in _hSets) totals[_hck] = _hSets[_hck].size;
  } catch (_) {}
  // ★ v2.15.8 (B): lookup do total pela chave CANÔNICA (o curso pode estar
  //   registrado sob a grafia legada /11: enquanto as pastas somam sob /9:).
  const _totFor = function(cp){ try { const _ck = (typeof canonicalCoursePath === 'function' ? canonicalCoursePath(cp) : null) || cp; if (totals[_ck] != null) return totals[_ck]; } catch (_) {} return totals[cp]; };
  const byCourse = {};
  try {
    const r = await d1.prepare('SELECT course_path, COUNT(*) AS n, MAX(watched_at) AS lastAt FROM user_watched WHERE username = ? GROUP BY course_path').bind(username).all();
    for (const row of (r.results || [])) byCourse[row.course_path || ''] = { n: row.n || 0, lastAt: row.lastAt || 0 };
  } catch (_) { const _s = (typeof loadTableSnapshot === 'function' ? await loadTableSnapshot('user_watched') : null); if (_s) for (const row of _s) { if (row.username !== username) continue; const k = row.course_path || ''; const en = byCourse[k] || (byCourse[k] = { n: 0, lastAt: 0 }); en.n++; if ((row.watched_at || 0) > en.lastAt) en.lastAt = row.watched_at || 0; } }
  // ★ v2.15.94: última aula (nome + caminho) por curso e a global
  //   do aluno — UMA query com ROW_NUMBER sobre user_watched (a
  //   mesma tabela que já alimenta o byCourse; nada de varrer a
  //   tabela lessons). Fallback = snapshot, como os blocos vizinhos.
  const lastByCourse = {};
  let lastLesson = null;
  const _noteLast94 = function(cp, lp, ln, at){ const k = cp || ''; const cur = lastByCourse[k]; if (!cur || (at || 0) > cur.at) lastByCourse[k] = { name: ln || null, path: lp || null, at: at || 0 }; if (!lastLesson || (at || 0) > lastLesson.at) lastLesson = { name: ln || null, path: lp || null, coursePath: cp || null, at: at || 0 }; };
  try {
    const r = await d1.prepare('SELECT course_path, lesson_path, lesson_name, watched_at FROM (SELECT course_path, lesson_path, lesson_name, watched_at, ROW_NUMBER() OVER (PARTITION BY course_path ORDER BY watched_at DESC) AS rn FROM user_watched WHERE username = ?) WHERE rn = 1').bind(username).all();
    for (const row of (r.results || [])) _noteLast94(row.course_path, row.lesson_path, row.lesson_name, row.watched_at || 0);
  } catch (_) { const _s = (typeof loadTableSnapshot === 'function' ? await loadTableSnapshot('user_watched') : null); if (_s) for (const row of _s) { if (row.username !== username) continue; _noteLast94(row.course_path, row.lesson_path, row.lesson_name, row.watched_at || 0); } }
  const courseMap = new Map();
  for (const c of courses) {
    courseMap.set(c.course_path, { coursePath: c.course_path, name: c.course_name || c.course_path, total: _totFor(c.course_path) || c.pdf_count || 0,
      watched: (byCourse[c.course_path] && byCourse[c.course_path].n) || 0, lastWatchedAt: (byCourse[c.course_path] && byCourse[c.course_path].lastAt) || 0 });
  }
  for (const cp in byCourse) {
    if (!courseMap.has(cp)) {
      courseMap.set(cp, { coursePath: cp || null, name: cp ? historyLessonName(cp) : 'Sem curso associado', total: (cp && _totFor(cp)) || 0,
        watched: byCourse[cp].n, lastWatchedAt: byCourse[cp].lastAt });
    }
  }
  const courseList = [...courseMap.values()].map(c => ({
    ...c, percent: c.total > 0 ? Math.round((c.watched / c.total) * 100) : null
  })).sort((a, b) => (b.watched - a.watched) || ((b.lastWatchedAt || 0) - (a.lastWatchedAt || 0)));
  for (const c of courseList) { const ll = lastByCourse[c.coursePath || '']; c.lastLessonName = ll ? ll.name : null; c.lastLessonPath = ll ? ll.path : null; }
  let timeline = [];
  try {
    const r = await d1.prepare('SELECT lesson_path, lesson_name, course_path, event_at, minutes FROM user_history_events WHERE username = ? ORDER BY event_at DESC LIMIT 100').bind(username).all();
    timeline = (r.results || []).map(ev => ({ at: ev.event_at, lesson_path: ev.lesson_path, lesson_name: ev.lesson_name, course_path: ev.course_path, minutes: ev.minutes || 0, kind: 'event' }));
  } catch (_) { const _s = (typeof loadTableSnapshot === 'function' ? await loadTableSnapshot('user_history_events') : null); if (_s) timeline = _s.filter(r => r.username === username).sort((a, b) => (b.event_at || 0) - (a.event_at || 0)).slice(0, 100).map(ev => ({ at: ev.event_at, lesson_path: ev.lesson_path, lesson_name: ev.lesson_name, course_path: ev.course_path, minutes: ev.minutes || 0, kind: 'event' })); }
  if (!timeline.length) {
    try {
      const r = await d1.prepare('SELECT lesson_path, lesson_name, course_path, watched_at FROM user_watched WHERE username = ? ORDER BY watched_at DESC LIMIT 100').bind(username).all();
      timeline = (r.results || []).map(w => ({ at: w.watched_at || 0, lesson_path: w.lesson_path, lesson_name: w.lesson_name, course_path: w.course_path, minutes: 0, kind: 'watched' }));
    } catch (_) { const _s = (typeof loadTableSnapshot === 'function' ? await loadTableSnapshot('user_watched') : null); if (_s) timeline = _s.filter(r => r.username === username).sort((a, b) => (b.watched_at || 0) - (a.watched_at || 0)).slice(0, 100).map(ev => ({ at: ev.watched_at, lesson_path: ev.lesson_path, lesson_name: ev.lesson_name, course_path: ev.course_path, kind: 'watched' })); }
  }
  let totalWatched = 0, lastActivity = 0, totalMinutes = 0;
  try { const r = await d1.prepare('SELECT COUNT(*) AS c, MAX(watched_at) AS lastAt FROM user_watched WHERE username = ?').bind(username).first(); totalWatched = (r && r.c) || 0; lastActivity = (r && r.lastAt) || 0; } catch (_) { const _s = (typeof loadTableSnapshot === 'function' ? await loadTableSnapshot('user_watched') : null); if (_s) { const _mine = _s.filter(r => r.username === username); totalWatched = _mine.length; lastActivity = _mine.reduce((m2, r) => Math.max(m2, r.watched_at || 0), 0); } }
  // ★ v2.14.6: "última atividade" = máximo de TODAS as fontes, igual à
  // lista de Alunos (antes, só a última aula assistida — divergia da lista
  // quando o aluno adicionou um curso ou escreveu um resumo depois).
  try { const r = await d1.prepare('SELECT MAX(event_at) AS lastAt FROM user_history_events WHERE username = ?').bind(username).first(); lastActivity = Math.max(lastActivity, (r && r.lastAt) || 0); } catch (_) { const _s = (typeof loadTableSnapshot === 'function' ? await loadTableSnapshot('user_history_events') : null); if (_s) for (const r of _s) if (r.username === username && r.event_at) lastActivity = Math.max(lastActivity, r.event_at); }
  try { const r = await d1.prepare('SELECT MAX(added_at) AS lastAt FROM user_courses WHERE username = ?').bind(username).first(); lastActivity = Math.max(lastActivity, (r && r.lastAt) || 0); } catch (_) { const _s = (typeof loadTableSnapshot === 'function' ? await loadTableSnapshot('user_courses') : null); if (_s) for (const r of _s) if (r.username === username && r.added_at) lastActivity = Math.max(lastActivity, r.added_at); }
  try { const r = await d1.prepare('SELECT MAX(date) AS lastAt FROM shared_summaries WHERE author = ?').bind(username).first(); lastActivity = Math.max(lastActivity, (r && r.lastAt) || 0); } catch (_) { const _s = (typeof loadTableSnapshot === 'function' ? await loadTableSnapshot('shared_summaries') : null); if (_s) for (const r of _s) if (r.author === username && r.date) lastActivity = Math.max(lastActivity, r.date); }
  try { const r = await d1.prepare('SELECT MAX(date) AS lastAt FROM shared_flashcards WHERE author = ?').bind(username).first(); lastActivity = Math.max(lastActivity, (r && r.lastAt) || 0); } catch (_) { const _s = (typeof loadTableSnapshot === 'function' ? await loadTableSnapshot('shared_flashcards') : null); if (_s) for (const r of _s) if (r.author === username && r.date) lastActivity = Math.max(lastActivity, r.date); }
  try { const r = await d1.prepare('SELECT COALESCE(SUM(minutes),0) AS m FROM user_history_events WHERE username = ?').bind(username).first(); totalMinutes = (r && r.m) || 0; } catch (_) { const _s = (typeof loadTableSnapshot === 'function' ? await loadTableSnapshot('user_history_events') : null); if (_s) totalMinutes = _s.filter(r => r.username === username).reduce((acc, r) => acc + (r.minutes || 0), 0); }
  return { ok: true, username,
    migrated: mig ? { status: mig.status, watched_done: mig.watched_done || 0, watched_total: mig.watched_total || 0, events_done: mig.events_done || 0, events_total: mig.events_total || 0, migrated_at: mig.migrated_at || 0, updated_at: mig.updated_at || 0 } : null,
    summary: { courses: courseList.length, watched: totalWatched, minutes: totalMinutes, lastActivity },
    courses: courseList, timeline, lastLesson };
}

// ═══ v2.7: scan com auto-resume + "done" definitivo ═══
// - scan_status (D1) marca o curso como concluído (scan completo + ≥1 aula no D1).
//   O rebuild da fila do backfill EXCLUI cursos done: completou, nunca mais é escaneado.
// - Falha de scan re-enfileira no fim da fila (máx. 3 tentativas) em vez de sumir —
//   se o CF cortar no meio, o próximo cron retoma sozinho até completar.
// - Adicionar pasta (admin: destaque; aluno: curso) enfileira o caminho no backfill:
//   o scan imediato (navegador) é o caminho rápido, o cron é a rede de segurança.
// ★ v2.15.2 (A4): forma canônica SÓ para comparação de caminhos no backfill
//   (done/dead/merge/purga/enqueue). O scan_status tem a MESMA pasta em duas
//   chaves ('/0:/A%20Primeira%20Ci%C3%AAncia' not_found e '.../' done/1) —
//   sem normalizar, doneSet/deadSet não se reconhecem e o curso volta à
//   fila (ou o morto volta a ser tentado). Não reescreve o coursePath
//   armazenado — só a comparação. (normalizeCoursePath sempre termina com
//   '/'; aqui a barra final é tirada para a comparação ser estável.)
function normScanPath(p){
  let n = '';
  try { n = normalizeCoursePath(p); } catch (_) { n = String(p || '').trim(); }
  return String(n || '').replace(/\/+$/, '');
}
// ★ v2.15.3 (W3): comparação canônica — '/11:/X' e '/9:/X' são a MESMA
//   pasta física; comparar pelo caminho canônico evita duplicar a fila,
//   ressuscitar um curso done/morto sob a outra identidade, ou remover
//   um e deixar o gêmeo.
function normCanonPath(p){
  try { return normScanPath(canonicalCoursePath(p)); } catch (_) { return normScanPath(p); }
}
async function markScanDone(d1, coursePath, lessons){
  try{
    // ★ v2.15.6 (scan): done limpa o diagnóstico da quarentena.
    try {
      await d1.prepare(`INSERT OR REPLACE INTO scan_status (course_path, status, lessons, completed_at, updated_at, last_error, fail_count) VALUES (?,'done',?,?,?,NULL,0)`)
        .bind(coursePath, lessons||0, Date.now(), Date.now()).run();
    } catch (e) {
      if (/no such column/i.test(String(e && e.message || e))) {
        await d1.prepare(`INSERT OR REPLACE INTO scan_status (course_path, status, lessons, completed_at, updated_at) VALUES (?,'done',?,?,?)`)
          .bind(coursePath, lessons||0, Date.now(), Date.now()).run();
      } else throw e;
    }
    return true;
  }catch(e){ console.warn('[scan-status] markScanDone failed:', e.message); return false; }
}
async function loadDoneScanPaths(d1){
  try{
    const r = await d1.prepare(`SELECT course_path FROM scan_status WHERE status='done'`).all();
    // ★ v2.15.3 (W3): done-ness é por pasta FÍSICA — um done gravado como
    //   '/11:/X' vale para o canônico '/9:/X' (e vice-versa).
    return new Set((r.results||[]).map(x=>normCanonPath(x.course_path)).filter(Boolean));
  }catch(e){ console.warn('[scan-status] loadDoneScanPaths failed:', e.message); return new Set(); }
}
// ★ v2.13.3: caminhos mortos (não encontrados após 3 tentativas, ou vazios
// marcados pelo admin) — o merge/rebuild não os re-adiciona sozinhos.
// ★ v2.15.5 (R7): 'error' também é morto — mas SÓ por 24h (updated_at).
//   Um curso que falha 3x (throw, drive fora, pasta que some) era
//   descartado da fila e RE-ADICIONADO pelo merge no run seguinte,
//   queimando 1 slot a cada ~3 runs p/ sempre sem nunca drenar. Com a
//   quarentena, o merge/rebuild o ignora por 24h e depois tenta de novo.
//   'not_found'/'empty' continuam permanentes. (Só usado no backfill.)
// ★ v2.15.6 (scan): backoff da quarentena — 24h × nº de quarentenas,
//   teto 7 dias. Um curso que falha de forma determinística não volta a
//   comer 1 slot por run: 1ª quarentena 24h, 2ª 48h, 3ª 72h…; a partir da
//   3ª quarentena (fail_count >= 3) só volta por re-enfileiramento manual
//   (o admin/aluno re-adiciona o curso — enqueueBackfillCourse não passa
//   pelo deadSet) — ver loadDeadScanPaths.
function scanQuarantineBackoffMs(failCount){
  const fc = Math.max(1, Number(failCount) || 1);
  return Math.min(7*24*3600*1000, 24*3600*1000*fc);
}
async function loadDeadScanPaths(d1){
  try{
    let rows = null;
    try {
      const r = await d1.prepare(`SELECT course_path, status, updated_at, fail_count FROM scan_status WHERE status IN ('not_found','empty','error')`).all();
      rows = r.results || [];
    } catch (_) {
      // D1 sem a migração v2.15.6 (coluna fail_count ausente): backoff 24h.
      const r = await d1.prepare(`SELECT course_path, status, updated_at FROM scan_status WHERE status IN ('not_found','empty','error')`).all();
      rows = (r.results || []).map(x => ({ course_path: x.course_path, status: x.status, updated_at: x.updated_at, fail_count: 1 }));
    }
    const now = Date.now();
    return new Set(rows.filter(x=>{
      const st = x && x.status;
      if(st === 'not_found' || st === 'empty') return true;
      if(st === 'error'){
        const fc = Math.max(1, Number((x && x.fail_count) || 1));
        // ★ v2.15.6: a partir da 3ª quarentena o curso NÃO volta sozinho.
        if (fc >= 3) return true;
        const at = Number((x && x.updated_at) || 0);
        return at > 0 && (now - at) < scanQuarantineBackoffMs(fc);
      }
      return false;
    }).map(x=>normCanonPath(x.course_path)).filter(Boolean));
  }catch(e){ console.warn('[scan-status] loadDeadScanPaths failed:', e.message); return new Set(); }
}
async function markScanDead(d1, coursePath, status, lastError){
  try{
    // ★ v2.15.6 (scan): registra o erro (last_error) e conta a quarentena
    //   (fail_count) — é o diagnóstico que o admin exibe em cron-progress.
    let failCount = 0;
    try { const cur = await d1.prepare(`SELECT fail_count FROM scan_status WHERE course_path=?`).bind(coursePath).first(); if (cur && typeof cur.fail_count === 'number') failCount = cur.fail_count; } catch (_) {}
    if (status === 'error') failCount = failCount + 1;
    const err = (lastError == null ? null : String(lastError).slice(0, 300));
    try {
      await d1.prepare(`INSERT OR REPLACE INTO scan_status (course_path, status, lessons, completed_at, updated_at, last_error, fail_count) VALUES (?,?,0,?,?,?,?)`)
        .bind(coursePath, status, null, Date.now(), err, failCount).run();
    } catch (e) {
      if (/no such column/i.test(String(e && e.message || e))) {
        await d1.prepare(`INSERT OR REPLACE INTO scan_status (course_path, status, lessons, completed_at, updated_at) VALUES (?,?,0,?,?)`)
          .bind(coursePath, status, null, Date.now()).run();
      } else throw e;
    }
    return true;
  }catch(e){ console.warn('[scan-status] markScanDead failed:', e.message); return false; }
}
// ★ v2.15.7 (P1): quarentena com TÚMULO em KV — o drop de um curso só
//   é definitivo quando a morte foi PERSISTIDA (D1 scan_status ou KV
//   cron-backfill:dead). Antes, markScanDead era best-effort (warn-only):
//   se a escrita no D1 falhasse, o item saía da fila SEM linha em
//   scan_status e o merge/rebuild do run seguinte o re-adicionava com
//   retries ZERADOS — loop infinito de 3 strikes sem quarentena e sem
//   rastro. Agora o drop só acontece com d1||kv persistido; se AMBOS
//   falharem o item FICA na fila (retries preservados,
//   deadWriteFailed:true) e o admin vê o erro em progress.lastError.
//   A lápide em KV também alimenta o deadSet do rebuild (o D1 pode estar
//   sem a migração last_error/fail_count — o KV não depende de schema).
const SCAN_STUCK_CYCLES = 10; // ★ v2.15.7 (P1): item da fila com cycles>=10 = travado (visível em blocked[])
const SCAN_DEAD_KV_KEY = 'cron-backfill:dead';
async function loadDeadScanPathsKv(kv){
  // Devolve a lista BRUTA de lápides [{coursePath,status,at,lastError,
  // failCount}] (ou []). Quem decide se a lápide bloqueia é
  // loadDeadScanPathsUnified — a lápide só vale quando NÃO há linha D1
  // p/ o curso (a linha D1 governa) e respeita o mesmo backoff da linha
  // (24h×failCount, teto 7d; fc>=3/not_found/empty permanentes).
  try{
    if(!kv) return [];
    const raw = await kv.get(SCAN_DEAD_KV_KEY);
    if(!raw) return [];
    const list = JSON.parse(raw);
    if(!Array.isArray(list)) return [];
    return list;
  }catch(e){ console.warn('[scan-status] loadDeadScanPathsKv failed:', e.message); return []; }
}
// ★ v2.15.7 (P1, fix S3.10): deadSet unificado — a linha D1 governa
//   quando existe (o teste S3.10 envelhece só a linha D1; um túmulo KV
//   fresco não pode bloquear o retorno após o backoff). E um túmulo
//   'not_found' permanente não pode bloquear um curso que depois
//   COMPLETOU (markScanDone → linha 'done' governa, túmulo ignorado).
//   A lápide só bloqueia o rebuild quando NÃO há linha D1 p/ o curso —
//   é o fallback p/ a escrita D1 falhada (o caso fail-closed do T2).
async function loadDeadScanPathsUnified(d1, kv){
  const dead = await loadDeadScanPaths(d1);
  try{
    if(!kv) return dead;
    let hasRow = new Set();
    try{
      const r = await d1.prepare(`SELECT course_path FROM scan_status`).all();
      for (const x of (r.results || [])) if (x && x.course_path) hasRow.add(normCanonPath(x.course_path));
    }catch(_){ hasRow = new Set(); }
    const now = Date.now();
    for (const x of await loadDeadScanPathsKv(kv)) {
      if (!x || !x.coursePath) continue;
      const key = normCanonPath(x.coursePath);
      if (!key || hasRow.has(key)) continue;
      const st = x.status || 'error';
      if (st === 'not_found' || st === 'empty') { dead.add(key); continue; }
      const fc = Math.max(1, Number(x.failCount) || 1);
      if (fc >= 3) { dead.add(key); continue; }
      const at = Number(x.at) || 0;
      if (at <= 0 || now < at + scanQuarantineBackoffMs(fc)) dead.add(key);
    }
  }catch(e){ console.warn('[scan-status] loadDeadScanPathsUnified KV failed:', e.message); }
  return dead;
}
async function quarantineCourse(d1, kv, coursePath, status, lastError){
  // Devolve {d1, kv}: true quando a morte foi persistida em cada store.
  let d1ok = false, kvok = false;
  try { d1ok = await markScanDead(d1, coursePath, status, lastError); } catch (_) {}
  try {
    if (kv) {
      const raw = await kv.get(SCAN_DEAD_KV_KEY);
      let list = [];
      try { const p = raw ? JSON.parse(raw) : null; if (Array.isArray(p)) list = p; } catch (_) {}
      const key = normCanonPath(coursePath);
      // ★ v2.15.7 (P1, fix S3.10): a lápide carrega failCount e o
      //   incrementa a cada queda (em sincronia com o fail_count da linha
      //   D1) — é o que permite ao backoff expirar (fc<3) e ao fc>=3
      //   ficar permanente (ver loadDeadScanPathsUnified).
      const prev = list.find(x => x && normCanonPath(x.coursePath) === key);
      const failCount = (prev && Number(prev.failCount) > 0 ? Number(prev.failCount) : 0) + 1;
      list = list.filter(x => x && normCanonPath(x.coursePath) !== key);
      list.unshift({ coursePath, status, at: Date.now(), lastError: lastError == null ? null : String(lastError).slice(0, 300), failCount });
      if (list.length > 200) list.length = 200;
      await kv.put(SCAN_DEAD_KV_KEY, JSON.stringify(list));
      kvok = true;
    }
  } catch (e) { console.warn('[scan-status] quarantineCourse KV failed:', e.message); }
  return { d1: d1ok, kv: kvok };
}
async function enqueueBackfillCourse(kv, coursePath){
  try{
    const m = String(coursePath||'').match(/^\s*\/(\d+):\//);
    if(!m) return false;
    const clean = String(coursePath).trim();
    // ★ v2.14.9: raiz de drive nunca entra na fila (ver isDriveRootCoursePath)
    if (typeof isDriveRootCoursePath === 'function' && isDriveRootCoursePath(clean)) { console.log('[scan-status] enqueue recusado (raiz de drive):', clean); return false; }
    let progress = { queue: [] };
    try{ const raw = await kv.get('cron-backfill:progress'); if(raw){ const p = JSON.parse(raw); if(p && Array.isArray(p.queue)) progress = p; } }catch(_){}
    if(progress.queue.some(it => it && it.coursePath && normCanonPath(it.coursePath) === normCanonPath(clean))) return false; // já na fila (canônico: o gêmeo conta como o mesmo curso)
    // ★ v2.15.3 (W3): a fila guarda a identidade canônica ('/11:' → '/9:').
    const canonClean = canonicalCoursePath(clean);
    const cm = canonClean.match(/^\s*\/(\d+):\//);
    progress.queue.push({ coursePath: canonClean, driveIndex: cm ? Number(cm[1]) : Number(m[1]), folderId: null, folderName: null });
    await kv.put('cron-backfill:progress', JSON.stringify(progress));
    return true;
  }catch(e){ console.warn('[scan-status] enqueueBackfillCourse failed:', e.message); return false; }
}

// ★ v2.15.2 (A3): tira um curso da fila do backfill (ao remover o curso ou
//   excluir o destaque). Match normalizado (A4): a fila pode ter a forma
//   codificada e a remoção, a decodificada (ou vice-versa).
async function removeFromBackfillQueue(kv, coursePath){
  try{
    if(!kv || !coursePath) return false;
    const want = normCanonPath(coursePath);
    if(!want) return false;
    const raw = await kv.get('cron-backfill:progress');
    if(!raw) return false;
    const p = JSON.parse(raw);
    if(!p || !Array.isArray(p.queue)) return false;
    const before = p.queue.length;
    p.queue = p.queue.filter(it => it && it.coursePath && normCanonPath(it.coursePath) !== want);
    if(p.queue.length === before) return false;
    await kv.put('cron-backfill:progress', JSON.stringify(p));
    return true;
  }catch(e){ console.warn('[scan-status] removeFromBackfillQueue failed:', e.message); return false; }
}

// ★ v2.14.9: caminho de curso que é RAIZ de drive (/N:/ ou /N:) — nunca entra
//   na fila de scan. Escanear a raiz é escanear o drive inteiro: foi assim que
//   o meuc ganhou 210 aulas de '/6:/CURSOS 2025/DISCIPLINAS ISOLADAS' pelo
//   destaque '/6:/' (e 1 aula da pasta de estado '/0:/AULAS - ESTADO DOS ALUNOS').
//   As linhas de featured_courses NÃO são apagadas — só não são escaneadas; o
//   admin vê o aviso com as raízes em GET /api/d1/cron-progress (rootPaths).
function isDriveRootCoursePath(cp) { return /^\/\d+:\/?$/.test(String(cp || '').trim()); }

// ★ v2.14.9: a fila é construída SÓ de cursos registrados (user_courses +
//   featured_courses). A listagem das raízes foi removida (o rebuild v2.12
//   enfileirava ~163 pastas raiz e as 382 aulas no D1 vieram delas, não dos
//   cursos registrados). Raiz de drive nunca entra (ver isDriveRootCoursePath).
function mergeBackfillQueue(d1Paths) {
  const seen = new Set();
  const out = [];
  for (const cp of d1Paths || []) {
    const clean = String(cp || '').trim();
    if (!clean) continue;
    if (isDriveRootCoursePath(clean)) { console.log('[Cron Backfill] pulado (raiz de drive, não é curso):', clean); continue; }
    const m = clean.match(/^\s*\/(\d+):\//);
    if (!m) continue;
    // ★ v2.15.3 (W3): UM item por pasta física — '/11:/CURSOS 2026' e
    //   '/9:/CURSOS 2026' colapsam no canônico '/9:/CURSOS 2026' (menor
    //   índice). Sem isso o round-robin retomava o pending da outra
    //   identidade e o guarda de prefixo mutilava os paths.
    const canon = canonicalCoursePath(clean);
    const key = physicalDriveKey(canon); // ★ v2.15.7 (dedup): a chave é da grafia CANÔNICA — '/11:/CURSOS%202026' e '/9:/CURSOS 2026' são o mesmo curso, mas após a F-04 têm ids de drive diferentes e a chave do caminho cru daria 2 itens na fila p/ o mesmo curso.
    if (seen.has(key)) continue;
    seen.add(key);
    const mm = canon.match(/^\s*\/(\d+):\//);
    out.push({ coursePath: canon, driveIndex: mm ? Number(mm[1]) : Number(m[1]), folderId: null, folderName: null });
  }
  return out;
}

async function resolveCourseFolderId(gd, coursePath) {
  const parsed = (typeof parseCoursePath === 'function') ? parseCoursePath(coursePath) : null;
  if (!parsed) return null;
  let currentFolderId = null;
  if (gd.root && gd.root.id) currentFolderId = gd.root.id;
  else if (gd.rid) currentFolderId = gd.rid;
  if (!currentFolderId) return null;
  const subParts = parsed.subPath.split('/').filter(Boolean);
  for (const part of subParts) {
    let decodedPart = part;
    try { decodedPart = decodeURIComponent(part); } catch (_) {}
    const opts = await gd.requestOptions();
    const q = "'" + currentFolderId + "' in parents and name = '" + driveEscape(decodedPart) + "' and trashed = false";
    const r = await fetch('https://www.googleapis.com/drive/v3/files?' + enQuery({ includeItemsFromAllDrives: 'true', supportsAllDrives: 'true', q, fields: 'files(id,mimeType)', pageSize: '1' }), opts);
    if (!r.ok) return null;
    const j = await r.json();
    if (!j.files || !j.files[0]) return null;
    currentFolderId = j.files[0].id;
  }
  return currentFolderId;
}

// ★ v2.4: reescrita do backfill — fila no KV + progresso por curso.
// ★ v2.14.9: a fila é rebuilt quando esvazia SÓ com course_path registrados
//   (user_courses + featured_courses); raiz de drive (/N:/) nunca entra.
//   Cada curso processado (1 batch + leitura + insert em lote) salva a fila
//   restante no KV imediatamente — um corte por CPU/subrequests retoma do ponto.
//   Compat: progresso antigo (driveIndex/lastFolderId, sem queue) é ignorado
//   e a fila é reconstruída.
async function handleCronBackfill() {
  console.log('[Cron Backfill v2.12] iniciando execução');
  const d1 = meggyD1Binding();
  const kv = meggyKvBinding();
  if (!d1 || !kv) {
    console.log('[Cron Backfill] D1 ou KV não configurado, abortando');
    return { ok: false, error: 'D1 or KV not bound', d1: !!d1, kv: !!kv };
  }

  // ★ v2.12: init PREGUIÇOSO por drive — o init de todos os 12 drives
  // (getAccessToken + findItemById por drive) comia o orçamento de
  // subrequests antes do primeiro scan. Agora só inicializa o drive
  // do curso que vai ser processado, quando for processado.
  // ★ v2.15.5 (R5): init LEVE — gd.init() gastava 1 fetch (findItemById
  //   'root') só p/ setar authConfig.user_drive_real_root_id, que o scanner
  //   nunca usa; o token continua lazy (1º requestOptions o busca, 1 fetch
  //   por drive/invocação, coberto pela margem do orçamento). initRootType
  //   é puro (0 fetches) e é mantido.
  const ensureDrive = async (idx) => {
    if (gds[idx]) return gds[idx];
    const gd = new googleDrive(authConfig, idx);
    try { await gd.initRootType(); } catch (_) {}
    gds[idx] = gd;
    return gd;
  };

  // ★ v2.15.8 (A): o drive 0 precisa existir p/ o mirror funcionar no
  //   caminho do cron: no scheduled o gds nasce vazio e o ensureDrive lazy
  //   só inicializava o drive do curso — gds[0] ficava undefined e TODOS os
  //   fallbacks p/ o mirror eram código morto nas runs do cron (no fetch
  //   manual o handleRequest já inicializa todos os drives). initRootType
  //   é puro (0 fetches, v2.15.5); o token continua lazy.
  try { await ensureDrive(0); } catch (_) {}
  try {
    await d1EnsureSchema();
  } catch (e) {
    console.warn('[Cron Backfill] schema init failed:', e.message);
    return { ok: false, error: 'schema init failed: ' + e.message };
  }

  // Ler progresso do KV (fila restante + totais)
  let progress = { queue: [], totalScanned: 0, totalLessons: 0, lastRun: 0 };
  try {
    const raw = await kv.get('cron-backfill:progress');
    if (raw) {
      const p = JSON.parse(raw);
      if (p && Array.isArray(p.queue)) progress = { queue: p.queue, totalScanned: p.totalScanned || 0, totalLessons: p.totalLessons || 0, lastRun: p.lastRun || 0 };
    }
  } catch (_) {}

  const saveProgress = async () => {
    progress.lastRun = Date.now();
    try { await kv.put('cron-backfill:progress', JSON.stringify(progress)); } catch (e) { console.warn('[Cron Backfill] failed to save progress:', e.message); }
  };

  // ★ v2.15.3 (W3): canonicalizar a fila carregada do KV — itens antigos
  //   ('/11:/…') viram a identidade canônica ('/9:/…'); duplicatas da
  //   mesma pasta física colapsam num só item (mantém retries/cycles).
  {
    const seenCanon = new Set();
    const canonQueue = [];
    for (const it of progress.queue || []) {
      if (!it || !it.coursePath) continue;
      const canon = canonicalCoursePath(it.coursePath);
      const key = physicalDriveKey(canon); // ★ v2.15.7 (dedup): idem — a chave é do canônico, não do caminho cru (v. mergeBackfillQueue).
      if (seenCanon.has(key)) continue;
      seenCanon.add(key);
      const mm = canon.match(/^\s*\/(\d+):\//);
      canonQueue.push({ ...it, coursePath: canon, driveIndex: mm ? Number(mm[1]) : it.driveIndex });
    }
    if (canonQueue.length !== progress.queue.length || canonQueue.some((it, i) => it.coursePath !== (progress.queue[i] || {}).coursePath)) { progress.queue = canonQueue; await saveProgress(); }
  }

  // ★ v2.13.3: caminhos mortos — um caminho que falhou 3x não é
  // re-adicionado sozinho pelo merge/rebuild (antes voltava e consumia 1
  // slot por run para sempre). Um caminho NA fila (ex.: re-adicionado pelo
  // admin) continua sendo tentado normalmente — o dead-set só impede o
  // merge/rebuild de trazê-lo de volta por conta própria.
  let deadSet = new Set();
  // ★ v2.15.7 (P1, fix S3.10): deadSet unificado — a linha D1 governa
  //   quando existe; a lápide KV só bloqueia sem linha D1 (fallback p/
  //   a escrita D1 falhada). Sem isto, um túmulo fresco bloqueava o
  //   retorno após o backoff do D1 expirar (S3.10) e um túmulo
  //   'not_found' permanente bloquearia um curso que depois completou.
  try { deadSet = await loadDeadScanPathsUnified(d1, kv); } catch (_) { try { deadSet = await loadDeadScanPaths(d1); } catch (_) {} }

  // ★ v2.14.9: o backfill só escaneia cursos REGISTRADOS (user_courses +
  //   featured_courses). A listagem das raízes foi REMOVIDA de vez: o rebuild
  //   v2.12 enfileirava ~163 pastas raiz e as 382 aulas no D1 vieram delas,
  //   não dos cursos registrados — por isso o CURSOS 2026 do Elton ficou com
  //   0 aulas. Sem registrados, a fila fica VAZIA (nunca lista raízes).
  //   A purga abaixo limpa os itens raiz da fila velha na primeira run após
  //   o deploy (drenar levaria ~78h a 2/run); e raiz de drive (/N:/) nunca
  //   entra, nem via featured (ver isDriveRootCoursePath).
  let runPurgedRoots = 0; // ★ v2.15.6 (P1): raízes purgadas nesta run (v. stats)
  let registeredPaths = [];
  try {
    const r = await d1.prepare('SELECT DISTINCT course_path FROM user_courses ORDER BY course_path LIMIT 500').all();
    registeredPaths = (r.results || []).map(x => x.course_path).filter(Boolean);
  } catch (_) {}
  try {
    const r2 = await d1.prepare('SELECT course_path FROM featured_courses LIMIT 500').all();
    for (const row of (r2.results || [])) if (row.course_path) registeredPaths.push(row.course_path);
  } catch (_) {}
  // ★ v2.14.9: purga — itens da fila que não são cursos registrados
  //   (pastas raiz do rebuild v2.12, órfãos de cursos removidos, raízes de
  //   drive) saem agora. Um curso re-enfileirado pelo admin continua sendo
  //   tentado: a purga só olha o REGISTRO no D1, não o scan_status.
  {
    const registeredSet = new Set(registeredPaths.map(cp => normCanonPath(cp)).filter(Boolean));
    if (progress.queue.length) {
      const before = progress.queue.length;
      // ★ v2.15.6 (P1): raiz de drive REGISTRADA também sai da fila — o
      //   purge antigo mantinha qualquer caminho registrado, então uma raiz
      //   ('/9:') ficava na fila e o loop a escaneava como se fosse um
      //   curso (o drive inteiro, milhares de pastas — nunca drena). A raiz
      //   continua visível no admin via rootPaths (cron-progress) p/ o
      //   admin corrigir o cadastro; o scanner nunca escaneia raiz.
      const purgedRoots = progress.queue.filter(it => it && it.coursePath && isDriveRootCoursePath(it.coursePath)).length;
      progress.queue = progress.queue.filter(it => it && it.coursePath && registeredSet.has(normCanonPath(it.coursePath)) && !isDriveRootCoursePath(it.coursePath));
      if (progress.queue.length !== before) { console.log('[Cron Backfill] purgados', before - progress.queue.length, 'itens não registrados da fila (' + purgedRoots + ' raízes de drive)'); await saveProgress(); }
      runPurgedRoots += purgedRoots;
    }
  }
  if (!progress.queue.length) {
    const d1Paths = registeredPaths.filter(cp => !deadSet.has(normCanonPath(cp))); // ★ v2.13.3: mortos não voltam no rebuild; ★ v2.15.6: a chave do deadSet é canônica — a comparação com normScanPath deixava o morto voltar sob a identidade gêmea ('/11:' vs '/9:')
    if (d1Paths.length) {
      progress.queue = mergeBackfillQueue(d1Paths);
      console.log('[Cron Backfill] fila reconstruída (cursos registrados):', progress.queue.length, 'cursos');
    } else {
      console.log('[Cron Backfill] sem cursos registrados — fila vazia (nunca lista raízes)');
    }
    await saveProgress();
  }

  // ★ v2.7: exclui cursos já concluídos (scan_status done) — completou, não volta à fila
  let doneSet = new Set();
  try {
    doneSet = await loadDoneScanPaths(d1);
    if (doneSet.size) {
      const before = progress.queue.length;
      progress.queue = progress.queue.filter(it => it && !doneSet.has(normCanonPath(it.coursePath)));
      if (progress.queue.length !== before) { console.log('[Cron Backfill] excluídos', before - progress.queue.length, 'cursos já concluídos'); await saveProgress(); }
    }
  } catch (_) {}

  // ★ v2.12: mescla cursos novos TODA execução (user_courses + featured) —
  // antes, um curso adicionado só entrava na fila quando ela esvaziava.
  try {
    const inQueue = new Set(progress.queue.map(it => it && normCanonPath(it.coursePath)).filter(Boolean));
    const extra = [];
    try {
      const r = await d1.prepare('SELECT DISTINCT course_path FROM user_courses ORDER BY course_path LIMIT 500').all();
      for (const row of (r.results || [])) if (row.course_path) extra.push(row.course_path);
    } catch (_) {}
    try {
      const r2 = await d1.prepare('SELECT course_path FROM featured_courses LIMIT 500').all();
      for (const row of (r2.results || [])) if (row.course_path) extra.push(row.course_path);
    } catch (_) {}
    let added = 0;
    const addedItems = [];
    for (const cp of extra) {
      const clean = String(cp).trim();
      const nclean = normCanonPath(clean);
      if (!clean || inQueue.has(nclean) || doneSet.has(nclean) || deadSet.has(nclean)) continue; // ★ v2.13.3: mortos não voltam pelo merge
      if (typeof isDriveRootCoursePath === 'function' && isDriveRootCoursePath(clean)) continue; // ★ v2.14.9: raiz de drive nunca entra na fila
      const m = clean.match(/^\s*\/(\d+):\//);
      if (!m) continue;
      // ★ v2.15.3 (W3): o item novo já entra canônico.
      const canonClean = canonicalCoursePath(clean);
      const cm = canonClean.match(/^\s*\/(\d+):\//);
      addedItems.push({ coursePath: canonClean, driveIndex: cm ? Number(cm[1]) : Number(m[1]), folderId: null, folderName: null });
      inQueue.add(nclean);
      added++;
    }
    // ★ v2.13.2: cursos registrados que JÁ estão na fila (vindos do rebuild
    // v2.12, no fim) também furam a fila. Antes só os NOVOS iam para o
    // início; os que já estavam enfileirados ficavam atrás das ~163 pastas
    // raiz — foi por isso que os 4 cursos do Elton ficaram com 0 aulas
    // enquanto 382 aulas de pastas raiz entravam. Move o item (mantém
    // retries/cycles) em vez de duplicar; a frente fica na ordem de `extra`
    // (user_courses ordenados, depois featured).
    const registeredSet = new Set(extra.map(cp => normCanonPath(String(cp).trim())).filter(Boolean).filter(cp => !doneSet.has(cp) && !deadSet.has(cp) && !(typeof isDriveRootCoursePath === 'function' && isDriveRootCoursePath(cp)))); // ★ v2.13.3: mortos fora da frente; ★ v2.14.9: raízes fora; ★ v2.15.3 (W3): chaves canônicas
    // ★ v2.15.9 (A): a frente é FIFO (round-robin) — o sort por tentativas
    //   da v2.13.3 foi REMOVIDO. O sort era re-aplicado TODA run e,
    //   combinado com o guarda de orçamento (1 curso grande/run — o 2º
    //   curso nunca é tentado), FAZIA O CURSO COM MAIS CICLOS MORRER DE
    //   FOME: o /9: (2 tentativas) passava sempre à frente do /10: (25
    //   tentativas) e o /10: nunca mais era tentado — cycles 23 e
    //   scanProgress null congelados do Passo 12 p/ o Passo 13, kind
    //   'stuck' e bloqueados 3 em vez de 2. Um curso grande e SAUDÁVEL
    //   acumula ciclos POR DESENHO (1 batch/run), então "mais tentativas"
    //   NÃO significa "quebrado". Ordem nova: os NOVOS furam a fila
    //   (v2.13.2 — sem mudança) e os que JÁ estão nela mantêm a ORDEM DA
    //   FILA: o incompleto volta p/ o FIM (round-robin da v2.13) e cada
    //   curso tem a sua vez a cada N runs. O objetivo da v2.13.3 ("curso
    //   quebrado não bloqueia os saudáveis") SEGUE VALENDO sem o sort: o
    //   erro de um curso quebrado é barato (resolve/meta falham com ~2–5
    //   subrequests) e o próximo curso ainda é tentado NA MESMA run; o
    //   quebrado vai p/ o fim e, em ≤3 rodadas, acumula os 3 retries e é
    //   quarentenado — antes, com o sort, um curso grande e saudável à
    //   frente podia adiar a quarentena dele p/ sempre.
    const front = [];
    for (const it of addedItems) front.push(it); // novos furam a fila (v2.13.2)
    for (const it of progress.queue) {
      if (it && it.coursePath && registeredSet.has(normCanonPath(it.coursePath)) && !front.some(x => normCanonPath(x.coursePath) === normCanonPath(it.coursePath))) front.push(it);
    }
    if (front.length) {
      const rest = progress.queue.filter(it => !(it && it.coursePath && registeredSet.has(normCanonPath(it.coursePath))));
      const movedCount = front.length - added;
      progress.queue = [...front, ...rest];
      console.log('[Cron Backfill] priorizados', front.length, 'cursos registrados (' + added + ' novos, ' + movedCount + ' movidos para o início)');
      await saveProgress();
    }
  } catch (_) {}

  const stats = { coursesScanned: 0, lessonsInserted: 0, errors: [], skipped: 0, dropped: [], queueLeft: progress.queue.length, purgedRoots: runPurgedRoots, dotfileFailures: 0, metaPersistFailures: 0 };
  // ★ v2.13: orçamento estimado de subrequests da execução. O teto do CF é
  // 50 por invocação; o batch de scan custa até ~20 (+~5 não contados) e a
  // leitura até ~24 (+~12 não contados) — scan+leitura juntos de 1 curso
  // grande já estouram o teto. Cap 40 deixa ~10 de folga para o overhead
  // (rebuild/merge/D1/KV/init do drive). Estimativas: scan 25, leitura 25.
  const RUN_BUDGET = 40;
  let budgetUsed = 6; // ★ v2.14.9: sem listagem de raízes, o custo fixo da run é só 6 (antes +12 quando o rebuild listava as raízes)
  const MAX_COURSES_PER_RUN = 2; // ★ v2.13: era 3 (o custo real por curso é ~25-35, não ~15)
  const attemptedThisRun = new Set();
  let stopAfterThis = false; // ★ v2.13.4: teto de subrequests — para após salvar

  // ★ v2.12: peek, não shift — o item só sai da cabeça da fila quando
  // termina (sucesso, descarte definitivo ou re-enfileirado no fim).
  // Salva o progresso ANTES de começar cada curso: se o CF cortar a
  // execução no meio, o curso continua na fila para a próxima run.
  // ★ v2.15.5 (R7): async — o drop por ERRO marca scan_status 'error'
  //   (quarentena 24h, v. loadDeadScanPaths). O drop por NOT FOUND continua
  //   permanente ('not_found', marcado pelo chamador como antes).
  const requeueOrDrop = async (item, reason, isNotFound) => {
    const retries = (item.retries || 0) + 1;
    let out = 'requeued';
    progress.lastError = reason; // ★ v2.15.6: o admin exibe (progress.lastCourse/lastError)
    if (retries <= 3) {
      progress.queue.shift();
      // ★ v2.15.7 (P1): o item re-enfileirado leva o erro + a hora da
      //   tentativa — o admin (blocked[]) mostra o diagnóstico mesmo sem
      //   linha em scan_status (o 'incomplete' nunca teve uma).
      progress.queue.push({ ...item, retries, lastError: reason, lastAttemptAt: Date.now() });
      stats.errors.push(reason + ' (tentativa ' + retries + '/3)');
      console.log('[Cron Backfill] re-enfileirado (tentativa ' + retries + '/3):', item.coursePath);
    } else {
      // ★ v2.15.7 (P1): o drop QUARENTENA o curso (D1 + lápide KV) e
      //   SÓ sai da fila se a morte foi persistida — se D1 e KV falharem,
      //   o item FICA (retries preservados) em vez de sumir sem rastro e
      //   voltar pelo rebuild com retries zerados. O guarda
      //   attemptedThisRun encerra o loop da run (o item fica na cabeça).
      const q = await quarantineCourse(d1, kv, item.coursePath, isNotFound ? 'not_found' : 'error', reason);
      if (!q.d1 && !q.kv) {
        stats.errors.push(reason + ' (quarentena NÃO persistida — item mantido na fila)');
        console.warn('[Cron Backfill] quarantine write failed, item mantido na fila:', item.coursePath);
        item.deadWriteFailed = true;
        item.lastError = reason;
        item.lastAttemptAt = Date.now();
        out = 'kept';
      } else {
        progress.queue.shift();
        stats.dropped.push(item.coursePath);
        stats.errors.push(reason + ' (descartado após 3 tentativas)');
        out = 'dropped';
      }
    }
    stats.coursesScanned++;
    return out;
  };

  while (stats.coursesScanned < MAX_COURSES_PER_RUN && progress.queue.length && budgetUsed < RUN_BUDGET) {
    const item = progress.queue[0];
    if (!item || !item.coursePath) { progress.queue.shift(); continue; }
    if (typeof isDriveRootCoursePath === 'function' && isDriveRootCoursePath(item.coursePath)) {
      // ★ v2.15.6 (P1): defesa em profundidade — raiz nunca é escaneada
      //   (o purge deve tê-la tirado; se chegou aqui, sai sem escanear).
      progress.queue.shift();
      stats.purgedRoots++;
      stats.errors.push('root_' + item.coursePath + ': raiz de drive, não escaneada (corrija o cadastro do curso)');
      progress.lastError = 'root_' + item.coursePath + ': raiz de drive';
      await saveProgress();
      continue;
    }
    if (attemptedThisRun.has(item.coursePath)) break; // já tentado nesta execução — deixa para a próxima
    attemptedThisRun.add(item.coursePath);
    const coursePath = item.coursePath;
    progress.lastCourse = coursePath; // ★ v2.15.6: o admin exibe (progress.lastCourse/lastError)
    const driveIdx = item.driveIndex;
    await saveProgress(); // item ainda na fila — um corte aqui não o perde
    let gd = null;
    try { gd = await ensureDrive(driveIdx); } catch (e) {
      await requeueOrDrop(item, 'course_' + coursePath + ':drive init failed');
      await saveProgress();
      continue;
    }
    if (!gd) {
      await requeueOrDrop(item, 'course_' + coursePath + ':no drive');
      await saveProgress();
      continue;
    }
    let insertedThisCourse = 0;
    let countIt = false; // true = conta este curso no orçamento da run
    let outcome = 'error'; // 'done' | 'incomplete' | 'error' — decide o destino do item na fila
    let batchResult = null; // ★ v2.15.8 (A): declarado AQUI (fora do try) — o ramo 'incomplete' abaixo o lê; o `let` interno dava ReferenceError no 1º incomplete e abortava a run do cron
    let scanDone = false;
    try {
      const courseHash = courseHashFromPath(coursePath);
      let folderId = item.folderId || null;
      if (!folderId) {
        // curso de subpasta (veio do user_courses) — navega até a pasta
        folderId = await resolveCourseFolderId(gd, coursePath);
        // ★ v2.15.6 (P1): persiste o folderId resolvido no item da fila —
        //   antes, TODA run re-resolvia o caminho (1 fetch por segmento, p/
        //   sempre). O id do Drive é estável (sobrevive a rename/move); se a
        //   pasta for apagada, o batch falha como 'root unreachable' (v.
        //   gdiScanCourseDistributedBatch) e o item vai p/ quarentena —
        //   nunca fica preso em 'incomplete' com 0 aulas.
        if (folderId) { item.folderId = folderId; await saveProgress(); }
        // ★ v2.15.5 (R5): 1 fetch por segmento do path (antes, fixo 2 — um
        //   curso fundo com 4 segmentos custava 4 e contava 2).
        budgetUsed += Math.max(2, (function(){ try{ const pp = (typeof parseCoursePath === 'function') ? parseCoursePath(coursePath) : null; return pp ? String(pp.subPath || '').split('/').filter(Boolean).length : 1; }catch(_){ return 1; } })());
        if (!folderId) {
          // ★ v2.12: "não encontrado" vira retry (antes descartava na hora)
          // ★ v2.13.3: após 3 tentativas o caminho é marcado morto no
          // scan_status — o merge não o re-adiciona sozinho.
          const dropped = await requeueOrDrop(item, 'course_' + coursePath + ':not found', true);
          if (dropped === 'dropped') await markScanDead(d1, coursePath, 'not_found');
          await saveProgress();
          continue;
        }
      }

      // ★ v2.13: lê o .gdi-course.json (2 subrequests) para saber se o scan
      // está 'done' ou 'scanning'. O check antigo só listava o arquivo — um
      // curso com scan parcial parecia "já escaneado" e o batch nunca mais
      // rodava, então o curso grande nunca completava.
      let scanState = 'fresh'; // 'fresh' | 'scanning' | 'done'
      // ★ v2.15.5 (R3): o meta lido aqui é passado ao batch (opts.meta) —
      //   sem isso o batch re-lia o mesmo dotfile (+2 reais, 0 contados).
      //   ★ v2.15.8 (A): a leitura é mirror-aware (gdiReadCourseRootDotfile):
      //   num drive read-only o meta vive no mirror e a leitura SÓ direta
      //   devolvia not_found → meta=null → o batch recomeçava da raiz a
      //   cada run. null aqui = "probado direto + mirror e não achado" — o
      //   batch NÃO re-tenta (já probado); a origem (direct/mirror) vai p/
      //   o batch em opts.metaSource (vira modo mirror p/ as pastas).
      let metaForBatch;
      let metaSource = null; // 'direct' | 'mirror' | null
      const metaCtr = { value: 0 };
      try {
        const meta = await gdiReadCourseRootDotfile(gd, courseHash, folderId, '.gdi-course.json', metaCtr);
        if (meta && meta.ok && meta.data) {
          metaForBatch = meta.data; metaSource = meta.source || 'direct';
          if (meta.data.scanStatus === 'done') scanState = 'done';
          else if (Array.isArray(meta.data.pending) && meta.data.pending.length > 0) scanState = 'scanning';
          else if (meta.data.scanStatus === 'scanning') scanState = 'scanning';
          else scanState = 'done'; // dotfile existe sem pending = scan completo (legado)
        } else if (meta && !meta.ok) { metaForBatch = null; }
      } catch (_) {}
      budgetUsed += metaCtr.value || 2; // leitura do meta (direto 2; +5 se probou o mirror)

      scanDone = false;
      batchResult = null; // ★ v2.15.3 (W4): o batch desta run, p/ inserir mesmo se incomplete
      if (scanState === 'done') {
        // ★ v2.13.5: cache hit — mas só lê direto se houver o consolidado na
        // raiz. Sem ele, a leitura por pastas custa 3 fetches/pasta e estoura
        // o teto em cursos grandes (foi o erro da run das 15:50 no TJSP).
        // Nesse caso, re-escaneia: o batch usa os dotfiles como cache e é
        // resumível via pending; no fim ele escreve o consolidado e a
        // próxima run lê barato.
        let hasConsolidated = false;
        try {
          const cons = await gdiReadFolderDotfile(gd, folderId, '.gdi-lessons.json');
          // ★ v2.15.2 (A): consolidado sem a versão atual foi montado com
          //   aulas faltando (dotfilesSkipped) — não vale como cache hit.
          hasConsolidated = !!(cons && cons.ok && cons.data && cons.data.consolidated === true && cons.data.scannerVersion === SCAN_DOTFILE_VERSION && Array.isArray(cons.data.lessons));
        } catch (_) {}
        budgetUsed += 2; // leitura do consolidado (lista + download)
        if (hasConsolidated) {
          scanDone = true;
          stats.skipped++;
          console.log('[Cron Backfill] cache hit, lendo dotfiles:', coursePath);
        } else {
          console.log('[Cron Backfill] cache hit sem consolidado — re-escaneando:', coursePath);
        }
      }
      if (!scanDone) {
        // ★ v2.13 — FASE 1 (scan): novo ou retomada do pending. Custa ~25.
        // A leitura fica para a próxima run, salvo se o scan completou
        // (curso pequeno) — ler um curso grande agora custaria outros ~25
        // subrequests e estouraria o teto de 50 do CF (foi o que matou a
        // run das 15:10). O 1º curso da run sempre tenta (o rebuild pode ter
        // custado 12 e o orçamento estimado diria "não", mas o custo real
        // fica em ~38 < 50); a partir do 2º curso o orçamento vale.
        if (budgetUsed + 32 > RUN_BUDGET && stats.coursesScanned > 0) break; // ★ v2.15.5 (R5): 32 = teto real do batch (contador honesto, R4) — um batch cheio custa ~40 reais dos 50 do CF; o 2º curso só é tentado quando o 1º gastou ≤ 8 contados (na prática, 1 curso/run)
        console.log('[Cron Backfill] escaneando:', coursePath, scanState === 'scanning' ? '(retomando)' : '');
        const counter = { value: 0 };
        batchResult = await gdiScanCourseDistributedBatch(gd, coursePath, courseHash, 'cron-backfill', folderId, coursePath, counter, { skipCleanup: true, meta: metaForBatch, metaSource: metaSource, skipLegacy: true });
        if (!batchResult || !batchResult.ok) {
          await requeueOrDrop(item, 'scan_' + coursePath + ':' + ((batchResult && batchResult.error) || 'unknown').slice(0, 120));
          await saveProgress();
          continue;
        }
        scanDone = !!batchResult.done;
        // ★ v2.15.6 (P1): meta (.gdi-course.json) NÃO persistiu → o cursor
        //   da próxima run não sabe o que falta — a run seguinte recomeçaria
        //   do pending antigo e rodaria p/ sempre. As aulas do batch são
        //   VÁLIDAS — entram no D1 agora — e o item re-enfileira p/ a
        //   próxima run (3 strikes → quarentena com o erro legível).
        if (batchResult.metaPersisted === false) {
          stats.metaPersistFailures++;
          if (Array.isArray(batchResult.lessons) && batchResult.lessons.length) {
            insertedThisCourse = await d1InsertLessons(d1, courseHash, coursePath, driveIdx, batchResult.lessons, Date.now());
            stats.lessonsInserted += insertedThisCourse;
          }
          progress.lastError = 'meta persist failed: ' + (batchResult.persistError || 'unknown') + ' (' + coursePath + ')';
          await requeueOrDrop(item, 'course_' + coursePath + ': meta persist failed (' + (batchResult.persistError || 'unknown') + ')', false);
          await saveProgress();
          continue;
        }
        if (batchResult.dotfileFailures > 0) {
          stats.dotfileFailures += batchResult.dotfileFailures;
          console.log('[Cron Backfill] dotfile failures:', batchResult.dotfileFailures, 'no curso', coursePath);
        }
        // ★ v2.15.5 (R5): o contador JÁ inclui cleanup/consolidado/meta
        //   (v2.15.3 + R3/R4) — o +8 era resíduo da época em que não
        //   incluía, e inflava o budgetUsed p/ ~55 após 1 curso. +2 cobre
        //   o token do drive (1 fetch/invocação, fora do contador).
        budgetUsed += (counter.value || 0) + 2;
      }

      // ★ v2.15.3 (W4) — INSERÇÃO INCREMENTAL: o batch desta run já traz
      //   as aulas das pastas que ESCANEOU (batchResult.lessons); persistir
      //   AGORA, com scanDone ou não. Antes, tudo era descartado quando
      //   incomplete e lessonsInserted era 0 por desenho em cursos grandes
      //   (~2 pastas novas/batch, 1 curso/run) — o D1 só crescia no fim.
      //   INSERT OR REPLACE por id de arquivo dedupa entre runs; o
      //   markScanDone continua só com scanComplete.
      if (batchResult && Array.isArray(batchResult.lessons) && batchResult.lessons.length) {
        insertedThisCourse = await d1InsertLessons(d1, courseHash, coursePath, driveIdx, batchResult.lessons, Date.now());
        stats.lessonsInserted += insertedThisCourse;
        console.log('[Cron Backfill] inseriu (incremental)', insertedThisCourse, 'lessons de', coursePath);
      }
      // ★ v2.13 — FASE 2 (leitura): quando o scan está completo, o
      //   consolidado .gdi-lessons.json existe na raiz e a leitura é barata
      //   (~3) — ela traz as aulas das runs ANTERIORES (as desta run já
      //   entraram acima; o REPLACE dedupa). Scan parcial NÃO lê agora: o
      //   progresso já está salvo nos dotfiles e no D1 (W4).
      if (!scanDone) {
        outcome = 'incomplete';
        countIt = true;
      } else {
        if (budgetUsed + 12 > RUN_BUDGET && stats.coursesScanned > 0) break; // sem orçamento para ler — volta na próxima como cache hit
        const counter2 = { value: 0 };
        const result = await gdiReadCourseDistributedLessons(gd, coursePath, courseHash, folderId, counter2);
        // ★ v2.13.4: custo REAL da leitura (contador) + margem (antes: 3 fixo).
        budgetUsed += (counter2.value || 0) + 2;
        if (result && Array.isArray(result.lessons) && result.lessons.length) {
          insertedThisCourse = await d1InsertLessons(d1, courseHash, coursePath, driveIdx, result.lessons, result.scannedAt);
          stats.lessonsInserted += insertedThisCourse;
          console.log('[Cron Backfill] inseriu', insertedThisCourse, 'lessons de', coursePath);
        }
        // ★ v2.7: scan completo + aulas no D1 = done definitivo (nunca mais entra na fila)
        if (result && result.scanComplete === true && Array.isArray(result.lessons) && result.lessons.length > 0) {
          await markScanDone(d1, coursePath, result.lessons.length);
          outcome = 'done';
        } else {
          outcome = 'incomplete';
        }
        countIt = true;
      }
    } catch (e) {
      const errMsg = (e.message || String(e));
      stats.errors.push('course_' + coursePath + ':' + errMsg.slice(0, 120));
      // ★ v2.13.4: teto de subrequests atingido — a invocação está sem
      // orçamento; tentar o próximo curso só geraria o mesmo erro. Para
      // após salvar (a próxima invocação retoma com orçamento novo).
      if (/Too many subrequests|subrequest/i.test(errMsg)) stopAfterThis = true;
      // ★ v2.7/v2.12: erro transitório — re-enfileira no fim (máx. 3 tentativas)
      const retries = (item.retries || 0) + 1;
      if (retries <= 3) {
        progress.queue.shift();
        progress.queue.push({ ...item, retries, lastError: 'course_' + coursePath + ':' + errMsg.slice(0, 120), lastAttemptAt: Date.now() });
      } else {
        // ★ v2.15.7 (P1): mesmo guarda do requeueOrDrop — o drop só sai
        //   da fila com a quarentena persistida (D1 ou lápide KV).
        const q = await quarantineCourse(d1, kv, coursePath, 'error', 'course_' + coursePath + ':' + errMsg.slice(0, 200));
        if (!q.d1 && !q.kv) {
          stats.errors.push('course_' + coursePath + ': quarantine write failed — item mantido na fila');
          item.deadWriteFailed = true;
          item.lastError = 'course_' + coursePath + ':' + errMsg.slice(0, 120);
          item.lastAttemptAt = Date.now();
        } else {
          progress.queue.shift();
          stats.dropped.push(coursePath);
        }
      }
      // já saiu da cabeça da fila (foi para o fim ou descartado) — não shiftar de novo
      countIt = true; outcome = 'error';
    }
    // ★ v2.13: curso incompleto volta ao FIM da fila (round-robin) com um
    // contador de ciclos visível no JSON da fila — antes ele era descartado
    // da fila e só voltava quando a fila esvaziava (ou nunca, no caso das
    // pastas raiz, que a mescla não recoloca). Curso concluído sai da fila.
    // 'error' já foi tratado no catch (requeueOrDrop) — nada a fazer aqui.
    if (outcome === 'incomplete') {
      if (progress.queue[0] && progress.queue[0].coursePath === coursePath) {
        // ★ v2.15.8 (A): o 'incomplete' passa a deixar DIAGNÓSTICO no item
        //   (progresso real + nº de ciclos sem progresso) — antes o requeue
        //   só incrementava cycles e o admin mostrava "erro desconhecido".
        //   Estagnação (pastas escaneadas sem crescer + 0 aulas, OU recomeço
        //   da raiz com progresso anterior, OU cursor perdido) por 3 ciclos
        //   seguidos é terminal: quarentena com o motivo real, em vez de
        //   ciclar p/ sempre. O nº de pastas vem do batch (scanProgress);
        //   sem batch (só fase 2 sem aulas), vale o progresso anterior.
        const sp = (batchResult && batchResult.scanProgress) || null;
        const prev = (item && item.scanProgress) || null;
        const scannedNow = sp ? (sp.scanned || 0) : (prev ? (prev.scanned || 0) : 0);
        const pendingNow = sp ? (sp.pending || 0) : (prev ? (prev.pending || 0) : 0);
        const totalNow = sp ? (sp.total || (scannedNow + pendingNow)) : (prev ? (prev.total || (scannedNow + pendingNow)) : (scannedNow + pendingNow));
        const grew = prev ? (scannedNow > (prev.scanned || 0)) : (scannedNow > 0);
        const restarted = !!((prev && batchResult && batchResult.freshStart));
        const cursorLost = !!(prev && scannedNow < (prev.scanned || 0));
        const stagnant = (restarted || cursorLost || (!grew && insertedThisCourse === 0)) ? ((item.stagnantCycles || 0) + 1) : 0;
        const metaSrc = (batchResult && batchResult.metaSource) || (prev && prev.metaSource) || 'n/d';
        const dotFails = (batchResult && batchResult.dotfileFailures) || 0;
        const note = 'em progresso: ' + scannedNow + '/' + totalNow + ' pastas escaneadas, ' + pendingNow + ' pendente(s), ' + insertedThisCourse + ' aula(s) nesta run · meta: ' + metaSrc + (restarted ? ' · ⚠️ recomeçou da raiz (meta não encontrado)' : '') + (cursorLost ? ' · ⚠️ cursor perdido' : '') + (!batchResult ? ' · sem batch nesta run (fase 2: 0 aulas)' : '') + (dotFails ? ' · dotfiles com falha: ' + dotFails : '');
        const next = { ...item, cycles: (item.cycles || 0) + 1, lastError: note, lastAttemptAt: Date.now(),
          scanProgress: { scanned: scannedNow, pending: pendingNow, total: totalNow, lessonsThisRun: insertedThisCourse, metaSource: (batchResult && batchResult.metaSource) || (prev && prev.metaSource) || null, note },
          stagnantCycles: stagnant };
        if (stagnant >= 3) {
          const reason = 'course_' + coursePath + ': sem progresso em 3 ciclos (pastas escaneadas travadas em ' + scannedNow + ', ' + pendingNow + ' pendente(s); meta: ' + metaSrc + (restarted ? '; recomeço da raiz' : '') + (cursorLost ? '; cursor perdido' : '') + (dotFails ? '; dotfiles com falha: ' + dotFails : '') + ')';
          const q = await quarantineCourse(d1, kv, coursePath, 'error', reason);
          if (!q.d1 && !q.kv) {
            progress.queue.shift();
            progress.queue.push({ ...next, deadWriteFailed: true });
            stats.errors.push(reason + ' (quarentena NÃO persistida — item mantido na fila)');
          } else {
            progress.queue.shift();
            stats.dropped.push(coursePath);
            stats.errors.push(reason + ' (quarentenado após 3 ciclos sem progresso)');
          }
        } else {
          progress.queue.shift();
          progress.queue.push(next);
        }
      }
    } else if (outcome === 'done') {
      if (progress.queue[0] && progress.queue[0].coursePath === coursePath) progress.queue.shift();
    }
    if (countIt) {
      stats.coursesScanned++;
      progress.totalScanned = (progress.totalScanned || 0) + 1;
      // ★ v2.12: soma só as aulas DESTE curso (antes somava o acumulado da run)
      progress.totalLessons = (progress.totalLessons || 0) + insertedThisCourse;
      await saveProgress();
    }
    if (stopAfterThis) break; // ★ v2.13.4: teto de subrequests — próxima run retoma
  }

  stats.queueLeft = progress.queue.length;
  // ★ v2.12: persiste os erros da execução para o admin exibir
  try { await kv.put('cron-backfill:errors', JSON.stringify({ at: Date.now(), errors: stats.errors, dropped: stats.dropped })); } catch (_) {}
  console.log('[Cron Backfill] concluído:', JSON.stringify(stats));
  return stats;
}


// ★ v1.0.211: CRON SCAN — Auto-varredura + Auto-correção + Backup
// Roda a cada hora via cron, verifica saúde da plataforma e corrige
// ═══════════════════════════════════════════════════════════════
async function handleCronScan(request){
  const cors = {'Content-Type':'application/json;charset=UTF-8','Access-Control-Allow-Origin':'*'};
  const user = await gdiSessionUser(request);
  if(!user) return new Response(JSON.stringify({ok:false,error:'auth'}),{status:401,headers:cors});
  if(!ADMIN_USERS.includes(user)) return new Response(JSON.stringify({ok:false,error:'forbidden'}),{status:403,headers:cors});
  
  const report = {
    timestamp: Date.now(),
    checks: [],
    fixes: [],
    errors: []
  };
  
  try {
    // ── CHECK 1: D1 schema integrity ──
    const d1 = meggyD1Binding();
    if (d1) {
      try {
        await d1EnsureSchema();
        report.checks.push({name: 'D1 schema', status: 'ok', detail: 'Schema verificado'});
        
        // Count rows in each table
        const tables = ['lessons', 'shared_summaries', 'shared_flashcards', 'user_courses', 'materials_meta'];
        for (const table of tables) {
          try {
            const count = await d1.prepare(`SELECT COUNT(*) as c FROM ${table}`).first();
            report.checks.push({name: `D1:${table}`, status: 'ok', detail: `${count?.c || 0} rows`});
          } catch(e) {
            report.errors.push({table, error: e.message});
            // Auto-fix: try to recreate the table
            report.fixes.push({table, action: 'schema check failed — will retry on next d1EnsureSchema()'});
          }
        }
      } catch(e) {
        report.errors.push({name: 'D1 schema', error: e.message});
      }
    } else {
      report.checks.push({name: 'D1', status: 'warn', detail: 'D1 not bound'});
    }
    
    // ── CHECK 2: KV namespace ──
    const kv = meggyKvBinding();
    if (kv) {
      try {
        const cronProgress = await kv.get('cron-backfill:progress');
        report.checks.push({name: 'KV:MEGGY_CACHE', status: 'ok', detail: cronProgress ? 'has progress' : 'empty'});
      } catch(e) {
        report.errors.push({name: 'KV:MEGGY_CACHE', error: e.message});
      }
    } else {
      report.checks.push({name: 'KV:MEGGY_CACHE', status: 'warn', detail: 'KV not bound'});
    }
    
    // ── CHECK 3: AI backends ──
    const cfAI = getAI();
    report.checks.push({name: 'CF AI', status: cfAI ? 'ok' : 'warn', detail: cfAI ? 'bound' : 'not bound'});
    
    const aiBackends = ['NVIDIA_API_KEY', 'OPENROUTER_API_KEY', 'GROQ_API_KEY', 'GROQ_API_KEY_2'];
    for (const key of aiBackends) {
      report.checks.push({name: `AI:${key}`, status: globalThis[key] ? 'ok' : 'warn', detail: globalThis[key] ? 'configured' : 'missing'});
    }
    
    // ── CHECK 4: gds (Google Drive) initialized ──
    report.checks.push({name: 'gds', status: gds.length > 0 ? 'ok' : 'warn', detail: `${gds.length} drives`});
    
    // ── CHECK 5: Orphan lessons (lessons without valid course_path) ──
    if (d1) {
      try {
        const orphans = await d1.prepare('SELECT COUNT(*) as c FROM lessons WHERE course_path IS NULL OR course_path = ""').first();
        if (orphans?.c > 0) {
          report.fixes.push({action: 'delete_orphan_lessons', count: orphans.c});
          await d1.prepare('DELETE FROM lessons WHERE course_path IS NULL OR course_path = ""').run();
          report.checks.push({name: 'orphan_lessons', status: 'fixed', detail: `${orphans.c} deleted`});
        } else {
          report.checks.push({name: 'orphan_lessons', status: 'ok', detail: 'none'});
        }
      } catch(e) {
        report.errors.push({name: 'orphan_lessons', error: e.message});
      }
    }
    
    // ── CHECK 6: Duplicate lessons (same lesson_path) ──
    if (d1) {
      try {
        const dups = await d1.prepare('SELECT lesson_path, COUNT(*) as c FROM lessons GROUP BY lesson_path HAVING c > 1 LIMIT 10').all();
        if (dups.results?.length > 0) {
          report.fixes.push({action: 'dedup_lessons', count: dups.results.length});
          for (const dup of dups.results) {
            await d1.prepare('DELETE FROM lessons WHERE lesson_path = ? AND id NOT IN (SELECT id FROM lessons WHERE lesson_path = ? LIMIT 1)').bind(dup.lesson_path, dup.lesson_path).run();
          }
          report.checks.push({name: 'duplicate_lessons', status: 'fixed', detail: `${dups.results.length} deduped`});
        } else {
          report.checks.push({name: 'duplicate_lessons', status: 'ok', detail: 'none'});
        }
      } catch(e) {
        report.errors.push({name: 'duplicate_lessons', error: e.message});
      }
    }
    
    // ── CHECK 7: AI cache cleanup (old entries > 7 days) ──
    if (kv) {
      try {
        // Can't list/delete by prefix efficiently in KV, but we can check the cache list
        // This is a soft check — actual cleanup happens on access (TTL)
        report.checks.push({name: 'ai_cache', status: 'ok', detail: 'TTL-based, self-cleaning'});
      } catch(e) {
        report.errors.push({name: 'ai_cache', error: e.message});
      }
    }
    
    // ── SUMMARY ──
    report.ok = report.errors.length === 0;
    report.checks_passed = report.checks.filter(c => c.status === 'ok').length;
    report.checks_warned = report.checks.filter(c => c.status === 'warn').length;
    report.checks_failed = report.checks.filter(c => c.status === 'error').length;
    report.fixes_applied = report.fixes.length;
    
    // ── LOG to worklog (KV) ──
    if (kv) {
      try {
        const logKey = `cron-scan:${Date.now()}`;
        await kv.put(logKey, JSON.stringify(report), {expirationTtl: 86400 * 7}); // 7 days
      } catch(_){}
    }
    
    console.log(`[CronScan] ${report.checks_passed} ok, ${report.checks_warned} warn, ${report.errors.length} errors, ${report.fixes_applied} fixes`);
    
  } catch(e) {
    report.errors.push({name: 'global', error: e.message});
    report.ok = false;
  }
  
  return new Response(JSON.stringify(report, null, 2),{headers:{...cors,'Cache-Control':'no-store'}});
}

export default {
  async scheduled(event, env, ctx) {
    // ★ v1.0.180 OPÇÃO A: Cron Worker — backfill automático de lessons a cada 6h.
    // Propagar env para globalThis (igual ao fetch handler) para que meggyKvBinding(),
    // meggyD1Binding(), meggyCacheBackend() e meggyD1Backend() funcionem no contexto do cron.
    if(env){
      try{
        const keys = ['NVIDIA_API_KEY','NVIDIA_API_KEY_2','NVIDIA_API_KEY_3','OPENROUTER_API_KEY',
                      'ZHIPU_API_KEY','AI_API_KEY','ZHIPU_API_URL','AI_MODEL','ZHIPU_MODEL',
                      'OPENAI_API_KEY','OPENAI_API_URL','OPENAI_MODEL',
                      'GROQ_API_KEY','GROQ_API_KEY_2',  // ★ v1.0.184: Groq keys para racing
                      'CRYPTO_BASE_KEY','HMAC_BASE_KEY',
                      'environment','MODULAR_REPO','MODULAR_REF','ADMIN_USERS','DEMO_SEED','CDN_VERSION','SITE_NAME','PLAYER',
                      'CACHE_BACKEND','D1_BACKEND'];
        for(const k of keys){
          if(env[k] !== undefined && globalThis[k] === undefined) globalThis[k] = env[k];
        }
        if(env.ENV && globalThis.ENV === undefined) globalThis.ENV = env.ENV;
        if(env.MEGGY_CACHE && globalThis.MEGGY_CACHE === undefined) globalThis.MEGGY_CACHE = env.MEGGY_CACHE;
        if(env.MEGGY_D1 && globalThis.MEGGY_D1 === undefined) globalThis.MEGGY_D1 = env.MEGGY_D1;
        if(env.MEGGY_D1_PEER && globalThis.MEGGY_D1_PEER === undefined) globalThis.MEGGY_D1_PEER = env.MEGGY_D1_PEER;  // ★ v2.15.63: binding do D1 do par (escrita dual)
        if(env.ai && globalThis.AI === undefined) globalThis.AI = env.ai;
      }catch(_){}
    }
    // ctx.waitUntil() mantém o isolate vivo após o cron retornar, permitindo que o
    // backfill complete sem ultrapassar o tempo de CPU do evento scheduled.
    // ★ v1.0.211: Cron scan — auto-varredura + auto-correção a cada hora
    try{ await ensureSecretsLoaded(); }catch(_){}
    ctx.waitUntil(handleCronBackfill());
    // ★ v2.15.34 (GenQueue): runner horário da fila de geração — waitUntil
    //   SEPARADO do backfill/scanner (não toca no cron do scanner).
    ctx.waitUntil(handleGenQueueRunner({ trigger: 'cron' }));
    // Auto-scan runs after backfill (separate ctx.waitUntil)
    try {
      const d1 = meggyD1Binding();
      const kv = meggyKvBinding();
      if (d1 && kv) {
        // Run auto-scan checks (orphan cleanup, dedup, etc.)
        // This is a lightweight version without auth (runs in cron context)
        const scanReport = { timestamp: Date.now(), fixes: [] };
        // ★ v2.15.43 (CF-9): as correcções abaixo (órfãos + dedup com
        //   GROUP BY sobre lessons INTEIRA) corriam TODAS as horas
        //   (~1,6M rows-read/dia). Agora no máx. 1×/dia; o backfill/
        //   scanner do cron NÃO é afectado.
        let _fixDue = true;
        try { const _lf = Number(await kv.get('cron-scan:last-fix')) || 0; if (Date.now() - _lf < 20 * 3600 * 1000) _fixDue = false; } catch (_) {}
        try {
          if (_fixDue) { const orphans = await d1.prepare('SELECT COUNT(*) as c FROM lessons WHERE course_path IS NULL OR course_path = ""').first();
          if (orphans?.c > 0) {
            await d1.prepare('DELETE FROM lessons WHERE course_path IS NULL OR course_path = ""').run();
            scanReport.fixes.push({action: 'delete_orphan_lessons', count: orphans.c});
          } }
        } catch(_){}
        try {
          if (_fixDue) { const dups = await d1.prepare('SELECT lesson_path, COUNT(*) as c FROM lessons GROUP BY lesson_path HAVING c > 1 LIMIT 5').all();
          if (dups.results?.length > 0) {
            for (const dup of dups.results) {
              await d1.prepare('DELETE FROM lessons WHERE lesson_path = ? AND id NOT IN (SELECT id FROM lessons WHERE lesson_path = ? LIMIT 1)').bind(dup.lesson_path, dup.lesson_path).run();
            }
            scanReport.fixes.push({action: 'dedup_lessons', count: dups.results.length});
          } }
        } catch(_){}
        if (scanReport.fixes.length > 0) {
          await kv.put(`cron-scan:${Date.now()}`, JSON.stringify(scanReport), {expirationTtl: 86400 * 7});
          console.log('[CronScan] fixes:', JSON.stringify(scanReport.fixes));
        }
        if (_fixDue) { try { await kv.put('cron-scan:last-fix', String(Date.now()), { expirationTtl: 172800 }); } catch (_) {} }
      }
    } catch(_){}
  },
  async fetch(request, env, ctx) {
    // Store em module scope para funções que não recebem env/ctx diretamente.
    // ★ v1.0.102 FIX (Agent 20 Bug 1): só atualiza se mudou (evita overwrite desnecessário
    // em isolates que manipulam múltiplas requests — ainda assim não é 100% race-safe,
    // ver comentário na declaração de _env acima).
    if (_env !== env) _env = env || null;
    if (_ctx !== ctx) _ctx = ctx || null;
    // ★ v1.0.88: Copia vars do env para globalThis — compatibilidade com código existente
    // que usa globalThis.NVIDIA_API_KEY etc. (Service Worker format).
    // Em Module format, vars vêm em env; em Service format, vêm em globalThis.
    // Isto garante que AMBOS os formatos funcionem.
    if (env) {
      try {
        const keys = ['NVIDIA_API_KEY','NVIDIA_API_KEY_2','NVIDIA_API_KEY_3','OPENROUTER_API_KEY',
                      'ZHIPU_API_KEY','AI_API_KEY','ZHIPU_API_URL','AI_MODEL','ZHIPU_MODEL',
                      'OPENAI_API_KEY','OPENAI_API_URL','OPENAI_MODEL',
                      'GROQ_API_KEY','GROQ_API_KEY_2',  // ★ v1.0.184: Groq keys para racing
                      'CRYPTO_BASE_KEY','HMAC_BASE_KEY',
                      'environment','MODULAR_REPO','MODULAR_REF','ADMIN_USERS','DEMO_SEED','CDN_VERSION','SITE_NAME','PLAYER',
                      'CACHE_BACKEND','D1_BACKEND'];  // ★ FASE 1.5 + 3a: adicionado para meggyCacheBackend() e meggyD1Backend() funcionarem
        for (const k of keys) {
          if (env[k] !== undefined && globalThis[k] === undefined) {
            globalThis[k] = env[k];
          }
        }
        // KV namespace
        if (env.ENV && globalThis.ENV === undefined) globalThis.ENV = env.ENV;
        // ★ FASE 1: MEGGY_CACHE KV namespace binding — precisa ser copiado para globalThis
        // explicitamente (igual ao ENV acima). Sem isso, meggyKvBinding() retorna null sempre.
        if (env.MEGGY_CACHE && globalThis.MEGGY_CACHE === undefined) globalThis.MEGGY_CACHE = env.MEGGY_CACHE;
        // ★ FASE 3a: MEGGY_D1 D1 database binding — mesma pattern do MEGGY_CACHE.
        // Sem isso, meggyD1Binding() retorna null e endpoints de busca não funcionam.
        if (env.MEGGY_D1 && globalThis.MEGGY_D1 === undefined) globalThis.MEGGY_D1 = env.MEGGY_D1;
        if (env.MEGGY_D1_PEER && globalThis.MEGGY_D1_PEER === undefined) globalThis.MEGGY_D1_PEER = env.MEGGY_D1_PEER;  // ★ v2.15.63: idem, caminho fetch
        // AI binding (quando existir)
        if (env.ai && globalThis.AI === undefined) globalThis.AI = env.ai;
      } catch(_) {}
    }
    // Cria um "event-like" para compat com handleRequest(request, event) existente.
    // event.waitUntil → ctx.waitUntil (mesma assinatura)
    const eventLike = ctx ? {
      request,
      waitUntil: (promise) => ctx.waitUntil(promise),
      respondWith: (response) => response,  // no-op em Module format
    } : null;
    try{ await ensureSecretsLoaded(); }catch(_){}
    return handleRequest(request, eventLike).catch(
      (err) => { console.error((err && err.stack) || err); return new Response('Internal Server Error', { status: 500, headers: { 'Content-Type': 'text/plain;charset=UTF-8', 'Access-Control-Allow-Origin': '*' } }); }
    );
  }
};

// ★ Fallback: addEventListener (Service Worker format) — usado se Cloudflare NÃO detectar export default.
// Em Module Worker format, este código é ignorado (export default tem precedência).
// Em Service Worker format (fallback), este é o entry point.
addEventListener('fetch', event => {
  // Em Service Worker format, env/ctx não são passados — _env fica null, getKV() usa globalThis.ENV.
  event.respondWith(handleRequest(event.request, event).catch(
    (err) => { console.error((err && err.stack) || err); return new Response('Internal Server Error', { status: 500, headers: { 'Content-Type': 'text/plain;charset=UTF-8', 'Access-Control-Allow-Origin': '*' } }); }
  ));
});// trigger rebuild



